    /// <summary>The scan-screen look of aegis\Aegis.ps1: one row per step with its glyph and result, a scan band while running.</summary>
    public sealed class StepView : Control
    {
        public readonly List<Step> Steps = new List<Step>();
        public volatile bool Running;
        public string Title = "", Result = "";
        public int ResultKind;
        float angle, sweep = -0.3f;
        readonly System.Windows.Forms.Timer anim = new System.Windows.Forms.Timer();
        Font fTitle, fRow, fRowBold, fResult;

        public StepView()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            BackColor = Ui.Bg;
            fTitle = Art.UiFont(11f, FontStyle.Bold);
            fRow = Art.UiFont(9.5f, FontStyle.Regular);
            fRowBold = Art.UiFont(9.5f, FontStyle.Bold);
            fResult = Art.UiFont(10f, FontStyle.Bold);
            anim.Interval = 30;
            anim.Tick += (s, e) => { angle = (angle + 7f) % 360f; sweep += 0.02f; if (sweep > 1.35f) sweep = -0.35f; Invalidate(); };
            VisibleChanged += (s, e) => { if (Visible) anim.Start(); else anim.Stop(); };
        }

        public int PreferredRowsHeight { get { return Ui.S(62) + Steps.Count * Ui.S(30) + Ui.S(64); } }

        protected override void Dispose(bool disposing) { if (disposing) anim.Dispose(); base.Dispose(disposing); }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
            int W = Width, H = Height;
            using (var bg = new LinearGradientBrush(new Rectangle(0, 0, Math.Max(1, W), Math.Max(1, H)), Ui.Ground, Ui.Panel, 90f)) g.FillRectangle(bg, 0, 0, W, H);
            Ui.Grid(g, W, H);
            bool done = !Running && Result.Length > 0;
            Color c1 = done ? (ResultKind == 4 ? Art.Red1 : ResultKind == 3 ? Art.Amber1 : Art.Green1) : Art.Shield1;
            Color c2 = done ? (ResultKind == 4 ? Art.Red2 : ResultKind == 3 ? Art.Amber2 : Art.Green2) : Art.Shield2;
            var sr = new RectangleF(Ui.S(22), Ui.S(14), Ui.S(26), Ui.S(30));
            if (Running)
                using (var p = new Pen(Color.FromArgb(200, Art.Teal1), Math.Max(1.5f, Ui.S(2))))
                {
                    p.StartCap = LineCap.Round; p.EndCap = LineCap.Round;
                    var rr = new RectangleF(sr.X - Ui.S(6), sr.Y + sr.Height / 2 - (sr.Width + Ui.S(12)) / 2, sr.Width + Ui.S(12), sr.Width + Ui.S(12));
                    g.DrawArc(p, rr, angle, 80); g.DrawArc(p, rr, angle + 180, 80);
                }
            Art.DrawShield(g, sr, c1, c2);
            TextRenderer.DrawText(g, Title, fTitle, new Rectangle(Ui.S(62), Ui.S(16), W - Ui.S(80), Ui.S(26)), Ui.Text, TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
            int y0 = Ui.S(62), rowH = Ui.S(30), detailX = Math.Max(Ui.S(280), W / 2);
            for (int i = 0; i < Steps.Count; i++)
            {
                var s = Steps[i];
                int st = s.State, y = y0 + i * rowH;
                Ui.Glyph(g, st, new RectangleF(Ui.S(26), y + Ui.S(4), Ui.S(16), Ui.S(16)), angle);
                Color tc = st == 0 ? Ui.Dim : Ui.Text;   // v0.5.5: waiting steps in Dim, details (right) in Muted
                TextRenderer.DrawText(g, s.Title, st == 1 ? fRowBold : fRow, new Rectangle(Ui.S(52), y, detailX - Ui.S(60), rowH - Ui.S(4)), tc, TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
                string d = s.Detail ?? "";
                if (st >= 2 || (st == 1 && d.Length > 0))
                {
                    Color dc = st == 4 ? Art.Red1 : st == 3 ? Art.Amber1 : st == 1 ? Ui.Text : Ui.Muted;
                    TextRenderer.DrawText(g, d, fRow, new Rectangle(detailX, y, W - detailX - Ui.S(20), rowH - Ui.S(4)), dc, TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
                }
                else if (st == 1)
                    TextRenderer.DrawText(g, new string('.', 1 + (int)(angle / 30) % 3), fRow, new Rectangle(detailX, y, Ui.S(40), rowH), Ui.Muted, TextFormatFlags.SingleLine);
            }
            if (Running) Ui.BandH(g, Ui.S(16), W - Ui.S(32), y0 - Ui.S(8) + sweep * (Steps.Count * rowH + Ui.S(16)), Ui.S(34), Art.Teal1);
            if (Result.Length > 0)
            {
                int ry = y0 + Steps.Count * rowH + Ui.S(10);
                TextRenderer.DrawText(g, Result, fResult, new Rectangle(Ui.S(26), ry, W - Ui.S(48), H - ry - Ui.S(6)), c1, TextFormatFlags.WordBreak);
            }
        }
    }

    // ------------------------------------------------------------------ v0.5.5 controls drawn for the dark theme (2026-09-22 readability)
    /// <summary>
    /// The border (and the empty-box hint) of a TextBox or a RichTextBox, drawn by the console instead of Windows: Windows drew
    /// a cold grey (#646464) or white frame and a grey hint that the dark theme cannot change (SetWindowTheme does not reach
    /// them). The frame is Ui.Edge (3.9:1 on Bg), gold while the box has the keyboard focus, Ui.Line when read-only or disabled;
    /// the hint of an empty box is written in Dim (4.6:1 on Panel2) and hides while the box has the focus.
    /// </summary>
    public sealed class FieldSkin : NativeWindow
    {
        [DllImport("user32.dll")] static extern IntPtr GetWindowDC(IntPtr h);
        [DllImport("user32.dll")] static extern int ReleaseDC(IntPtr h, IntPtr dc);
        [DllImport("user32.dll")] static extern bool RedrawWindow(IntPtr h, IntPtr rect, IntPtr rgn, uint flags);
        static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Control, FieldSkin> Skins = new System.Runtime.CompilerServices.ConditionalWeakTable<Control, FieldSkin>();
        readonly TextBoxBase box;
        /// <summary>The hint of an empty box ("" = none).</summary>
        public string Cue = "";

        FieldSkin(TextBoxBase b) { box = b; }

        public static FieldSkin Attach(TextBoxBase b)
        {
            FieldSkin s;
            if (Skins.TryGetValue(b, out s)) return s;
            s = new FieldSkin(b);
            Skins.Add(b, s);
            b.HandleCreated += (o, e) => { try { s.AssignHandle(b.Handle); s.Frame(); } catch (Exception) { } };
            b.HandleDestroyed += (o, e) => { try { s.ReleaseHandle(); } catch (Exception) { } };
            EventHandler redraw = (o, e) => s.Frame();
            b.GotFocus += redraw; b.LostFocus += redraw; b.EnabledChanged += redraw; b.ReadOnlyChanged += redraw;
            b.TextChanged += (o, e) => { if (s.Cue.Length > 0) b.Invalidate(); };
            if (b.IsHandleCreated) s.AssignHandle(b.Handle);
            return s;
        }

        /// <summary>The skin of a box (null when it has none).</summary>
        public static FieldSkin Of(Control c) { FieldSkin s; return c != null && Skins.TryGetValue(c, out s) ? s : null; }

        /// <summary>The frame's colour now.</summary>
        public Color EdgeColor { get { return !box.Enabled || box.ReadOnly ? Ui.Line : box.Focused ? Ui.Focus : Ui.Edge; } }

        void Frame()
        {
            if (Handle == IntPtr.Zero) return;
            try { RedrawWindow(Handle, IntPtr.Zero, IntPtr.Zero, 0x0401 | 0x0100); }   // RDW_INVALIDATE | RDW_FRAME | RDW_UPDATENOW
            catch (Exception) { }
        }

        protected override void WndProc(ref Message m)
        {
            base.WndProc(ref m);
            if (m.Msg == 0x0085 || m.Msg == 0x0086) PaintFrame();          // WM_NCPAINT, WM_NCACTIVATE
            else if (m.Msg == 0x000F) { PaintCue(); PaintFrame(); }        // WM_PAINT (RichEdit repaints its own frame there)
        }

        void PaintFrame()
        {
            if (Handle == IntPtr.Zero || box.BorderStyle == BorderStyle.None) return;
            IntPtr dc = IntPtr.Zero;
            try
            {
                dc = GetWindowDC(Handle);
                if (dc == IntPtr.Zero) return;
                using (var g = Graphics.FromHdc(dc))
                {
                    using (var pen = new Pen(EdgeColor, 1f)) g.DrawRectangle(pen, 0, 0, box.Width - 1, box.Height - 1);
                    // RichEdit keeps a 2 px frame (a sunken grey / white inner line): the inner line takes the box's own colour
                    if ((box.Height - box.ClientSize.Height) / 2 >= 2)
                        using (var pen = new Pen(box.BackColor, 1f)) g.DrawRectangle(pen, 1, 1, box.Width - 3, box.Height - 3);
                }
            }
            catch (Exception) { }
            finally { if (dc != IntPtr.Zero) ReleaseDC(Handle, dc); }
        }

        void PaintCue()
        {
            if (Cue.Length == 0 || box.TextLength > 0 || box.Focused || !(box is TextBox)) return;
            try
            {
                using (var g = Graphics.FromHwnd(Handle))
                    TextRenderer.DrawText(g, Cue, box.Font, new Rectangle(Ui.S(2), 0, box.ClientSize.Width - Ui.S(4), box.ClientSize.Height), Ui.Dim, box.BackColor,
                        TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
            }
            catch (Exception) { }
        }
    }

    /// <summary>
    /// A drop-down list drawn for the dark theme: Windows drew the closed box with a light grey button and the system blue
    /// selection. The face: Panel2, a 1 px Edge frame (warm white, Ui.Focus, with the keyboard focus or while open), the choice in the body
    /// colour and a chevron in Muted; the open list: the choice under the pointer on the selection colour.
    /// </summary>
    public sealed class DarkCombo : ComboBox
    {
        bool hot;

        public DarkCombo()
        {
            DropDownStyle = ComboBoxStyle.DropDownList;
            FlatStyle = FlatStyle.Flat;
            DrawMode = DrawMode.OwnerDrawFixed;
            BackColor = Ui.Panel2;
            ForeColor = Ui.Text;
        }

        protected override void OnDrawItem(DrawItemEventArgs e)
        {
            if (e.Index < 0 || e.Index >= Items.Count) return;
            bool face = (e.State & DrawItemState.ComboBoxEdit) != 0, sel = (e.State & DrawItemState.Selected) != 0;
            using (var b = new SolidBrush(!face && sel ? Ui.Sel : Ui.Panel2)) e.Graphics.FillRectangle(b, e.Bounds);
            var r = new Rectangle(e.Bounds.X + Ui.S(6), e.Bounds.Y, e.Bounds.Width - Ui.S(8), e.Bounds.Height);
            TextRenderer.DrawText(e.Graphics, GetItemText(Items[e.Index]), Font, r, Ui.Text, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }

        protected override void WndProc(ref Message m)
        {
            base.WndProc(ref m);
            if (m.Msg == 0x000F) PaintFace();   // WM_PAINT: the whole closed face, over what Windows drew
        }

        [StructLayout(LayoutKind.Sequential)] struct RECT { public int L, T, R, B; }
        [StructLayout(LayoutKind.Sequential)] struct COMBOBOXINFO { public int cbSize; public RECT rcItem, rcButton; public int stateButton; public IntPtr hwndCombo, hwndItem, hwndList; }
        [DllImport("user32.dll")] static extern bool GetComboBoxInfo(IntPtr h, ref COMBOBOXINFO info);

        /// <summary>An editable box (DropDown): the rectangle its text box covers (left alone), else empty.</summary>
        Rectangle EditRect()
        {
            if (DropDownStyle == ComboBoxStyle.DropDownList) return Rectangle.Empty;
            try
            {
                var i = new COMBOBOXINFO();
                i.cbSize = Marshal.SizeOf(i);
                if (GetComboBoxInfo(Handle, ref i)) return Rectangle.FromLTRB(i.rcItem.L, i.rcItem.T, i.rcItem.R, i.rcItem.B);
            }
            catch (Exception) { }
            return Rectangle.Empty;
        }

        void PaintFace()
        {
            try
            {
                using (var g = Graphics.FromHwnd(Handle))
                {
                    var edit = EditRect();
                    if (!edit.IsEmpty) g.ExcludeClip(edit);   // an editable box: its own text box draws the text
                    g.SmoothingMode = SmoothingMode.AntiAlias;
                    var r = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f);
                    g.Clear(Parent != null ? Parent.BackColor : Ui.Bg);
                    Color fill = !Enabled ? Ui.Panel : hot && edit.IsEmpty ? Ui.Blend(Ui.Panel2, Art.Teal1, 0.10f) : Ui.Panel2;
                    Color edge = !Enabled ? Ui.Line : Focused || ContainsFocus || DroppedDown ? Ui.Focus : hot ? Art.Teal1 : Ui.Edge;
                    using (var p = Ui.Round(r, Ui.S(4)))
                    {
                        using (var b = new SolidBrush(fill)) g.FillPath(b, p);
                        using (var pen = new Pen(edge, 1f)) g.DrawPath(pen, p);
                    }
                    int cw = Ui.S(22);
                    string t = SelectedIndex >= 0 ? GetItemText(SelectedItem) : Text;
                    if (edit.IsEmpty)
                        TextRenderer.DrawText(g, t, Font, new Rectangle(Ui.S(7), 0, Width - cw - Ui.S(8), Height), Enabled ? Ui.Text : Ui.Dim,
                            TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
                    float cx = Width - cw / 2f - Ui.S(2), cy = Height / 2f, s = Ui.S(4);
                    using (var pen = new Pen(Enabled ? Ui.Muted : Ui.Dim, Math.Max(1.4f, Ui.S(1.6f))) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                        g.DrawLines(pen, new[] { new PointF(cx - s, cy - s / 2), new PointF(cx, cy + s / 2), new PointF(cx + s, cy - s / 2) });
                }
            }
            catch (Exception) { }
        }

        protected override void OnMouseEnter(EventArgs e) { hot = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hot = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
        protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }
        protected override void OnDropDownClosed(EventArgs e) { Invalidate(); base.OnDropDownClosed(e); }
        protected override void OnSelectedIndexChanged(EventArgs e) { Invalidate(); base.OnSelectedIndexChanged(e); }
    }

    /// <summary>
    /// v0.5.5 review: a choice mark drawn for the dark theme (Windows drew a white-filled circle and its blue dot, or a white
    /// box): the mark on Panel2 with an Edge rim, the chosen one's teal dot (or tick), the words in the body colour, a
    /// warm-white ring for the keyboard focus. <see cref="DarkRadio"/> and <see cref="DarkCheck"/> keep Windows' behaviour.
    /// </summary>
    static class ChoicePaint
    {
        public static Size Preferred(Control c)
        {
            var t = TextRenderer.MeasureText(c.Text, c.Font, Size.Empty, TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
            return new Size(Ui.S(30) + t.Width + Ui.S(4), Math.Max(t.Height, Ui.S(20)) + Ui.S(4));
        }

        public static void Paint(ButtonBase c, Graphics g, bool isChecked, bool round, bool hover, bool focused)
        {
            g.Clear(c.Parent != null ? c.Parent.BackColor : Ui.Bg);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            float d = Ui.S(16), x = Ui.S(4) + 0.5f, y = (c.Height - d) / 2f;
            var r = new RectangleF(x, y, d, d);
            Color rim = !c.Enabled ? Ui.Line : isChecked || hover ? Art.Teal1 : Ui.Edge;
            using (var p = round ? new GraphicsPath() : Ui.Round(r, Ui.S(3)))
            {
                if (round) p.AddEllipse(r);
                using (var b = new SolidBrush(c.Enabled ? Ui.Panel2 : Ui.Panel)) g.FillPath(b, p);
                using (var pen = new Pen(rim, 1.5f)) g.DrawPath(pen, p);
            }
            if (isChecked)
            {
                Color mark = c.Enabled ? Art.Teal1 : Ui.Dim;
                if (round) { float k = d * 0.5f; using (var b = new SolidBrush(mark)) g.FillEllipse(b, x + (d - k) / 2f, y + (d - k) / 2f, k, k); }
                else
                    using (var pen = new Pen(mark, Math.Max(1.8f, Ui.S(2f))) { StartCap = LineCap.Round, EndCap = LineCap.Round, LineJoin = LineJoin.Round })
                        g.DrawLines(pen, new[] { new PointF(x + d * 0.24f, y + d * 0.52f), new PointF(x + d * 0.43f, y + d * 0.71f), new PointF(x + d * 0.77f, y + d * 0.30f) });
            }
            if (focused)
                using (var pen = new Pen(Ui.Focus, 2f))
                {
                    var f = new RectangleF(x - 3f, y - 3f, d + 6f, d + 6f);
                    if (round) g.DrawEllipse(pen, f); else using (var fp = Ui.Round(f, Ui.S(5))) g.DrawPath(pen, fp);
                }
            int tx = (int)(x + d + Ui.S(10));
            TextRenderer.DrawText(g, c.Text, c.Font, new Rectangle(tx, 0, Math.Max(0, c.Width - tx), c.Height), c.Enabled ? Ui.Text : Ui.Dim,
                TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        }
    }

    public sealed class DarkRadio : RadioButton
    {
        bool hover;
        public DarkRadio()
        {
            SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            AutoSize = true; ForeColor = Ui.Text; BackColor = Ui.Bg; Cursor = Cursors.Hand;
