    public sealed class DarkCheck : CheckBox
    {
        bool hover;
        public DarkCheck()
        {
            SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            AutoSize = true; ForeColor = Ui.Text; BackColor = Ui.Bg; Cursor = Cursors.Hand;
        }
        public override Size GetPreferredSize(Size proposedSize) { return ChoicePaint.Preferred(this); }
        protected override void OnPaint(PaintEventArgs e) { ChoicePaint.Paint(this, e.Graphics, Checked, false, hover, Focused && ShowFocusCues); }
        protected override void OnMouseEnter(EventArgs e) { hover = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { hover = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
        protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }
    }

    /// <summary>A dialog's section heading: the words in the body colour after a short accent bar (the accent is never the text's colour, except a warning's).</summary>
    public sealed class HeadLabel : Label
    {
        public Color Accent = Art.Teal1;
        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            int bh = Math.Min(Height, Font.Height) - Ui.S(4);
            using (var b = new SolidBrush(Accent)) e.Graphics.FillRectangle(b, 0, Ui.S(2) + Math.Max(0, (Font.Height - Ui.S(4) - bh) / 2), Math.Max(2, Ui.S(3)), Math.Max(4, bh));
        }
    }

    /// <summary>
    /// A note on a raised card (Panel2, rounded) with an accent rule on the left and a mark (ⓘ / ⚠) before the words: the
    /// reply dialog's ban-number line and the AI draft's warning. The mark is drawn, not part of Text.
    /// </summary>
    public sealed class CardLabel : Label
    {
        public Color Accent = Art.Teal1;
        public string Mark = "ⓘ";

        public CardLabel() { SetStyle(ControlStyles.OptimizedDoubleBuffer | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.ResizeRedraw, true); }

        protected override void OnPaintBackground(PaintEventArgs e)
        {
            var g = e.Graphics;
            g.Clear(Parent != null ? Parent.BackColor : Ui.Bg);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (var p = Ui.Round(new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f), Ui.S(6)))
            {
                using (var b = new SolidBrush(Ui.Panel2)) g.FillPath(b, p);
                using (var pen = new Pen(Color.FromArgb(90, Accent), 1f)) g.DrawPath(pen, p);
            }
            g.SmoothingMode = SmoothingMode.None;
            using (var b = new SolidBrush(Accent)) g.FillRectangle(b, Ui.S(1), Ui.S(6), Math.Max(2, Ui.S(3)), Math.Max(1, Height - Ui.S(12)));
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            if (Mark.Length > 0)
                TextRenderer.DrawText(e.Graphics, Mark, Font, new Rectangle(Ui.S(10), Padding.Top, Padding.Left - Ui.S(10), Font.Height + Ui.S(2)), Accent, TextFormatFlags.Left | TextFormatFlags.Top | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
        }
    }

    /// <summary>A small spinning arc while something runs (the only motion the dialogs have; it stops when hidden).</summary>
    public sealed class BusySpin : Control
    {
        readonly System.Windows.Forms.Timer t = new System.Windows.Forms.Timer();
        float angle;

        public BusySpin()
        {
            SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.SupportsTransparentBackColor, true);
            Size = new Size(Ui.S(18), Ui.S(18));
            t.Interval = 40;
            t.Tick += (s, e) => { angle = (angle + 9f) % 360f; Invalidate(); };
            VisibleChanged += (s, e) => { if (Visible) t.Start(); else t.Stop(); };
        }

        protected override void Dispose(bool disposing) { if (disposing) t.Dispose(); base.Dispose(disposing); }

        protected override void OnPaint(PaintEventArgs e)
        {
            var g = e.Graphics;
            g.Clear(Parent != null ? Parent.BackColor : Ui.Bg);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Ui.Glyph(g, 1, new RectangleF(Ui.S(1), Ui.S(1), Width - Ui.S(3), Height - Ui.S(3)), angle);
        }
    }

    // ------------------------------------------------------------------ dialogs
    public static class Dlg
    {
        public static void Style(Form f, string title)
        {
            f.Text = title;
            f.BackColor = Ui.Bg;
            f.ForeColor = Ui.Text;
            f.Font = Art.UiFont(9.5f, FontStyle.Regular);
            f.FormBorderStyle = FormBorderStyle.FixedDialog;
            f.MaximizeBox = false;
            f.MinimizeBox = false;
            f.ShowInTaskbar = false;
            f.StartPosition = FormStartPosition.CenterParent;
            f.AutoScaleMode = AutoScaleMode.None;
            try { f.Icon = Art.ShieldIcon(32, Art.Shield1, Art.Shield2); } catch (Exception) { }
            Native.DarkTitle(f);
        }

        public static Label Text(string text, float size, FontStyle style, Color c, int maxW)
        {
            return new Label { AutoSize = true, MaximumSize = new Size(maxW, 0), Text = text, ForeColor = c, Font = Art.UiFont(size, style), Margin = new Padding(0, 0, 0, Ui.S(8)) };
        }

        /// <summary>v0.5.5: a section heading (was "■ " + the words in teal): the words in the body colour after a short accent bar; a warning's words keep the warning colour.</summary>
        public static Label Head(string text, float size, Color accent, int maxW)
        {
            return new HeadLabel
            {
                AutoSize = true, MaximumSize = new Size(maxW, 0), Text = text, Accent = accent, ForeColor = accent == Art.Amber1 || accent == Art.Red1 ? accent : Ui.Text,
                Font = Art.UiFont(size, FontStyle.Bold), Padding = new Padding(Ui.S(10), 0, 0, 0), Margin = new Padding(0, Ui.S(2), 0, Ui.S(8)),
            };
        }

        /// <summary>v0.5.5: a note on a card (the reply's ban number, the AI draft's warning): body-colour words, an accent rule and a mark.</summary>
        public static CardLabel Card(string text, float size, Color accent, string mark, int maxW)
        {
            return new CardLabel
            {
                AutoSize = true, MaximumSize = new Size(maxW, 0), Text = text, Accent = accent, Mark = mark ?? "", ForeColor = Ui.Text, Font = Art.UiFont(size, FontStyle.Regular),
                Padding = new Padding(Ui.S(30), Ui.S(8), Ui.S(12), Ui.S(8)), Margin = new Padding(0, Ui.S(4), 0, Ui.S(12)),
            };
        }

        /// <summary>v0.5.5: the 8 px rhythm (24 at the sides, 20 on top).</summary>
        public static FlowLayoutPanel Column()
        {
            return new FlowLayoutPanel { FlowDirection = FlowDirection.TopDown, WrapContents = false, AutoSize = true, AutoSizeMode = AutoSizeMode.GrowAndShrink, Padding = new Padding(Ui.S(24), Ui.S(20), Ui.S(24), Ui.S(18)), BackColor = Ui.Bg, Location = new Point(0, 0) };
        }

        /// <summary>A dialog's button row (right-aligned); v0.5.5: its buttons are at least 36 px tall.</summary>
        public static FlowLayoutPanel Buttons()
        {
            var p = new FlowLayoutPanel { FlowDirection = FlowDirection.LeftToRight, WrapContents = false, AutoSize = true, AutoSizeMode = AutoSizeMode.GrowAndShrink, Anchor = AnchorStyles.Right, Margin = new Padding(0, Ui.S(14), 0, 0), BackColor = Ui.Bg };
            p.ControlAdded += (s, e) => { var b = e.Control as DarkButton; if (b != null) b.MinimumSize = new Size(Math.Max(b.MinimumSize.Width, Ui.S(88)), Ui.S(36)); };
            return p;
        }

        /// <summary>A one-line text box; v0.5.5: its frame and empty-box hint are drawn for the dark theme (<see cref="FieldSkin"/>).</summary>
        public static TextBox Box(int width)
        {
            var t = new TextBox { Width = width, BackColor = Ui.Panel2, ForeColor = Ui.Text, BorderStyle = BorderStyle.FixedSingle };
            FieldSkin.Attach(t);
            return t;
        }

        /// <summary>A drop-down list; v0.5.5: drawn for the dark theme (<see cref="DarkCombo"/>).</summary>
        public static ComboBox Combo(int width)
        {
            return new DarkCombo { Width = width };
        }

        /// <summary>
        /// v0.5.5 every multi-line text of a dialog: a RichTextBox that always wraps (a multi-line TextBox cut Japanese lines
        /// at its right edge: 「…ご了」), plain text only (a paste keeps the words, never the formatting), dark scroll bar.
        /// </summary>
        public static RichTextBox Memo(int width, int height, bool readOnly, float size)
        {
            var r = new RichTextBox
            {
                Width = width, Height = height, Multiline = true, WordWrap = true, ScrollBars = RichTextBoxScrollBars.Vertical, DetectUrls = false,
                ReadOnly = readOnly, BorderStyle = BorderStyle.FixedSingle, HideSelection = false, RightMargin = 0,
                BackColor = readOnly ? Ui.MemoRO : Ui.Panel2, ForeColor = readOnly ? Ui.Muted : Ui.Text,
                Font = Art.RichFont(size, FontStyle.Regular), Margin = new Padding(0, 0, 0, Ui.S(4)),
            };
            try { r.LanguageOption = RichTextBoxLanguageOptions.UIFonts; } catch (Exception) { }
            Native.NoAutoFont(r);
            Native.DarkScroll(r);
            FieldSkin.Attach(r);
            r.KeyDown += (s, e) =>
            {
                if (!((e.Control && e.KeyCode == Keys.V) || (e.Shift && e.KeyCode == Keys.Insert))) return;
                e.Handled = true; e.SuppressKeyPress = true;
                if (r.ReadOnly) return;
                try { if (Clipboard.ContainsText()) r.SelectedText = Clipboard.GetText().Replace("\r\n", "\n"); } catch (Exception) { }
            };
            return r;
        }

        /// <summary>A memo's text with CRLF line ends (for the clipboard).</summary>
        public static string Crlf(string s) { return (s ?? "").Replace("\r\n", "\n").Replace('\r', '\n').Replace("\n", "\r\n"); }

        /// <summary>
        /// The self-test's check that nothing in a dialog can be cut at its right edge: no multi-line TextBox, every
        /// RichTextBox wraps, every longer auto-sized label has a width to wrap at. Returns what is wrong ("" = fine).
        /// </summary>
        public static string ClipRisks(Control root)
        {
            var bad = new List<string>();
            var todo = new Stack<Control>();
            todo.Push(root);
            while (todo.Count > 0)
            {
                var c = todo.Pop();
                foreach (Control ch in c.Controls) todo.Push(ch);
                var tb = c as TextBox;
                if (tb != null && tb.Multiline) bad.Add("multi-line TextBox");
                var rt = c as RichTextBox;
                if (rt != null && (!rt.WordWrap || rt.RightMargin != 0)) bad.Add("RichTextBox without wrap");
                var lb = c as Label;
                if (lb != null && lb.AutoSize && lb.MaximumSize.Width <= 0 && (lb.Text ?? "").Length > 24) bad.Add("label without a wrap width: " + lb.Text.Substring(0, 24));
            }
            return string.Join("; ", bad.ToArray());
        }
    }

    /// <summary>
    /// The double check (2026-09-22 design): the exact statement of what happens, the details, and a Proceed button that
    /// unlocks after <c>seconds</c>. A change for every host is marked in amber.
    /// </summary>
    public sealed class ConfirmDialog : Form
    {
        /// <summary>v0.5.5 review: a bullet starting with this is shown in amber (a warning the author should not skim past).</summary>
        public const string Warn = "⚠ ";
        readonly DarkButton ok;
        readonly Label wait;
        readonly System.Windows.Forms.Timer t = new System.Windows.Forms.Timer();
        readonly Gate gate;
        readonly ComboBox cRule;
        readonly RichTextBox tReason, tOverride;
        readonly Label lCount, lOvrCount;
        readonly CheckBox cMistake;
        readonly List<CheckBox> cMistakeHosts = new List<CheckBox>();
        int left;

        /// <summary>
        /// <paramref name="gate"/> (v0.5.5, may be null): a pasted proposal to show, the evidence's rule to show, or the rule and
        /// the reason to ask (the legitimacy check). Proceed unlocks only after the seconds AND when the gate is satisfied; the
        /// chosen rule and the reason are then written back into the gate.
        /// </summary>
        public ConfirmDialog(string statement, IList<string> bullets, bool global, int seconds, Gate gate)
        {
            this.gate = gate;
            Dlg.Style(this, S.Get("cf.title"));
            int maxW = Ui.S(600);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head((global ? "⚠ " : "") + S.Get(global ? "cf.global" : "cf.local"), 9.5f, global ? Art.Amber1 : Art.Teal1, maxW));
            var st = Dlg.Text(statement, 12f, FontStyle.Bold, Ui.Text, maxW);
            st.Margin = new Padding(0, Ui.S(2), 0, Ui.S(12));
            col.Controls.Add(st);
            if (bullets != null && bullets.Count > 0)
            {
                // v0.5.5 review: a bullet that starts with Warn is shown in amber (in its place: runs of the same colour)
                var sb = new StringBuilder();
                bool runWarn = false;
                foreach (var b in bullets)
                {
                    bool w = b.StartsWith(Warn, StringComparison.Ordinal);
                    if (w != runWarn && sb.Length > 0) { col.Controls.Add(Dlg.Text(sb.ToString(), 9.5f, FontStyle.Regular, runWarn ? Art.Amber1 : Ui.Muted, maxW)); sb.Length = 0; }
                    runWarn = w;
                    if (sb.Length > 0) sb.Append("\n");
                    sb.Append("・").Append(b);
                }
                if (sb.Length > 0) col.Controls.Add(Dlg.Text(sb.ToString(), 9.5f, FontStyle.Regular, runWarn ? Art.Amber1 : Ui.Muted, maxW));
            }
            if (gate != null && gate.Proposal != null)
            {
                var p = gate.Proposal;
                col.Controls.Add(Dlg.Head(S.Get("h.prop"), 9.5f, Ui.Violet, maxW));
                col.Controls.Add(Dlg.Text(S.Get("g.prop", S.Get(p.Kind == "unban" ? "pf.kind.unban" : "pf.kind.share") + " · " + (p.By.Length > 0 ? p.By : "—"),
                    Fmt.LocalUtc(p.At == DateTime.MinValue ? (DateTime?)null : p.At), Proposal.StrengthWord(p.Strength, S.Idx), p.Reason.Length > 0 ? p.Reason : "—"), 9.5f, FontStyle.Regular, Ui.Text, maxW));
            }
            if (gate != null && (gate.NeedRule || gate.NeedReason || gate.AskReason || gate.ShowRule.Length > 0))
            {
                col.Controls.Add(Dlg.Head(S.Get("g.head"), 9.5f, Art.Teal1, maxW));
                if (gate.Note.Length > 0) col.Controls.Add(Dlg.Text(gate.Note, 9.5f, FontStyle.Regular, Art.Amber1, maxW));
                if (gate.ShowRule.Length > 0) col.Controls.Add(Dlg.Text(S.Get("g.shown", gate.ShowRule), 10f, FontStyle.Bold, Art.Green1, maxW));
                if (gate.NeedRule)
                {
                    col.Controls.Add(Dlg.Text(S.Get(string.IsNullOrEmpty(gate.RuleKey) ? "g.rule" : gate.RuleKey), 9.5f, FontStyle.Bold, Ui.Text, maxW));
                    cRule = Dlg.Combo(Ui.S(360));
                    cRule.Items.Add(S.Get("g.pick"));
                    foreach (var r in GateRules.Rules) cRule.Items.Add(r + " — " + S.Get("g." + r));
                    int pre = System.Array.IndexOf(GateRules.Rules, gate.Rule ?? "");
                    cRule.SelectedIndex = pre >= 0 ? pre + 1 : 0;
                    cRule.Margin = new Padding(0, 0, 0, Ui.S(14));   // v0.5.5 review: the same space under a list as under a box
                    cRule.SelectedIndexChanged += (s, e) => Upd();
                    col.Controls.Add(cRule);
                }
                if (gate.NeedReason || gate.AskReason)
                {
                    col.Controls.Add(Dlg.Text(S.Get(gate.NeedReason ? "g.reason" : "g.reason.opt"), 9.5f, FontStyle.Bold, Ui.Text, maxW));
                    tReason = Dlg.Memo(maxW, Ui.S(58), false, 10f);
                    tReason.MaxLength = 500;
                    tReason.Margin = new Padding(0, 0, 0, Ui.S(2));
                    Native.DarkScroll(tReason);
                    tReason.TextChanged += (s, e) => Upd();
                    col.Controls.Add(tReason);
                    lCount = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, maxW);
                    col.Controls.Add(lCount);
                }
            }
            // v0.5.5 (「いいよ」): one host only: the author's own written reason (audit.log: override=, with who and when)
            if (gate != null && gate.Override)
            {
                col.Controls.Add(Dlg.Text("■ " + S.Get("g.ovr.head"), 9f, FontStyle.Bold, Art.Amber1, maxW));
                col.Controls.Add(Dlg.Text(gate.OverrideWhy, 9.5f, FontStyle.Regular, Art.Amber1, maxW));
                col.Controls.Add(Dlg.Text(S.Get("g.ovr.help"), 9f, FontStyle.Regular, Ui.Muted, maxW));   // (v0.5.5 review: not the same question as the reason above)
                tOverride = Dlg.Memo(maxW, Ui.S(58), false, 10f);
                tOverride.MaxLength = 500;
                tOverride.Margin = new Padding(0, 0, 0, Ui.S(2));
                tOverride.TextChanged += (s, e) => Upd();
                col.Controls.Add(tOverride);
                lOvrCount = Dlg.Text("", 8.5f, FontStyle.Regular, Ui.Dim, maxW);
                col.Controls.Add(lOvrCount);
            }
            // v0.5.5 (「いいよ」): lifting a shared ban that imported reports backed: 「誤りだった」 counts against those hosts (Reporters)
            if (gate != null && gate.MistakeHosts != null && gate.MistakeHosts.Count > 0)
            {
                cMistake = new CheckBox { Text = S.Get("g.mistake"), AutoSize = true, ForeColor = Ui.Text, BackColor = Ui.Bg, FlatStyle = FlatStyle.Flat, Font = Art.UiFont(9.5f, FontStyle.Bold), Margin = new Padding(0, Ui.S(4), 0, Ui.S(2)) };
                col.Controls.Add(cMistake);
                col.Controls.Add(Dlg.Text(S.Get("g.mistake.d", string.Join(S.Idx == 2 ? ", " : "、", gate.MistakeHosts.ToArray()), Reporters.WindowDays, Reporters.Threshold), 9f, FontStyle.Regular, Ui.Muted, maxW));
                // v0.5.5 review: more than one host: one box each (ticked with the main box; untick a host that was not wrong)
                if (gate.MistakeHosts.Count > 1)
                    foreach (var h in gate.MistakeHosts)
                    {
                        var cb = new CheckBox { Text = S.Get("g.mistake.one", h), Tag = h, AutoSize = true, Enabled = false, ForeColor = Ui.Text, BackColor = Ui.Bg, FlatStyle = FlatStyle.Flat, Font = Art.UiFont(9f, FontStyle.Regular), Margin = new Padding(Ui.S(22), 0, 0, 0) };
                        cMistakeHosts.Add(cb);
                        col.Controls.Add(cb);
                    }
                cMistake.CheckedChanged += (s, e) => { foreach (var cb in cMistakeHosts) { cb.Enabled = cMistake.Checked; cb.Checked = cMistake.Checked; } };
            }
            left = Math.Max(0, seconds);
            wait = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, maxW);
            col.Controls.Add(wait);
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            ok = new DarkButton(S.Get("b.do")) { Accent = global ? Art.Amber1 : Art.Teal1, Enabled = false };
            ok.Click += (s, e) =>
            {
                if (left > 0 || !GateReady()) return;
                if (gate != null)
                {
                    gate.Rule = ChosenRule(); gate.Reason = ReasonText(); gate.OverrideReason = OverrideText(); gate.Mistake = cMistake != null && cMistake.Checked;
                    gate.MistakeChosen = new List<string>();
                    if (gate.Mistake)
                    {
                        if (cMistakeHosts.Count == 0) gate.MistakeChosen.AddRange(gate.MistakeHosts);
                        else foreach (var cb in cMistakeHosts) if (cb.Checked) gate.MistakeChosen.Add((string)cb.Tag);
                    }
                }
                DialogResult = DialogResult.OK;
                Close();
            };
            btns.Controls.Add(cancel);
            btns.Controls.Add(ok);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true;
            AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
            t.Interval = 1000;
            t.Tick += (s, e) => { left--; Upd(); if (left <= 0) t.Stop(); };
            Shown += (s, e) =>
            {
                Upd();
                if (cRule != null) cRule.Focus(); else if (tReason != null && gate.NeedReason) tReason.Focus(); else cancel.Focus();
                if (left > 0) t.Start();
            };
            FormClosed += (s, e) => t.Dispose();
        }

        /// <summary>The rule in the box ("" while it shows "(choose)": a preset from a pasted proposal counts only while it stays selected); the gate's own rule when there is no box.</summary>
        string ChosenRule() { return GateRules.Picked(cRule != null, cRule != null ? cRule.SelectedIndex : -1, gate != null ? gate.Rule : ""); }
        string ReasonText() { return tReason != null ? Proposal.OneLine(tReason.Text, 500) : ""; }
        string OverrideText() { return tOverride != null ? Proposal.OneLine(tOverride.Text, 500) : ""; }
        bool GateReady() { return gate == null || gate.Ready(ChosenRule(), ReasonText(), OverrideText()); }

        void Upd()
        {
            bool ready = GateReady();
            ok.Enabled = left <= 0 && ready;
            ok.Text = left > 0 ? S.Get("b.wait", left) : S.Get("b.do");
            wait.Text = left > 0 ? S.Get("cf.wait", left) : !ready ? S.Get(gate != null && gate.Override ? "g.need.ovr" : "g.need") : S.Get("cf.ready");
            if (lCount != null)
            {
                int n = GateRules.ReasonLength(tReason.Text);
                lCount.Text = gate.NeedReason ? (n < GateRules.MinReason ? S.Get("pp.short", GateRules.MinReason - n) : "✓ " + n) : "";
                lCount.ForeColor = gate.NeedReason && n < GateRules.MinReason ? Art.Amber1 : Ui.Muted;
            }
            if (lOvrCount != null)
            {
                int n = GateRules.ReasonLength(tOverride.Text);
                lOvrCount.Text = n < GateRules.MinReason ? S.Get("pp.short", GateRules.MinReason - n) : "✓ " + n;
                lOvrCount.ForeColor = n < GateRules.MinReason ? Art.Amber1 : Ui.Dim;
            }
        }
    }

    /// <summary>A message with one OK button (why something was not done).</summary>
