    /// <summary>
    /// Admin mode: makes the proposal text (the proposer's name, the reason of 10+ characters, the rule for circumstantial
    /// evidence), shows it and copies it for the Discord ticket. Nothing else happens.
    /// </summary>
    public sealed class ProposalDialog : Form
    {
        public Proposal Result;
        readonly Proposal draft;
        readonly TextBox tName;
        readonly RichTextBox tReason, tPreview;
        readonly ComboBox cRule;
        readonly Label lNeed;
        readonly DarkButton copy;
        readonly bool needRule;

        public ProposalDialog(Proposal draft, string statement, bool needRule, IList<string> notes)
        {
            this.draft = draft.Clone();
            this.needRule = needRule;
            Dlg.Style(this, S.Get("pp.title"));
            int w = Ui.S(640);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head(S.Get("mode.admin"), 9.5f, Art.Amber1, w));
            var st = Dlg.Text(statement, 12f, FontStyle.Bold, Ui.Text, w);
            st.Margin = new Padding(0, Ui.S(2), 0, Ui.S(8));
            col.Controls.Add(st);
            var sb = new StringBuilder("・" + S.Get("pp.note"));
            if (notes != null) foreach (var n in notes) sb.Append("\n・").Append(n);
            col.Controls.Add(Dlg.Text(sb.ToString(), 9.5f, FontStyle.Regular, Ui.Muted, w));
            col.Controls.Add(Dlg.Text(S.Get("pp.name"), 9.5f, FontStyle.Bold, Ui.Text, w));
            tName = Dlg.Box(Ui.S(300));
            tName.MaxLength = 40;
            tName.Text = Settings.Get("proposer", "");
            tName.Margin = new Padding(0, 0, 0, Ui.S(10));
            col.Controls.Add(tName);
            if (needRule)
            {
                col.Controls.Add(Dlg.Text(S.Get("pp.rule"), 9.5f, FontStyle.Bold, Ui.Text, w));
                cRule = Dlg.Combo(Ui.S(360));
                cRule.Items.Add(S.Get("g.pick"));
                foreach (var r in GateRules.Rules) cRule.Items.Add(r + " — " + S.Get("g." + r));
                int pre = System.Array.IndexOf(GateRules.Rules, draft.Rule ?? "");
                cRule.SelectedIndex = pre >= 0 ? pre + 1 : 0;
                cRule.Margin = new Padding(0, 0, 0, Ui.S(14));   // v0.5.5 review: the same space under a list as under a box
                col.Controls.Add(cRule);
            }
            col.Controls.Add(Dlg.Text(S.Get("pp.reason"), 9.5f, FontStyle.Bold, Ui.Text, w));
            tReason = Dlg.Memo(w, Ui.S(64), false, 10f);
            tReason.MaxLength = 500;
            Native.DarkScroll(tReason);
            col.Controls.Add(tReason);
            lNeed = Dlg.Text("", 9f, FontStyle.Regular, Art.Amber1, w);
            col.Controls.Add(lNeed);
            col.Controls.Add(Dlg.Text(S.Get("pp.preview"), 9f, FontStyle.Bold, Ui.Muted, w));
            tPreview = Dlg.Memo(w, Ui.S(190), true, 9f);
            Native.DarkScroll(tPreview);
            col.Controls.Add(tPreview);
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            copy = new DarkButton(S.Get("b.copyprop")) { Accent = Art.Green1, Enabled = false };
            copy.Click += (s, e) =>
            {
                var p = Current();
                if (!Valid(p)) return;
                try { Clipboard.SetText(Proposal.Clip(p, S.Idx)); }
                catch (Exception ex) { lNeed.Text = ex.Message; App.Log("clipboard: " + ex.Message); return; }
                if (p.By != Settings.Get("proposer", "")) Settings.Set("proposer", p.By);
                Result = p;
                DialogResult = DialogResult.OK;
                Close();
            };
            btns.Controls.Add(cancel);
            btns.Controls.Add(copy);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
            tName.TextChanged += (s, e) => Upd();
            tReason.TextChanged += (s, e) => Upd();
            if (cRule != null) cRule.SelectedIndexChanged += (s, e) => Upd();
            Shown += (s, e) => { Upd(); if (tName.Text.Trim().Length == 0) tName.Focus(); else tReason.Focus(); };
        }

        Proposal Current()
        {
            var p = draft.Clone();
            p.By = Audit.Mask(Proposal.OneLine(tName.Text, 40));
            p.Reason = Audit.Mask(Proposal.OneLine(tReason.Text, 500));
            p.Name = Audit.Mask(p.Name);
            if (cRule != null) p.Rule = cRule.SelectedIndex > 0 ? GateRules.Rules[cRule.SelectedIndex - 1] : "";
            p.At = DateTime.UtcNow;
            return p;
        }

        bool Valid(Proposal p) { return p.By.Length > 0 && GateRules.ReasonOk(p.Reason) && (!needRule || GateRules.IsGate(p.Rule)); }

        void Upd()
        {
            var p = Current();
            tPreview.Text = Proposal.Format(p, S.Idx).Replace("\n", "\r\n");
            copy.Enabled = Valid(p);
            int n = GateRules.ReasonLength(p.Reason);
            lNeed.ForeColor = Valid(p) ? Art.Green1 : Art.Amber1;
            lNeed.Text = p.By.Length == 0 ? S.Get("pp.noname") : n < GateRules.MinReason ? S.Get("pp.short", GateRules.MinReason - n)
                : needRule && !GateRules.IsGate(p.Rule) ? S.Get("pp.norule") : "✓ " + S.Get("pp.ok");
        }
    }

    /// <summary>Owner: a box to paste a proposal into (filled from the clipboard when it holds one). Only the text comes back.</summary>
    public sealed class PasteDialog : Form
    {
        public string Pasted = "";

        public PasteDialog()
        {
            Dlg.Style(this, S.Get("pa.title"));
            int w = Ui.S(640);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Text(S.Get("pa.head"), 9.5f, FontStyle.Regular, Ui.Muted, w));
            var box = Dlg.Memo(w, Ui.S(280), false, 9.5f);
            box.MaxLength = 20000;
            Native.DarkScroll(box);
            try { if (Clipboard.ContainsText()) { string c = Clipboard.GetText(); if (c.IndexOf(Proposal.Marker, StringComparison.OrdinalIgnoreCase) >= 0 && c.Length <= 20000) box.Text = c.Replace("\r\n", "\n").Replace("\n", "\r\n"); } }
            catch (Exception) { }
            col.Controls.Add(box);
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            var read = new DarkButton(S.Get("b.read")) { Accent = Ui.Violet };
            read.Click += (s, e) => { Pasted = box.Text; DialogResult = DialogResult.OK; Close(); };
            btns.Controls.Add(cancel);
            btns.Controls.Add(read);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
            Shown += (s, e) => box.Focus();
        }
    }

    /// <summary>Chooses a ban length: the same as now (optional), 30 / 180 days, permanent or N days. <see cref="Days"/>: -1 same, 0 permanent, N.</summary>
    public sealed class PeriodDialog : Form
    {
        public int Days = -2;
        readonly RadioButton rSame, r30, r180, rPerm, rCustom;
        // v0.5.5 review: the days in a dark text box (Windows drew the spin box's arrows and frame light grey): digits only,
        // ↑ / ↓ step by one, kept between 1 and the most allowed (an empty or wrong entry keeps the last good number)
        readonly TextBox num;
        int numVal = 7, numMax = 3650;
        readonly Label result;
        readonly DateTime from;
        readonly DateTime? sameEnd;

        public PeriodDialog(string head, DateTime fromUtc, bool offerSame, DateTime? sameEndUtc, int defDays) : this(head, fromUtc, offerSame, sameEndUtc, defDays, 0) { }

        /// <summary>v0.5.5 <paramref name="capDays"/> &gt; 0: at most that many days (a shared ban on imported records only): 180 days and permanent are not offered.</summary>
        public PeriodDialog(string head, DateTime fromUtc, bool offerSame, DateTime? sameEndUtc, int defDays, int capDays)
        {
            Dlg.Style(this, S.Get("pd.title"));
            if (capDays > 0)
            {
                if (offerSame && (sameEndUtc == null || sameEndUtc.Value > fromUtc.AddDays(capDays))) offerSame = false;
                if (defDays <= 0 || defDays > capDays) defDays = Math.Min(30, capDays);
            }
            from = fromUtc; sameEnd = sameEndUtc;
            int maxW = Ui.S(460);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Text(head, 10.5f, FontStyle.Bold, Ui.Text, maxW));
            // v0.5.5 review: the choices drawn for the dark theme (Windows drew white circles and its blue dot): DarkRadio
            Func<string, RadioButton> radio = text => new DarkRadio { Text = text, Margin = new Padding(Ui.S(2), Ui.S(2), 0, Ui.S(4)) };
            rSame = radio(S.Get("pd.same", Fmt.UntilText(sameEndUtc, S.Idx)));
            r30 = radio(S.Get("pd.30"));
            r180 = radio(S.Get("pd.180"));
            rPerm = radio(S.Get("pd.perm"));
            rCustom = radio(S.Get("pd.custom"));
            num = Dlg.Box(Ui.S(90));
            num.Name = "days";
            num.MaxLength = 4;
            num.Text = numVal.ToString(CultureInfo.InvariantCulture);
            num.Margin = new Padding(Ui.S(30), 0, 0, Ui.S(6));
            num.KeyPress += (s, e) => { if (!char.IsControl(e.KeyChar) && (e.KeyChar < '0' || e.KeyChar > '9')) e.Handled = true; };
            num.KeyDown += (s, e) =>
            {
                if (e.KeyCode != Keys.Up && e.KeyCode != Keys.Down) return;
                e.Handled = true;
                SetNum(numVal + (e.KeyCode == Keys.Up ? 1 : -1));
            };
            num.Leave += (s, e) => SetNum(numVal);
            if (offerSame) col.Controls.Add(rSame);
            col.Controls.Add(r30); col.Controls.Add(r180); col.Controls.Add(rPerm); col.Controls.Add(rCustom); col.Controls.Add(num);
            if (capDays > 0)
            {
                r180.Visible = false; rPerm.Visible = false;
                numMax = capDays;
                col.Controls.Add(Dlg.Text(S.Get("pd.cap"), 9f, FontStyle.Regular, Art.Amber1, maxW));
            }
            result = Dlg.Text("", 10f, FontStyle.Bold, Ui.Text, maxW);
            result.Margin = new Padding(0, Ui.S(8), 0, Ui.S(4));
            col.Controls.Add(result);
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            var ok = new DarkButton(S.Get("b.ok"));
            ok.Click += (s, e) => { Days = Chosen(); DialogResult = DialogResult.OK; Close(); };
            btns.Controls.Add(cancel); btns.Controls.Add(ok);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel; AcceptButton = ok;
            if (offerSame) rSame.Checked = true;
            else if (defDays == 30) r30.Checked = true;
            else if (defDays == 180) r180.Checked = true;
            else if (defDays == 0) rPerm.Checked = true;
            else { rCustom.Checked = true; SetNum(defDays); }
            foreach (var r in new[] { rSame, r30, r180, rPerm, rCustom }) r.CheckedChanged += (s, e) => Upd();
            num.TextChanged += (s, e) =>
            {
                if (setting) return;
                int v;
                if (int.TryParse(num.Text, NumberStyles.None, CultureInfo.InvariantCulture, out v)) numVal = Math.Max(1, Math.Min(numMax, v));
                if (!rCustom.Checked) rCustom.Checked = true;
                Upd();
            };
            Upd();
        }

        bool setting;

        /// <summary>The days box: <paramref name="v"/> kept between 1 and the most allowed, and written back.</summary>
        void SetNum(int v)
        {
            numVal = Math.Max(1, Math.Min(numMax, v));
            setting = true;
            try { num.Text = numVal.ToString(CultureInfo.InvariantCulture); num.SelectionStart = num.Text.Length; }
            finally { setting = false; }
            Upd();
        }

        /// <summary>The choice now (the self-test): -1 same, 0 permanent, N days.</summary>
        public int ChosenDays { get { return Chosen(); } }

        int Chosen()
        {
            if (rSame.Checked) return -1;
            if (r30.Checked) return 30;
            if (r180.Checked) return 180;
            if (rPerm.Checked) return 0;
            return numVal;
        }

        /// <summary>When a choice ends (null = permanent).</summary>
        public DateTime? EndFor(int days) { return days == -1 ? sameEnd : days == 0 ? (DateTime?)null : from.AddDays(days); }

        void Upd()
        {
            int d = Chosen();
            var end = EndFor(d);
            num.Enabled = rCustom.Checked;
            bool past = end != null && end.Value <= DateTime.UtcNow;
            result.ForeColor = past ? Art.Amber1 : Ui.Text;
            result.Text = S.Get("pd.result", Fmt.UntilText(end, S.Idx)) + (past ? "\n" + S.Get("cf.p.past") : "");
        }
    }

    /// <summary>
    /// v0.5.5 replies to an appeal (ja / zh / en × need info / accept / reject; <see cref="Replies"/>): the ban's number
    /// (found from the selected ban, <see cref="Replies.FieldsOf"/>, and filled into the body and the subject; the line
    /// says where it came from, or that none is known; "need more info" never names it), the addressee (2026-09-22
    /// 「なまえわかるのに」: the name the person used in their message; v0.5.5 review: the recorded game name is filled in for
    /// 「受け入れる」「受け入れない」 only, until the author types (「情報が足りない」 goes out before the person is confirmed,
    /// and asks for the name they were banned under); the hint says where the name came from and that 「さま」 is added; a
    /// recorded name that is empty or hits the NG list is never filled in; empty, the reply starts without a name), the
    /// staff name (Settings), a suggested e-mail subject and the body, each with its copy button. Every text wraps
    /// (<see cref="Dlg.Memo"/>).
