        readonly FlowLayoutPanel col, foot, theirsPanel, aiRow;
        readonly Panel scroller;
        readonly Padding colPad;
        readonly System.Windows.Forms.Timer aiTick = new System.Windows.Forms.Timer();
        readonly ReplyFields fields;
        readonly bool ngHit, aiShown, theirsAllowed;
        readonly string recName, rawName;
        readonly int bodyH, bodyMin;
        IReplyDrafter drafter, running;
        bool typed, filling, drafted, busy, theirsOpen, fitting;
        string kind = "info", template = "", confirmed = "";
        int gen;
        DateTime started;

        /// <summary>The self-test's and the screenshots' screen (null = the real one): <see cref="Fit"/> fits the dialog to this working area.</summary>
        public static Rectangle? TestWorkArea;
        /// <summary>Asked before a request with their message first goes out (true = send); null: <see cref="AiSendDialog.Confirm"/>. The self-test sets it.</summary>
