        public ReplyDialog(string gameName, ReplyFields f, NgNames ng, Action<string> copied)
        {
            Dlg.Style(this, S.Get("rp.title"));
            // v0.5.5 review (a laptop screen: 826 px high at 125%): the fields scroll, the note and the buttons stay at the bottom,
            // the body takes the height the window has; the window can be made taller or shorter (not wider)
            FormBorderStyle = FormBorderStyle.Sizable;
            MaximizeBox = false; MinimizeBox = false; SizeGripStyle = SizeGripStyle.Show;
            fields = f ?? new ReplyFields();
            drafter = Drafters.Current;
            string dwhy;
            // v0.5.5 review: an admin's PC (no key there) with no support-desk server shows no AI part at all
            aiShown = App.KeySignal || drafter.Ready(out dwhy);
            // their message: off until the owner turns it on in the AI settings (the privacy policy 3.5 5, D-04)
