            lang.SelectedIndex = S.Idx;
            top.Controls.Add(ll); top.Controls.Add(lang);
            col.Controls.Add(top);
            // v0.5.5 (2026-09-22 readability): the three kinds as one segmented control (the chosen one filled teal; the words say which)
            var kinds = new FlowLayoutPanel { AutoSize = true, WrapContents = false, BackColor = Ui.Bg, Margin = new Padding(0, 0, 0, Ui.S(2)) };
            kInfo = new DarkButton(S.Get("rp.info")) { Seg = 1 };
