            kinds.Controls.Add(kInfo); kinds.Controls.Add(kAccept); kinds.Controls.Add(kReject);
            col.Controls.Add(kinds);
            // the ban's number: found, never typed (where it came from; none known: left out of the mail, said here only;
            // what it says depends on the kind: Fill). v0.5.5: on a card in the body colour (was two lines of cyan)
            bool hasId = Replies.IdText(S.Idx, fields).Length > 0;
            lId = Dlg.Card("", 9.5f, hasId ? Art.Teal1 : Art.Amber1, hasId ? "ⓘ" : "⚠", w);
