            recName = Replies.Addressee(gameName, ng, out hit);   // "" when there is none or it hits the NG list; filled in by Fill for accept / reject
            ngHit = hit;
            col.Controls.Add(tTo);
            lHint = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, w);
