            aiRow.Controls.Add(bAi); aiRow.Controls.Add(spin); aiRow.Controls.Add(bAiStop); aiRow.Controls.Add(bAiRevert); aiRow.Controls.Add(bWhat);
            if (App.KeySignal)
            {
                var bSet = new DarkButton(AiText.Get("ai.settings")) { Name = "aiSettings" };
