            Controls.Add(scroller);
            Controls.Add(foot);   // docked first (the last one added): the bottom; the scroller takes the rest
            Native.DarkScroll(scroller);
            // the subject's copy button as tall as the box beside it (the two read as one field)
            copySubj.AutoSize = false;
            copySubj.MinimumSize = new Size(Ui.S(64), 0);
            copySubj.Size = new Size(Math.Max(Ui.S(64), copySubj.GetPreferredSize(Size.Empty).Width), tSubject.Height);
            CancelButton = close;
            ActiveControl = tTo;   // v0.5.5 review: the dialog opens on the addressee (was the language list, with its focus frame)
            lNg.Text = ngHit ? S.Get("rp.ngname") : "";
            lang.SelectedIndexChanged += (s, e) => Fill();
            tTo.TextChanged += (s, e) => { if (filling) return; typed = true; Fill(); };   // a typed name gives 「名前 さま」 at once, and stays
            tStaff.TextChanged += (s, e) => Fill();
            scroller.Resize += (s, e) => LayoutBody();
            aiTick.Interval = 250;
            aiTick.Tick += (s, e) => { if (busy) SetStatus(AiText.Get("ai.busy", (int)(DateTime.UtcNow - started).TotalSeconds), Ui.Muted); };
            FormClosing += (s, e) => StopDraft(false);
            Fill();
            UpdateAi();
        }

        static Label FieldLabel(string text, int w)
        {
            var l = Dlg.Text(text, 9.5f, FontStyle.Bold, Ui.Text, w);
            l.Margin = new Padding(0, 0, 0, Ui.S(4));
            return l;
        }

        protected override void OnLoad(EventArgs e) { base.OnLoad(e); Fit(); }
        protected override void OnShown(EventArgs e) { base.OnShown(e); KeepOrder(); KeepOnScreen(); }

        protected override void Dispose(bool disposing)
        {
            if (disposing) { try { StopDraft(false); } catch (Exception) { } aiTick.Dispose(); }
            base.Dispose(disposing);
        }

        Rectangle WorkArea()
        {
            if (TestWorkArea != null) return TestWorkArea.Value;
            try { return Screen.FromControl(Owner != null ? (Control)Owner : this).WorkingArea; }
            catch (Exception) { return new Rectangle(0, 0, 1920, 1040); }
        }

        /// <summary>
        /// v0.5.5 review: the window's size for what it shows now: as tall as the fields, the body (its usual height) and the
        /// foot need, never taller than the screen's working area (then the fields scroll and the body keeps at least
        /// 200 px); the width is fixed. Called when it opens, when their message is shown or hidden, and when a draft comes.
        /// </summary>
        public void Fit()
        {
            if (fitting) return;
            fitting = true;
            try
            {
                var wa = WorkArea();
                box.Height = bodyH;
                col.Padding = colPad;
                var pref = col.GetPreferredSize(Size.Empty);
                int natural = pref.Height + foot.GetPreferredSize(new Size(pref.Width, 0)).Height;
                int chrome = Height - ClientSize.Height;
                int maxH = Math.Max(Ui.S(360), wa.Height - Ui.S(16) - chrome);
                MinimumSize = Size.Empty;
                MaximumSize = Size.Empty;
                ClientSize = new Size(pref.Width, Math.Min(natural, maxH));
                // only the height can change: between a short window (the fields scroll) and the working area
                MaximumSize = new Size(Width, Math.Max(Height, wa.Height));
                MinimumSize = new Size(Width, Math.Min(Height, Ui.S(420) + chrome));
            }
            finally { fitting = false; }
            PerformLayout();
            LayoutBody();
            KeepOnScreen();
        }

        void KeepOnScreen()
        {
            if (!Visible) return;
            var wa = WorkArea();
            if (Bottom > wa.Bottom) Top = Math.Max(wa.Top, wa.Bottom - Height);
        }

        /// <summary>The body takes the height left over (at least 200 px); when even that does not fit, the fields above it scroll.</summary>
        void LayoutBody()
        {
            if (fitting || scroller == null) return;
            fitting = true;
            try
            {
                col.Padding = colPad;
                int other = col.GetPreferredSize(Size.Empty).Height - box.Height;
                int avail = scroller.ClientSize.Height;
                int h = Math.Max(bodyMin, avail - other);
                // scrolling: the scroll bar takes the right margin (no sideways scroll bar)
                if (other + h > avail) col.Padding = new Padding(colPad.Left, colPad.Top, Math.Max(Ui.S(4), colPad.Right - SystemInformation.VerticalScrollBarWidth), colPad.Bottom);
                if (box.Height != h) box.Height = h;
            }
            finally { fitting = false; }
        }

        /// <summary>The self-test: the foot (the note and the buttons) inside the window, and how tall the body is.</summary>
        public bool FootInside { get { return foot.Bottom <= ClientSize.Height && foot.Top >= 0 && foot.Height > 0; } }
        public int BodyHeight { get { return box.Height; } }

        /// <summary>Their message shown (only when the owner turned it on): the toggle; the self-test sets it.</summary>
        public bool TheirsOpen
        {
            get { return theirsOpen; }
            set { if (value != theirsOpen && (theirsAllowed || !value)) ToggleTheirs(); }
        }

        void ToggleTheirs()
        {
            theirsOpen = !theirsOpen;
            theirsPanel.Visible = theirsOpen;
            bTheirs.Text = (theirsOpen ? "▾ " : "▸ ") + AiText.Get("ai.theirs");
            Fit();
            if (theirsOpen) { scroller.ScrollControlIntoView(theirs); theirs.Focus(); }
        }

        /// <summary>Shows the reply of one kind ("info" / "accept" / "reject"): the kind buttons call it.</summary>
        public void SetKind(string k)
        {
            kind = k == "accept" || k == "reject" ? k : "info";
            Fill();
        }

        /// <summary>How a reply in the chosen language starts without a name (the hint says it).</summary>
        static string StartText(int idx)
        {
            string plain = S.In(idx, "rt.greet.anon");
            return plain.Length == 0 ? S.Get("rp.start.none") : S.Get("rp.start.plain", plain);
        }

        /// <summary>
        /// The ban's number line for this kind (the body and the subject of accept / reject name it; "need more info" never
        /// does, so its unknown date is not mentioned either) and the hint under the addressee (where a filled-in name came
        /// from, the word the greeting adds, how the reply starts without a name).
        /// </summary>
        void Notes(int idx)
        {
            string idText = Replies.IdText(S.Idx, fields);
            string from = S.Get("rp.id." + (fields.IdFrom.Length > 0 && S.Has("rp.id." + fields.IdFrom) ? fields.IdFrom : "entry"));
            var idLines = new List<string>();
            idLines.Add(idText.Length == 0 ? S.Get("rp.noid") : S.Get(kind == "info" ? "rp.id.info" : "rp.id", idText, from));
            if (kind != "info" && (fields.Since == null || fields.Since.Value == DateTime.MinValue)) idLines.Add(S.Get("rp.nodate"));
            lId.Text = string.Join("\n", idLines.ToArray());
            string auto = S.Get("rp.to.auto", Replies.GreetWord(idx)), start = StartText(idx);
            if (recName.Length == 0) lHint.Text = S.Get("rp.to.hint", auto, start);
            else if (kind == "info") lHint.Text = S.Get("rp.to.hint.info", auto, start, recName);
            else lHint.Text = S.Get("rp.to.hint.rec", auto, start);
        }

        ReplyFields Current()
        {
            return new ReplyFields { To = tTo.Text, Staff = tStaff.Text, Id = fields.Id, Line = fields.Line, IdFrom = fields.IdFrom, Shared = fields.Shared, Rule = fields.Rule, Since = fields.Since, End = fields.End, Now = fields.Now };
        }

        void Fill()
        {
            int idx = Math.Max(0, lang.SelectedIndex);
            kAccept.Active = kind == "accept"; kReject.Active = kind == "reject"; kInfo.Active = kind == "info";
            // the recorded name: filled in for accept / reject (the person is confirmed by then), never for "need more info";
            // once the author types, the box is theirs
            if (!typed && tTo.Text != (kind == "info" ? "" : recName))
            {
                filling = true;
                try { tTo.Text = kind == "info" ? "" : recName; }
                finally { filling = false; }
            }
            Notes(idx);
            // v0.5.5 AI: any change of the kind, the language, the addressee or the staff name makes a new template; a draft
            // (or one being made: dropped, and said so) was for the old one, so the body goes back to the template
            bool wasBusy = busy;
            if (busy) StopDraft(false);
            gen++;
            bool had = drafted;
            drafted = false;
            if (aiNote != null) { aiNote.Visible = false; bAiRevert.Visible = false; }
            var f = Current();
            template = Replies.Body(idx, kind, f);
            box.Text = template;
            ClearMarks();
            tSubject.Text = Replies.Subject(idx, kind, f);
            if (wasBusy) SetStatus(AiText.Get("ai.dropped"), Ui.Muted);
            else if (had) SetStatus(AiText.Get("ai.reverted"), Ui.Muted);
            if (had) LayoutBody();
        }

        // ---- v0.5.5 the AI draft

        /// <summary>The generation of the text shown: a draft asked for an older one is dropped (<see cref="ApplyDraft"/>).</summary>
        public int Generation { get { return gen; } }
        public bool Drafted { get { return drafted; } }
        public bool Busy { get { return busy; } }

        void SetStatus(string text, Color c)
        {
            if (aiStatus == null) return;
            aiStatus.Text = text ?? "";
            aiStatus.ForeColor = c;
        }

        /// <summary>
        /// v0.5.5 review: a draft with the author's key sends data and spends the author's credit, so it needs the unlock as the
        /// author (like the AI settings; the 4-digit code is not enough); the support-desk server later: any unlock (its staff
        /// login is its own check).
        /// </summary>
        bool MayDraft() { return drafter.Name == "desk" ? Session.Unlocked : Session.OwnerActive; }

        /// <summary>The AI button and its line: ready (this month's use), no key, locked, not unlocked as the author.</summary>
        public void UpdateAi()
        {
            if (busy || !aiShown) return;
            string why;
            bool ready = drafter.Ready(out why), may = MayDraft();
            bAi.Enabled = ready && may;
            if (!ready) SetStatus(why == "nokey" ? AiText.Get(App.KeySignal ? "ai.nokey.owner" : "ai.nokey.admin") : AiText.Get(AiText.Has("ai." + why) ? "ai." + why : "ai.e.nokey"), Ui.Muted);
            else if (!Session.Unlocked) SetStatus(AiText.Get("ai.locked"), Ui.Muted);
            else if (!may) SetStatus(AiText.Get("ai.owneronly"), Ui.Muted);
            else if (!drafted) SetStatus(AiSpend.Text(S.Idx, DateTime.UtcNow), Ui.Muted);
        }

        void SetBusy(bool on)
        {
            spin.Visible = on;
            bAiStop.Visible = on;
            if (on) { bAi.Enabled = false; started = DateTime.UtcNow; SetStatus(AiText.Get("ai.busy", 0), Ui.Muted); aiTick.Start(); }
            else { aiTick.Stop(); UpdateAi(); }
        }

        /// <summary>
        /// The request for what the dialog shows now (the kind, the language, the template, their message when the owner turned
        /// it on and it is open), without starting a draft (「送る内容」 shows it word for word). The addressee and the staff name
        /// stay on this PC as typed: the template is made with the placeholders NAME_1 / STAFF_1 and the names are put back
        /// when the draft comes (<see cref="DraftRequest.Restore"/>); in their message the addressee, the recorded name and the
        /// staff name become the placeholders too. The request holds nothing else (<see cref="DraftRequest"/>).
        /// </summary>
        public DraftRequest BuildRequest()
        {
            int idx = Math.Max(0, lang.SelectedIndex);
            string to = Proposal.OneLine(tTo.Text, 60), staff = Proposal.OneLine(tStaff.Text, 40);
            var ph = Current();
            ph.To = to.Length > 0 ? DraftRequest.NameToken : "";
            ph.Staff = staff.Length > 0 ? DraftRequest.StaffToken : "";
            var names = new List<string> { to, recName, rawName };
            var staffNames = new List<string> { staff, Proposal.OneLine(Settings.Get("staff", ""), 40) };
            var req = DraftRequest.FromDialog(kind, idx, ph.To, fields, Replies.Body(idx, kind, ph), theirsAllowed && theirsOpen ? theirs.Text : "", names, staffNames);
            req.LocalTo = to;
            req.LocalStaff = staff;
            return req;
        }

        /// <summary>The request (<see cref="BuildRequest"/>) and a new generation (a draft asked for before is dropped).</summary>
        public int PrepareDraft(out DraftRequest req)
        {
            req = BuildRequest();
            return ++gen;
        }

        /// <summary>「AI で返事の案を作る」: the request on a worker; its result comes back through <see cref="ApplyDraft"/>.</summary>
        public void StartDraft()
        {
            if (busy || !aiShown) return;
            string why;
            if (!MayDraft() || !drafter.Ready(out why)) { UpdateAi(); return; }
            Session.Touch();
            var req = BuildRequest();
            // their message: shown word for word before it first goes out; nothing is sent when staff say no
            if (req.Theirs.Length > 0 && req.Theirs != confirmed)
            {
                bool ok = ConfirmSend != null ? ConfirmSend(req) : AiSendDialog.Confirm(this, req);
                if (!ok) { SetStatus(AiText.Get("ai.notsent"), Ui.Muted); return; }
                confirmed = req.Theirs;
            }
            int g = ++gen;
            App.Log("ai draft asked unlock=" + Session.Mode + "/" + Session.Method + " kind=" + req.Kind + " theirs=" + (req.Theirs.Length > 0 ? "yes" : "no"));
            var d = drafter is AnthropicDrafter ? Drafters.Current : drafter;   // a fresh one per draft (its stop only stops this draft)
            running = d;
            busy = true;
            SetBusy(true);
            var t = new Thread(() =>
            {
                DraftResult res;
                try { res = d.Draft(req); }
                catch (Exception ex) { App.Log("ai draft failed: " + ex.GetType().Name); res = DraftResult.Fail("network", ""); }
                if (res == null) res = DraftResult.Fail("badreply", "");
                Action done = () => { AiSpend.Add(res.Model.Length > 0 ? res.Model : Drafters.Model, res.InTokens, res.OutTokens, DateTime.UtcNow); ApplyDraft(res, g, req); };
                try { BeginInvoke(done); }
                catch (Exception) { AiSpend.Add(res.Model.Length > 0 ? res.Model : Drafters.Model, res.InTokens, res.OutTokens, DateTime.UtcNow); }   // closed meanwhile: the use still counts
            });
            t.IsBackground = true;
            t.Start();
        }

        /// <summary>「やめる」.</summary>
        public void Stop() { StopDraft(true); }

        void StopDraft(bool user)
        {
            if (!busy) return;
            gen++;
            busy = false;
            try { if (running != null) running.Cancel(); } catch (Exception) { }
            running = null;
            if (IsDisposed) return;
            SetBusy(false);
            if (user) SetStatus(AiText.Get("ai.stopped"), Ui.Muted);
        }

        /// <summary>
        /// A draft's result for generation <paramref name="g"/>: dropped (false) when anything changed since it was asked for
        /// (the kind, the language, the addressee, the staff name; a stop; the dialog closed). An error is said on the AI line;
        /// a draft that fails <see cref="AiCheck"/> is not used; otherwise the body becomes the draft with 「AI の案です…」,
        /// 「元の文に戻す」 and the lines the AI wrote highlighted (the subject stays the template's). Nothing is sent anywhere
        /// by this dialog.
        /// </summary>
        public bool ApplyDraft(DraftResult r, int g, DraftRequest req)
        {
            if (IsDisposed || g != gen) return false;
            bool wasBusy = busy;
            busy = false;
            running = null;
            if (wasBusy) SetBusy(false);
            if (r == null || !r.Ok) { SetStatus("✕ " + (r ?? DraftResult.Fail("badreply", "")).Message(S.Idx), Art.Red1); return false; }
            string bad = AiCheck.Why(req, r.Text);
            if (bad.Length > 0)
            {
                App.Log("ai draft not used: check=" + bad);
                SetStatus("✕ " + new DraftResult { Error = "check", Detail = bad }.Message(S.Idx), Art.Red1);
                return false;
            }
            box.Text = req.Restore(AiCheck.Clean(r.Text));   // the names back in place of NAME_1 / STAFF_1 (and BANID_1)
            MarkChanges();
            drafted = true;
            KeepOrder();
            aiNote.Visible = true;
            bAiRevert.Visible = true;
            int secs = Math.Max(1, (int)Math.Round((DateTime.UtcNow - started).TotalSeconds));
            SetStatus(AiText.Get("ai.done", wasBusy ? secs : 0) + "  ·  " + AiSpend.Text(S.Idx, DateTime.UtcNow), Ui.Muted);
            Fit();
            // on a low screen the fields above scroll away: the whole draft (the text to read before sending) and its note in view
            scroller.ScrollControlIntoView(box);
            scroller.ScrollControlIntoView(aiNote);
            return true;
        }

        /// <summary>v0.5.5 review: the lines the AI wrote (not word for word in the template) on the highlight colour, so staff see what to check.</summary>
        void MarkChanges()
        {
            try
            {
                var same = new HashSet<string>(StringComparer.Ordinal);
                foreach (var l in template.Replace("\r\n", "\n").Split('\n')) same.Add(l.Trim());
                int pos = 0;
                marked = 0;
                // (the formatting only once the box exists on screen: making its window early would reorder the dialog's controls)
                bool paint = box.IsHandleCreated;
                foreach (var l in box.Text.Split('\n'))
                {
                    if (l.Trim().Length > 0 && !same.Contains(l.Trim())) { if (paint) { box.Select(pos, l.Length); box.SelectionBackColor = Ui.Hit; } marked++; }
                    pos += l.Length + 1;
                }
                if (paint) box.Select(0, 0);
            }
            catch (Exception) { }
        }

        int marked;

        /// <summary>How many lines carry the highlight (the self-test).</summary>
        public int MarkedLines { get { return marked; } }

        void ClearMarks()
        {
            marked = 0;
            if (!box.IsHandleCreated) return;   // (no window yet: no formatting to clear)
            try { box.SelectAll(); box.SelectionBackColor = box.BackColor; box.Select(0, 0); } catch (Exception) { }
        }

        /// <summary>The draft's warning card right above the body (a hidden control can end up after it when the windows are made).</summary>
        void KeepOrder()
        {
            int b = col.Controls.GetChildIndex(box), n = col.Controls.GetChildIndex(aiNote);
            if (n > b) col.Controls.SetChildIndex(aiNote, b);
        }

        /// <summary>「元の文に戻す」: the template again (exactly what the kind, the language, the addressee and the staff name make).</summary>
        public void Revert(bool manual)
        {
            drafted = false;
            Fill();
            if (manual) SetStatus(AiText.Get("ai.reverted.manual"), Ui.Muted);
        }
    }

    /// <summary>
    /// v0.5.5 review: what a draft sends, word for word: 「送る内容」 (to look at) and the check before their message first goes
    /// out (send / do not send; Esc and ✕ never send). What is sent, what is not and what happens afterwards, then the exact
    /// request text for what the reply dialog shows now (the fixed instructions to the AI go with it; they hold nothing
    /// about the person).
    /// </summary>
    public sealed class AiSendDialog : Form
    {
        public AiSendDialog(DraftRequest req, bool asking)
        {
            Dlg.Style(this, AiText.Get("ai.what"));
            int w = Ui.S(600);
            var col = Dlg.Column();
            if (asking) col.Controls.Add(Dlg.Head("⚠ " + AiText.Get("ai.ask.head"), 11f, Art.Amber1, w));
            AiSettingsDialog.Privacy(col, w);
            var lb = Dlg.Text(AiText.Get("ai.exact"), 9.5f, FontStyle.Bold, Ui.Text, w);
            lb.Margin = new Padding(0, Ui.S(4), 0, Ui.S(4));
            col.Controls.Add(lb);
            var memo = Dlg.Memo(w, Ui.S(170), true, 9.5f);
            memo.Name = "payload";
            memo.Text = req != null ? req.ToPromptText() : "";
            col.Controls.Add(memo);
            var btns = Dlg.Buttons();
            if (asking)
            {
                var no = new DarkButton(AiText.Get("ai.ask.no")) { DialogResult = DialogResult.Cancel, Name = "no" };
                var yes = new DarkButton(AiText.Get("ai.ask.yes")) { DialogResult = DialogResult.OK, Primary = true, Name = "send" };
                btns.Controls.Add(no); btns.Controls.Add(yes);
                CancelButton = no;
            }
            else
            {
                var close = new DarkButton(S.Get("b.close")) { DialogResult = DialogResult.Cancel, Name = "close" };
                btns.Controls.Add(close);
                CancelButton = close;
            }
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            ActiveControl = (Control)CancelButton;   // the keyboard starts on 「送らない」 / 「閉じる」 (Enter never sends by accident)
        }

        /// <summary>Asks before their message first goes out: true only for 「送って案を作る」.</summary>
        public static bool Confirm(IWin32Window owner, DraftRequest req)
        {
            using (var d = new AiSendDialog(req, true)) return d.ShowDialog(owner) == DialogResult.OK;
        }
    }

    /// <summary>
    /// v0.5.5 the AI settings (the author's PC, unlocked as the author only): the API key typed once (hidden while typed,
    /// kept with Windows DPAPI for this Windows user: <see cref="AiKey"/>; never shown again, not even its last letters; a
    /// delete button), the model (default claude-sonnet-5), the time to wait (15–180 s), a free check (GET /v1/models/{model}),
    /// whether 「相手の文を貼る」 is shown (off until D-04), this month's use, and what is sent. The key is cleared from the
    /// box once saved.
    /// </summary>
    public sealed class AiSettingsDialog : Form
    {
        readonly TextBox tKey, tModel;
        readonly ComboBox nTimeout;
        static readonly int[] Waits = { 15, 30, 45, 60, 90, 120, 180 };
        readonly Label lKey, lResult;
        readonly DarkButton bDelete, bTest;
        readonly DarkCheck cTheirs;
        bool testing;

        /// <summary>Why the settings cannot open now ("" = they can): not the author's PC, or not unlocked as the author.</summary>
        public static string Blocked() { return !App.KeySignal ? AiText.Get("ai.nokey.admin") : !Session.OwnerActive ? AiText.Get("as.owneronly") : ""; }

        /// <summary>Opens the settings, or says why they cannot open.</summary>
        public static void Open(IWin32Window owner)
        {
            string why = Blocked();
            if (why.Length > 0) { using (var n = new NoticeDialog(AiText.Get("as.title"), why, Art.Amber1)) n.ShowDialog(owner); return; }
            using (var d = new AiSettingsDialog()) d.ShowDialog(owner);
        }

        /// <summary>v0.5.5 review: what is sent, in three parts at a readable size (was one 9 pt paragraph): sent, not sent, afterwards.</summary>
        public static void Privacy(Control col, int w)
        {
            var card = Dlg.Card(AiText.Get("ai.p.when"), 9.5f, Art.Teal1, "ⓘ", w);
            card.Margin = new Padding(0, Ui.S(2), 0, Ui.S(12));
            col.Controls.Add(card);
            foreach (var k in new[] { "sent", "notsent", "after" })
            {
                var h = Dlg.Text(AiText.Get("ai.p.h." + k), 9.5f, FontStyle.Bold, Ui.Text, w);
                h.Margin = new Padding(0, 0, 0, Ui.S(2));
                col.Controls.Add(h);
                var t = Dlg.Text(AiText.Get("ai.p." + k), 9.5f, FontStyle.Regular, Ui.Muted, w);
                t.Margin = new Padding(0, 0, 0, Ui.S(10));
                col.Controls.Add(t);
            }
        }

        static string KeyState()
        {
            var at = AiKey.SavedAt;
            return at == DateTime.MinValue ? AiText.Get("as.key.none") : AiText.Get("as.key.saved", Fmt.Local(at));
        }

        public AiSettingsDialog()
        {
            Dlg.Style(this, AiText.Get("as.title"));
            int w = Ui.S(560);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head(AiText.Get("as.head"), 11f, Art.Teal1, w));
            Privacy(col, w);
            var lk = Dlg.Text(AiText.Get("as.key"), 9.5f, FontStyle.Bold, Ui.Text, w);
            lk.Margin = new Padding(0, Ui.S(4), 0, Ui.S(4));
            col.Controls.Add(lk);
            var keyRow = new FlowLayoutPanel { AutoSize = true, WrapContents = false, BackColor = Ui.Bg, Margin = new Padding(0, 0, 0, Ui.S(4)) };
            tKey = Dlg.Box(Ui.S(340));
            tKey.Name = "key";
            tKey.UseSystemPasswordChar = true;
            tKey.MaxLength = 200;
            Native.Cue(tKey, "sk-ant-…");
            tKey.Margin = new Padding(0, Ui.S(4), Ui.S(8), 0);
            bDelete = new DarkButton(AiText.Get("as.key.del")) { Name = "delete", Accent = Art.Red1, Enabled = AiKey.Has() };
            bDelete.Click += (s, e) =>
            {
                if (!Session.OwnerActive) { Say("✕ " + AiText.Get("as.owneronly"), Art.Red1); return; }
                // v0.5.5 review: said and logged as deleted only when every copy is gone (an interrupted save's .tmp too)
                bool gone = AiKey.Delete();
                App.Log(gone ? "ai key deleted" : "ai key not deleted");
                lKey.Text = KeyState();
                bDelete.Enabled = AiKey.Has();
                if (gone) Say(AiText.Get("as.key.deleted"), Ui.Text); else Say("✕ " + AiText.Get("as.key.delfail"), Art.Red1);
            };
            keyRow.Controls.Add(tKey); keyRow.Controls.Add(bDelete);
            col.Controls.Add(keyRow);
            lKey = Dlg.Text(KeyState(), 9f, FontStyle.Regular, Ui.Muted, w);
            lKey.Name = "keyState";
            lKey.Margin = new Padding(0, 0, 0, Ui.S(14));
            col.Controls.Add(lKey);
            var lm = Dlg.Text(AiText.Get("as.model", AnthropicDrafter.DefaultModel), 9.5f, FontStyle.Bold, Ui.Text, w);
            lm.Margin = new Padding(0, 0, 0, Ui.S(4));
            col.Controls.Add(lm);
            var mRow = new FlowLayoutPanel { AutoSize = true, WrapContents = false, BackColor = Ui.Bg, Margin = new Padding(0, 0, 0, Ui.S(4)) };
            tModel = Dlg.Box(Ui.S(220));
            tModel.Name = "model";
            tModel.MaxLength = 64;
            tModel.Text = Drafters.Model;
            tModel.Margin = new Padding(0, Ui.S(4), Ui.S(16), 0);
            var lt = Dlg.Text(AiText.Get("as.timeout"), 9.5f, FontStyle.Regular, Ui.Muted, Ui.S(200));
            lt.Margin = new Padding(0, Ui.S(7), Ui.S(8), 0);
            // (a list, not a spin box: Windows draws a spin box's arrows light grey on the dark dialog)
            nTimeout = Dlg.Combo(Ui.S(76));
            nTimeout.Name = "timeout";
            nTimeout.Margin = new Padding(0, Ui.S(4), Ui.S(16), 0);
            int wait = Drafters.TimeoutSec, pick = 0;
            for (int i = 0; i < Waits.Length; i++) { nTimeout.Items.Add(Waits[i].ToString(CultureInfo.InvariantCulture)); if (Math.Abs(Waits[i] - wait) < Math.Abs(Waits[pick] - wait)) pick = i; }
            nTimeout.SelectedIndex = pick;
            bTest = new DarkButton(AiText.Get("as.test")) { Name = "test" };
            bTest.Click += (s, e) => Test();
            mRow.Controls.Add(tModel); mRow.Controls.Add(lt); mRow.Controls.Add(nTimeout); mRow.Controls.Add(bTest);
            col.Controls.Add(mRow);
            lResult = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, w);
            lResult.Name = "result";
            lResult.Margin = new Padding(0, 0, 0, Ui.S(14));
            col.Controls.Add(lResult);
            // v0.5.5 review: 「相手の文を貼る」 off by default (the privacy policy 3.5 5: not until D-04 is decided)
            cTheirs = new DarkCheck { Text = AiText.Get("as.theirs"), Name = "theirs", Checked = Settings.Get("ai.theirs", "0") == "1", Margin = new Padding(0, 0, 0, Ui.S(2)) };
            col.Controls.Add(cTheirs);
            var tn = Dlg.Text(AiText.Get("as.theirs.note"), 9f, FontStyle.Regular, Ui.Muted, w - Ui.S(30));
            tn.Margin = new Padding(Ui.S(30), 0, 0, Ui.S(14));
            col.Controls.Add(tn);
            col.Controls.Add(Dlg.Text(AiText.Get("as.backend"), 9f, FontStyle.Regular, Ui.Muted, w));
            col.Controls.Add(Dlg.Text(AiSpend.Text(S.Idx, DateTime.UtcNow) + "\n" + AiText.Get("ai.spend.limit"), 9f, FontStyle.Regular, Ui.Muted, w));
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.close")) { DialogResult = DialogResult.Cancel };
            var save = new DarkButton(S.Get("b.save")) { Primary = true, Name = "save" };
            save.Click += (s, e) =>
            {
                string err = SaveAll();
                if (err.Length > 0) { Say("✕ " + err, Art.Red1); return; }
                DialogResult = DialogResult.OK;
                Close();
            };
            btns.Controls.Add(cancel); btns.Controls.Add(save);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
            ActiveControl = tKey;
            FormClosed += (s, e) => { tKey.Text = ""; };
        }

        void Say(string text, Color c) { lResult.Text = text; lResult.ForeColor = c; }

        /// <summary>Saves what was typed ("" = done, else why not): the key (cleared from the box, never logged), the model, the time to wait, 「相手の文を貼る」.</summary>
        public string SaveAll()
        {
            if (!Session.OwnerActive) return AiText.Get("as.owneronly");
            string m = tModel.Text.Trim();
            if (!Drafters.ModelOk(m)) return AiText.Get("as.model.bad");
            string k = tKey.Text.Trim();
            if (k.Length > 0)
            {
                if (!AiKey.LooksOk(k)) return AiText.Get("as.key.bad");
                if (!AiKey.Save(k)) return AiText.Get("as.key.fail");
                tKey.Text = "";
                App.Log("ai key saved");
                lKey.Text = KeyState();
                bDelete.Enabled = true;
            }
            k = null;
            if (m != Settings.Get("ai.model", AnthropicDrafter.DefaultModel)) Settings.Set("ai.model", m);
            string t = Waits[Math.Max(0, nTimeout.SelectedIndex)].ToString(CultureInfo.InvariantCulture);
            if (t != Settings.Get("ai.timeout", "60")) Settings.Set("ai.timeout", t);
            string th = cTheirs.Checked ? "1" : "0";
            if (th != Settings.Get("ai.theirs", "0")) Settings.Set("ai.theirs", th);
            return "";
        }

        /// <summary>「確かめる」: GET /v1/models/{model} with the key typed (not saved yet) or the saved one; free, on a worker.</summary>
        void Test()
        {
            if (testing) return;
            string m = tModel.Text.Trim(), k = tKey.Text.Trim();
            if (!Drafters.ModelOk(m)) { Say("✕ " + AiText.Get("as.model.bad"), Art.Red1); return; }
            if (k.Length > 0 && !AiKey.LooksOk(k)) { Say("✕ " + AiText.Get("as.key.bad"), Art.Red1); return; }
            var d = new AnthropicDrafter { Model = m, TimeoutMs = Waits[Math.Max(0, nTimeout.SelectedIndex)] * 1000, KeyOverride = k.Length > 0 ? k : null };
            k = null;
            testing = true;
            bTest.Enabled = false;
            Say(AiText.Get("as.test.run"), Ui.Muted);
            var th = new Thread(() =>
            {
                DraftResult r;
                try { r = d.CheckModel(); } catch (Exception ex) { App.Log("ai check failed: " + ex.GetType().Name); r = DraftResult.Fail("network", ""); }
                d.KeyOverride = null;
                try
                {
                    BeginInvoke(new Action(() =>
                    {
                        testing = false;
                        bTest.Enabled = true;
                        if (r.Ok) Say(AiText.Get("as.test.ok", m), Art.Green1); else Say("✕ " + r.Message(S.Idx), Art.Red1);
                    }));
                }
                catch (Exception) { }
            });
            th.IsBackground = true;
            th.Start();
        }
    }

    /// <summary>
    /// v0.5.5 the unlock (本人確認): Windows Hello, the signing key (owner; the key challenge runs after this dialog closes
    /// with <see cref="Method"/> "key-request"), or the 4-digit code where Windows Hello cannot be used (admin, unverified).
    /// Windows Hello is asked on a worker and answers through a callback; nothing waits on the UI thread.
    /// </summary>
    public sealed class UnlockDialog : Form
    {
        public string Method = "";
        readonly DarkButton bHello, bKey, bCode, bRevoke, cancel;
        readonly Label lHello, lStatus, lCodeHead, lCode;
        readonly TextBox tCode;
        readonly FlowLayoutPanel codeRow;
        readonly string code;
        bool waiting;

        /// <summary>
        /// v0.5.5 (2026-09-23 「乗っ取られたら…」) The 4-digit code on the screen is not a check on a person: it only stops an
        /// accidental click, and its answer is right there. It is offered only where this PC holds no signing key — on the
        /// owner's PC 「署名の鍵で確認」 is always there instead, so nobody is locked out by leaving it away.
        /// </summary>
        public static bool CodeAllowed() { return !App.KeySignal; }

        public UnlockDialog()
        {
            Dlg.Style(this, S.Get("ul.title"));
            int w = Ui.S(560);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head(S.Get("ul.title"), 11f, Art.Teal1, w));
            col.Controls.Add(Dlg.Text(S.Get("ul.head", Session.IdleMinutes), 9.5f, FontStyle.Regular, Ui.Text, w));
            col.Controls.Add(Dlg.Text(S.Get(App.KeySignal ? "ul.state.key" : "ul.state.nokey"), 9.5f, FontStyle.Bold, App.KeySignal ? Ui.Text : Art.Amber1, w));
            bHello = new DarkButton(S.Get("ul.hello")) { Accent = Art.Green1, Enabled = false };
            bHello.Click += (s, e) => AskHello();
            col.Controls.Add(bHello);
            lHello = Dlg.Text(HelloNote(), 9f, FontStyle.Regular, Ui.Muted, w);
            col.Controls.Add(lHello);
            bKey = new DarkButton(S.Get("ul.key")) { Accent = Art.Amber1, Visible = App.KeySignal };
            bKey.Click += (s, e) => { if (waiting) return; Method = "key-request"; DialogResult = DialogResult.OK; Close(); };
            col.Controls.Add(bKey);
            if (App.KeySignal) col.Controls.Add(Dlg.Text(S.Get("ul.key.note"), 9f, FontStyle.Regular, Ui.Muted, w));
            // the code: only where Windows Hello cannot be used (anti-accident only; the audit log marks it unverified)
            var rnd = new byte[4];
            using (var r = new RNGCryptoServiceProvider()) r.GetBytes(rnd);
            code = ((BitConverter.ToUInt32(rnd, 0) % 9000) + 1000).ToString(CultureInfo.InvariantCulture);
            lCodeHead = Dlg.Text(S.Get("ul.code.head"), 9f, FontStyle.Regular, Art.Amber1, w);
            lCodeHead.Visible = false;
            col.Controls.Add(lCodeHead);
            codeRow = new FlowLayoutPanel { AutoSize = true, WrapContents = false, BackColor = Ui.Bg, Visible = false, Margin = new Padding(0, 0, 0, Ui.S(6)) };
            lCode = new Label { AutoSize = true, Text = code, ForeColor = Ui.Text, Font = Art.Mono(20f), Margin = new Padding(0, 0, Ui.S(16), 0) };
            tCode = Dlg.Box(Ui.S(90));
            tCode.MaxLength = 4;
            tCode.Margin = new Padding(0, Ui.S(8), Ui.S(8), 0);
            bCode = new DarkButton(S.Get("ul.code")) { Accent = Ui.Muted, Enabled = false };
            tCode.TextChanged += (s, e) => bCode.Enabled = tCode.Text.Trim() == code;
            bCode.Click += (s, e) => { if (tCode.Text.Trim() != code) return; Method = "code"; DialogResult = DialogResult.OK; Close(); };
            codeRow.Controls.Add(lCode); codeRow.Controls.Add(tCode); codeRow.Controls.Add(bCode);
            col.Controls.Add(codeRow);
            lStatus = Dlg.Text("", 9f, FontStyle.Regular, Art.Amber1, w);
            col.Controls.Add(lStatus);
            // v0.5.5 (2026-09-23): 「保存した鍵の記録を今すぐ無効にする」 — reachable from the LOCKED console, on every PC
            bRevoke = new DarkButton(S.Get("rv.button")) { Accent = Art.Red1 };
            bRevoke.Click += (s, e) => { if (waiting) return; Method = "revoke"; DialogResult = DialogResult.OK; Close(); };
            col.Controls.Add(bRevoke);
            var btns = Dlg.Buttons();
            cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            btns.Controls.Add(cancel);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
            Shown += (s, e) => CheckHello();
        }

        string HelloNote()
        {
            if (!App.KeySignal) return S.Get("ul.hello.admin");
            if (Session.KeyProven) return S.Get("ul.hello.owner2");
            var now = DateTime.UtcNow;
            var tok = UnlockProof.Token(now);
            if (tok != null) return S.Get("ul.hello.owner", Fmt.Local(tok.At), UnlockProof.TokenDays);
            string note = S.Get("ul.hello.admin") + "\n" + S.Get("ul.hello.nokeyrec", UnlockProof.TokenDays);
            if (UnlockProof.ClockWentBack(now)) note += "\n" + S.Get("ul.fail", S.Get("pv.9"));
            var rev = UnlockProof.RevokedAt();
            if (rev != DateTime.MinValue) note += "\n" + S.Get("ul.fail", S.Get("pv.10"));
            return note;
        }

        /// <summary>The availability (cached for a minute, else asked on a worker); the code appears only when Windows Hello cannot be used.</summary>
        void CheckHello()
        {
            int c = Hello.Cached(TimeSpan.FromMinutes(1));
            if (c != Hello.Unknown) { ShowHello(c); return; }
            lStatus.ForeColor = Ui.Muted;
            lStatus.Text = S.Get("ul.checking");
            var t = new Thread(() =>
            {
                int r = Hello.Availability(5000);
                try { if (!IsDisposed) BeginInvoke(new Action(() => ShowHello(r))); } catch (Exception) { }
            });
            t.IsBackground = true;
            t.Start();
        }

        void ShowHello(int avail)
        {
            if (IsDisposed) return;
            lStatus.Text = "";
            bool ok = avail == Hello.Available;
            bHello.Enabled = ok && !waiting;
            if (!ok)
            {
                lHello.Text = S.Get("ul.hello.no", S.Get("hl." + avail.ToString(CultureInfo.InvariantCulture)));
                lHello.ForeColor = Art.Amber1;
                ShowCode();
            }
        }

        /// <summary>
        /// The 4-digit code (admin, unverified): where Windows Hello cannot be used, or where it answers with an error.
        /// v0.5.5 (2026-09-23): never on a PC that holds a signing key (<see cref="CodeAllowed"/>) — the answer is on the
        /// screen, so it would hand the admin mode to anyone sitting there, and 「署名の鍵で確認」 is always available instead.
        /// </summary>
        void ShowCode()
        {
            if (!CodeAllowed()) return;
            lCodeHead.Visible = true;
            codeRow.Visible = true;
        }

        void AskHello()
        {
            if (waiting) return;
            waiting = true;
            bHello.Enabled = false; bKey.Enabled = false;
            lStatus.ForeColor = Ui.Text;
            lStatus.Text = S.Get("ul.wait");
            Hello.Request(Handle, S.Get("ul.hello.msg"), r =>
            {
                try { if (!IsDisposed) BeginInvoke(new Action(() => HelloDone(r))); } catch (Exception) { }
            });
        }

        void HelloDone(int r)
        {
            if (IsDisposed) return;
            waiting = false;
            if (r == Hello.Verified) { Method = "hello"; DialogResult = DialogResult.OK; Close(); return; }
            string why = S.Has("hr." + r.ToString(CultureInfo.InvariantCulture)) ? S.Get("hr." + r.ToString(CultureInfo.InvariantCulture)) : S.Get("hl." + r.ToString(CultureInfo.InvariantCulture));
            lStatus.ForeColor = Art.Amber1;
            lStatus.Text = S.Get("ul.fail", why);
            bKey.Enabled = true;
            if (r >= 1 && r <= 3) ShowHello(r);   // no device / not set up / policy: offer the code
            else
            {
                bHello.Enabled = true;
                // v0.5.5 review: Windows Hello said "available" but the request itself fails (an error, not a cancel): the
                // code too, so an admin without the key is never locked out (the audit log still marks it unverified)
                if (r == Hello.Error) ShowCode();
            }
        }
    }

    /// <summary>v0.5.5 "前回からの変化": the audit lines since this user last closed the console, and the bans changed outside it. Shown only.</summary>
    public sealed class SinceDialog : Form
    {
        public SinceDialog(List<AuditRec> ops, List<BanSnap.Change> outside) : this(ops, outside, null) { }

        /// <summary><paramref name="notes"/>: v0.5.5 review warnings ("key" or "key|arg": a line added past audit.head, the ban snapshot gone), shown first.</summary>
        public SinceDialog(List<AuditRec> ops, List<BanSnap.Change> outside, List<string> notes)
        {
            Dlg.Style(this, S.Get("sn.title"));
            int w = Ui.S(700);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head(S.Get("sn.title"), 11f, Art.Teal1, w));
            var sb = new StringBuilder();
            if (notes != null)
                foreach (var n in notes)
                {
                    int bar = n.IndexOf('|');
                    string k = bar < 0 ? n : n.Substring(0, bar);
                    sb.Append("⚠ ").Append(bar < 0 ? S.Get(k) : S.Get(k, n.Substring(bar + 1))).Append("\n\n");
                }
            // v0.5.5 (2026-09-23 「乗っ取られたら Windows Hello で管理が渡らない？」): 「前回からの解錠: N 回」 first, with the
            // methods. Every unlock is an audit line, so a console opened while the owner was away shows up here.
            string unlocks = Audit.UnlockSummary(ops, S.Idx);
            if (unlocks.Length > 0) sb.Append("■ ").Append(unlocks).Append('\n').Append(S.Get("sn.unlocks.note")).Append("\n\n");
            if (ops != null && ops.Count > 0)
            {
                sb.Append("■ ").Append(S.Get("sn.ops", ops.Count)).Append('\n');
                foreach (var a in ops) sb.Append(Line(a)).Append('\n');
                sb.Append('\n');
            }
            if (outside != null && outside.Count > 0)
            {
                sb.Append("■ ").Append(S.Get("sn.outside", outside.Count)).Append('\n');
                foreach (var c in outside)
                {
                    sb.Append("・").Append(S.Get("sn." + c.Kind)).Append("  ").Append(c.Name.Length > 0 ? c.Name : S.Get("noname"));
                    if (c.Ev.Length > 0 && c.Ev != "null") sb.Append("  ").Append(c.Ev);
                    sb.Append("  — ").Append(S.Get(c.Mod ? "ar.mod" : "ar.outside")).Append('\n');
                    foreach (var d in c.Diffs) sb.Append("    ").Append(BanSnap.DiffText(d, S.Idx)).Append('\n');
                }
            }
            var memo = Dlg.Memo(w, Ui.S(320), true, 9.5f);
            memo.Text = sb.ToString().TrimEnd('\n');
            col.Controls.Add(memo);
            col.Controls.Add(Dlg.Text(S.Get("sn.note"), 9f, FontStyle.Regular, Ui.Muted, w));
            var btns = Dlg.Buttons();
            var ok = new DarkButton(S.Get("b.ok")) { DialogResult = DialogResult.OK };
            btns.Controls.Add(ok);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            AcceptButton = ok; CancelButton = ok;
        }

        /// <summary>One audit line: when, who (user @ PC, mode, method), what, on whom, the result.</summary>
        public static string Line(AuditRec a)
        {
            string k = "ak." + a.Action;
            var sb = new StringBuilder("・");
            sb.Append(Fmt.Local(a.At)).Append("  ");
            string who = Audit.OperatorText(a, S.Idx);
            if (who.Length > 0) sb.Append(who).Append("  ");
            sb.Append(S.Has(k) ? S.Get(k) : a.Action);
            if (a.Name.Length > 0) sb.Append("  ").Append(a.Name);
            if (a.Ev.Length > 0) sb.Append("  ").Append(a.Ev);
            string res = Audit.ResultText(a.Result, S.Idx);
            if (res.Length > 0) sb.Append("  · ").Append(res);
            if (a.Method == "code") sb.Append("  · ").Append(S.Get("au.unverified"));
            return sb.ToString();
        }
    }

    /// <summary>v0.5.5 the host of each report zip to import (the two-hosts rule: <see cref="HostCount"/>): a name per zip, from the names given before or new.</summary>
    public sealed class ImportHostDialog : Form
    {
        public readonly List<string> Labels = new List<string>();
        readonly List<ComboBox> boxes = new List<ComboBox>();
        readonly DarkButton go;
        readonly Label need, trustWarn;

        public ImportHostDialog(IList<string> zips, IList<string> known)
        {
            Dlg.Style(this, S.Get("ih.title"));
            int w = Ui.S(620);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Head(S.Get("ih.title"), 11f, Art.Teal1, w));
            col.Controls.Add(Dlg.Text(S.Get("ih.head"), 9.5f, FontStyle.Regular, Ui.Text, w));
            foreach (var z in zips)
            {
                col.Controls.Add(Dlg.Text(Path.GetFileName(z), 9f, FontStyle.Bold, Ui.Muted, w));
                var cb = new DarkCombo { DropDownStyle = ComboBoxStyle.DropDown, Width = Ui.S(320), MaxLength = 40, Margin = new Padding(0, 0, 0, Ui.S(8)) };   // v0.5.5: the dark frame (an editable one)
                if (known != null) foreach (var k in known) cb.Items.Add(k);
                cb.TextChanged += (s, e) => Upd();
                boxes.Add(cb);
                col.Controls.Add(cb);
            }
            need = Dlg.Text(S.Get("ih.need"), 9f, FontStyle.Regular, Art.Amber1, w);
            col.Controls.Add(need);
            // v0.5.5 review: a trusted admin's name is only for that person's zips (such a zip backs a shared ban on one host)
            trustWarn = Dlg.Text("", 9f, FontStyle.Regular, Art.Amber1, w);
            trustWarn.Visible = false;
            col.Controls.Add(trustWarn);
            var btns = Dlg.Buttons();
            var cancel = new DarkButton(S.Get("b.cancel")) { DialogResult = DialogResult.Cancel };
            go = new DarkButton(S.Get("b.import.go")) { Accent = Art.Teal1, Enabled = false };
            go.Click += (s, e) =>
            {
                Labels.Clear();
                foreach (var b in boxes) Labels.Add(Proposal.OneLine(Audit.Mask(b.Text), 40));
                if (Labels.Exists(x => x.Length == 0)) return;
                DialogResult = DialogResult.OK;
                Close();
            };
            btns.Controls.Add(cancel); btns.Controls.Add(go);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = cancel;
        }

        void Upd()
        {
            bool all = boxes.TrueForAll(b => Proposal.OneLine(b.Text, 40).Length > 0);
            go.Enabled = all;
            need.Visible = !all;
            var trusted = new List<string>();
            foreach (var b in boxes) { string l = Proposal.OneLine(b.Text, 40); if (l.Length > 0 && Reporters.Current.IsTrusted(l) && !trusted.Contains(l)) trusted.Add(l); }
            trustWarn.Text = trusted.Count > 0 ? S.Get("ih.trusted", string.Join(S.Idx == 2 ? ", " : "、", trusted.ToArray())) : "";
            trustWarn.Visible = trusted.Count > 0;
        }
    }

    /// <summary>
    /// v0.5.5 (2026-09-22 「いいよ」) 「取り込み元のホスト」 from the settings: every host name given when importing, its trust and
    /// its overturned reports (<see cref="Reporters"/>). It only picks what to change (<see cref="Act"/>: trust / untrust /
    /// clear, on <see cref="Chosen"/>); the main window asks for the unlock and the 5-second check, writes reporters.txt and
    /// the audit line, and opens it again. v0.5.5 review: the shared bans in effect that a host's reports backed
    /// (<paramref name="activeLines"/>, may be null), and why trust or clears may be missing (unreadable files, reporters.txt
    /// lines audit.log does not have, a broken audit chain).
    /// </summary>
    public sealed class ReporterDialog : Form
    {
        public string Chosen = "", Act = "";
        readonly ComboBox cHost;
        readonly Label lState, lOver, lActive;
        readonly DarkButton bTrust, bUntrust, bClear;
        readonly Reporters.State st;
        readonly bool canChange;
        readonly Func<string, List<string>> activeLines;

        public ReporterDialog(Reporters.State state, bool canChange, string preselect) : this(state, canChange, preselect, null) { }

        public ReporterDialog(Reporters.State state, bool canChange, string preselect, Func<string, List<string>> activeLines)
        {
            st = state ?? new Reporters.State();
            this.canChange = canChange;
            this.activeLines = activeLines;
            Dlg.Style(this, S.Get("rh.title"));
            int w = Ui.S(600);
            var col = Dlg.Column();
            col.Controls.Add(Dlg.Text("■ " + S.Get("rh.title"), 11f, FontStyle.Bold, Art.Teal1, w));
            col.Controls.Add(Dlg.Text(S.Get("rh.head", Reporters.Threshold, Reporters.WindowDays, GateRules.CertainCap, GateRules.CertainCapDays), 9.5f, FontStyle.Regular, Ui.Text, w));
            if (st.Failed) col.Controls.Add(Dlg.Text(S.Get("rh.fail"), 9.5f, FontStyle.Bold, Art.Red1, w));
            if (st.ChainLimited) col.Controls.Add(Dlg.Text(S.Get("rh.chain"), 9.5f, FontStyle.Regular, Art.Amber1, w));
            if (st.Unmatched > 0) col.Controls.Add(Dlg.Text(S.Get("rh.unmatched", st.Unmatched), 9.5f, FontStyle.Regular, Art.Amber1, w));
            string sum = Reporters.Summary(st, S.Idx);
            if (sum.Length > 0) col.Controls.Add(Dlg.Text(sum, 9.5f, FontStyle.Bold, Ui.Violet, w));
            var labels = st.Labels();
            if (labels.Count == 0) col.Controls.Add(Dlg.Text(S.Get("rh.none"), 9.5f, FontStyle.Regular, Ui.Muted, w));
            else
            {
                col.Controls.Add(Dlg.Text(S.Get("rh.pick"), 9.5f, FontStyle.Bold, Ui.Text, w));
                cHost = Dlg.Combo(Ui.S(320));
                foreach (var l in labels) cHost.Items.Add(l);
                int pre = 0;
                for (int i = 0; i < labels.Count; i++) if (string.Equals(labels[i], preselect ?? "", StringComparison.OrdinalIgnoreCase)) pre = i;
                cHost.SelectedIndex = pre;
                cHost.Margin = new Padding(0, 0, 0, Ui.S(8));
                cHost.SelectedIndexChanged += (s, e) => Upd();
                col.Controls.Add(cHost);
                lState = Dlg.Text("", 9.5f, FontStyle.Bold, Ui.Text, w);
                col.Controls.Add(lState);
                lOver = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, w);
                col.Controls.Add(lOver);
                lActive = Dlg.Text("", 9f, FontStyle.Regular, Ui.Muted, w);
                col.Controls.Add(lActive);
            }
            if (!canChange) col.Controls.Add(Dlg.Text(S.Get("rh.owneronly"), 9f, FontStyle.Regular, Art.Amber1, w));
            var btns = Dlg.Buttons();
            bTrust = new DarkButton(S.Get("rh.b.trust")) { Accent = Ui.Violet, Enabled = false };
            bUntrust = new DarkButton(S.Get("rh.b.untrust")) { Enabled = false };
            bClear = new DarkButton(S.Get("rh.b.clear")) { Accent = Art.Amber1, Enabled = false };
            var close = new DarkButton(S.Get("b.close")) { DialogResult = DialogResult.Cancel };
            bTrust.Click += (s, e) => Pick("trust");
            bUntrust.Click += (s, e) => Pick("untrust");
            bClear.Click += (s, e) => Pick("clear");
            btns.Controls.Add(bTrust); btns.Controls.Add(bUntrust); btns.Controls.Add(bClear); btns.Controls.Add(close);
            col.Controls.Add(btns);
            Controls.Add(col);
            AutoSize = true; AutoSizeMode = AutoSizeMode.GrowAndShrink;
            CancelButton = close;
            Upd();
        }

        string Selected() { return cHost != null && cHost.SelectedItem != null ? cHost.SelectedItem.ToString() : ""; }

        void Pick(string act)
        {
            if (!canChange || Selected().Length == 0) return;
            Chosen = Selected(); Act = act;
            DialogResult = DialogResult.OK;
            Close();
        }

        void Upd()
        {
            string l = Selected();
            if (l.Length == 0 || lState == null) return;
            var i = st.For(l, "");
            string cap = MainForm.CapText(i, st.CertainUnknown, S.Idx);   // 9/23 the certain cap (review: a trusted admin is never "at the cap")
            lState.Text = Reporters.StateText(i, S.Idx) + (i.Flagged ? "\n" + S.Get("rp.flagged.d", Reporters.WindowDays, Reporters.Threshold) : "")
                + (cap.Length > 0 ? "\n" + cap : "");
            lState.ForeColor = i.Flagged ? Art.Red1 : i.Trusted ? Ui.Violet : i.Count > 0 ? Art.Amber1 : Ui.Text;
            lOver.Text = Reporters.OverText(i, S.Idx);
            var active = activeLines != null ? activeLines(l) : null;
            lActive.Text = active == null ? "" : S.Get("rh.active", active.Count > 0 ? string.Join(S.Idx == 2 ? ", " : "、", active.ToArray()) : S.Get("rh.active.none"));
            lActive.ForeColor = i.Flagged && active != null && active.Count > 0 ? Art.Red1 : Ui.Muted;
            bTrust.Enabled = canChange && !i.Trusted;
            bUntrust.Enabled = canChange && i.Trusted;
            bClear.Enabled = canChange && i.Count > 0;
        }
    }

