    /// <summary>An operation on the scan screen: its steps run on a worker; closing is locked until they finish; an optional follow-up button and a log box (git output).</summary>
    public sealed class OpForm : Form
    {
        public readonly StepView View = new StepView();
        readonly RichTextBox logBox;
        readonly DarkButton close, extra;
        readonly StringBuilder logText = new StringBuilder();
        readonly System.Windows.Forms.Timer sync = new System.Windows.Forms.Timer();
        int shownLen = -1;
        bool running, counted;
        public bool Ok, ExtraChosen;
        public string OkText = "";
        /// <summary>
        /// v0.5.5 review: the operations whose steps are running now (the idle lock counts only this as input: an operation
        /// window left open after its steps, with its 「GitHub に反映」 button, no longer keeps the console unlocked).
        /// </summary>
        static int runningCount;
        public static bool AnyRunning { get { return Thread.VolatileRead(ref runningCount) > 0; } }

        void Uncount() { if (counted) { counted = false; Interlocked.Decrement(ref runningCount); } }

        public OpForm(string title, List<Step> steps, bool withLog, string extraText)
        {
            Dlg.Style(this, "Aegis — " + title);
            View.Title = title;
            View.Steps.AddRange(steps);
            View.Dock = DockStyle.Top;
            View.Height = View.PreferredRowsHeight;
            var buttons = new FlowLayoutPanel { Dock = DockStyle.Bottom, FlowDirection = FlowDirection.RightToLeft, WrapContents = false, Height = Ui.S(54), Padding = new Padding(Ui.S(14), Ui.S(10), Ui.S(8), Ui.S(6)), BackColor = Ui.Panel };
            close = new DarkButton(S.Get("b.close")) { Enabled = false };
            close.Click += (s, e) => Close();
            extra = new DarkButton(extraText ?? "") { Visible = false, Accent = Art.Amber1 };
            extra.Click += (s, e) => { ExtraChosen = true; Close(); };
            buttons.Controls.Add(close);
            buttons.Controls.Add(extra);
            if (withLog)
            {
                logBox = Dlg.Memo(Ui.S(200), Ui.S(100), true, 9f);   // v0.5.5: wraps (git output can hold Japanese)
                logBox.Dock = DockStyle.Fill; logBox.BorderStyle = BorderStyle.None; logBox.Font = Art.Mono(9f); logBox.Margin = new Padding(0);
                Native.DarkScroll(logBox);
                Controls.Add(logBox);
            }
            Controls.Add(buttons);
            Controls.Add(View);
            ClientSize = new Size(Ui.S(760), View.Height + (withLog ? Ui.S(210) : 0) + buttons.Height);
            sync.Interval = 150;
            sync.Tick += (s, e) => SyncLog();
        }

        public void AppendLog(string text)
        {
            if (text == null) return;
            lock (logText)
                foreach (var l in text.Replace("\r\n", "\n").Split('\n'))
                    if (l.Length > 0) logText.Append(l).Append("\r\n");
        }

        void SyncLog()
        {
            if (logBox == null) return;
            string t;
            lock (logText) { if (logText.Length == shownLen) return; shownLen = logText.Length; t = logText.ToString(); }
            logBox.Text = t;
            logBox.SelectionStart = logBox.TextLength;
            logBox.ScrollToCaret();
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            running = true;
            View.Running = true;
            sync.Start();
            counted = true;
            Interlocked.Increment(ref runningCount);
            Runner.Start(this, View.Steps, 300, ok =>
            {
                running = false;
                Uncount();
                View.Running = false;
                Ok = ok;
                if (ok)
                {
                    bool warn = false;
                    foreach (var s in View.Steps) if (s.State == 3) warn = true;
                    View.ResultKind = warn ? 3 : 2;
                    View.Result = OkText;
                }
                else
                {
                    string d = "";
                    foreach (var s in View.Steps) if (s.State == 4) d = s.Detail ?? "";
                    View.ResultKind = 4;
                    View.Result = S.Get("op.fail", d.Length > 0 ? d : "?");
                }
                close.Enabled = true;
                extra.Visible = ok && extra.Text.Length > 0;
                SyncLog();
                View.Invalidate();
                if (extra.Visible) extra.Focus(); else close.Focus();
            });
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (running) { e.Cancel = true; return; }
            sync.Stop();
            base.OnFormClosing(e);
        }

        protected override void OnFormClosed(FormClosedEventArgs e)
        {
            Uncount();   // (never left counted)
            base.OnFormClosed(e);
        }
    }

    // ------------------------------------------------------------------ operations (worker thread)
    public static class Ops
    {
        public const string DefsRel = "aegis/definitions.txt", SigRel = "aegis/definitions.txt.sig";

        /// <summary>The highest version signed so far (the ledger of tools\sign-definitions.ps1; not secret); 0 when none.</summary>
        public static int LedgerMax()
        {
            int max = 0;
            try
            {
                if (!File.Exists(App.LedgerPath)) return 0;
                foreach (var line in File.ReadAllLines(App.LedgerPath, Encoding.UTF8))
                {
                    string t = line.Trim();
                    if (t.Length == 0 || t[0] == '#') continue;
                    var p = t.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                    int v;
                    if (p.Length >= 2 && int.TryParse(p[0], NumberStyles.Integer, CultureInfo.InvariantCulture, out v) && v > max) max = v;
                }
            }
            catch (Exception e) { App.Log("ledger not read: " + e.Message); }
            return max;
        }

        public static JObj LoadPending()
        {
            try { return File.Exists(App.PendingFile) && File.Exists(App.WorkDefs) ? Json.Parse(Json.ReadText(App.PendingFile)) as JObj : null; }
            catch (Exception) { return null; }
        }

        // ---- local-only change

        /// <summary>Writes the action's local fields into its aegis-bans.json entry (keeping the values before in localOld) and its history line.</summary>
        public static string ApplyLocal(JObj a)
        {
            var nw = a.Obj("localNew");
            var hist = a.Obj("localHist");
            if (nw == null && hist == null) return null;
            if (!File.Exists(App.BansPath)) return nw == null ? null : S.Get("e.notfound");
            var hashes = new HashSet<string>(Json.Strings(a.Arr("hashes")));
            string guard = a.Str("guardSince");
            var old = new JObj();
            string err = BanStore.Mutate(App.BansPath, root =>
            {
                old.Items.Clear();
                var bans = root.Arr("bans");
                JObj e = null;
                if (bans != null) foreach (var o in bans) { var x = o as JObj; if (x != null && BanStore.Matches(x, hashes)) { e = x; break; } }
                if (e == null) return nw == null ? BanStore.NoChange : S.Get("e.notfound");
                if (guard.Length > 0 && e.Str("since") != guard) return S.Get("e.changed");
                if (nw != null)
                    foreach (var kv in nw.Items)
                    {
                        old.Set(kv.Key, e.Get(kv.Key));
                        e.Set(kv.Key, kv.Value as string == "@now" ? Json.Time(DateTime.UtcNow) : kv.Value);
                    }
                if (hist != null) BanStore.AddHistory(e, hist.Str("event"), hist.Str("detail"));
                return null;
            });
            if (err == null && nw != null) a.Set("localOld", old);
            return err;
        }

        public static bool RunLocal(JObj a, Step st)
        {
            if (!Session.Unlocked) { st.Detail = S.Get("e.locked"); App.Log("a local change was refused while locked"); return false; }
            string err = ApplyLocal(a);
            if (err != null) { st.Detail = err; return false; }
            BanSnap.Refresh(new HashSet<string>(Json.Strings(a.Arr("hashes"))));   // this console's own change is not "outside"
            var list = Journal.Load();
            a.Set("state", "done");
            MarkUndone(list, a);
            list.Add(a);
            Journal.Save(list);
            App.Log("local " + a.Str("kind") + " " + ShortList(a) + " done");
            st.Detail = Path.GetFileName(App.BansPath);
            return true;
        }

        // ---- v0.5.5: adding this PC's ban from an evidence record (a candidate); never from a typed name

        public const string ConsoleBy = "console (BAN 管理)";

        /// <summary>A ban about to be recorded: the offence count, the ladder step, the length, when it ends, and whether a longer running ban was kept.</summary>
        public sealed class AddPlan
        {
            public int Count, Level, Days;
            public DateTime? Expires;
            public bool KeptLonger;
        }

        /// <summary>
        /// The mod's AegisBans.AddBan rules: the offences go on from the larger of this PC's count and the shared line's level,
        /// the step is min(count, 3), <paramref name="days"/> &lt; 0 = the ladder (30 / 180 / permanent), 0 = permanent,
        /// N = N days (at most 3650), and a ban still running is never shortened.
        /// </summary>
        public static AddPlan PlanAdd(int priorCount, int sharedLevel, bool running, DateTime? oldExpires, int days, DateTime now)
        {
            int prior = Math.Max(Math.Max(0, priorCount), Math.Max(0, sharedLevel));
            int count = prior + 1;
            int step = Math.Min(count, 3);
            int used = days < 0 ? (step == 1 ? 30 : step == 2 ? 180 : 0) : Math.Min(days, 3650);
            DateTime? exp = used > 0 ? now.AddDays(used) : (DateTime?)null;
            bool kept = false;
            if (running && exp != null && (oldExpires == null || oldExpires.Value > exp.Value))
            {
                exp = oldExpires;
                used = oldExpires == null ? 0 : Math.Max(1, (int)Math.Ceiling((oldExpires.Value - now).TotalDays));
                kept = true;
            }
            return new AddPlan { Count = count, Level = step, Days = used, Expires = exp, KeptLonger = kept };
        }

        static readonly string[] AddFields = { "count", "level", "days", "since", "expires", "rule", "source", "evidence", "by", "active", "unbannedAt", "unbanBy" };

        /// <summary>The value of an added field before the player had any ban here (an undo of the add writes these back).</summary>
        static object NotBanned(string k)
        {
            switch (k)
            {
                case "count": case "level": case "days": return JNum.Of(0);
                case "source": return "manual";
                case "active": return false;
                case "unbannedAt": return "@now";
                case "unbanBy": return ConsoleBy + ", undo";
                case "since": case "expires": return null;
                default: return "";
            }
        }

        /// <summary>A new aegis-bans.json entry for the evidence's player (the fields in the mod's order; not banned yet).</summary>
        static JObj NewEntry(EvInfo ev, DateTime now)
        {
            var e = new JObj();
            string seen = Json.Time(ev.Time != DateTime.MinValue ? ev.Time : now);
            e.Set("hash", ev.Hash);
            e.Set("puidHash", ev.PuidHash);
            e.Set("name", ev.Name);
            e.Set("count", JNum.Of(0)); e.Set("level", JNum.Of(0)); e.Set("days", JNum.Of(0));
            e.Set("since", null); e.Set("expires", null);
            e.Set("rule", ""); e.Set("source", "manual"); e.Set("evidence", ""); e.Set("by", "");
            e.Set("firstSeen", seen); e.Set("lastSeen", seen);
            e.Set("reported", false); e.Set("reportedAt", null);
            e.Set("active", false); e.Set("unbannedAt", null); e.Set("unbanBy", "");
            e.Set("history", new List<object>());
            return e;
        }

        /// <summary>
        /// Records this PC's ban of the evidence's player in aegis-bans.json (the file is made when there is none): the entry
        /// of that friend-code / PUID hash, or a new one; <see cref="PlanAdd"/> on the file's own values at the time of
        /// writing; source "manual", by <see cref="ConsoleBy"/>, the evidence id, a "ban" history line. The values before go
        /// into the action's localOld (so "元に戻す" takes it back, the offence count included). Null on success.
        /// </summary>
        public static string AddLocal(JObj a, EvInfo ev, int days, string rule, int sharedLevel, DateTime now, out string sinceText)
        {
            string since = Json.Time(now);
            sinceText = since;
            if (ev == null || !Hashes.IsHash(ev.Hash)) return S.Get("e.nohash");
            var old = new JObj();
            Func<JObj, string> change = root =>
            {
                old.Items.Clear();
                var bans = root.Arr("bans");
                if (bans == null) { bans = new List<object>(); root.Set("bans", bans); }
                var hashes = new HashSet<string>();
                hashes.Add(ev.Hash);
                if (ev.PuidHash.Length > 0) hashes.Add(ev.PuidHash);
                JObj e = null;
                foreach (var o in bans) { var x = o as JObj; if (x != null && BanStore.Matches(x, hashes)) { e = x; break; } }
                bool created = e == null;
                if (created) { e = NewEntry(ev, now); bans.Add(e); }
                else if (e.Str("puidHash").Length == 0 && ev.PuidHash.Length > 0) e.Set("puidHash", ev.PuidHash);
                foreach (var k in AddFields) old.Set(k, created ? NotBanned(k) : e.Get(k));
                var exp0 = e.Time("expires");
                bool running = e.Str("source").ToLowerInvariant() != "shared" && e.Bool("active", true) && (exp0 == null || now < exp0.Value);
                var plan = PlanAdd(e.Int("count"), sharedLevel, running, exp0, days, now);
                e.Set("count", JNum.Of(plan.Count));
                e.Set("level", JNum.Of(plan.Level));
                e.Set("days", JNum.Of(plan.Days));
                e.Set("since", since);
                e.Set("expires", plan.Expires == null ? null : Json.Time(plan.Expires.Value));
                e.Set("rule", rule ?? "");
                e.Set("source", "manual");
                e.Set("evidence", ev.Id);
                e.Set("by", ConsoleBy);
                if (ev.Name.Length > 0) e.Set("name", ev.Name);
                e.Set("lastSeen", since);
                e.Set("active", true);
                e.Set("unbannedAt", null);
                e.Set("unbanBy", "");
                BanStore.AddHistory(e, "ban", ("manual " + (rule ?? "") + " " + (plan.Expires == null ? "permanent" : plan.Days.ToString(CultureInfo.InvariantCulture) + " d") + " " + ev.Id + " (console)").Trim());
                return null;
            };
            string err = File.Exists(App.BansPath) ? BanStore.Mutate(App.BansPath, change) : BanStore.Create(App.BansPath, change);
            if (err == null) a.Set("localOld", old);
            return err;
        }

        public static bool RunAdd(JObj a, EvInfo ev, int days, string rule, int sharedLevel, Step st)
        {
            if (!Session.Unlocked) { st.Detail = S.Get("e.locked"); App.Log("a local add was refused while locked"); return false; }
            string since;
            string err = AddLocal(a, ev, days, rule, sharedLevel, DateTime.UtcNow, out since);
            if (err != null) { st.Detail = err; return false; }
            BanSnap.Refresh(new HashSet<string>(Json.Strings(a.Arr("hashes"))));
            a.Set("guardSince", since);   // an undo never overwrites a newer ban
            var list = Journal.Load();
            a.Set("state", "done");
            list.Add(a);
            Journal.Save(list);
            App.Log("local add " + ShortList(a) + " " + ev.Id + " done");
            st.Detail = Path.GetFileName(App.BansPath);
            return true;
        }

        static void MarkUndone(List<JObj> list, JObj a)
        {
            if (a.Str("kind") != "undo") return;
            var orig = Journal.Find(list, a.Str("undoOf"));
            if (orig != null) orig.Set("state", "undone");
        }

        public static string ShortList(JObj a)
        {
            var o = new List<string>();
            foreach (var h in Json.Strings(a.Arr("hashes"))) o.Add(Hashes.Short(h));
            return string.Join(",", o.ToArray());
        }

        // ---- what an action did: the history (UI language) and the commit line (Japanese, public on GitHub)

        /// <summary>
        /// Sets what the action did: "d" (the fields the history shows in the UI language) and "desc" (the same in Japanese:
        /// the line of the commit message on GitHub). <paramref name="lineHash"/> is the SHARED line's hash (a PUID's hash,
        /// public in the definitions file once listed), never a friend code's hash: the commit message is public, and 8 hex
        /// digits of a friend code's hash are enough to find the friend code (a word + 4 digits) by trying them all. Without
        /// a shared line (this PC's ban only) the evidence id stands for the player.
        /// </summary>
        public static void SetDesc(JObj a, string lineHash, int level, DateTime? date, string reason, bool alsoLocal, string ev, string from, string undoOf)
        {
            var d = new JObj();
            d.Set("line", string.IsNullOrEmpty(lineHash) ? "" : Hashes.Short(lineHash));
            d.Set("level", JNum.Of(level));
            d.Set("until", date == null ? "never" : date.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture));
            d.Set("reason", reason ?? "");
            d.Set("local", alsoLocal);
            d.Set("ev", ev ?? "");
            d.Set("from", from ?? "");
            d.Set("of", undoOf ?? "");
            a.Set("d", d);
            a.Set("desc", DescIn(0, a));
        }

        /// <summary>What the action did, in language <paramref name="idx"/> (an action of an older build without "d": its desc as it was).</summary>
        public static string DescIn(int idx, JObj a)
        {
            var d = a.Obj("d");
            if (d == null) return a.Str("desc");
            string line = d.Str("line"), ev = d.Str("ev"), until = d.Str("until");
            string id = line.Length > 0 ? line : ev.Length > 0 ? ev : "—";
            string untilText = until == "never" || until.Length == 0 ? S.In(idx, "perm") : S.In(idx, "until", until);
            switch (a.Str("kind"))
            {
                case "share":
                    {
                        string why = d.Str("reason"), from = d.Str("from");
                        if (from.Length > 0 && S.Has("ds.from." + from)) why += (idx == 2 ? ", " : "、") + S.In(idx, "ds.from." + from);
                        return S.In(idx, "ds.share", id, d.Int("level"), untilText, why);
                    }
                case "unban": return S.In(idx, "ds.unban", id) + (d.Bool("local", false) ? S.In(idx, "ds.alsolocal") : "");
                case "period": return S.In(idx, "ds.period", id, until == "never" || until.Length == 0 ? S.In(idx, "perm") : until);
                case "undo":
                    {
                        string of = d.Str("of"), k = "ak." + of;
                        return S.In(idx, "ds.undo", S.Has(k) ? S.In(idx, k) : of, id);
                    }
                case "add": return S.In(idx, "ds.add", ev.Length > 0 ? ev : id);
            }
            return a.Str("desc");
        }

        /// <summary>The first hash of a list of [bans] lines ("" when none).</summary>
        public static string FirstLineHash(IEnumerable<string> lines)
        {
            if (lines != null) foreach (var l in lines) { var b = SharedLine.Parse(l); if (b != null) return b.Hash; }
            return "";
        }

        static readonly Regex HexTok = new Regex("[0-9a-fA-F]{8,}");

        /// <summary>
        /// A change line as it may go into the public commit message: a run of 8+ hex digits that is not the start of a hash in
        /// <paramref name="publicHashes"/> (the [bans] lines before and after the change: public anyway) becomes "(id)", and
        /// anything shaped like a friend code is masked. It keeps a line of an older build (which could hold 8 digits of a
        /// friend code's hash) off GitHub.
        /// </summary>
        public static string PublicLine(string line, ICollection<string> publicHashes)
        {
            string s = HexTok.Replace(line ?? "", m =>
            {
                string v = m.Value.ToLowerInvariant();
                if (publicHashes != null) foreach (var h in publicHashes) if (h.StartsWith(v, StringComparison.Ordinal)) return m.Value;
                return "(id)";
            });
            return Audit.Mask(s);
        }

        static void AddLineHashes(ICollection<string> set, DefsDoc d) { if (d != null) foreach (var b in d.Bans) set.Add(b.Hash); }
        static void AddLineHashes(ICollection<string> set, IEnumerable<string> lines) { foreach (var l in lines) { var b = SharedLine.Parse(l); if (b != null) set.Add(b.Hash); } }

        /// <summary>Defence in depth: each step that signs or publishes refuses admin mode by itself (the buttons are hidden there too).</summary>
        static bool AdminStop(Step st)
        {
            if (App.Admin)
            {
                st.Detail = S.Get("e.admin");
                App.Log("a signing / publishing step was refused in admin mode");
                return true;
            }
            // v0.5.5: the owner mode itself needs the unlock with a key proof (Session); a locked console never signs
            if (!Session.OwnerActive)
            {
                st.Detail = S.Get("e.notowner");
                App.Log("a signing / publishing step was refused: not unlocked as the owner");
                return true;
            }
            // v0.5.5 (2026-09-23 「乗っ取られたら Windows Hello で管理が渡らない？」): what reaches other people needs the key
            // challenge in THIS run, never the stored Windows Hello proof. The buttons ask for it first (MainForm.KeyGate);
            // this is the last check, so a path that forgot to ask still cannot sign or publish.
            if (!Session.KeyProven)
            {
                st.Detail = S.Get("e.needkey");
                App.Log("a signing / publishing step was refused: the signing key was not proven in this run");
                return true;
            }
            return false;
        }

        // ---- shared change: working copy → signature → pending

        public static bool CheckRepo(Step st)
        {
            if (AdminStop(st)) return false;
            if (!Directory.Exists(App.RepoDir)) { st.Detail = S.Get("e.norepo", App.RepoDir); return false; }
            if (!File.Exists(App.RepoDefs)) { st.Detail = S.Get("e.nodefs", App.RepoDefs); return false; }
            if (!File.Exists(App.SignScript)) { st.Detail = S.Get("e.nosigner", App.SignScript); return false; }
            var pend = LoadPending();
            if (pend != null)
            {
                var repo = DefsDoc.Load(App.RepoDefs);
                if (repo.CanonSha != pend.Str("baseSha")) { st.Detail = S.Get("e.basechanged"); return false; }
            }
            st.Detail = App.RepoDir;
            return true;
        }

        /// <summary>Writes the working copy: the [bans] lines of the action's hashes replaced by sharedAfter, version= raised past every signed version.</summary>
        public static bool BuildWork(JObj a, Step st)
        {
            if (AdminStop(st)) return false;
            var repo = DefsDoc.Load(App.RepoDefs);
            if (repo == null) { st.Detail = S.Get("e.nodefs", App.RepoDefs); return false; }
            var pend = LoadPending();
            DefsDoc baseDoc = pend != null ? DefsDoc.Load(App.WorkDefs) : repo;
            if (baseDoc == null) { st.Detail = S.Get("e.nodefs", App.WorkDefs); return false; }
            if (baseDoc.VersionIdx < 0) { st.Detail = S.Get("e.noversion"); return false; }
            var hashes = new HashSet<string>(Json.Strings(a.Arr("hashes")));
            var after = Json.Strings(a.Arr("sharedAfter"));
            a.Set("sharedBefore", Json.Array(baseDoc.LinesFor(hashes)));
            int ver = Math.Max(Math.Max(baseDoc.Version, repo.Version), LedgerMax()) + 1;
            string text = baseDoc.Rewrite(hashes, after, ver);
            if (text.Length > DefsDoc.MaxChars) { st.Detail = S.Get("e.big", text.Length); return false; }
            // the result must list exactly sharedAfter for these hashes
            var chk = DefsDoc.Parse(text);
            var want = new List<string>();
            foreach (var l in after) { var b = SharedLine.Parse(l); if (b == null) { st.Detail = S.Get("e.check"); return false; } want.Add(b.Raw); }
            var got = chk.LinesFor(hashes);
            if (got.Count != want.Count || chk.Version != ver) { st.Detail = S.Get("e.check"); return false; }
            for (int i = 0; i < got.Count; i++) if (got[i] != want[i]) { st.Detail = S.Get("e.check"); return false; }
            Directory.CreateDirectory(App.WorkDir);
            // keep the signed working copy of earlier changes, to put back if this signing fails
            try { if (Directory.Exists(App.BackupDir)) Directory.Delete(App.BackupDir, true); } catch (Exception) { }
            if (pend != null)
            {
                Directory.CreateDirectory(App.BackupDir);
                File.Copy(App.WorkDefs, Path.Combine(App.BackupDir, "definitions.txt"), true);
                if (File.Exists(App.WorkDefs + ".sig")) File.Copy(App.WorkDefs + ".sig", Path.Combine(App.BackupDir, "definitions.txt.sig"), true);
            }
            File.WriteAllText(App.WorkDefs, text, new UTF8Encoding(false));
            if (File.Exists(App.WorkDefs + ".sig")) File.Delete(App.WorkDefs + ".sig");
            a.Set("version", JNum.Of(ver));
            a.Set("baseSha", pend != null ? pend.Str("baseSha") : repo.CanonSha);
            int kb = (Encoding.UTF8.GetByteCount(text) + 1023) / 1024;
            st.Detail = "v" + ver.ToString(CultureInfo.InvariantCulture) + " · " + kb.ToString(CultureInfo.InvariantCulture) + " KB";
            if (text.Length > 56 * 1024) { st.State = 3; st.Detail = S.Get("e.near", kb); }
            return true;
        }

        /// <summary>Puts the working copy back as it was before <see cref="BuildWork"/> (the earlier signed changes, or nothing).</summary>
        public static void Rollback()
        {
            try
            {
                string bd = Path.Combine(App.BackupDir, "definitions.txt"), bs = bd + ".sig";
                if (File.Exists(bd))
                {
                    File.Copy(bd, App.WorkDefs, true);
                    if (File.Exists(bs)) File.Copy(bs, App.WorkDefs + ".sig", true);
                    else if (File.Exists(App.WorkDefs + ".sig")) File.Delete(App.WorkDefs + ".sig");
                }
                else if (!File.Exists(App.PendingFile))
                {
                    if (File.Exists(App.WorkDefs)) File.Delete(App.WorkDefs);
                    if (File.Exists(App.WorkDefs + ".sig")) File.Delete(App.WorkDefs + ".sig");
                }
                if (Directory.Exists(App.BackupDir)) Directory.Delete(App.BackupDir, true);
            }
            catch (Exception e) { App.Log("rollback: " + e.Message); }
        }

        static string PsQ(string s) { return "'" + (s ?? "").Replace("'", "''") + "'"; }

        /// <summary>
        /// The PowerShell command of the signing console: runs tools\sign-definitions.ps1 -File on the working copy, says
        /// whether it worked and waits for Enter, then exits with the script's exit code. The key password (when the script
        /// asks for one) is typed there by the user; this app never sees it.
        /// </summary>
        public static string SignCommand(string script, string defs)
        {
            return ConsoleCommand(S.Get("sign.head"), script, "& " + PsQ(script) + " -File " + PsQ(defs), S.Get("sign.ok"), S.Get("sign.fail"), true);
        }

        /// <summary>
        /// v0.5.5 the key challenge's console: tools\sign-definitions.ps1 -Unlock &lt;nonce&gt; -UnlockOut &lt;file&gt; (the key password,
        /// when asked, is typed there by the owner; this app never sees it). Only a 32-hex nonce and a path in the state
        /// folder are passed. v0.5.5 review: its own texts (it confirms who you are; it does not sign the definitions), and
        /// it closes by itself when it worked (no Enter to wait for: the answer's 5 minutes are counted when it comes back).
        /// </summary>
        public static string UnlockCommand(string script, string nonce, string outPath)
        {
            if (!UnlockProof.NonceOk(nonce)) throw new ArgumentException("nonce");
            return ConsoleCommand(S.Get("ul.head.console"), script, "& " + PsQ(script) + " -Unlock " + PsQ(nonce) + " -UnlockOut " + PsQ(outPath), S.Get("ul.console.ok"), S.Get("ul.console.fail"), false);
        }

        /// <summary>The first 16 hex digits of a file's SHA-256 ("—" when it cannot be read): the console and Settings show it for the signing script.</summary>
        public static string ScriptSha16(string path)
        {
            try
            {
                var fi = new FileInfo(path ?? "");
                if (!fi.Exists || fi.Length > 16L * 1024 * 1024) return "—";
                return Hashes.Sha256(File.ReadAllBytes(fi.FullName)).Substring(0, 16);
            }
            catch (Exception) { return "—"; }
        }

        /// <summary>
        /// The console's script: its head, then (v0.5.5 review) the full path of the script that will run and the first 16
        /// digits of its SHA-256 (the owner types the key password into it), the call, then the result line; it waits for
        /// Enter after a failure always, after a success only when <paramref name="waitOnSuccess"/>.
        /// </summary>
        static string ConsoleCommand(string head, string script, string call, string okText, string failText, bool waitOnSuccess)
        {
            string full = script ?? "";
            try { full = Path.GetFullPath(full); } catch (Exception) { }
            return "try { $Host.UI.RawUI.WindowTitle = " + PsQ(S.Get("title")) + " } catch { }\n"
                + "Write-Host " + PsQ(head) + " -ForegroundColor Cyan\n"
                + "Write-Host " + PsQ(S.Get("cs.script", full)) + " -ForegroundColor Gray\n"
                + "Write-Host " + PsQ(S.Get("cs.sha", ScriptSha16(full))) + " -ForegroundColor Gray\n"
                + "Write-Host ''\n"
                + "$code = 1\n"
                + "try { " + call + "; $code = $LASTEXITCODE } catch { Write-Host $_ -ForegroundColor Red; $code = 1 }\n"
                + "if ($null -eq $code) { $code = 1 }\n"
                + "Write-Host ''\n"
                + "if ($code -eq 0) { Write-Host " + PsQ(okText) + " -ForegroundColor Green } else { Write-Host " + PsQ(failText) + " -ForegroundColor Red }\n"
                + (waitOnSuccess ? "try { [void](Read-Host) } catch { }\n" : "if ($code -eq 0) { Start-Sleep -Seconds 2 } else { try { [void](Read-Host) } catch { } }\n")
                + "exit $code\n";
        }

        /// <summary>Runs a console command in its own visible window and waits for it (on the worker thread); the exit code, or -1 with <paramref name="error"/>.</summary>
        static int RunConsole(string command, string workDir, out string error)
        {
            error = "";
            try
            {
                string b64 = Convert.ToBase64String(Encoding.Unicode.GetBytes(command));
                var psi = new ProcessStartInfo("powershell.exe", "-NoProfile -NoLogo -ExecutionPolicy Bypass -EncodedCommand " + b64)
                {
                    UseShellExecute = true,   // its own visible console window (the key password is typed there)
                    WindowStyle = ProcessWindowStyle.Normal,
                    WorkingDirectory = Directory.Exists(workDir) ? workDir : Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
                };
                using (var p = Process.Start(psi)) { p.WaitForExit(); return p.ExitCode; }
            }
            catch (Exception e) { error = e.Message; return -1; }
        }

        /// <summary>v0.5.5 the key challenge (owner unlock): the visible console signs the nonce; nothing secret passes through this app.</summary>
        public static bool KeyChallenge(string nonce, string outPath, Step st)
        {
            if (!App.KeySignal) { st.Detail = S.Get("e.admin"); return false; }
            if (!File.Exists(App.SignScript)) { st.Detail = S.Get("e.nosigner", App.SignScript); return false; }
            try
            {
                Directory.CreateDirectory(App.UnlockDir);
                foreach (var f in Directory.GetFiles(App.UnlockDir, "response-*.txt")) try { File.Delete(f); } catch (Exception) { }   // old answers never count
            }
            catch (Exception e) { st.Detail = e.Message; return false; }
            st.Detail = S.Get("ul.step.key.d");
            string err;
            int code = RunConsole(UnlockCommand(App.SignScript, nonce, outPath), App.RepoDir, out err);
            if (code == -1 && err.Length > 0) { st.Detail = S.Get("e.ulconsole", err); return false; }
            if (code != 0) { st.Detail = S.Get("e.ulexit", code); App.Log("unlock console exit " + code); return false; }
            st.Detail = "exit 0";
            return true;
        }

        public static bool VerifyChallenge(string nonce, string outPath, Step st)
        {
            int r = UnlockProof.Accept(outPath, nonce, DateTime.UtcNow);
            if (r != UnlockProof.Ok) { st.Detail = S.Get("ul.fail", S.Get("pv." + r.ToString(CultureInfo.InvariantCulture))); App.Log("unlock proof refused: " + r); return false; }
            var tok = UnlockProof.Token(DateTime.UtcNow);
            st.Detail = S.Get("ld.sig.ok") + (tok != null ? " · keyid " + tok.KeyId : "");
            return true;
        }

        public static bool Sign(Step st)
        {
            if (AdminStop(st)) return false;
            st.Detail = S.Get("step.sign.d");
            int code;
            try
            {
                string b64 = Convert.ToBase64String(Encoding.Unicode.GetBytes(SignCommand(App.SignScript, App.WorkDefs)));
                var psi = new ProcessStartInfo("powershell.exe", "-NoProfile -NoLogo -ExecutionPolicy Bypass -EncodedCommand " + b64)
                {
                    UseShellExecute = true,   // its own visible console window (the key password is typed there)
                    WindowStyle = ProcessWindowStyle.Normal,
                    WorkingDirectory = App.RepoDir,
                };
                using (var p = Process.Start(psi)) { p.WaitForExit(); code = p.ExitCode; }
            }
            catch (Exception e) { Rollback(); st.Detail = S.Get("e.console", e.Message); return false; }
            if (code != 0) { Rollback(); st.Detail = S.Get("e.sigexit", code); App.Log("signing console exit " + code); return false; }
            st.Detail = "exit 0";
            return true;
        }

        public static bool VerifyWork(Step st)
        {
            int r = Sig.VerifyFile(App.WorkDefs);
            if (r != Sig.Ok) { Rollback(); st.Detail = S.Get("e.sigbad"); return false; }
            var d = DefsDoc.Load(App.WorkDefs);
            string kid = "";
            try { kid = Sig.KeyIdIn(File.ReadAllText(App.WorkDefs + ".sig", Encoding.UTF8)); } catch (Exception) { }
            st.Detail = S.Get("ld.sig.ok") + " · v" + d.Version.ToString(CultureInfo.InvariantCulture) + (kid.Length > 0 ? " · keyid " + kid : "");
            return true;
        }

        public static bool RecordPending(JObj a, Step st)
        {
            if (AdminStop(st)) return false;
            var pend = LoadPending() ?? new JObj();
            pend.Set("format", "PocketRoles.AegisBanConsole.Pending");
            pend.Set("baseSha", a.Str("baseSha"));
            pend.Set("version", a.Get("version"));
            if (!pend.Has("commit")) pend.Set("commit", "");
            var changes = pend.Arr("changes") ?? new List<object>();
            changes.Add(a.Str("desc"));
            pend.Set("changes", changes);
            var ids = pend.Arr("actions") ?? new List<object>();
            ids.Add(a.Str("id"));
            pend.Set("actions", ids);
            Json.WriteFile(App.PendingFile, pend);
            try { if (Directory.Exists(App.BackupDir)) Directory.Delete(App.BackupDir, true); } catch (Exception) { }
            var list = Journal.Load();
            a.Set("state", "signed");
            list.Add(a);
            Journal.Save(list);
            App.Log("signed v" + a.Int("version") + ": " + a.Str("desc"));
            st.Detail = S.Get("ld.pending", pend.Int("version"), changes.Count);
            return true;
        }

        public static void Discard()
        {
            var list = Journal.Load();
            foreach (var a in list) if (a.Str("state") == "signed") a.Set("state", "discarded");
            Journal.Save(list);
            foreach (var f in new[] { App.WorkDefs, App.WorkDefs + ".sig", App.PendingFile })
                try { if (File.Exists(f)) File.Delete(f); } catch (Exception) { }
            try { if (Directory.Exists(App.BackupDir)) Directory.Delete(App.BackupDir, true); } catch (Exception) { }
            App.Log("unpublished changes discarded");
        }

        // ---- publishing: git add / commit / push in the repository

        public sealed class PublishCtx
        {
            public JObj Pending;
            public bool Retry;   // the commit was made earlier; only the push is left
            public string Commit = "";
            public OpForm Form;
            /// <summary>The hashes of the [bans] lines before and after (public anyway): the only hash digits the commit message may hold.</summary>
            public readonly HashSet<string> Public = new HashSet<string>(StringComparer.Ordinal);
            public void Log(string s) { if (Form != null) Form.AppendLog(s); }
        }

        public static bool GitCheck(PublishCtx c, Step st)
        {
            if (AdminStop(st)) return false;
            c.Pending = LoadPending();
            if (c.Pending == null) { st.Detail = S.Get("e.nothing"); return false; }
            if (Sig.VerifyFile(App.WorkDefs) != Sig.Ok) { st.Detail = S.Get("e.sigbad"); return false; }
            string o;
            int code = Git.Run(App.RepoDir, "rev-parse --show-toplevel", c, 20000, out o);
            if (code == -2) { st.Detail = S.Get("e.nogit"); return false; }
            if (code != 0 || !SameDir(o.Trim(), App.RepoDir)) { st.Detail = S.Get("e.notrepo", App.RepoDir); return false; }
            Git.Run(App.RepoDir, "rev-parse --abbrev-ref HEAD", c, 20000, out o);
            string branch = o.Trim();
            if (branch != "main") { st.Detail = S.Get("e.branch", branch.Length > 0 ? branch : "?"); return false; }
            Git.Run(App.RepoDir, "remote get-url origin", c, 20000, out o);
            string url = o.Trim();
            if (url.IndexOf("wakayamachannel/PocketRoles", StringComparison.OrdinalIgnoreCase) < 0) { st.Detail = S.Get("e.remote", url.Length > 0 ? url : "?"); return false; }
            if (Git.Run(App.RepoDir, "status --porcelain=v1 -unormal", c, 30000, out o) != 0) { st.Detail = S.Get("e.git", "status"); return false; }
            var unrelated = new List<string>();
            int untracked = 0;
            foreach (var raw in o.Replace("\r\n", "\n").Split('\n'))
            {
                if (raw.Length < 4) continue;
                if (raw.StartsWith("??")) { untracked++; continue; }
                string path = raw.Substring(3);
                int arrow = path.IndexOf(" -> ", StringComparison.Ordinal);
                if (arrow >= 0) path = path.Substring(arrow + 4);
                path = path.Trim().Trim('"');
                if (path != DefsRel && path != SigRel) unrelated.Add(path);
            }
            if (unrelated.Count > 0)
            {
                string list = string.Join(", ", unrelated.GetRange(0, Math.Min(5, unrelated.Count)).ToArray()) + (unrelated.Count > 5 ? " …" : "");
                st.Detail = S.Get("e.dirty", list);
                return false;
            }
            st.Detail = "main · " + url + (untracked > 0 ? " " + S.Get("untracked", untracked) : "");
            return true;
        }

        public static bool GitFetch(PublishCtx c, Step st)
        {
            string o;
            if (Git.Run(App.RepoDir, "fetch origin main", c, 120000, out o) != 0) { st.Detail = S.Get("e.fetch"); return false; }
            if (Git.Run(App.RepoDir, "rev-list --left-right --count origin/main...HEAD", c, 20000, out o) != 0) { st.Detail = S.Get("e.git", "rev-list"); return false; }
            var p = o.Trim().Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
            int behind, ahead;
            if (p.Length < 2 || !int.TryParse(p[0], out behind) || !int.TryParse(p[1], out ahead)) { st.Detail = S.Get("e.git", "rev-list"); return false; }
            Git.Run(App.RepoDir, "rev-parse HEAD", c, 20000, out o);
            string head = o.Trim();
            string mine = c.Pending.Str("commit");
            if (behind > 0) { st.Detail = S.Get("e.behind", behind); return false; }
            if (ahead == 1 && mine.Length > 0 && head == mine) { c.Retry = true; c.Commit = head; st.Detail = "HEAD " + head.Substring(0, Math.Min(8, head.Length)) + " (push only)"; return true; }
            if (ahead > 0) { st.Detail = S.Get("e.ahead", ahead); return false; }
            st.Detail = "HEAD " + head.Substring(0, Math.Min(8, head.Length));
            return true;
        }

        public static bool Place(PublishCtx c, Step st)
        {
            if (AdminStop(st)) return false;
            if (c.Retry) { st.Detail = "—"; return true; }
            var repo = DefsDoc.Load(App.RepoDefs);
            var work = DefsDoc.Load(App.WorkDefs);
            if (repo == null || work == null) { st.Detail = S.Get("e.nodefs", App.RepoDefs); return false; }
            if (repo.CanonSha != work.CanonSha && repo.CanonSha != c.Pending.Str("baseSha")) { st.Detail = S.Get("e.basechanged"); return false; }
            if (Sig.VerifyFile(App.WorkDefs) != Sig.Ok) { st.Detail = S.Get("e.sigbad"); return false; }
            // the lines before (the repository's file, not yet replaced) and after, and those of the pending actions
            AddLineHashes(c.Public, repo);
            AddLineHashes(c.Public, work);
            var journal = Journal.Load();
            foreach (var id in Json.Strings(c.Pending.Arr("actions")))
            {
                var a = Journal.Find(journal, id);
                if (a == null) continue;
                AddLineHashes(c.Public, Json.Strings(a.Arr("sharedBefore")));
                AddLineHashes(c.Public, Json.Strings(a.Arr("sharedAfter")));
            }
            File.Copy(App.WorkDefs, App.RepoDefs, true);
            File.Copy(App.WorkDefs + ".sig", App.RepoDefs + ".sig", true);
            if (Sig.VerifyFile(App.RepoDefs) != Sig.Ok) { st.Detail = S.Get("e.sigbad"); return false; }
            st.Detail = "v" + work.Version.ToString(CultureInfo.InvariantCulture);
            return true;
        }

        /// <summary>The public commit message: each change line through <see cref="PublicLine"/> (only hash digits of listed lines; no name, no friend code, no friend-code hash).</summary>
        public static string CommitMessage(JObj pend, ICollection<string> publicHashes)
        {
            var sb = new StringBuilder();
            sb.Append("Aegis: 全体の BAN を更新（定義ファイル v").Append(pend.Int("version").ToString(CultureInfo.InvariantCulture)).Append("）\n\n");
            foreach (var l in Json.Strings(pend.Arr("changes"))) sb.Append(PublicLine(l, publicHashes)).Append('\n');   // "+ 1a2b3c4d… …" / "- …" / "~ …" / "undo: …"
            sb.Append("\n（Aegis BAN 管理で署名。名前は含めていません）\n");
            return sb.ToString();
        }

        public static bool Commit(PublishCtx c, Step st)
        {
            if (AdminStop(st)) return false;
            if (c.Retry) { st.Detail = c.Commit.Substring(0, Math.Min(8, c.Commit.Length)); return true; }
            string o;
            if (Git.Run(App.RepoDir, "add -- " + DefsRel + " " + SigRel, c, 30000, out o) != 0) { st.Detail = S.Get("e.git", "add"); return false; }
            string msg = Path.Combine(App.WorkDir, "commit-message.txt");
            File.WriteAllText(msg, CommitMessage(c.Pending, c.Public), new UTF8Encoding(false));
            if (Git.Run(App.RepoDir, "commit -F \"" + msg + "\" -- " + DefsRel + " " + SigRel, c, 60000, out o) != 0) { st.Detail = S.Get("e.git", "commit"); return false; }
            Git.Run(App.RepoDir, "rev-parse HEAD", c, 20000, out o);
            c.Commit = o.Trim();
            c.Pending.Set("commit", c.Commit);
            Json.WriteFile(App.PendingFile, c.Pending);
            st.Detail = c.Commit.Substring(0, Math.Min(8, c.Commit.Length));
            return true;
        }

        public static bool Push(PublishCtx c, Step st)
        {
            if (AdminStop(st)) return false;
            string o;
            if (Git.Run(App.RepoDir, "push origin main", c, 180000, out o) != 0) { st.Detail = S.Get("e.git", "push"); return false; }
            st.Detail = "origin/main";
            App.Log("pushed definitions v" + c.Pending.Int("version") + " (" + c.Commit + ")");
            return true;
        }

        /// <summary>After the push: the local parts of the published actions, their journal state, and the working copy removed.</summary>
        public static bool Finish(PublishCtx c, Step st)
        {
            var list = Journal.Load();
            var errors = new List<string>();
            string ver = "v" + c.Pending.Int("version").ToString(CultureInfo.InvariantCulture);
            foreach (var id in Json.Strings(c.Pending.Arr("actions")))
            {
                var a = Journal.Find(list, id);
                if (a == null || a.Str("state") != "signed") continue;
                var hist = a.Obj("localHist");
                if (hist != null) hist.Set("detail", hist.Str("detail") + " (" + ver + ", " + c.Commit.Substring(0, Math.Min(8, c.Commit.Length)) + ")");
                string err = ApplyLocal(a);
                if (err != null) errors.Add(err);
                else BanSnap.Refresh(new HashSet<string>(Json.Strings(a.Arr("hashes"))));
                a.Set("state", "pushed");
                MarkUndone(list, a);
            }
            Journal.Save(list);
            foreach (var f in new[] { App.WorkDefs, App.WorkDefs + ".sig", App.PendingFile })
                try { if (File.Exists(f)) File.Delete(f); } catch (Exception) { }
            if (errors.Count > 0) { st.State = 3; st.Detail = errors[0]; }
            else st.Detail = ver;
            return true;
        }

        static bool SameDir(string gitTop, string dir)
        {
            try
            {
                string a = Path.GetFullPath(gitTop.Replace('/', '\\')).TrimEnd('\\'), b = Path.GetFullPath(dir).TrimEnd('\\');
                return string.Equals(a, b, StringComparison.OrdinalIgnoreCase);
            }
            catch (Exception) { return false; }
        }

        // ---- report zips

        static readonly string[] AegisTokens = { "CheatDetector:", "AegisBans:", "AegisEvidence:", "AegisMore", "Aegis rules:", "SelfScan:", "AntiCheat:", "NgWords: #" };

        /// <summary>v0.5.5 「A」: a record's backing file in a zip (evidence\&lt;id&gt;.log: the lines of a deleted log that back it).</summary>
        static readonly Regex BackingLogName = new Regex("^AEG-[0-9A-Za-z]{5,6}\\.log$", RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);

        /// <summary>
        /// Reads a report zip (never extracted to disk by its own paths): evidence files (AEG-*.json anywhere in it) are
        /// copied, after a format check, and the Aegis lines of its logs collected, into imports\&lt;time&gt;-&lt;zip name&gt;\.
        /// v0.5.5: every "AegisEvidence:" line is kept (the log check needs them: <see cref="LogCheck"/>), beyond the 5000
        /// other lines, and the lines of the backing files (AEG-&lt;id&gt;.log) have a cap of their own, so a busy log cannot
        /// crowd out a kept record's detection line (review 2026-09-23); source.txt gets host=&lt;the host's name the owner gave&gt; and pc=&lt;a mark of the PC the zip came from&gt;
        /// (<see cref="PcMark"/>) for the two-hosts rule (<see cref="HostCount"/>).
        /// </summary>
        public static bool Import(string zip, string hostLabel, Step st, ref int evTotal, ref int lineTotal)
        {
            int ev = 0, lines = 0;
            string name = Path.GetFileNameWithoutExtension(zip);
            var safe = new StringBuilder();
            foreach (char ch in name) safe.Append(char.IsLetterOrDigit(ch) || ch == '-' || ch == '_' || ch == '.' ? ch : '_');
            string baseName = DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + "-" + (safe.Length > 40 ? safe.ToString(0, 40) : safe.ToString());
            string dest = Path.Combine(App.ImportDir, baseName);
            for (int n = 2; Directory.Exists(dest) && n < 100; n++) dest = Path.Combine(App.ImportDir, baseName + "-" + n.ToString(CultureInfo.InvariantCulture));
            var collected = new List<string>();
            int other = 0, written = 0, kept = 0;   // kept: the lines of the backing files (AEG-….log), with a cap of their own
            bool onePlayer = false;   // review 2026-09-23: this zip is the launcher's one-player evidence export (an appeal)
            string system = "", state = "";
            try
            {
                using (var za = ZipFile.OpenRead(zip))
                {
                    if (za.Entries.Count > 5000) throw new InvalidDataException("more than 5000 entries");
                    long total = 0;
                    foreach (var e in za.Entries)
                    {
                        string full = e.FullName.Replace('\\', '/');
                        string leaf = full.Substring(full.LastIndexOf('/') + 1);
                        if (leaf.Length == 0) continue;
                        total += e.Length;
                        if (total > 512L * 1024 * 1024) break;
                        if (leaf.StartsWith("AEG-", StringComparison.OrdinalIgnoreCase) && leaf.EndsWith(".json", StringComparison.OrdinalIgnoreCase))
                        {
                            if (e.Length > 1024 * 1024) continue;
                            string text;
                            using (var sr = new StreamReader(e.Open(), new UTF8Encoding(false), true)) text = sr.ReadToEnd();
                            JObj o;
                            try { o = Json.Parse(text) as JObj; } catch (FormatException) { continue; }
                            var info = EvInfo.FromObj(o, "", "");
                            if (info == null) continue;
                            Directory.CreateDirectory(dest);
                            File.WriteAllText(Path.Combine(dest, info.Id + ".json"), Json.Write(o) + Json.NL, new UTF8Encoding(false));
                            ev++;
                            continue;
                        }
                        if (full == "export.txt" && e.Length <= 64 * 1024)
                        {
                            // v0.5.5 review 2026-09-23: the launcher writes "PocketRoles one-player evidence <time>" as the first
                            // line of the export it makes for an appeal. source.txt keeps that, so the author can tell these
                            // records came from one player's appeal export and not from an ordinary report zip (they are all of
                            // that player's records on that PC, of any age, and their log check may rest on the kept 2 lines).
                            string head;
                            using (var sr0 = new StreamReader(e.Open(), new UTF8Encoding(false), true)) head = sr0.ReadLine() ?? "";
                            if (head.IndexOf("one-player evidence", StringComparison.OrdinalIgnoreCase) >= 0) onePlayer = true;
                        }
                        if (full == "launcher-state.json" && e.Length <= 64 * 1024)
                        {
                            using (var sr = new StreamReader(e.Open(), new UTF8Encoding(false), true)) state = sr.ReadToEnd();
                            continue;
                        }
                        if (full == "system.txt" && e.Length <= 64 * 1024)
                            using (var sr = new StreamReader(e.Open(), new UTF8Encoding(false), true)) system = sr.ReadToEnd();
                        if ((leaf.EndsWith(".log", StringComparison.OrdinalIgnoreCase) || leaf.EndsWith(".txt", StringComparison.OrdinalIgnoreCase)) && e.Length <= 256L * 1024 * 1024)
                        {
                            // v0.5.5 review 2026-09-23: a backing file (AEG-….log: at most 2 lines kept when that day's log was
                            // deleted) has its own room, so a busy LogOutput.log can never use up the 5000 "other" lines before
                            // the zip's evidence/ folder is read (it comes last) and leave a kept record without its detection line
                            bool backing = BackingLogName.IsMatch(leaf);
                            using (var sr = new StreamReader(e.Open(), new UTF8Encoding(false), true))
                            {
                                string line;
                                while ((line = sr.ReadLine()) != null)
                                {
                                    bool ev0 = line.IndexOf("AegisEvidence:", StringComparison.Ordinal) >= 0;
                                    if (backing ? kept >= 4000 : (ev0 ? written >= 20000 : other >= 5000))
                                    {
                                        if (backing ? kept >= 4000 : (written >= 20000 && other >= 5000)) break;
                                        continue;
                                    }
                                    foreach (var tok in AegisTokens)
                                        if (line.IndexOf(tok, StringComparison.Ordinal) >= 0)
                                        {
                                            collected.Add("[" + leaf + "] " + (line.Length > 600 ? line.Substring(0, 600) + "…" : line));
                                            if (backing) kept++; else if (ev0) written++; else other++;
                                            break;
                                        }
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception e) { st.Detail = S.Get("e.zip", e.Message); App.Log("import " + Path.GetFileName(zip) + ": " + e.Message); return false; }
            if (collected.Count > 0)
            {
                Directory.CreateDirectory(dest);
                File.WriteAllLines(Path.Combine(dest, "aegis-log.txt"), collected.ToArray(), new UTF8Encoding(false));
                lines = collected.Count;
            }
            string host = Proposal.OneLine(Audit.Mask(hostLabel ?? ""), 40), pc = PcMark(system, state);
            if (Directory.Exists(dest))
                File.WriteAllText(Path.Combine(dest, "source.txt"), Path.GetFileName(zip) + "\r\n" + DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture) + "\r\n"
                    + "host=" + host + "\r\n" + "pc=" + pc + "\r\n" + (onePlayer ? "kind=one-player\r\n" : ""), new UTF8Encoding(false));
            evTotal += ev; lineTotal += lines;
            st.Detail = S.Get("step.zip.d", ev, lines);
            if (ev == 0 && lines == 0) st.State = 3;
            App.Log("imported " + Path.GetFileName(zip) + ": " + ev + " evidence, " + lines + " lines" + (pc.Length > 0 ? ", pc " + pc : "") + (onePlayer ? ", one-player (appeal export)" : ""));
            return true;
        }

        /// <summary>
        /// A mark of the PC a report zip came from ("" when the zip does not tell): 16 hex digits of a SHA-256 of its
        /// system.txt's OS and culture lines and the time its launcher last built the mod (launcher-state.json
        /// lastBuiltAt). Two zips with the same mark count as one host (the two-hosts rule); nothing personal goes in.
        /// </summary>
        public static string PcMark(string systemTxt, string stateJson)
        {
            string os = "", culture = "", built = "";
            foreach (var raw in (systemTxt ?? "").Replace("\r\n", "\n").Split('\n'))
            {
                int c = raw.IndexOf(':');
                if (c <= 0) continue;
                string k = raw.Substring(0, c).Trim(), v = raw.Substring(c + 1).Trim();
                if (k == "OS") os = v; else if (k == "culture") culture = v;
            }
            var m = Regex.Match(stateJson ?? "", "\"lastBuiltAt\"\\s*:\\s*\"([^\"]{1,40})\"");
            if (m.Success) built = m.Groups[1].Value;
            if (os.Length == 0 || built.Length == 0) return "";
            return Hashes.Sha256(Encoding.UTF8.GetBytes("PocketRoles.Aegis.HostPc|" + os + "|" + culture + "|" + built)).Substring(0, 16);
        }
    }

    /// <summary>git in the repository (Git for Windows on PATH): output to the operation's log; no terminal prompt.</summary>
    public static class Git
    {
        public static string Exe = "git";

        /// <summary>Exit code; -2 when git cannot be started, -1 on a timeout.</summary>
        public static int Run(string repo, string args, Ops.PublishCtx ctx, int timeoutMs, out string stdout)
        {
            stdout = "";
            var outB = new StringBuilder();
            var errB = new StringBuilder();
            if (ctx != null) ctx.Log("> git " + args);
            try
            {
                var psi = new ProcessStartInfo(Exe, "-C \"" + repo + "\" -c core.quotepath=false " + args)
                {
                    UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true, CreateNoWindow = true,
                    StandardOutputEncoding = Encoding.UTF8, StandardErrorEncoding = Encoding.UTF8,
                };
                psi.EnvironmentVariables["GIT_TERMINAL_PROMPT"] = "0";
                using (var p = new Process { StartInfo = psi })
                {
                    p.OutputDataReceived += (s, e) => { if (e.Data != null) lock (outB) outB.Append(e.Data).Append('\n'); };
                    p.ErrorDataReceived += (s, e) => { if (e.Data != null) lock (errB) errB.Append(e.Data).Append('\n'); };
                    p.Start();
                    p.BeginOutputReadLine();
                    p.BeginErrorReadLine();
                    if (!p.WaitForExit(timeoutMs))
                    {
                        try { p.Kill(); } catch (Exception) { }
                        if (ctx != null) ctx.Log("(timeout)");
                        return -1;
                    }
                    p.WaitForExit();
                    lock (outB) stdout = outB.ToString();
                    string err;
                    lock (errB) err = errB.ToString();
                    if (ctx != null) { ctx.Log(stdout); ctx.Log(err); if (p.ExitCode != 0) ctx.Log("(exit " + p.ExitCode + ")"); }
                    return p.ExitCode;
                }
            }
            catch (System.ComponentModel.Win32Exception e) { if (ctx != null) ctx.Log(e.Message); return -2; }
        }
    }

