            lockTimer.Interval = 15000;
            lockTimer.Tick += (s, e) => LockTick();
            // v0.5.5 (2026-09-23): the screen lock (Win+L), sleep, a user switch or a log off lock the console too — walking
            // away should not leave it open for the idle minutes. The handlers are taken off again in CloseDown.
            try
            {
                switchLock = (s, e) => { if (Session.LocksOnSwitch(e.Reason)) LockAway(); };
                powerLock = (s, e) => { if (e.Mode == PowerModes.Suspend) LockAway(); };
                endLock = (s, e) => LockAway();
                SystemEvents.SessionSwitch += switchLock;
                SystemEvents.PowerModeChanged += powerLock;
                SystemEvents.SessionEnding += endLock;
            }
            catch (Exception e) { App.Log("the away lock could not be set up: " + e.Message); }
            Shown += (s, e) =>
            {
                uiReady = true;
