            KeyDown += (s, e) =>
            {
                if (e.Control && e.KeyCode == Keys.F) { search.Focus(); search.SelectAll(); e.Handled = true; }
                else if (e.KeyCode == Keys.F5) { Reload(true); e.Handled = true; }
                else if (e.KeyCode == Keys.Escape && search.Focused && search.Text.Length > 0) { search.Text = ""; e.Handled = true; }
            };
        }

