        /// <summary>The banner's height for its (wrapped) text.</summary>
        void FitBanner()
        {
            if (!banner.Visible) return;
            int w = Math.Max(Ui.S(200), banner.ClientSize.Width - banner.Padding.Horizontal);
            var sz = TextRenderer.MeasureText(bannerText.Text, bannerText.Font, new Size(w, 0), TextFormatFlags.WordBreak);
            int h = sz.Height + banner.Padding.Vertical + Ui.S(4);
            if (banner.Height != h) banner.Height = h;
        }

        void ShowBanner(Audit.Check c)
        {
            if (c == null || c.Ok) { banner.Visible = false; return; }
            bannerText.Font = Art.UiFont(10f, FontStyle.Bold);
            bannerText.Text = "⚠ " + S.Get("au.broken", c.At) + "   " + Audit.Explain(c, S.Idx) + " " + S.Get("au.d.note");
            banner.Visible = true;
            FitBanner();
        }

        void LayoutHeader()
        {
            int y = Ui.S(14), x = header.Width - Ui.S(16);
            foreach (Control c in new Control[] { bSettings, bReload })
            {
                c.Location = new Point(x - c.Width, y);
                x -= c.Width + Ui.S(8);
            }
            cLang.Location = new Point(x - cLang.Width, y + Math.Max(0, (bSettings.Height - cLang.Height) / 2));
            x -= cLang.Width + Ui.S(8);
            bLock.Location = new Point(x - bLock.Width, y);
        }

        // ---- v0.5.5 the lock

        /// <summary>The lock chip's text and colour (locked: amber; unlocked: green with the minutes left).</summary>
        void UpdateLockUi()
        {
            string t = Session.Unlocked ? S.Get("lk.open", Session.Describe(S.Idx), Session.MinutesLeft) : S.Get("lk.locked");
            if (t == lockShown) return;
            lockShown = t;
            bLock.Text = t;
            bLock.Accent = Session.Unlocked ? (Session.OwnerActive ? Art.Green1 : Art.Teal1) : Art.Amber1;
            bLock.AutoSize = false; bLock.Size = bLock.MinimumSize; bLock.AutoSize = true;
            LayoutHeader();
        }

        /// <summary>
        /// The idle lock (15 minutes without input). v0.5.5 review: only an operation whose steps are running counts as input
        /// (<see cref="OpForm.AnyRunning"/>: the signing console, a push); not a reload (the file watch reloads whenever the
        /// game writes aegis-bans.json) and not an operation window left open after its steps.
        /// </summary>
        void LockTick()
        {
            if (OpForm.AnyRunning) { Session.Touch(); return; }
            if (Session.IdleExpired) { LockNow("lk.idle", Session.IdleMinutes); return; }
            UpdateLockUi();
        }

        void LockNow(string why, params object[] args)
        {
            Session.Lock();
            UpdateLockUi();
            status.Set(S.Get(why, args), Art.Amber1);
        }

        /// <summary>
        /// v0.5.5 (2026-09-23 「乗っ取られたら…」) Windows says the owner walked away (the screen locked, the PC is going to
        /// sleep, another user took over, Windows is shutting down): lock at once. These come in on another thread, so the
        /// session is locked here and the window is only told afterwards; if the window is gone, the lock still happened.
        /// </summary>
        void LockAway()
        {
            if (!Session.Unlocked) return;
            Session.Lock();
            try
            {
                if (IsDisposed || !IsHandleCreated) return;
                BeginInvoke(new Action(() => { UpdateLockUi(); status.Set(S.Get("lk.away"), Art.Amber1); }));
            }
            catch (Exception) { }
        }

        /// <summary>Before any change: unlocked already, or the unlock now. False when the action must not go on (not unlocked, or the mode changed and the data was read again).</summary>
        bool Guard()
        {
            if (Session.Unlocked) { Session.Touch(); return true; }
            status.Set(S.Get("lk.need"), Art.Amber1);
            return DoUnlock();
        }

        /// <summary>Right before an action runs (after its confirmation): still unlocked (the idle lock may have come in between).</summary>
        bool StillUnlocked()
        {
            if (Session.Unlocked) return true;
            status.Set(S.Get("lk.expired"), Art.Amber1);
            return false;
        }

        /// <summary>
        /// The unlock (本人確認): Windows Hello, the signing key (the key challenge in a visible console) or the code. The
        /// owner mode needs the key signal and a proof (<see cref="Session"/>); when the mode differs from what was loaded,
        /// the data is read again and false is returned (the user presses the button again).
        /// </summary>
        bool DoUnlock()
        {
            if (busy > 0) return false;
            string method;
            using (var d = new UnlockDialog())
            {
                if (d.ShowDialog(this) != DialogResult.OK) return false;
                method = d.Method;
            }
            string mode, how;
            if (method == "revoke") { DoRevokeProofs(); return false; }   // v0.5.5 (2026-09-23): from the locked console too
            if (method == "key-request")
            {
                if (!RunKeyChallenge()) return false;
                Session.KeyProven = true;
                mode = "owner"; how = "key";
            }
            else if (method == "hello")
            {
                bool owner = App.KeySignal && (Session.KeyProven || UnlockProof.Token(DateTime.UtcNow) != null);
                mode = owner ? "owner" : "admin"; how = owner ? "hello+proof" : "hello";
            }
            else if (method == "code") { mode = "admin"; how = "code"; }
            else return false;
            Session.Unlock(mode, how);
            Record(new AuditRec { Action = "unlock", Result = "as." + mode });
            UpdateLockUi();
            status.Set(S.Get("lk.done", Session.Describe(S.Idx), Session.IdleMinutes), Session.OwnerActive ? Art.Green1 : Art.Teal1);
            bool admin = mode != "owner";
            if (admin != App.Admin)
            {
                App.Admin = admin;
                App.Log("mode now " + (admin ? "admin" : "owner") + " (unlock)");
                ApplyLanguage();
                Reload(true);
                string changed = S.Get(admin && App.KeySignal ? "lk.modechanged.k" : "lk.modechanged", Session.Describe(S.Idx));
                afterReload = changed;   // (the reload's list refresh resets the status bar: shown again when it is done)
                status.Set(changed, Art.Amber1);
                return false;
            }
            return true;
        }

        /// <summary>The key challenge on the scan screen: the console signs a fresh number; the proof is checked here.</summary>
        bool RunKeyChallenge()
        {
            string nonce = UnlockProof.NewNonce();
            string outPath = UnlockProof.ResponsePath(nonce);
            var steps = new List<Step>
            {
                new Step(S.Get("ul.step.key"), st => Ops.KeyChallenge(nonce, outPath, st)),
                new Step(S.Get("ul.step.verify"), st => Ops.VerifyChallenge(nonce, outPath, st)),
            };
            // (the days of Windows Hello alone only where Windows Hello can be used)
            bool hello = Hello.LastAvailability == Hello.Available;
            using (var f = new OpForm(S.Get("ul.op"), steps, false, null) { OkText = hello ? S.Get("ul.ok", UnlockProof.TokenDays) : S.Get("ul.ok.nohello") })
            {
                RunOp(f);
                return f.Ok;
            }
        }

        /// <summary>
        /// v0.5.5 (2026-09-23 「乗っ取られたら Windows Hello で管理が渡らない？」) Before anything that reaches other hosts or
        /// players: unlocked, in the owner mode, AND the key challenge passed in THIS run. The stored Windows Hello proof is
        /// not enough here — that is the whole point: someone who took this PC over but does not know the key password stops
        /// at this line. When the key has not been proven yet, the challenge is offered right here (it costs one password,
        /// once per run, in the signing script's own console window; this app never sees it).
        /// <paramref name="opKey"/> is the "ak.*" name of the operation, for the question and for the audit line.
        /// </summary>
        bool KeyGate(string opKey)
        {
            if (!Guard()) return false;
            if (Session.KeyProven && Session.OwnerActive) return true;
            string what = S.Has("ak." + opKey) ? S.Get("ak." + opKey) : opKey;
            if (App.Admin || !App.KeySignal)
            {
                status.Set(S.Get(App.KeySignal ? "kg.needowner" : "e.admin"), Art.Amber1);
                ShowNotice(S.Get("kg.title"), S.Get(App.KeySignal ? "kg.needowner" : "e.admin"), Art.Amber1);
                return false;
            }
            var bullets = new List<string> { S.Get("kg.what", what), S.Get("kg.p.why"), S.Get("kg.p.once") };
            if (!ConfirmNow(S.Get("kg.head"), bullets)) { KeyRefused(opKey); return false; }
            if (!RunKeyChallenge()) { status.Set(S.Get("kg.failed"), Art.Amber1); KeyRefused(opKey); return false; }
            Session.KeyProven = true;
            // the session becomes an owner-by-key one: the header, the audit lines and 「前回からの解錠」 all say "key"
            Session.Unlock("owner", "key");
            Record(new AuditRec { Action = "unlock", Result = "as.owner" });
            UpdateLockUi();
            status.Set(S.Get("kg.done"), Art.Green1);
            return Session.OwnerActive;
        }

        /// <summary>v0.5.5 (2026-09-23): an action that reaches other people was stopped for want of the key check — the owner sees it at the next start.</summary>
        void KeyRefused(string opKey)
        {
            Record(new AuditRec { Action = "gate.key", Name = S.Has("ak." + opKey) ? S.In(0, "ak." + opKey) : opKey, Result = "refused" });
        }

        /// <summary>
        /// v0.5.5 (2026-09-23) 「保存した鍵の記録を今すぐ無効にする」: every stored key proof on this PC stops counting at once
        /// (<see cref="UnlockProof.Revoke"/>). It needs no unlock, so it works from a locked console, and the audit log keeps
        /// the line: someone in the owner mode cannot take it out again without breaking the chain.
        /// </summary>
        void DoRevokeProofs()
        {
            var bullets = new List<string> { S.Get("rv.p.1"), S.Get("rv.p.2"), S.Get("rv.p.3"), S.Get("rv.p.4") };
            if (!ConfirmNow(S.Get("rv.ask"), bullets)) return;
            bool logged = UnlockProof.Revoke(DateTime.UtcNow);
            UpdateLockUi();
            string said = S.Get(logged ? "rv.done" : "rv.failed");
            ShowNotice(S.Get("rv.title"), said, logged ? Art.Green1 : Art.Amber1);
            afterReload = said;   // (the reload's list refresh resets the status bar: said again when it is done)
            status.Set(said, logged ? Art.Green1 : Art.Amber1);
            Reload(true);
        }

        /// <summary>On close: the seen mark (the audit lines this user has seen), then the ban file compared once more (changes go to the audit log, shown at the next start), then locked.</summary>
        void CloseDown()
        {
            if (closedDown) return;
            closedDown = true;
            // v0.5.5 (2026-09-23): the away lock's handlers are static events of Windows: they must be taken off again
            try
            {
                if (switchLock != null) { SystemEvents.SessionSwitch -= switchLock; switchLock = null; }
                if (powerLock != null) { SystemEvents.PowerModeChanged -= powerLock; powerLock = null; }
                if (endLock != null) { SystemEvents.SessionEnding -= endLock; endLock = null; }
            }
            catch (Exception e) { App.Log("the away lock could not be taken off: " + e.Message); }
            try
            {
                int n;
                string last = Audit.Tail(out n);
                SeenMarks.Put(n, last);
                bool first, missing;
                BanSnap.Observe(App.BansPath, true, out first, out missing);   // (open until now: a snapshot gone meanwhile is reported)
            }
            catch (Exception e) { App.Log("close: " + e.Message); }
            Session.Lock();
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            base.OnFormClosing(e);
            if (!e.Cancel) CloseDown();
        }

        /// <summary>The action bar's height for its wrapped rows of buttons (a FlowLayoutPanel docked to the bottom does not grow by itself).</summary>
        void FitActs()
        {
            int w = acts.ClientSize.Width - acts.Padding.Horizontal;
            if (w <= 0 || !acts.Visible) return;
            int x = 0, rowH = 0, h = 0;
            foreach (Control c in acts.Controls)
            {
                if (!c.Visible) continue;
                var pref = c.GetPreferredSize(Size.Empty);
                int cw = Math.Max(c.Width, pref.Width) + c.Margin.Horizontal, ch = Math.Max(c.Height, pref.Height) + c.Margin.Vertical;
                if (x > 0 && x + cw > w) { h += rowH; x = 0; rowH = 0; }
                x += cw;
                rowH = Math.Max(rowH, ch);
            }
            h += rowH + acts.Padding.Vertical;
            if (acts.Height != h) { acts.Height = h; split.Panel2.PerformLayout(); }
        }

        bool fitQueued;

        /// <summary>FitActs after the current layout pass (changing a docked control's height inside its own Resize leaves it at a stale place).</summary>
        void QueueFit()
        {
            if (!IsHandleCreated) return;
            if (fitQueued) return;
            fitQueued = true;
            BeginInvoke(new Action(() => { fitQueued = false; FitActs(); }));
        }

        void ResetFonts()
        {
            Font = Art.UiFont(9.5f, FontStyle.Regular);
            header.ResetFonts(); status.ResetFonts(); dhead.ResetFonts();
            fH = Art.RichFont(10.5f, FontStyle.Bold);
            fK = Art.RichFont(9.5f, FontStyle.Regular);
            fV = Art.RichFont(9.5f, FontStyle.Regular);
            fMono = Art.Mono(9f);
            rtb.Font = fV;   // the base character format carries the language's character set too
            foreach (var g in new[] { gBans, gCands })
            {
                g.ColumnHeadersDefaultCellStyle.Font = Art.UiFont(9f, FontStyle.Bold);
                g.DefaultCellStyle.Font = Art.UiFont(9.5f, FontStyle.Regular);
            }
            foreach (Control c in new Control[] { search, cState, cScope, cLang, lCount }) c.Font = Font;
        }

        void ApplyLanguage()
        {
            ResetFonts();
            Text = S.Get("title") + (App.Admin ? " — " + S.Get("mode.admin") : "");
            bSettings.Text = S.Get("settings");
            bReload.Text = S.Get("reload");
            bImport.Text = S.Get("import");
            bDiscard.Text = S.Get("b.discard");
            vBans.Text = S.Get("view.bans");
            Native.Cue(search, S.Get("search.cue"));
            filling = true;
            int si = Math.Max(0, cState.SelectedIndex), sc = Math.Max(0, cScope.SelectedIndex);
            cState.Items.Clear(); cState.Items.AddRange(new object[] { S.Get("f.active"), S.Get("f.ended"), S.Get("f.all") });
            cScope.Items.Clear(); cScope.Items.AddRange(new object[] { S.Get("f.both"), S.Get("f.local"), S.Get("f.shared") });
            cState.SelectedIndex = si; cScope.SelectedIndex = sc;
            filling = false;
            string[] bans = { "col.name", "col.date", "col.rule", "col.level", "col.source", "col.ev", "col.rep" };
            for (int i = 0; i < bans.Length; i++) gBans.Columns[i].HeaderText = S.Get(bans[i]);
            string[] cands = { "col.name", "col.date", "col.rule", "col.strength", "col.kind", "col.from" };
            for (int i = 0; i < cands.Length; i++) gCands.Columns[i].HeaderText = S.Get(cands[i]);
            tEv.Text = S.Get("tab.ev"); tHist.Text = S.Get("tab.hist"); tPolicy.Text = S.Get("tab.policy");
            aCopy.Text = S.Get("b.copy"); aReply.Text = S.Get("b.reply"); aUnban.Text = S.Get(App.Admin ? "b.unban.pc" : "b.unban"); aShare.Text = S.Get("b.share");
            aPeriod.Text = S.Get(App.Admin ? "b.period.pc" : "b.period"); aUndo.Text = S.Get("b.undo"); aDismiss.Text = S.Get("b.dismiss");
            aPropUnban.Text = S.Get("b.prop.unban"); aPropShare.Text = S.Get("b.prop.share"); aAdd.Text = S.Get("b.add"); bPaste.Text = S.Get("b.paste");
            // DarkButton only grows (AutoSizeMode.GrowOnly): shrink to the new text
            foreach (var b in new[] { bSettings, bReload, bImport, bDiscard, vBans, vCands, tEv, tHist, tPolicy, aCopy, aReply, aUnban, aShare, aPeriod, aUndo, aDismiss, bPublish, aPropUnban, aPropShare, aAdd, bPaste })
            { b.AutoSize = false; b.Size = b.MinimumSize; b.AutoSize = true; }
            lockShown = "";
            UpdateLockUi();
            LayoutHeader();
            status.RightText = App.BansPath;
            if (data != null) { FillAll(); UpdateChips(); ShowBanner(data.Chain); } else { ShowDetail(); status.Set(S.Get("m.ready"), Ui.Muted); }
            header.Invalidate();
        }

        // ---- busy look

        void SetBusy(bool on)
        {
            busy = Math.Max(0, busy + (on ? 1 : -1));
            bool b = busy > 0;
            header.Busy = b; scan.Busy = b; status.Busy = b;
            if (b) anim.Start(); else { anim.Stop(); header.Invalidate(); scan.Invalidate(); status.Invalidate(); }
        }

        // ---- loading

        void Reload(bool animate)
        {
            if (busy > 0) return;
            SetBusy(true);
            var snap = new Snapshot { First = firstLoad };
            // v0.5.5 the scan also checks: the imported records against their logs, the audit log's chain, the ban file
            // against the snapshot (changes outside the console), and who may do what (the lock, the key, Windows Hello)
            var steps = new List<Step>
            {
                new Step(S.Get("ld.bans"), st => Loader.Bans(snap, st)),
                new Step(S.Get("ld.ev"), st => Loader.Evidence(snap, st)),
                new Step(S.Get("ld.defs"), st => Loader.Defs(snap, st)),
                new Step(S.Get("ld.sig"), st => Loader.Signature(snap, st)),
                new Step(S.Get("ld.cand"), st => Loader.Rows(snap, st)),
                new Step(S.Get("ld.audit"), st => Loader.AuditStep(snap, st)),   // (v0.5.5 review: before the imports: the report hosts' trust comes from its verified lines)
                new Step(S.Get("ld.imp"), st => Loader.Imports(snap, st)),
                new Step(S.Get("ld.outside"), st => Loader.Outside(snap, st)),
                new Step(S.Get("ld.lock"), st => Loader.Lock(snap, st)),
            };
            bool wasFirst = firstLoad;
            firstLoad = false;
            if (animate)
            {
                overlay.Steps.Clear();
                overlay.Steps.AddRange(steps);
                overlay.Title = S.Get("ld.title");
                overlay.Result = "";
                overlay.Running = true;
                overlay.Visible = true;
                overlay.BringToFront();
            }
            Runner.Start(this, steps, animate ? 200 : 0, ok =>
            {
                data = snap;
                SetBusy(false);
                FillAll();
                UpdateChips();
                ShowBanner(snap.Chain);
                if (afterReload.Length > 0) { status.Set(afterReload, Art.Amber1); afterReload = ""; }   // (FillAll resets an amber status)
                AfterLoad(snap, wasFirst);
                BeginInvoke(new Action(NoticePaused));   // D-35: a host the last lift paused (3 in the last 30 days since 9/23) and its shared bans in effect
                if (animate)
                {
                    overlay.Running = false;
                    overlay.ResultKind = 2;
                    overlay.Result = S.Get("ld.done");
                    overlay.Invalidate();
                    var hide = new System.Windows.Forms.Timer { Interval = 650 };
                    hide.Tick += (s, e) => { hide.Stop(); hide.Dispose(); overlay.Visible = false; };
                    hide.Start();
                }
            });
        }

        /// <summary>
        /// v0.5.5 after a load: the first one shows 「前回からの変化」 (the audit lines since this user last closed the
        /// console, and the bans changed outside it); later ones show a change by the game in the status bar and one from
        /// anywhere else in the same dialog.
        /// </summary>
        void AfterLoad(Snapshot snap, bool first)
        {
            var outside = snap.Outside ?? new List<BanSnap.Change>();
            var ops = first ? snap.SinceOps : new List<AuditRec>();
            var notes = snap.Notes ?? new List<string>();
            bool other = outside.Exists(c => !c.Mod);
            if (!first && outside.Count > 0 && !other && notes.Count == 0) { status.Set(S.Get("m.outside.mod", outside.Count), Art.Teal1); return; }
            if (ops.Count == 0 && outside.Count == 0 && notes.Count == 0) return;
            BeginInvoke(new Action(() =>
            {
                if (IsDisposed) return;
                using (var d = new SinceDialog(ops, outside, notes)) d.ShowDialog(this);
            }));
        }

        void Watch()
        {
            if (busy > 0 || data == null || data.Store == null) return;
            DateTime w; long l;
            bool exists = BanStore.Stat(App.BansPath, out w, out l);
            DateTime evw = DateTime.MinValue;
            try { var di = new DirectoryInfo(App.EvidenceDir); if (di.Exists) evw = di.LastWriteTimeUtc; } catch (Exception) { }
            if (exists != data.Store.Exists || (exists && (w != data.Store.Write || l != data.Store.Length)) || evw != data.EvDirWrite)
            {
                Reload(false);
                status.Set(S.Get("m.reloaded"), Art.Teal1);
            }
        }

        void UpdateChips()
        {
            header.Chips.Clear();
            bPaste.Visible = !App.Admin;
            if (App.Admin) header.Chips.Add(new Badge(S.Get("mode.admin"), Art.Amber1));
            if (data == null) { header.Invalidate(); return; }
            int total = 0;
            foreach (var r in data.Rows) if (r.IsLocal) total++;
            header.Chips.Add(new Badge(S.Get("chip.bans", total, data.Active), Art.Teal1));
            if (data.Repo == null) header.Chips.Add(new Badge(S.Get(App.Admin ? "chip.nolist" : "chip.norepo"), Art.Amber1, "⚠"));
            else
            {
                header.Chips.Add(new Badge(App.Admin && App.SharedSource.Length > 0
                    ? S.Get("chip.shared.src", data.Repo.Version, data.Repo.DistinctHashes(), S.Get("src.defs." + App.SharedSource))
                    : S.Get("chip.shared", data.Repo.Version, data.Repo.DistinctHashes()), Ui.Violet));
                // v0.5.5 review: good ✓, a missing file ⚠, a bad signature ✕ (the mark as well as the colour)
                header.Chips.Add(data.RepoSig == Sig.Ok ? new Badge(S.Get("ld.sig.ok"), Art.Green1, "✓")
                    : data.RepoSig == Sig.Missing ? new Badge(S.Get("ld.sig.none"), Art.Amber1, "⚠") : new Badge(S.Get("ld.sig.bad"), Art.Red1, "✕"));
            }
            if (data.Pending != null && !App.Admin) header.Chips.Add(new Badge(S.Get("ld.pending", data.PendingVersion, data.PendingCount), Art.Amber1));
            header.Invalidate();
            bool pend = data.Pending != null && !App.Admin;   // admin mode never signs or publishes
            bPublish.Visible = pend; bDiscard.Visible = pend;
            if (pend) { bPublish.Text = S.Get("b.publishn", data.PendingVersion, data.PendingCount); bPublish.AutoSize = false; bPublish.Size = bPublish.MinimumSize; bPublish.AutoSize = true; }
            vCands.Text = S.Get("view.cand", data.Cands.Count);
            vCands.AutoSize = false; vCands.Size = vCands.MinimumSize; vCands.AutoSize = true;
        }

        // ---- search

        static readonly Regex HexRe = new Regex("^[0-9a-f]{8,64}$"), PuidRe = new Regex("^[0-9a-f]{32}$"), EvRe = new Regex("^AEG-[0-9A-Z]{1,6}$", RegexOptions.IgnoreCase);

        void ApplySearch()
        {
            string q = search.Text.Trim().Replace((char)0xFF03, '#');   // a friend code typed with a full-width ＃
            q = Replies.NumberQuery(q);   // v0.5.5 review: a reply's number pasted as it is (「共有 BAN 1a2b3c4d」, 「（AEG-7F3K2）」)
            string ql = q.ToLowerInvariant();
            searchHash = ""; searchNorm = "";
            if (q.Length == 0) searchMode = 0;
            else if (EvRe.IsMatch(q)) { searchMode = 4; searchNorm = q.ToUpperInvariant(); }
            else if (q.IndexOf('#') > 0 || PuidRe.IsMatch(ql)) { searchMode = 2; searchHash = Hashes.HashOf(q); }
            else if (HexRe.IsMatch(ql)) { searchMode = 3; searchNorm = ql; }
            else { searchMode = 1; searchNorm = ql; }
            FillAll();
        }

        bool Hit(Row r)
        {
            switch (searchMode)
            {
                case 1: return r.Name.ToLowerInvariant().Contains(searchNorm);
                case 2: return searchHash.Length > 0 && (r.Hash == searchHash || r.PuidHash == searchHash);
                case 3: return r.Hash.StartsWith(searchNorm) || (r.PuidHash.Length > 0 && r.PuidHash.StartsWith(searchNorm)) || r.Name.ToLowerInvariant().Contains(searchNorm);
                // v0.5.5: also the evidence linked to a row only on the shared list; v0.5.5 review: and the number its reply
                // names and every evidence ID this console's history kept for the player (a shared ban seen here, for one)
                case 4: return r.Evidence.ToUpperInvariant().StartsWith(searchNorm) || (r.Ev != null && r.Ev.Id.StartsWith(searchNorm)) || ReplyIdHit(r);
            }
            return false;
        }

        bool ReplyIdHit(Row r)
        {
            if (data == null) return false;
            if (Replies.FieldsOf(r, data.Journal, DateTime.UtcNow, Records()).Id.StartsWith(searchNorm, StringComparison.Ordinal)) return true;
            foreach (var id in Replies.HistoryIds(r, data.Journal)) if (id.StartsWith(searchNorm, StringComparison.Ordinal)) return true;
            return false;
        }

        bool Hit(Cand c)
        {
            if (c.Ev == null) return searchMode == 1 && c.FromText.ToLowerInvariant().Contains(searchNorm);
            switch (searchMode)
            {
                case 1: return c.Ev.Name.ToLowerInvariant().Contains(searchNorm);
                case 2: return searchHash.Length > 0 && (c.Ev.Hash == searchHash || c.Ev.PuidHash == searchHash);
                case 3: return c.Ev.Hash.StartsWith(searchNorm) || (c.Ev.PuidHash.Length > 0 && c.Ev.PuidHash.StartsWith(searchNorm)) || c.Ev.Name.ToLowerInvariant().Contains(searchNorm);
                case 4: return c.Ev.Id.StartsWith(searchNorm);
            }
            return false;
        }

        // ---- lists

        void SetView(bool cands)
        {
            candView = cands;
            vBans.Active = !cands; vCands.Active = cands;
            gBans.Visible = !cands; gCands.Visible = cands;
            cState.Visible = !cands; cScope.Visible = !cands;   // the filters are for bans only (a disabled flat combo box turns light grey)
            if (overlay.Visible) overlay.BringToFront();
            FillAll();
            try { (cands ? gCands : gBans).Focus(); } catch (Exception) { }   // not the detail viewer (it would show a text cursor)
        }

        void SetTab(int t)
        {
            tab = t;
            tEv.Active = t == 0; tHist.Active = t == 1; tPolicy.Active = t == 2;
            ShowDetail();
        }

        void FillAll()
        {
            if (data == null) { ShowDetail(); return; }
            int hits = FillBans() + FillCands();
            UpdateChips();
            string note = "";
            if (searchMode == 2) note = S.Get("m.fc", hits);
            else if (searchMode == 3) note = S.Get("m.hash", hits);
            else if (searchMode == 4) note = S.Get("m.evid", hits);
            else if (searchMode == 1) note = S.Get("m.name", hits);
            if (note.Length > 0) status.Set(note, hits > 0 ? Art.Amber1 : Ui.Muted);
            else if (status.LeftText.Length == 0 || status.LeftColor == Art.Amber1) status.Set(S.Get("m.ready"), Ui.Muted);
            ShowDetail();
        }

        string RuleText(string rule) { return S.Rule(rule); }

        string LevelText(Row r, DateTime now)
        {
            if (r.LocalActive(now)) return S.Get("lv", Math.Max(1, r.Level)) + " · " + Fmt.Remain(r.Expires, now, S.Idx);
            if (r.SharedActive(now)) return S.Get("lv", r.Effective.Level) + " · " + Fmt.Remain(r.Effective.EndsAt, now, S.Idx);
            if (r.IsLocal && !r.Active) return S.Get("lifted");
            return S.Get("expired");
        }

        string SourceText(Row r)
        {
            string s = r.IsLocal ? S.Get(r.Source == "auto" ? "src.auto" : "src.manual") : "";
            string sh = "";
            if (r.Effective != null && r.Committed != null) sh = S.Get("src.shared");
            else if (r.Effective != null) sh = S.Get("src.add");
            else if (r.Committed != null) sh = S.Get("src.del");
            else if (r.Source == "shared") sh = S.Get("src.shared");
            if (s.Length > 0 && sh.Length > 0) return s + S.Get("plus") + sh;
            return s.Length > 0 ? s : sh;
        }

        string ReportedText(Row r)
        {
            if (!r.Reported) return "—";
            if (r.ReportedAt != null && r.Since != DateTime.MinValue && r.ReportedAt.Value < r.Since) return S.Get("rep.old");
            return S.Get("rep.yes");
        }

        bool PassFilter(Row r, DateTime now)
        {
            bool active = r.IsActive(now);
            int st = cState.SelectedIndex, sc = cScope.SelectedIndex;
            if (st == 0 && !active) return false;
            if (st == 1 && active) return false;
            if (sc == 1 && !r.IsLocal) return false;
            if (sc == 2 && !r.OnShared) return false;
            return true;
        }

        int FillBans()
        {
            filling = true;
            var now = DateTime.UtcNow;
            bool idSearch = searchMode >= 2;
            DataGridViewRow sel = null, first = null;
            int hits = 0;
            gBans.SuspendLayout();
            gBans.Rows.Clear();
            var rows = new List<DataGridViewRow>();
            foreach (var r in data.Rows)
            {
                bool hit = searchMode > 0 && Hit(r);
                if (!idSearch)
                {
                    if (!PassFilter(r, now)) continue;
                    if (searchMode == 1 && !hit) continue;
                }
                if (hit) hits++;
                var gr = new DataGridViewRow();
                gr.CreateCells(gBans, r.Display, r.Since != DateTime.MinValue ? Fmt.Local(r.Since) : "—", RuleText(r.Rule),
                    LevelText(r, now), SourceText(r), r.Evidence.Length > 0 ? r.Evidence : "—", ReportedText(r));
                gr.Tag = r;
                gr.Height = Ui.S(31);
                if (!r.IsActive(now)) gr.DefaultCellStyle.ForeColor = Ui.Dim;
                if (hit && idSearch) { gr.DefaultCellStyle.BackColor = Ui.Hit; gr.DefaultCellStyle.ForeColor = Ui.Gold; if (first == null) first = gr; }
                if (r.Key == selBan) sel = gr;
                rows.Add(gr);
            }
            gBans.Rows.AddRange(rows.ToArray());
            Resort(gBans);
            gBans.ResumeLayout();
            if (idSearch && first != null) sel = first;
            SelectGridRow(gBans, sel);
            if (!candView) lCount.Text = S.Get("count", rows.Count, data.Rows.Count);
            filling = false;
            return candView ? 0 : hits;
        }

        int FillCands()
        {
            filling = true;
            bool idSearch = searchMode >= 2;
            DataGridViewRow sel = null, first = null;
            int hits = 0;
            gCands.SuspendLayout();
            gCands.Rows.Clear();
            var rows = new List<DataGridViewRow>();
            foreach (var c in data.Cands)
            {
                bool hit = searchMode > 0 && Hit(c);
                if (searchMode == 1 && !hit) continue;
                if (hit) hits++;
                string kind = c.Kind == "own" ? S.Get("kind.own") : c.Kind == "ev" ? S.Get("kind.ev") : S.Get("kind.log", c.Lines);
                var gr = new DataGridViewRow();
                gr.CreateCells(gCands, c.Ev != null ? (c.Ev.Name.Length > 0 ? c.Ev.Name : S.Get("noname")) : "—", Fmt.Local(c.Time),
                    c.Ev != null ? RuleText(c.Ev.Rule) : "—", c.Ev != null ? (c.Ev.LogOk ? Fmt.StrengthOf(c.Ev, S.Idx) : S.Get("lc.bad")) : "—", kind, c.FromText);
                gr.Tag = c;
                gr.Height = Ui.S(31);
                if (GateRules.Trusted(c.Ev)) gr.Cells[3].Style.ForeColor = Art.Green1;
                else if (c.Ev != null && !c.Ev.LogOk) gr.Cells[3].Style.ForeColor = Art.Red1;   // v0.5.5: an imported record its log does not back
                else if (GateRules.CertainLogged(c.Ev)) gr.Cells[3].Style.ForeColor = Art.Amber1;   // v0.5.5 review: its zip's log agrees (amber: both come from the same zip)
                // v0.5.5 (「いいよ」): the host of the zip: flagged for overturned reports (red) or a trusted admin (violet)
                if (c.Ev != null && c.Kind != "own") { if (Reporters.Unreliable(c.Ev)) gr.Cells[5].Style.ForeColor = Art.Red1; else if (Reporters.TrustedHost(c.Ev)) gr.Cells[5].Style.ForeColor = Ui.Violet; }
                // v0.5.5 (palette): the row the search hit keeps the gold text (Ui.Gold), which is no longer Art.Amber1
                if (hit && idSearch) { gr.DefaultCellStyle.BackColor = Ui.Hit; gr.DefaultCellStyle.ForeColor = Ui.Gold; if (first == null) first = gr; }
                if (c.Key == selCand) sel = gr;
                rows.Add(gr);
            }
            gCands.Rows.AddRange(rows.ToArray());
            Resort(gCands);
            gCands.ResumeLayout();
            if (idSearch && first != null) sel = first;
            SelectGridRow(gCands, sel);
            if (candView) lCount.Text = S.Get("count", rows.Count, data.Cands.Count);
            filling = false;
            return candView ? hits : 0;
        }

        /// <summary>Rows added to an unbound grid are not sorted: the column the user sorted by is applied again.</summary>
        static void Resort(DataGridView g)
        {
            try
            {
                if (g.SortedColumn != null && g.SortOrder != SortOrder.None)
                    g.Sort(g.SortedColumn, g.SortOrder == SortOrder.Descending ? System.ComponentModel.ListSortDirection.Descending : System.ComponentModel.ListSortDirection.Ascending);
            }
            catch (Exception) { }
        }

        static void SelectGridRow(DataGridView g, DataGridViewRow sel)
        {
            try
            {
                if (sel != null && sel.Index >= 0)
                {
                    g.CurrentCell = sel.Cells[0];
                    sel.Selected = true;
                    if (sel.Index < g.FirstDisplayedScrollingRowIndex || sel.Index >= g.FirstDisplayedScrollingRowIndex + g.DisplayedRowCount(false)) g.FirstDisplayedScrollingRowIndex = sel.Index;
                }
                else { g.CurrentCell = null; g.ClearSelection(); }
            }
            catch (Exception) { }
        }

        Row SelectedRow()
        {
            if (gBans.SelectedRows.Count == 0) return null;
            return gBans.SelectedRows[0].Tag as Row;
        }

        Cand SelectedCand()
        {
            if (gCands.SelectedRows.Count == 0) return null;
            return gCands.SelectedRows[0].Tag as Cand;
        }

        // ---- detail pane

        void Begin() { Native.Redraw(rtb, false); rtb.ReadOnly = false; rtb.Clear(); rtb.SelectionTabs = new[] { Ui.S(150) }; }
        void End() { rtb.SelectionStart = 0; rtb.SelectionLength = 0; rtb.ReadOnly = true; Native.Redraw(rtb, true); Native.HideCaretOf(rtb); }

        void Add(string t, Font f, Color c)
        {
            rtb.SelectionStart = rtb.TextLength;
            rtb.SelectionLength = 0;
            rtb.SelectionFont = f;
            rtb.SelectionColor = c;
            rtb.SelectedText = t;
        }

        // v0.5.5 (2026-09-22 readability): a heading in the body colour after a short teal bar (was the whole heading in cyan)
        void H(string t) { Add((rtb.TextLength > 0 ? "\n" : "") + "▍", fH, Art.Teal1); Add(t + "\n", fH, Ui.Text); }
        void KV(string k, string v) { if (string.IsNullOrEmpty(v)) return; Add("  " + k + "\t", fK, Ui.Muted); Add(v + "\n", fV, Ui.Text); }
        void KVc(string k, string v, Color c) { if (string.IsNullOrEmpty(v)) return; Add("  " + k + "\t", fK, Ui.Muted); Add(v + "\n", fV, c); }
        void P(string t, Color c) { Add(t + "\n", fV, c); }
        void M(string t) { Add(t + "\n", fMono, Ui.Muted); }

        void ShowDetail()
        {
            dhead.Badges.Clear();
            if (tab == 2) { RenderPolicy(); UpdateActions(); return; }
            if (candView)
            {
                var c = data != null ? SelectedCand() : null;
                if (c == null) { Empty(); UpdateActions(); return; }
                RenderCand(c);
            }
            else
            {
                var r = data != null ? SelectedRow() : null;
                if (r == null) { Empty(); UpdateActions(); return; }
                RenderRow(r);
            }
            UpdateActions();
        }

        void Empty()
        {
            dhead.Title = S.Get("title");
            dhead.Sub = data == null ? "" : App.BansPath;
            dhead.Invalidate();
            Begin();
            P(S.Get("d.none"), Ui.Muted);
            End();
        }

        void RenderPolicy()
        {
            dhead.Title = S.Get("tab.policy");
            dhead.Sub = "PocketRoles Aegis";
            dhead.Badges.Add(new Badge(S.Get("st.certain"), Art.Green1, "✓"));
            dhead.Badges.Add(new Badge(S.Get("st.circ"), Art.Amber1, "△"));
            dhead.Invalidate();
            Begin();
            var lines = S.Get("policy").Split('\n');
            for (int i = 0; i < lines.Length; i++)
            {
                string l = lines[i];
                if (i == 0 || (l.Length > 0 && !l.StartsWith("・") && !l.StartsWith("-") && i > 0 && lines[i - 1].Length == 0 && !l.Contains(":") && !l.Contains("："))) H(l);
                else if (l.Length > 0) P(l, l.StartsWith("・") || l.StartsWith("-") ? Ui.Text : Ui.Muted);
                else P("", Ui.Text);
            }
            End();
        }

        JObj LoadEv(string path)
        {
            if (path == evPath && evObj != null) return evObj;
            evPath = path; evObj = null;
            try { evObj = EvInfo.ReadObj(path); } catch (Exception e) { App.Log("evidence not read: " + e.Message); }
            return evObj;
        }

        void RenderRow(Row r)
        {
            var now = DateTime.UtcNow;
            dhead.Title = r.Display;
            dhead.Sub = S.Get("k.hash") + " " + Hashes.Short(r.Hash) + (r.Evidence.Length > 0 ? "   ·   " + r.Evidence : "");
            dhead.Badges.Add(Fmt.StrengthBadge(r.Ev));
            if (r.Ev != null && r.Ev.Imported) ImportBadges(r.Ev);
            if (r.IsActive(now)) dhead.Badges.Add(new Badge(S.Get("bd.active"), Art.Red1));
            else dhead.Badges.Add(new Badge(r.IsLocal && !r.Active ? S.Get("lifted") : S.Get("expired"), Ui.Muted));
            if (r.IsLocal) dhead.Badges.Add(new Badge(S.Get("bd.local"), Art.Teal1));
            if (r.OnShared) dhead.Badges.Add(new Badge(S.Get("bd.shared"), Ui.Violet));
            if ((r.Effective != null) != (r.Committed != null) || (data != null && Journal.HasSigned(data.Journal, r.Hashes()))) dhead.Badges.Add(new Badge(S.Get("bd.pending"), Art.Amber1));
            var prop = PastedFor(r.Key, false);
            if (prop != null) dhead.Badges.Add(new Badge(S.Get("bd.prop"), Ui.Violet));
            dhead.Invalidate();
            Begin();
            if (tab == 1) { RenderHistory(r); End(); return; }
            if (prop != null)
            {
                var warn = PasteWarnings(prop, r.Name);
                if (prop.Kind == "unban" && r.Effective == null) warn.Add(S.Get("pa.w.notshared"));
                if (prop.Kind == "share" && r.Effective != null) warn.Add(S.Get("pa.w.shared"));
                if (prop.Kind == "share" && r.Ev == null) warn.Add(S.Get("pa.w.noev"));
                string mine = Proposal.StrengthOf(r.Ev);
                if (Proposal.StrengthWord(mine, S.Idx) != Proposal.StrengthWord(prop.Strength, S.Idx)) warn.Add(S.Get("pa.w.strength", Proposal.StrengthWord(prop.Strength, S.Idx), Proposal.StrengthWord(mine, S.Idx)));
                RenderProposal(prop, warn);
            }
            // the ban record
            if (r.Entry != null)
            {
                H(S.Get("h.entry"));
                if (!r.IsLocal) P("  " + S.Get("v.mirror"), Ui.Muted);   // a "shared" entry: only the name and when it was last stopped
                else
                {
                    string state = r.LocalActive(now) ? S.Get("bd.active") : !r.Active ? S.Get("lifted") + " (" + Fmt.Local(r.UnbannedAt) + ")" : S.Get("expired");
                    KVc(S.Get("k.state"), state, r.LocalActive(now) ? Art.Red1 : Ui.Muted);
                    KV(S.Get("k.source"), SourceText(r) + (r.By.Length > 0 ? " · " + r.By : ""));
                    KV(S.Get("k.rule"), RuleText(r.Rule) + (r.Rule.Length > 0 ? "（" + r.Rule + "）" : ""));
                    KV(S.Get("k.stage"), S.Get("lv", Math.Max(1, r.Level)) + " · " + (r.Days > 0 ? S.Get("v.days", r.Days) : S.Get("perm")));
                    KV(S.Get("k.since"), Fmt.LocalUtc(r.Since));
                    KV(S.Get("k.until"), r.Expires == null ? S.Get("perm") : Fmt.LocalUtc(r.Expires) + " · " + Fmt.Remain(r.Expires, now, S.Idx));
                    KV(S.Get("k.count"), r.Count.ToString(CultureInfo.InvariantCulture));
                    KV(S.Get("k.reported"), r.Reported ? ReportedText(r) + " (" + Fmt.Local(r.ReportedAt) + ")" : "—");
                }
                KV(S.Get("k.seen"), Fmt.Local(r.LastSeen));
            }
            if (r.Effective != null || r.Committed != null)
            {
                H(S.Get("h.shared"));
                if (r.Entry == null) P("  " + S.Get("v.sharedonly"), Ui.Muted);
                var b = r.Effective ?? r.Committed;
                KV(S.Get("k.stage"), S.Get("lv", b.Level));
                KV(S.Get("k.until"), Fmt.SharedUntil(b, S.Idx) + " · " + Fmt.Remain(b.EndsAt, now, S.Idx));
                KV(S.Get("k.reason"), b.Reason);
                if (r.Effective != null && r.Committed == null) P("  " + S.Get("v.pendadd"), Art.Amber1);
                if (r.Effective == null && r.Committed != null) P("  " + S.Get("v.penddel"), Art.Amber1);
                if (r.PuidHash.Length > 0) KV(S.Get("k.puid"), Hashes.Short(r.PuidHash));
            }
            // the evidence
            if (r.Ev != null)
            {
                var o = LoadEv(r.Ev.Path);
                if (o != null)
                {
                    if (r.Ev.Imported) { P("", Ui.Text); P(S.Get("v.imported"), Art.Amber1); KV(S.Get("k.from"), r.Ev.From); ImportFacts(r.Ev); }
                    RenderEvidence(o, r.Ev.Imported, r.Ev);
                }
            }
            else if (r.Evidence.Length > 0) { H(S.Get("tab.ev")); P("  " + S.Get("v.nofile", r.Evidence), Art.Amber1); }
            else if (r.Entry != null) { H(S.Get("tab.ev")); P("  " + S.Get("v.noev"), Ui.Muted); }
            End();
        }

        void RenderCand(Cand c)
        {
            dhead.Title = c.Ev != null ? (c.Ev.Name.Length > 0 ? c.Ev.Name : S.Get("noname")) : S.Get("h.lines");
            dhead.Sub = c.Ev != null ? S.Get("k.hash") + " " + Hashes.Short(c.Ev.Hash) + "   ·   " + c.Ev.Id + "   ·   " + c.FromText : c.FromText;
            if (c.Ev != null) dhead.Badges.Add(Fmt.StrengthBadge(c.Ev));
            if (c.Kind != "own") dhead.Badges.Add(new Badge(S.Get("bd.imported"), Ui.Violet));
            if (c.Ev != null && c.Kind != "own") ImportBadges(c.Ev);
            if (c.Ev != null && data != null && data.Effective != null && data.Effective.Find(c.Ev.Hash) != null) dhead.Badges.Add(new Badge(S.Get("bd.shared"), Ui.Violet));
            var prop = PastedFor(c.Key, true);
            if (prop != null) dhead.Badges.Add(new Badge(S.Get("bd.prop"), Ui.Violet));
            dhead.Invalidate();
            Begin();
            if (tab == 1)
            {
                if (c.Ev == null || !RenderAudit(null, c.Ev.Id)) P(S.Get("hist.none"), Ui.Muted);
                End();
                return;
            }
            if (prop != null)
            {
                var warn = PasteWarnings(prop, c.Ev != null ? c.Ev.Name : "");
                bool onShared = c.Ev != null && data != null && data.Effective != null && (data.Effective.Find(c.Ev.PuidHash) != null || data.Effective.Find(c.Ev.Hash) != null);
                if (prop.Kind == "share" && onShared) warn.Add(S.Get("pa.w.shared"));
                if (prop.Kind == "unban" && !onShared) warn.Add(S.Get("pa.w.notshared"));
                string mine = Proposal.StrengthOf(c.Ev);
                if (Proposal.StrengthWord(mine, S.Idx) != Proposal.StrengthWord(prop.Strength, S.Idx)) warn.Add(S.Get("pa.w.strength", Proposal.StrengthWord(prop.Strength, S.Idx), Proposal.StrengthWord(mine, S.Idx)));
                RenderProposal(prop, warn);
            }
            if (c.Kind != "own") { P(S.Get("v.imported"), Art.Amber1); KV(S.Get("k.from"), c.From); if (c.Ev != null) ImportFacts(c.Ev); }
            if (c.Kind == "log")
            {
                H(S.Get("h.lines"));
                try { foreach (var l in File.ReadAllLines(c.Path, Encoding.UTF8)) M(l); }
                catch (Exception e) { P(e.Message, Art.Red1); }
            }
            else
            {
                var o = LoadEv(c.Path);
                if (o != null) RenderEvidence(o, c.Kind != "own", c.Ev);
            }
            End();
        }

        void RenderHistory(Row r)
        {
            bool any = false;
            if (r.Entry != null)
            {
                var h = r.Entry.Arr("history");
                if (h != null && h.Count > 0)
                {
                    H(S.Get("tab.hist"));
                    for (int i = h.Count - 1; i >= 0; i--)
                    {
                        var x = h[i] as JObj;
                        if (x == null) continue;
                        KV(Fmt.Local(x.Time("at")), Fmt.Event(x.Str("event")) + (x.Str("detail").Length > 0 ? " — " + x.Str("detail") : ""));
                        any = true;
                    }
                }
            }
            var acts = new HashSet<string>(StringComparer.Ordinal);
            if (data != null)
            {
                var mine = new List<JObj>();
                var hashes = r.Hashes();
                foreach (var a in data.Journal) if (Journal.Touches(a, hashes)) mine.Add(a);
                foreach (var a in mine) if (a.Str("id").Length > 0) acts.Add(a.Str("id"));
                if (mine.Count > 0)
                {
                    H(S.Get("h.console"));
                    for (int i = mine.Count - 1; i >= 0; i--)
                    {
                        var a = mine[i];
                        string k = "ak." + a.Str("kind"), stt = "as." + a.Str("state"), desc = Ops.DescIn(S.Idx, a);
                        KV(Fmt.Local(a.Time("at")), (S.Has(k) ? S.Get(k) : a.Str("kind")) + " · " + (S.Has(stt) ? S.Get(stt) : a.Str("state")) + (desc.Length > 0 ? " — " + desc : ""));
                        any = true;
                    }
                }
            }
            // v0.5.5: the audit lines of this ban (its console actions, and proposals about its evidence)
            string ev = r.Evidence.Length > 0 ? r.Evidence : r.Ev != null ? r.Ev.Id : "";
            if (RenderAudit(acts, ev)) any = true;
            if (!any) P(S.Get("hist.none"), Ui.Muted);
        }

        /// <summary>The audit.log lines of these journal actions or this evidence id, newest first; false when there are none.</summary>
        bool RenderAudit(ICollection<string> acts, string ev)
        {
            var lines = Audit.For(acts, ev);
            if (lines.Count == 0) return false;
            H(S.Get("h.audit"));
            for (int i = lines.Count - 1; i >= 0; i--)
            {
                var a = lines[i];
                string k = "ak." + a.Action;
                var sb = new StringBuilder(S.Has(k) ? S.Get(k) : a.Action);
                if (a.Rule.Length > 0) sb.Append(" · ").Append(GateRules.Text(a.Rule, S.Idx));
                if (a.Reason.Length > 0) sb.Append(" — ").Append(a.Action.StartsWith("observed.", StringComparison.Ordinal) ? BanSnap.DiffsText(a.Reason, S.Idx) : a.Reason);
                if (a.Proposer.Length > 0) sb.Append(" · ").Append(S.Get("pf.by")).Append(": ").Append(a.Proposer);
                // v0.5.5 (「いいよ」): why imported evidence could be shared, and the author's written reason when overridden
                if (a.Gate.Length > 0 && S.Has("au.gate." + a.Gate)) sb.Append(" · ").Append(S.Get("au.gate." + a.Gate));
                if (a.Host.Length > 0) sb.Append(" · ").Append(S.Get("au.host", a.Host));   // 9/23: the host of one host's record
                if (a.Override.Length > 0) sb.Append(" · ").Append(S.Get("au.override", a.Override));
                string res = Audit.ResultText(a.Result, S.Idx);
                if (res.Length > 0) sb.Append(" · ").Append(res);
                // v0.5.5 who did it (Windows user @ PC, mode, unlock method), and for a shared change the key and the commit
                string who = Audit.OperatorText(a, S.Idx);
                if (who.Length > 0) sb.Append(" · ").Append(who);
                if (a.Method == "code") sb.Append(" · ").Append(S.Get("au.unverified"));
                if (a.KeyId.Length > 0) sb.Append(" · keyid ").Append(a.KeyId);
                if (a.Commit.Length > 0) sb.Append(" · commit ").Append(a.Commit);
                KV(Fmt.Local(a.At), sb.ToString());
            }
            return true;
        }

        /// <summary>The pasted proposal when it points at this row / candidate (else null).</summary>
        Proposal PastedFor(string key, bool cand)
        {
            return pasted != null && pastedCand == cand && key.Length > 0 && key == pastedKey ? pasted : null;
        }

        /// <summary>
        /// What does not fit between a pasted proposal and the target it selected: its evidence id and line disagree, the
        /// text held several proposal lines, or its name is not the target's (names are compared as the proposal shows them).
        /// </summary>
        List<string> PasteWarnings(Proposal p, string targetName)
        {
            var warn = new List<string>();
            if (pastedWarn.Length > 0) warn.Add(S.Get(pastedWarn));
            if (p.Found > 1) warn.Add(S.Get("pa.w.multi", p.Found));
            string shown = Proposal.ShownName(targetName);
            if (p.Name.Length > 0 && !string.Equals(p.Name, shown, StringComparison.Ordinal))
                warn.Add(S.Get("pa.w.name", p.Name, shown.Length > 0 ? shown : S.Get("noname")));
            return warn;
        }

        /// <summary>The pasted proposal in the evidence tab, with what no longer fits; it is shown only.</summary>
        void RenderProposal(Proposal p, List<string> warn)
        {
            H(S.Get("h.prop"));
            KVc(S.Get("pf.kind"), S.Get(p.Kind == "unban" ? "pf.kind.unban" : "pf.kind.share"), Ui.Violet);
            KV(S.Get("k.name"), p.Name.Length > 0 ? p.Name : S.Get("noname"));
            KV(S.Get("pf.target"), (p.Ev.Length > 0 ? p.Ev : "—") + " / " + S.Get("pf.line") + " " + (p.Line.Length > 0 ? p.Line : "—"));
            KV(S.Get("pf.by"), p.By.Length > 0 ? p.By : "—");
            KV(S.Get("pf.at"), Fmt.LocalUtc(p.At == DateTime.MinValue ? (DateTime?)null : p.At));
            KV(S.Get("k.strength"), Proposal.StrengthWord(p.Strength, S.Idx));
            if (p.Rule.Length > 0) KV(S.Get("pf.rule"), GateRules.Text(p.Rule, S.Idx) + "（" + p.Rule + "）");
            KV(S.Get("pf.reason"), p.Reason.Length > 0 ? p.Reason : "—");
            if (warn != null) foreach (var w in warn) P("  ⚠ " + w, Art.Amber1);
            P("  " + S.Get("pa.only"), Ui.Muted);
        }

        /// <summary>v0.5.5 an imported record: its log check, its zip's host and the hosts that reported the player (the fake-evidence rules).</summary>
        void ImportFacts(EvInfo ev)
        {
            KVc(S.Get("k.logcheck"), LogCheck.Why(ev, S.Idx), ev.LogOk ? Art.Green1 : Art.Red1);
            // v0.5.5 review: the name trust and pauses go by (the record's first import), and a zip without a PC mark
            string hostText = ev.HostLabel.Length > 0 ? ev.HostLabel : S.Get("v.nohost");
            if (ev.HostLabel.Length > 0 && Reporters.Key(ev.FirstLabel) != Reporters.Key(ev.HostLabel)) hostText += " " + S.Get("v.firsthost", ev.FirstLabel.Length > 0 ? ev.FirstLabel : "—");
            if (ev.HostLabel.Length > 0 && ev.HostPc.Length == 0) hostText += " " + S.Get("v.nopc");
            KVc(S.Get("k.host"), hostText, ev.HostLabel.Length > 0 ? Ui.Text : Art.Amber1);
            // v0.5.5 (「いいよ」): the host's trust and overturned reports, and whether (and why) the record can back a shared ban
            var rep = Reporters.InfoOf(ev);
            if (ev.HostLabel.Length > 0 || rep.Count > 0)
            {
                KVc(S.Get("k.reporter"), Reporters.StateText(rep, S.Idx), rep.Flagged ? Art.Red1 : rep.Trusted ? Ui.Violet : rep.Count > 0 ? Art.Amber1 : Ui.Text);
                if (rep.Flagged) P("  " + S.Get("rp.flagged.d", Reporters.WindowDays, Reporters.Threshold), Art.Red1);
                string over = Reporters.OverText(rep, S.Idx);
                if (over.Length > 0) P("  " + over, rep.Flagged ? Art.Red1 : Art.Amber1);
            }
            DateTime listedAt;
            if (Reporters.Current.Listed.TryGetValue(ev.Id, out listedAt)) P("  " + S.Get("v.listed", Fmt.Date(listedAt)), Art.Amber1);
            string basis = GateRules.Basis(ev), block = GateRules.ShareBlock(ev);
            // a paused host's own record is not counted: say so rather than 「0 人（—）」 next to its host's name
            if (block == "g.block.unreliable") KVc(S.Get("k.hosts"), S.Get("v.hosts.flagged", ev.HostCount, HostsText(ev), rep.Label.Length > 0 ? rep.Label : ev.FirstLabel), Art.Red1);
            else KVc(S.Get("k.hosts"), S.Get("v.hosts", ev.HostCount, HostsText(ev)), ev.HostCount >= GateRules.MinHosts || basis.Length > 0 ? Ui.Text : Art.Amber1);
            // v0.5.5 review: amber for the certain path (the record and its log come from the same zip), green for two hosts
            KVc(S.Get("k.basis"), GateRules.BasisText(ev, S.Idx), basis == "hosts" ? Art.Green1 : basis == "trusted" ? Ui.Violet : basis.Length > 0 || GateRules.Overridable(block) ? Art.Amber1 : Art.Red1);
            if (basis == "certain") P("  " + S.Get("bs.certain.note"), Art.Amber1);
            // 9/23 the certain cap: 「このホストの確実な検知だけの共有: 直近 30 日に 2/2 件」 (a trusted admin: not capped; review:
            // not on a record two hosts back, an admin's PC does not count, the ones lifted later in amber)
            string cap = CertCapLine(ev, S.Idx);
            if (cap.Length > 0) P("  " + cap, GateRules.CertainCapped(ev) && basis != "trusted" ? Art.Amber1 : Ui.Muted);
            string lifted = CertLiftedLine(ev, S.Idx);
            if (lifted.Length > 0) P("  " + lifted, Art.Amber1);
        }

        void ImportBadges(EvInfo ev)
        {
            dhead.Badges.Add(ev.LogOk ? new Badge(S.Get("lc.ok"), Art.Green1, "✓") : new Badge(S.Get("lc.bad"), Art.Red1, "✕"));
            // v0.5.5 (「いいよ」): one host is enough (certain / trusted admin), a flagged host, or the author's call
            // (merge 9/23: the gate's badges keep the shared-ban conditions and take the palette's marks, so colour is never the only sign)
            string basis = GateRules.Basis(ev), block = GateRules.ShareBlock(ev);
            dhead.Badges.Add(ev.HostCount >= GateRules.MinHosts || basis.Length > 0
                ? new Badge(S.Get("bd.hosts", ev.HostCount), Ui.Violet)
                : new Badge(S.Get("bd.hosts", ev.HostCount), Art.Amber1, "⚠"));
            if (block == "g.block.unreliable") dhead.Badges.Add(new Badge(S.Get("bd.flagged", Reporters.InfoOf(ev).Count), Art.Red1, "✕"));
            else if (basis == "certain") dhead.Badges.Add(new Badge(S.Get("bd.certain1"), Art.Amber1, "⚠"));   // (v0.5.5 review: amber, not the green of this PC's own certain records)
            else if (basis == "trusted") dhead.Badges.Add(new Badge(S.Get("bd.trusted"), Ui.Violet));
            else if (block == "g.block.noname") dhead.Badges.Add(new Badge(S.Get("bd.noname"), Art.Red1, "✕"));
            else if (block == "g.block.certcap") dhead.Badges.Add(new Badge(Reporters.Current.CertainUnknown ? S.Get("bd.capunknown") : S.Get("bd.certcap", GateRules.CertainCap), Art.Amber1, "⚠"));   // 9/23 the certain cap
            else if (GateRules.Overridable(block)) dhead.Badges.Add(new Badge(S.Get("bd.override"), Art.Amber1, "⚠"));
        }

        void RenderEvidence(JObj o, bool imported) { RenderEvidence(o, imported, null); }

        /// <summary><paramref name="ev"/> (v0.5.5 review, may be null): the record, so a certain record its zip's log agrees with says so instead of 「自己申告」.</summary>
        void RenderEvidence(JObj o, bool imported, EvInfo ev)
        {
            H(S.Get("tab.ev") + "  " + o.Str("id"));
            string strength = o.Str("strength");
            bool claimed = imported && strength == "certain";   // an imported record's strength is only its own claim
            bool logged = claimed && GateRules.CertainLogged(ev);   // ... unless its zip's log agrees (both still come from the same zip)
            KVc(S.Get("k.strength"), Fmt.Strength(strength, S.Idx) + "（" + S.Get(strength == "certain" ? "st.certain.n" : "st.circ.n") + "）" + (logged ? " · " + S.Get("st.log") : claimed ? " · " + S.Get("st.self") : ""),
                strength == "certain" && !claimed ? Art.Green1 : Art.Amber1);
            KV(S.Get("k.time"), Fmt.LocalUtc(o.Time("time")));
            var ban = o.Obj("ban");
            if (o.Str("action") == "ban" && ban != null)
            {
                int days = ban.Int("days");
                KV(S.Get("k.action"), S.Get("v.ban", days > 0 ? S.Get("v.days", days) : S.Get("perm"), ban.Int("offence")) + " · " + S.Get("lv", ban.Int("level")));
            }
            else KV(S.Get("k.action"), S.Get(EvActionKey(o.Str("action"))));
            KV(S.Get("k.rule"), RuleText(o.Str("rule")) + "（" + o.Str("rule") + "）");
            KV(S.Get("k.by"), o.Str("by") + (o.Str("source").Length > 0 ? " · " + o.Str("source") : ""));
            var p = o.Obj("player");
            if (p != null)
            {
                H(S.Get("h.player"));
                KV(S.Get("k.name"), p.Str("name"));
                KV(S.Get("k.hash"), Hashes.Short(p.Str("hash")));
                if (p.Str("puidHash").Length > 0) KV(S.Get("k.puid"), Hashes.Short(p.Str("puidHash")));
                // v0.5.5 review: the code to list on [unban] comes from here (the record checked), never from the appeal
                string shownCode = EvInfo.ShowCode(p.Str("eraseCode"));
                if (shownCode.Length > 0) KV(S.Get("k.erasecode"), shownCode);
                KV(S.Get("k.platform"), p.Str("platform"));
                KV(S.Get("k.client"), "client " + p.Int("clientId") + " · #" + p.Int("playerId"));
            }
            var l = o.Obj("lobby");
            if (l != null)
            {
                H(S.Get("h.lobby"));
                KV(S.Get("k.code"), l.Str("code"));
                KV(S.Get("k.server"), l.Str("server"));
                KV(S.Get("k.reg"), S.Get(l.Bool("registered", false) ? "v.yes" : "v.no"));
                KV(S.Get("k.phase"), S.Get(l.Bool("inGame", false) ? "v.ingame" : "v.lobby"));
                KV(S.Get("k.players"), l.Int("players").ToString(CultureInfo.InvariantCulture));
                int rtt = l.Int("hostRttMs");
                if (rtt >= 0 && l.Has("hostRttMs")) KV(S.Get("k.rtt"), rtt + " ms");
                KV(S.Get("k.ver"), "PocketRoles " + l.Str("hostVersion") + " · Among Us " + l.Str("gameVersion"));
            }
            var d = o.Obj("detection");
            if (d != null)
            {
                H(S.Get("h.detect"));
                KV(S.Get("k.detail"), d.Str("detail"));
                KV(S.Get("k.dlevel"), d.Str("level"));
                var hits = d.Obj("hits");
                if (hits != null && hits.Items.Count > 0)
                {
                    var sb = new StringBuilder();
                    foreach (var kv in hits.Items) { if (sb.Length > 0) sb.Append(", "); sb.Append(kv.Key).Append(" ×").Append(Json.ToInt(kv.Value)); }
                    KV(S.Get("k.hits"), sb.ToString());
                }
                KV(S.Get("k.rules"), d.Str("rules"));
                if (d.Int("jitterPercent") != 0) KV(S.Get("k.jitter"), "±" + d.Int("jitterPercent") + "%");
                var lim = d.Obj("limits");
                if (lim != null && lim.Items.Count > 0)
                {
                    var sb = new StringBuilder();
                    int n = 0;
                    foreach (var kv in lim.Items)
                    {
                        if (n++ >= 12) { sb.Append(" …"); break; }
                        if (sb.Length > 0) sb.Append(", ");
                        var num = kv.Value as JNum;
                        sb.Append(kv.Key).Append('=').Append(num != null ? num.Raw : "?");
                    }
                    KV(S.Get("k.limits"), sb.ToString());
                }
            }
            var ro = o.Obj("roles");
            if (ro != null && (ro.Str("snapshot").Length > 0 || ro.Str("live").Length > 0))
            {
                H(S.Get("h.roles"));
                KV(S.Get("k.snapshot"), ro.Str("snapshot"));
                KV(S.Get("k.live"), ro.Str("live"));
                object dead = ro.Get("dead");
                if (dead is bool) KV(S.Get("k.dead"), S.Get((bool)dead ? "v.dead" : "v.alive"));
            }
            var log = Json.Strings(o.Arr("log"));
            if (log.Count > 0) { H(S.Get("h.log")); foreach (var x in log) M(x); }
            var rep = o.Obj("report");
            H(S.Get("h.report"));
            if (rep != null && rep.Bool("sent", false)) KV(S.Get("k.reported"), S.Get("v.sent", rep.Str("reason"), Fmt.Local(rep.Time("at"))));
            else KV(S.Get("k.reported"), S.Get("v.notsent"));
            if (o.Str("note").Length > 0) KV(S.Get("k.note"), o.Str("note"));
        }

        void UpdateActions()
        {
            var now = DateTime.UtcNow;
            bool pol = tab == 2, admin = App.Admin;
            foreach (Control c in acts.Controls) c.Visible = true;
            aDismiss.Visible = candView;
            aAdd.Visible = candView;
            aUnban.Visible = aPeriod.Visible = aUndo.Visible = aReply.Visible = !candView;
            // admin mode: every shared operation is a proposal; this PC's bans stay as they are
            aShare.Visible = !admin;
            aPropShare.Visible = admin;
            aPropUnban.Visible = admin && !candView;
            if (!candView)
            {
                var r = data != null ? SelectedRow() : null;
                bool sel = r != null && !pol;
                bool signed = r != null && data != null && Journal.HasSigned(data.Journal, r.Hashes());
                aCopy.Enabled = sel && (r.Ev != null || r.Entry != null);
                aReply.Enabled = sel;
                if (admin)
                {
                    var last = sel && data != null ? Journal.LastUndoable(data.Journal, r.Hashes()) : null;
                    aUnban.Enabled = sel && r.LocalActive(now);
                    aPeriod.Enabled = sel && r.LocalActive(now);
                    aUndo.Enabled = last != null && !last.Has("sharedAfter");
                    aPropUnban.Enabled = sel && r.Effective != null;
                    aPropShare.Enabled = sel && r.Effective == null && r.LocalActive(now) && r.Hash.Length > 0;   // no evidence / PUID: DoProposeShare says why
                }
                else
                {
                    aUnban.Enabled = sel && !signed && (r.LocalActive(now) || r.Effective != null);
                    aShare.Enabled = sel && !signed && r.Effective == null && r.LocalActive(now) && r.Hash.Length > 0;   // no evidence / PUID: DoShare says why
                    aPeriod.Enabled = sel && !signed && (r.LocalActive(now) || r.Effective != null);
                    aUndo.Enabled = sel && !signed && data != null && Journal.LastUndoable(data.Journal, r.Hashes()) != null;
                }
            }
            else
            {
                var c = data != null ? SelectedCand() : null;
                bool sel = c != null && !pol;
                bool ev = sel && c.Ev != null && c.Ev.Hash.Length > 0;
                bool signed = ev && data != null && Journal.HasSigned(data.Journal, c.Hashes());
                aCopy.Enabled = sel;
                aShare.Enabled = ev && !signed;   // no PUID: DoShareCand says why
                aPropShare.Enabled = ev;
                aAdd.Enabled = ev && !signed;
                aDismiss.Enabled = sel;
            }
            QueueFit();
        }

        // ---- actions

        bool Confirm(string statement, List<string> bullets, bool global)
        {
            return Confirm(statement, bullets, global, null);
        }

        /// <summary>The 5-second double check; <paramref name="gate"/> (may be null) adds the legitimacy check and a pasted proposal.</summary>
        bool Confirm(string statement, List<string> bullets, bool global, Gate gate)
        {
            using (var d = new ConfirmDialog(statement, bullets, global, 5, gate)) return d.ShowDialog(this) == DialogResult.OK;
        }

        /// <summary>
        /// v0.5.5 (2026-09-23) The same double check without the seconds, for the two questions that change no ban and only
        /// ever make things safer: proving the signing key before an action that reaches other people, and invalidating the
        /// stored key records. Keeping a worried owner waiting there helps nobody; the action itself is still confirmed.
        /// </summary>
        bool ConfirmNow(string statement, List<string> bullets)
        {
            using (var d = new ConfirmDialog(statement, bullets, false, 0, null)) return d.ShowDialog(this) == DialogResult.OK;
        }

        void ShowNotice(string head, string text, Color c)
        {
            using (var d = new NoticeDialog(head, text, c)) d.ShowDialog(this);
        }

        void RunOp(OpForm f)
        {
            SetBusy(true);
            try { f.ShowDialog(this); }
            finally { SetBusy(false); }
        }

        /// <summary>The audit line of an action on a ban row (the evidence id and the name only; the gate's rule / reason; the proposer of a matching pasted proposal).</summary>
        AuditRec AuditFor(string action, Row r, Gate g, string rule, string kind)
        {
            var au = new AuditRec { Action = action, Ev = r.Evidence.Length > 0 ? r.Evidence : r.Ev != null ? r.Ev.Id : "", Name = r.Name, Rule = rule ?? "" };
            if (g != null)
            {
                au.Reason = g.Reason ?? "";
                if (g.Proposal != null && g.Proposal.Kind == kind) au.Proposer = g.Proposal.By + (g.Proposal.At != DateTime.MinValue ? " (" + Json.Time(g.Proposal.At) + ")" : "");
            }
            return au;
        }

        /// <summary>Appends the audit line; when audit.log cannot be written, the status bar says so (after the reload that follows).</summary>
        void Record(AuditRec au)
        {
            if (Audit.Append(au)) return;
            afterReload = S.Get("m.auditfail");
            status.Set(afterReload, Art.Amber1);
        }

        void DoLocal(JObj a) { DoLocal(a, null); }

        void DoLocal(JObj a, AuditRec au)
        {
            if (!StillUnlocked()) { Reload(false); return; }
            var steps = new List<Step> { new Step(S.Get("step.local"), st => Ops.RunLocal(a, st)) };
            bool ok;
            using (var f = new OpForm(S.Get("op.local"), steps, false, null) { OkText = S.Get("op.ok.local") }) { RunOp(f); ok = f.Ok; }
            if (ok && au != null) { au.At = DateTime.UtcNow; au.Act = a.Str("id"); au.Result = "done.local"; Record(au); }
            Reload(false);
        }

        void DoShared(JObj a) { DoShared(a, null); }

        void DoShared(JObj a, AuditRec au) { DoShared(a, au, null); }

        /// <summary><paramref name="signed"/> (v0.5.5, may be null): runs once the change is signed and recorded, before the reload.</summary>
        void DoShared(JObj a, AuditRec au, Action signed)
        {
            if (App.Admin) { status.Set(S.Get(AdminSharedKey()), Art.Amber1); return; }   // never reached: admin mode has no shared buttons
            if (!StillUnlocked()) { Reload(false); return; }
            var steps = new List<Step>
            {
                new Step(S.Get("step.repo"), st => Ops.CheckRepo(st)),
                new Step(S.Get("step.build"), st => Ops.BuildWork(a, st)),
                new Step(S.Get("step.sign"), st => Ops.Sign(st)),
                new Step(S.Get("step.verify"), st => Ops.VerifyWork(st)),
                new Step(S.Get("step.record"), st => Ops.RecordPending(a, st)),
            };
            bool publish, ok;
            using (var f = new OpForm(S.Get("op.sign"), steps, false, S.Get("b.publish")) { OkText = S.Get("op.ok.sign") })
            {
                RunOp(f);
                ok = f.Ok;
                publish = f.Ok && f.ExtraChosen;
            }
            if (ok && au != null) { au.At = DateTime.UtcNow; au.Act = a.Str("id"); au.Result = "signed " + a.Int("version").ToString(CultureInfo.InvariantCulture); au.KeyId = SigKeyId(App.WorkDefs); Record(au); }
            if (ok && signed != null) signed();
            if (publish) DoPublish(); else Reload(false);
        }

        /// <summary>The keyid= of a definitions file's .sig ("" when none): the audit line of a shared change names the key that signed it.</summary>
        static string SigKeyId(string defs)
        {
            try { return File.Exists(defs + ".sig") ? Sig.KeyIdIn(File.ReadAllText(defs + ".sig", Encoding.UTF8)) : ""; }
            catch (Exception) { return ""; }
        }

        List<string> SignBullets()
        {
            return new List<string> { S.Get("cf.p.sign"), S.Get("cf.p.push"), S.Get("cf.p.reach") };
        }

        void DoUnban()
        {
            var r = SelectedRow();
            if (r == null) return;
            if (!Guard()) return;
            var now = DateTime.UtcNow;
            // admin mode: only this PC's ban (the shared one is "解除を提案")
            bool local = r.LocalActive(now), shared = r.Effective != null && !App.Admin;
            if (!local && !shared) { if (App.Admin && r.Effective != null) status.Set(S.Get(AdminSharedKey()), Art.Amber1); return; }
            // v0.5.5 (2026-09-23): lifting a SHARED ban reaches every host (this PC's own ban stays on Windows Hello)
            if (shared && !KeyGate("unban")) return;
            var bullets = new List<string>();
            if (local) bullets.Add(S.Get(shared ? "cf.p.later" : "cf.p.now"));
            else bullets.Add(S.Get("cf.p.nolocal"));
            if (r.IsLocal) bullets.Add(S.Get("cf.p.count", r.Count));
            if (App.Admin && r.Effective != null) bullets.Add(S.Get(App.KeySignal ? "m.admin.shared.k" : "cf.p.adminlocal"));
            if (shared) bullets.AddRange(SignBullets());
            var g = new Gate { AskReason = true, Proposal = PastedFor(r.Key, false) };
            // v0.5.5 (「いいよ」): the imported reports that backed this shared listing: 「誤りだった」 counts against their hosts
            // (review: only the records the listing named as its backers, one box per host)
            var backers = shared && data != null ? Reporters.Backers(r.Effective.Hash, data.Imported, data.Journal, now) : new List<Reporters.Backer>();
            g.MistakeHosts = MistakeHostsOf(backers);
            if (!Confirm(S.Get(shared ? "cf.unban.g" : "cf.unban.l", r.Display), bullets, shared, g)) return;
            var au = AuditFor("unban", r, g, shared ? r.Effective.Reason : r.Rule, "unban");
            var a = Journal.NewAction("unban", r.Hashes(), r.Name);
            if (local)
            {
                var nw = new JObj();
                nw.Set("active", false); nw.Set("unbannedAt", "@now"); nw.Set("unbanBy", "console (BAN 管理)");
                a.Set("localNew", nw);
                a.Set("localHist", HistLine("unban", "console (BAN 管理)"));
                a.Set("guardSince", r.Entry.Str("since"));
            }
            // the shared line's id only (a PUID's hash): never 8 digits of the friend code's hash (the commit message is public)
            Ops.SetDesc(a, shared ? r.Effective.Hash : "", 0, null, "", local && shared, EvIdOf(r), "", "");
            if (shared)
            {
                a.Set("sharedAfter", new List<object>());
                DoShared(a, au, MistakeAfter(g, backers, a, "unban"));
            }
            else DoLocal(a, au);
        }

        /// <summary>v0.5.5 review: one entry per host of these backers (the name of the record's first import), for the 「誤りだった」 boxes; D-35: not for a certain detection its log confirms.</summary>
        internal static List<string> MistakeHostsOf(IList<Reporters.Backer> backers)
        {
            var o = new List<string>();
            foreach (var b in Reporters.OnePerHost(Reporters.Chargeable(backers)))
            {
                string l = b.Ev.HostLabel.Length > 0 ? b.Ev.HostLabel : S.Get("noname");
                if (!o.Exists(x => string.Equals(x, l, StringComparison.OrdinalIgnoreCase))) o.Add(l);
            }
            return o;
        }

        /// <summary>v0.5.5 review: what runs once a lift with 「誤りだった」 ticked is signed (null when nothing to record).</summary>
        Action MistakeAfter(Gate g, List<Reporters.Backer> backers, JObj a, string how)
        {
            if (g == null || !g.Mistake || backers == null || backers.Count == 0 || g.MistakeChosen.Count == 0) return null;
            var chosen = new List<string>(g.MistakeChosen);
            return () => RecordOverturns(backers, chosen, a.Str("id"), how);
        }

        /// <summary>
        /// v0.5.5 (「いいよ」): the shared ban these reports backed was lifted as a mistake (signed): ONE overturned report for each
        /// chosen host (review: never one per record; the host's records of this lift go in one event), in reporters.txt with the
        /// lift's journal id (it stops counting if the lift is discarded or undone) and the listing lifted, and an audit line
        /// each (audit.log is the authority: <see cref="Reporters.Merge"/>). D-35: a certain detection its log confirms is not
        /// charged (<see cref="Reporters.Chargeable"/>); a host this lift may pause is looked at after the reload
        /// (<see cref="NoticePaused"/>).
        /// </summary>
        void RecordOverturns(List<Reporters.Backer> backers, List<string> chosen, string act, string how)
        {
            var now = DateTime.UtcNow;
            var st = Reporters.Current;
            var groups = new List<List<Reporters.Backer>>();
            var keys = new List<string>();
            foreach (var b in Reporters.Chargeable(backers))
            {
                string l = b.Ev.HostLabel.Length > 0 ? b.Ev.HostLabel : S.Get("noname");
                if (!chosen.Exists(x => string.Equals(x, l, StringComparison.OrdinalIgnoreCase))) continue;
                string k = st.RootOf(b.Ev.HostLabel, b.Ev.HostPc) ?? ("l:" + Reporters.Key(b.Ev.HostLabel) + "|p:" + b.Ev.HostPc);
                int i = keys.IndexOf(k);
                if (i < 0) { keys.Add(k); groups.Add(new List<Reporters.Backer>()); i = groups.Count - 1; }
                groups[i].Add(b);
            }
            foreach (var grp in groups)
            {
                var ids = new List<string>();
                foreach (var b in grp) if (!ids.Contains(b.Ev.Id)) ids.Add(b.Ev.Id);
                var first = grp[0];
                var e = new Reporters.Event { Kind = "overturn", At = now, Label = first.Ev.HostLabel, Pc = first.Ev.HostPc, Ev = string.Join(",", ids.ToArray()), Act = act, How = how, Share = first.Share };
                if (!Reporters.Append(e)) afterReload = S.Get("m.hostsfail");
                Record(new AuditRec { At = now, Action = "host.overturn", Ev = first.Ev.Id, Name = first.Ev.HostLabel, Act = act, Result = "done.local" });
                if (!st.For(first.Ev.HostLabel, first.Ev.HostPc).Flagged) justCharged.Add(new Reporters.Event { Label = first.Ev.HostLabel, Pc = first.Ev.HostPc });
            }
        }

        /// <summary>D-35: the hosts a lift just charged that were not paused before it (looked at once after the reload).</summary>
        List<Reporters.Event> justCharged = new List<Reporters.Event>();

        /// <summary>
        /// D-35 (after a load): a host the lift just charged that is paused now (<see cref="Reporters.Threshold"/> in the last
        /// <see cref="Reporters.WindowDays"/> days): the owner sees it once, with the shared bans in effect that its reports
        /// backed. Nothing is written: the pause follows from the overturns and ends by itself when they leave the window.
        /// </summary>
        void NoticePaused()
        {
            if (IsDisposed || data == null || justCharged.Count == 0) return;
            var charged = justCharged;
            justCharged = new List<Reporters.Event>();
            var now = DateTime.UtcNow;
            var names = new List<string>();
            var lines = new List<string>();
            foreach (var e in charged)
            {
                if (!Reporters.Current.For(e.Label, e.Pc).Flagged) continue;
                string n = e.Label.Length > 0 ? e.Label : "—";
                if (!names.Contains(n)) names.Add(n);
                foreach (var l in Reporters.ActiveLines(e.Label, e.Pc, data.Imported, data.Journal, data.Effective, now, S.Idx)) if (!lines.Contains(l)) lines.Add(l);
            }
            if (names.Count == 0) return;
            string sep = S.Idx == 2 ? ", " : "、";
            ShowNotice(S.Get("rh.flag.title"), S.Get("rh.flag.body", string.Join(sep, names.ToArray()), Reporters.WindowDays, Reporters.Threshold,
                lines.Count > 0 ? "・" + string.Join("\n・", lines.ToArray()) : S.Get("rh.active.none")), Art.Red1);
        }

        static JObj HistLine(string ev, string detail)
        {
            var h = new JObj();
            h.Set("event", ev);
            h.Set("detail", detail);
            return h;
        }

        static int LadderDays(int level) { return level <= 1 ? 30 : level == 2 ? 180 : 0; }

        /// <summary>v0.5.5: shows why this evidence cannot back a shared ban (no evidence file, not matching its zip's log, a paused host, one host only); false when it can.</summary>
        bool ShowBlock(EvInfo ev, string noevKey)
        {
            bool over;
            return ShowBlock(ev, noevKey, false, out over);
        }

        /// <summary>
        /// v0.5.5 (2026-09-22 「いいよ」): as <see cref="ShowBlock(EvInfo, string)"/>, but with <paramref name="mayOverride"/> a
        /// record of one host only (not a certain detection its log agrees with, not a trusted admin; or one host's record
        /// used once already) is not blocked: <paramref name="over"/> is set and the caller asks the author's written reason
        /// (<see cref="SetOverride"/>; an admin's proposal says the author has to decide). A record its log does not back, a
        /// paused host, a zip with no host name or an unreadable hosts' record is always blocked.
        /// </summary>
        bool ShowBlock(EvInfo ev, string noevKey, bool mayOverride, out bool over)
        {
            over = false;
            string k = GateRules.ShareBlock(ev);
            if (k.Length == 0) return false;
            if (mayOverride && GateRules.Overridable(k)) { over = true; return false; }
            string text;
            if (k == "g.block.nolog") text = S.Get(k, LogCheck.Why(ev, S.Idx));
            else if (k == "g.block.certcap") text = CertCapWhy(ev);
            else if (k == "g.block.onehost" || k == "g.block.used") text = S.Get("g.block.onehost", ev.HostCount, HostsText(ev));
            else if (k == "g.block.unreliable") { var i = Reporters.InfoOf(ev); text = S.Get(k, i.Label.Length > 0 ? i.Label : ev.FirstLabel, i.Count, Reporters.WindowDays, Reporters.Threshold, Fmt.Date(i.ResumeAt)); }
            else if (k == "g.block.noname" || k == "g.block.hostsfail") text = S.Get(k);
            else text = S.Get(noevKey);
            ShowNotice(S.Get("g.block.title"), text, Art.Amber1);
            return true;
        }

        internal static void SetOverride(Gate g, EvInfo ev, bool over) { SetOverride(g, ev, over, null); }

        /// <summary>
        /// v0.5.5 (「いいよ」): why the evidence may be shared, for the audit line; with <paramref name="over"/> the author's written
        /// reason is asked in the confirmation (<paramref name="why"/>: what the author is told; null = one host, or one host's
        /// record used once already).
        /// </summary>
        internal static void SetOverride(Gate g, EvInfo ev, bool over, string why)
        {
            string b = over ? "override" : GateRules.Basis(ev);
            g.Basis = b == "own" ? "" : b;   // this PC's own records: the audit line as before
            if (!over) return;
            g.Override = true;
            if (why == null)
            {
                string block = GateRules.ShareBlock(ev);
                if (block == "g.block.used") why = S.Get("g.ovr.used", ev.FirstLabel.Length > 0 ? ev.FirstLabel : "—");
                else if (block == "g.block.certcap") why = CertCapWhy(ev);   // 9/23 the certain cap
                else why = S.Get("g.ovr.why", ev != null ? ev.HostCount : 0, HostsText(ev));
            }
            g.OverrideWhy = why;
        }

        /// <summary>9/23 the certain cap: why a certain detection needs a second host or the author's call now (the host, its count in the window, the day a slot frees).</summary>
        internal static string CertCapWhy(EvInfo ev)
        {
            var ci = Reporters.CertainOf(ev);
            string label = ev != null && ev.FirstLabel.Length > 0 ? ev.FirstLabel : "—";
            if (Reporters.Current.CertainUnknown) return S.Get("g.ovr.capunknown", label, GateRules.CertainCap, GateRules.CertainCapDays);   // (review: fail closed)
            return S.Get("g.ovr.certcap", label, ci.Certain.Count, GateRules.CertainCap, GateRules.CertainCapDays, Fmt.Date(ci.CertainFreeAt));
        }

        /// <summary>
        /// 9/23 the certain cap: 「このホストの確実な検知だけの共有: 直近 30 日に 1/2 件」 for a certain detection one host is
        /// enough for (<see cref="GateRules.CertainOneHost"/>), with the day a slot frees when at the cap ("" otherwise). Review:
        /// none on a record <see cref="GateRules.MinHosts"/> hosts back already (the cap does not apply to it); a trusted admin
        /// is never "at the cap" (<see cref="CapLine"/>); an admin's PC shares nothing and does not count (only a note).
        /// </summary>
        internal static string CertCapLine(EvInfo ev, int idx)
        {
            if (!GateRules.CertainOneHost(ev) || ev.HostCount >= GateRules.MinHosts) return "";
            if (App.Admin) return S.In(idx, "cap.admin", GateRules.CertainCap, GateRules.CertainCapDays);
            return CapLine(Reporters.CertainOf(ev), Reporters.TrustedHost(ev), Reporters.Current.CertainUnknown, idx);
        }

        /// <summary>Review: the ones of a host's certain-only shares lifted or undone later ("" when none, and where <see cref="CertCapLine"/> says nothing or on an admin's PC).</summary>
        internal static string CertLiftedLine(EvInfo ev, int idx)
        {
            if (App.Admin || !GateRules.CertainOneHost(ev) || ev.HostCount >= GateRules.MinHosts) return "";
            var ci = Reporters.CertainOf(ev);
            return ci.CertainLifted > 0 ? S.In(idx, "cap.lifted", ci.CertainLifted, GateRules.CertainCapDays) : "";
        }

        /// <summary>
        /// Review: one host's certain-only count: 「…直近 30 日に n/2 件」, then for a trusted admin 「（信頼する管理人なので、この
        /// 上限はありません）」 and never 「上限です」; when the count cannot be confirmed (<paramref name="unknown"/>) the fail-closed
        /// line; else at the cap the day a slot frees.
        /// </summary>
        internal static string CapLine(Reporters.Info i, bool trusted, bool unknown, int idx)
        {
            string t = S.In(idx, "cap.line", i.Certain.Count, GateRules.CertainCap, GateRules.CertainCapDays);
            if (trusted) return t + S.In(idx, "cap.trusted");
            if (unknown) return S.In(idx, "cap.unknown", GateRules.CertainCap, GateRules.CertainCapDays);
            if (i.Certain.Count >= GateRules.CertainCap) t += S.In(idx, "cap.full", Fmt.Date(i.CertainFreeAt));
            return t;
        }

        /// <summary>Review: the "Report hosts" dialog's lines on one host's certain-only shares (its count, and the ones lifted later); "" for a host with none.</summary>
        internal static string CapText(Reporters.Info i, bool unknown, int idx)
        {
            var o = new List<string>();
            if (i.Certain.Count > 0 || (unknown && !i.Trusted)) o.Add(CapLine(i, i.Trusted, unknown, idx));
            if (i.CertainLifted > 0) o.Add(S.In(idx, "cap.lifted", i.CertainLifted, GateRules.CertainCapDays));
            return string.Join("\n", o.ToArray());
        }

        /// <summary>
        /// The confirmation's lines on why an imported record may be shared (or that the author decides); v0.5.5 review: for one
        /// host (certain, trusted or the author's call) also whether this is the host's first zip, how many shared bans its
        /// reports backed lately, and other names the same player has in other records (the name is the zip's too).
        /// </summary>
        void BasisBullets(List<string> bullets, EvInfo ev, bool over)
        {
            if (ev == null || !ev.Imported) return;
            if (over) bullets.Add(S.Get("cf.p.override"));
            else { string t = GateRules.BasisWhy(ev, S.Idx); if (t.Length > 0) bullets.Add(S.Get("cf.p.basis", t)); }
            if (!GateRules.IsSingleHost(over ? "override" : GateRules.Basis(ev)) || data == null) return;
            string label = ev.FirstLabel.Length > 0 ? ev.FirstLabel : "—";
            var now = DateTime.UtcNow;
            // review: on the certain path a first zip from this name is in amber (the cap goes by the name and the PC mark: a
            // host that came before under another name would start again at 0)
            if (Reporters.HostZips(ev, data.Imported) <= 1) bullets.Add((!over && GateRules.Basis(ev) == "certain" ? ConfirmDialog.Warn : "") + S.Get("cf.p.hostfirst", label));
            bullets.Add(S.Get("cf.p.hostshares", label, Reporters.HostShares(ev, data.Imported, data.Journal, now, 30), Reporters.HostShares(ev, data.Imported, data.Journal, now, 180)));
            // 9/23 the certain cap: this host's shares on its certain detection alone (and, on that basis now, the count after
            // this one; a trusted admin's line says there is no cap: CapLine), and the ones lifted later (amber)
            string cap = CertCapLine(ev, S.Idx);
            if (cap.Length > 0)
            {
                if (!over && GateRules.Basis(ev) == "certain") cap += S.Get("cap.after", Reporters.CertainOf(ev).Certain.Count + 1, GateRules.CertainCap);
                bullets.Add(cap);
            }
            string lifted = CertLiftedLine(ev, S.Idx);
            if (lifted.Length > 0) bullets.Add(ConfirmDialog.Warn + lifted);
            var all = new List<EvInfo>(data.Imported);
            all.AddRange(data.Ev.Values);
            var other = Reporters.OtherNames(ev, all);
            if (other.Count > 0) bullets.Add(S.Get("cf.p.othernames", string.Join(S.Idx == 2 ? ", " : "、", other.ToArray())));
        }

        /// <summary>「状況証拠です…」 for evidence the gate does not trust (v0.5.5 review: not for a certain record its zip's log agrees with; the basis line says what that means).</summary>
        internal static void CircBullet(List<string> bullets, EvInfo ev)
        {
            if (!GateRules.Trusted(ev) && !GateRules.CertainLogged(ev)) bullets.Add(S.Get("cf.p.circ"));
        }

        /// <summary>
        /// v0.5.5 review: the records a share (or a lengthening) rests on, in the journal action ("backers"): the evidence for
        /// one host (certain, trusted or the author's call), the records <see cref="HostCount"/> counted for "hosts", none for
        /// this PC's own record. An overturn is charged only to these (<see cref="Reporters.Backers"/>). Review (the certain
        /// cap): an imported record's basis too ("gate", like the audit line's gate=), so a certain-only share still counts when
        /// its audit line could not be written or was cut off (<see cref="Reporters.CertainShareActions"/>).
        /// </summary>
        internal static void SetBackers(JObj a, EvInfo ev, Gate g)
        {
            var ids = new List<string>();
            string basis = g != null && g.Override ? "override" : GateRules.Basis(ev);
            if (ev != null && ev.Imported)
            {
                if (basis == "hosts") { foreach (var x in ev.HostRecords) if (!ids.Contains(x.Id)) ids.Add(x.Id); }
                else ids.Add(ev.Id);
                if (basis.Length > 0 && basis != "own") a.Set("gate", basis);
            }
            a.Set("backers", Json.Array(ids));
        }

        /// <summary>
        /// The gate's basis and the author's written reason go into the audit line (who and when come from the session); 9/23:
        /// on one host's imported record (certain / trusted / override) also that record's first-import host name (host=), the
        /// name the certain cap is counted by (<see cref="Reporters.CertainShareLines"/>).
        /// </summary>
        internal static void GateAudit(AuditRec au, Gate g, EvInfo ev)
        {
            if (au == null || g == null) return;
            au.Gate = g.Basis ?? "";
            au.Override = g.Override ? g.OverrideReason ?? "" : "";
            au.Host = ev != null && ev.Imported && GateRules.IsSingleHost(au.Gate) ? ev.FirstLabel : "";
        }

        static string HostsText(EvInfo ev) { return ev != null && ev.HostNames.Count > 0 ? string.Join(S.Idx == 2 ? ", " : "、", ev.HostNames.ToArray()) : "—"; }

        /// <summary>Why a shared change is not possible in admin mode: on a PC with the signing key (unlocked without the key) how to become the owner, else "propose it".</summary>
        static string AdminSharedKey() { return App.KeySignal ? "m.admin.shared.k" : "m.admin.shared"; }

        /// <summary>
        /// v0.5.5 review: stops (with a notice and an audit line) a shared line whose hash is not the linked evidence's own
        /// PUID hash (a ban entry or a journal edited to point at someone else); false when it is the evidence's player.
        /// </summary>
        bool BlockOtherPlayer(Row r, string listed)
        {
            if (GateRules.ListsEvidencePlayer(r.Ev, listed)) return false;
            App.Log("shared line refused: its hash is not the evidence record's player (" + (r.Ev != null ? r.Ev.Id : "-") + ")");
            Record(new AuditRec { Action = "blocked.puid", Ev = EvIdOf(r), Name = r.Name, Result = "outside" });
            ShowNotice(S.Get("g.block.title"), S.Get("g.block.puid"), Art.Amber1);
            return true;
        }

        void DoShare()
        {
            if (App.Admin) { DoProposeShare(); return; }   // (the button is hidden in admin mode)
            // v0.5.5 (2026-09-23): this reaches every host: the key challenge of this run, not the stored Windows Hello proof
            if (!KeyGate("share")) return;
            if (candView) { DoShareCand(); return; }
            var r = SelectedRow();
            var now = DateTime.UtcNow;
            if (r == null || !r.LocalActive(now) || r.Effective != null) return;
            // the legitimacy gate: no evidence file, no shared ban (it stays this PC's ban); v0.5.5: an imported record
            // only when it matches its zip's log and (「いいよ」) two hosts, a certain detection its log backs or a trusted
            // admin; one host otherwise: the author's written reason
            bool over;
            if (ShowBlock(r.Ev, "g.block.noev", true, out over)) return;
            var share = r.ShareHashes();   // the PUID's hash only (a friend code's hash could be guessed back)
            if (share.Count == 0) { status.Set(S.Get("e.nopuid"), Art.Amber1); ShowNotice(S.Get("g.block.title"), S.Get("e.nopuid"), Art.Amber1); return; }
            // v0.5.5 review: the entry's PUID hash (aegis-bans.json) must be the evidence's own player
            if (BlockOtherPlayer(r, share[0])) return;
            int level = GateRules.ShareLevel(r.Ev, r.Level);   // imported records only: level 1, 30 days at most
            DateTime? end;
            using (var pd = new PeriodDialog(S.Get("pd.head.g"), now, true, r.Expires, LadderDays(level), GateRules.MaxDays(r.Ev)))
            {
                if (pd.ShowDialog(this) != DialogResult.OK) return;
                end = pd.EndFor(pd.Days);
            }
            // the shared list holds a date: the ban applies through the end of that UTC day
            DateTime? date = end == null ? (DateTime?)null : end.Value.Date;
            string until = date == null ? "never" : date.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            var g = GateRules.For(r.Ev);
            g.Proposal = PastedFor(r.Key, false);
            if (g.NeedRule && g.Proposal != null && GateRules.IsGate(g.Proposal.Rule)) g.Rule = g.Proposal.Rule;   // preset only: the owner still confirms it
            SetOverride(g, r.Ev, over);
            var bullets = new List<string>();
            if (g.NeedRule) bullets.Add(S.Get("cf.p.line.rule", level, date == null ? S.Get("perm") : until + " (UTC)", Hashes.Short(share[0])));
            else bullets.Add(S.Get("cf.p.line", level, date == null ? S.Get("perm") : until + " (UTC)", GateRules.SharedReason(r.Ev, r.Rule, ""), Hashes.Short(share[0])));
            CircBullet(bullets, r.Ev);
            if (r.Ev.Imported) { bullets.Add(S.Get("v.imported")); bullets.Add(S.Get("cf.p.impcap")); bullets.Add(S.Get("cf.p.hosts", r.Ev.HostCount, HostsText(r.Ev))); BasisBullets(bullets, r.Ev, over); }
            if (end != null && end.Value <= now) bullets.Add(S.Get("cf.p.past"));
            bullets.Add(S.Get("cf.p.nolocal"));
            bullets.AddRange(SignBullets());
            if (!Confirm(S.Get("cf.share", r.Display), bullets, true, g)) return;
            string reason = GateRules.SharedReason(r.Ev, r.Rule, g.Rule);   // a reason CODE only: the written reason stays in audit.log
            var lines = new List<string>();
            foreach (var h in share) lines.Add(SharedLine.Format(h, level, date, reason));
            var a = Journal.NewAction("share", r.Hashes(), r.Name);
            a.Set("sharedAfter", Json.Array(lines));
            a.Set("localHist", HistLine("shared", "console: listed on the shared ban list" + (r.Evidence.Length > 0 ? " " + r.Evidence : "")));
            Ops.SetDesc(a, share[0], level, date, reason, false, EvIdOf(r), "", "");   // the listed PUID hash, never the friend code's
            SetBackers(a, r.Ev, g);
            var au = AuditFor("share", r, g, reason, "share");
            GateAudit(au, g, r.Ev);
            DoShared(a, au);
        }

        void DoShareCand()
        {
            var c = SelectedCand();
            if (c == null || c.Ev == null || c.Ev.Hash.Length == 0) return;
            var share = c.ShareHashes();   // the PUID's hash only (a friend code's hash could be guessed back)
            bool over;   // v0.5.5: an imported record must match its log; one host only (「いいよ」): the author's written reason
            if (ShowBlock(c.Ev, "g.block.noev", true, out over)) return;
            if (share.Count == 0) { status.Set(S.Get("e.nopuid"), Art.Amber1); ShowNotice(S.Get("g.block.title"), S.Get("e.nopuid"), Art.Amber1); return; }
            var now = DateTime.UtcNow;
            // v0.5.5 review: the line of the PUID's hash that will be listed only (never the record's other hash)
            SharedLine had = data != null && data.Effective != null ? data.Effective.Find(share[0]) : null;
            bool hadActive = had != null && had.ActiveAt(now), impOnly = GateRules.ImportedOnly(c.Ev);
            // an imported record never cuts down a ban in effect: a longer (or permanent) shared ban stays as it is
            if (impOnly && hadActive && GateRules.TooLong(c.Ev, had.EndsAt, now)) { ShowNotice(S.Get("g.block.title"), S.Get("g.block.stronger", had.Level, Fmt.SharedUntil(had, S.Idx)), Art.Amber1); return; }
            // v0.5.5 review: one host's record (certain / trusted) would keep a higher level of a line in effect for 30 more
            // days (the line is never lowered): only as the author's call
            string ovrWhy = null;
            if (!over && impOnly && hadActive && had.Level > 1 && GateRules.IsSingleHost(GateRules.Basis(c.Ev))) { over = true; ovrWhy = S.Get("g.ovr.level", had.Level); }
            // imported records only: level 1 for a new listing (rule 5c), the line's own level when it is still in effect (never lowered)
            int level = impOnly ? (hadActive ? Math.Max(1, had.Level) : 1) : GateRules.ShareLevel(c.Ev, had != null ? had.Level + 1 : 1);
            DateTime? end;
            using (var pd = new PeriodDialog(S.Get("pd.head.g"), now, false, null, LadderDays(level), GateRules.MaxDays(c.Ev)))
            {
                if (pd.ShowDialog(this) != DialogResult.OK) return;
                end = pd.EndFor(pd.Days);
            }
            DateTime? date = end == null ? (DateTime?)null : end.Value.Date;
            bool shorter = GateRules.Shortens(had, date == null ? (DateTime?)null : date.Value.AddDays(1), now);
            if (shorter && impOnly) { ShowNotice(S.Get("g.block.title"), S.Get("g.block.stronger", had.Level, Fmt.SharedUntil(had, S.Idx)), Art.Amber1); return; }
            var hashes = c.Hashes();
            string until = date == null ? "never" : date.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            string name = c.Ev.Name.Length > 0 ? c.Ev.Name : S.Get("noname") + " " + Hashes.Short(c.Ev.Hash);
            var g = GateRules.For(c.Ev);
            g.Proposal = PastedFor(c.Key, true);
            if (g.NeedRule && g.Proposal != null && GateRules.IsGate(g.Proposal.Rule)) g.Rule = g.Proposal.Rule;   // preset only: the owner still confirms it
            SetOverride(g, c.Ev, over, ovrWhy);
            var bullets = new List<string>();
            if (g.NeedRule) bullets.Add(S.Get("cf.p.line.rule", level, date == null ? S.Get("perm") : until + " (UTC)", Hashes.Short(share[0])));
            else bullets.Add(S.Get("cf.p.line", level, date == null ? S.Get("perm") : until + " (UTC)", GateRules.SharedReason(c.Ev, "", ""), Hashes.Short(share[0])));
            if (had != null) bullets.Add(S.Get("cf.p.ladder", had.Level, Fmt.SharedUntil(had, S.Idx), level));
            if (shorter) bullets.Add(S.Get("cf.p.shorter", had.Level, Fmt.SharedUntil(had, S.Idx)));
            CircBullet(bullets, c.Ev);
            if (c.Kind != "own")
            {
                bullets.Add(S.Get("v.imported"));
                if (!hadActive) bullets.Add(S.Get("cf.p.impcap"));   // (a line in effect keeps its level: the ladder line above says so)
                bullets.Add(S.Get("cf.p.hosts", c.Ev.HostCount, HostsText(c.Ev)));
                BasisBullets(bullets, c.Ev, over);
            }
            bullets.Add(S.Get("cf.p.nolocal"));
            bullets.AddRange(SignBullets());
            if (!Confirm(S.Get("cf.share", name), bullets, true, g)) return;
            string reason = GateRules.SharedReason(c.Ev, "", g.Rule);   // a reason CODE only: the written reason stays in audit.log
            var lines = new List<string>();
            foreach (var h in share) lines.Add(SharedLine.Format(h, level, date, reason));
            var a = Journal.NewAction("share", hashes, c.Ev.Name);
            a.Set("sharedAfter", Json.Array(lines));
            a.Set("localHist", HistLine("shared", "console: listed on the shared ban list " + c.Ev.Id));
            Ops.SetDesc(a, share[0], level, date, reason, false, c.Ev.Id, c.Kind == "own" ? "own" : "imp", "");   // the listed PUID hash, never the friend code's
            SetBackers(a, c.Ev, g);
            var au = new AuditRec { Action = "share", Ev = c.Ev.Id, Name = c.Ev.Name, Rule = reason, Reason = g.Reason ?? "" };
            if (g.Proposal != null && g.Proposal.Kind == "share") au.Proposer = g.Proposal.By + (g.Proposal.At != DateTime.MinValue ? " (" + Json.Time(g.Proposal.At) + ")" : "");
            GateAudit(au, g, c.Ev);
            DoShared(a, au);
        }

        void DoPeriod()
        {
            var r = SelectedRow();
            var now = DateTime.UtcNow;
            if (r == null) return;
            if (!Guard()) return;
            bool local = r.LocalActive(now), shared = r.Effective != null && !App.Admin;   // admin mode: this PC's ban only
            if (!local && !shared) { if (App.Admin && r.Effective != null) status.Set(S.Get(AdminSharedKey()), Art.Amber1); return; }
            // v0.5.5 (2026-09-23): changing a SHARED ban's length reaches every host (this PC's own ban stays on Windows Hello)
            if (shared && !KeyGate("period")) return;
            DateTime from = local && r.Since != DateTime.MinValue ? r.Since : now;
            int def = local ? (r.Days > 0 ? r.Days : 0) : (r.Effective.Expires == null ? 0 : 30);
            int days;
            DateTime? end;
            // v0.5.5 review: a shared ban on imported records only offers no choice past 30 days from now (unless the line in effect is longer: it may be shortened)
            int cap = shared ? GateRules.PeriodCap(r.Ev, r.Effective, from, now) : 0;
            using (var pd = new PeriodDialog(local ? S.Get("pd.head.l", Fmt.Local(from)) : S.Get("pd.head.g"), from, false, null, def, cap))
            {
                if (pd.ShowDialog(this) != DialogResult.OK) return;
                days = pd.Days;
                end = pd.EndFor(days);
            }
            string what = end == null ? S.Get("perm") : S.Get("v.days", days) + "・" + Fmt.UntilText(end, S.Idx);
            DateTime? date = end == null ? (DateTime?)null : end.Value.Date;
            string until = date == null ? "never" : date.Value.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
            // a longer shared ban (or an ended one brought back) is a new share in effect: the same legitimacy gate
            // (no evidence: blocked; circumstantial or imported evidence: the rule and a reason). Shortening needs none.
            bool extend = shared && GateRules.Lengthens(r.Effective, true, date == null ? (DateTime?)null : date.Value.AddDays(1), now);
            bool over = false;   // v0.5.5 (「いいよ」): one host only: the author's written reason
            if (extend && ShowBlock(r.Ev, "g.block.extend", true, out over)) return;
            // v0.5.5: a shared ban on imported records only is never longer than 30 days
            if (extend && GateRules.TooLong(r.Ev, date == null ? (DateTime?)null : date.Value.AddDays(1), now)) { ShowNotice(S.Get("g.block.title"), S.Get("g.block.impext"), Art.Amber1); return; }
            var share = r.ShareHashes();   // the PUID's hash (an old friend-code line is replaced by it); none known: the line as listed
            // v0.5.5 review: a longer line lists the evidence's own player only (a ban entry edited to someone else's PUID hash)
            if (extend && BlockOtherPlayer(r, share.Count > 0 ? share[0] : r.Effective.Hash)) return;
            // v0.5.5 review: an ended line brought back on imported records only starts again at level 1 (rule 5c)
            int lineLevel = extend ? GateRules.ExtendLevel(r.Ev, r.Effective, now) : r.Effective != null ? r.Effective.Level : 1;
            var g = extend ? GateRules.For(r.Ev) : new Gate { AskReason = true };
            g.Proposal = PastedFor(r.Key, false);
            if (extend) SetOverride(g, r.Ev, over);
            // v0.5.5 review: a shared ban ended or made shorter: 「誤りだった」 for the hosts whose reports backed it
            bool lifts = shared && !extend && ((end != null && end.Value <= now) || GateRules.Shortens(r.Effective, date == null ? (DateTime?)null : date.Value.AddDays(1), now));
            var backers = lifts && data != null ? Reporters.Backers(r.Effective.Hash, data.Imported, data.Journal, now) : new List<Reporters.Backer>();
            g.MistakeHosts = MistakeHostsOf(backers);
            var bullets = new List<string>();
            if (end != null && end.Value <= now) bullets.Add(S.Get("cf.p.past"));
            if (local) bullets.Add(S.Get(shared ? "cf.p.later" : "cf.p.now"));
            if (r.IsLocal) bullets.Add(S.Get("cf.p.count", r.Count));
            if (App.Admin && r.Effective != null) bullets.Add(S.Get(App.KeySignal ? "m.admin.shared.k" : "cf.p.adminlocal"));
            if (extend)
            {
                bullets.Add(S.Get("cf.p.extend"));
                string id = Hashes.Short(share.Count > 0 ? share[0] : r.Effective.Hash);
                if (g.NeedRule) bullets.Add(S.Get("cf.p.line.rule", lineLevel, date == null ? S.Get("perm") : until + " (UTC)", id));
                else bullets.Add(S.Get("cf.p.line", lineLevel, date == null ? S.Get("perm") : until + " (UTC)", r.Effective.Reason, id));
                if (lineLevel != r.Effective.Level) bullets.Add(S.Get("cf.p.implevel"));
                CircBullet(bullets, r.Ev);
                BasisBullets(bullets, r.Ev, over);
            }
            if (shared) bullets.AddRange(SignBullets());
            if (!Confirm(S.Get(shared ? "cf.period.g" : "cf.period.l", r.Display, what), bullets, shared, g)) return;
            // the line's reason code: as listed; when the gate asked for the rule (a longer ban on evidence that is not
            // this PC's certain one), the chosen rule
            string lineReason = shared ? (extend && g.NeedRule && GateRules.IsGate(g.Rule) ? g.Rule : r.Effective.Reason) : "";
            var au = AuditFor("period", r, g, shared ? lineReason : local ? r.Rule : "", "");
            if (extend) GateAudit(au, g, r.Ev);
            var a = Journal.NewAction("period", r.Hashes(), r.Name);
            if (local)
            {
                var nw = new JObj();
                nw.Set("days", JNum.Of(end == null ? 0 : days));
                nw.Set("expires", end == null ? null : Json.Time(end.Value));
                a.Set("localNew", nw);
                a.Set("localHist", HistLine("change", "console: " + (r.Expires == null ? "permanent" : Json.Time(r.Expires.Value)) + " -> " + (end == null ? "permanent" : Json.Time(end.Value))));
                a.Set("guardSince", r.Entry.Str("since"));
            }
            // the shared line's id only (a PUID's hash; the commit message is public), else the evidence id
            Ops.SetDesc(a, shared ? (share.Count > 0 ? share[0] : r.Effective.Hash) : "", shared ? lineLevel : 0, date, lineReason, local && shared, EvIdOf(r), "", "");
            if (extend) SetBackers(a, r.Ev, g);   // (v0.5.5 review: a lengthening is a listing in effect: its backers)
            if (shared)
            {
                var lines = new List<string>();
                foreach (var h in (share.Count > 0 ? share : new List<string> { r.Effective.Hash })) lines.Add(SharedLine.Format(h, lineLevel, date, lineReason));
                a.Set("sharedAfter", Json.Array(lines));
                DoShared(a, au, MistakeAfter(g, backers, a, "period"));
            }
            else DoLocal(a, au);
        }

        void DoUndo()
        {
            var r = SelectedRow();
            if (r == null || data == null) return;
            if (!Guard()) return;
            var orig = Journal.LastUndoable(data.Journal, r.Hashes());
            if (orig == null) { status.Set(S.Get("e.noundo"), Art.Amber1); return; }
            // v0.5.5 review: undoing a lift: its overturned reports (and a pause resting on them) no longer count, so the
            // gate below is checked as if the lift were undone already
            Reporters.State without = null;
            try { without = Reporters.From(data, DateTime.UtcNow, orig.Str("id")); }
            catch (Exception ex) { App.Log("report hosts not read for the undo: " + ex.Message); }
            string kindKey = "ak." + orig.Str("kind");
            string what = S.Has(kindKey) ? S.Get(kindKey) : orig.Str("kind");
            bool shared = orig.Has("sharedAfter");
            bool local = orig.Obj("localOld") != null;
            if (shared && App.Admin) { ShowNotice(S.Get("b.undo"), S.Get("e.admin.undo"), Art.Amber1); return; }
            // v0.5.5 (2026-09-23): undoing a SHARED change reaches every host (an undo of this PC's ban stays on Windows Hello)
            if (shared && !KeyGate("undo")) return;
            // the lines an undo puts back: when they list the player again or longer (the undo of an unban or of a
            // shortening), it is a share in effect and gets the same legitimacy gate
            var now = DateTime.UtcNow;
            var restore = shared ? Json.Strings(orig.Arr("sharedBefore")) : new List<string>();
            bool any = false, never = false;
            DateTime? newEnd = null;
            foreach (var l in restore)
            {
                var b = SharedLine.Parse(l);
                if (b == null) continue;
                any = true;
                if (b.EndsAt == null) never = true;
                else if (newEnd == null || b.EndsAt.Value > newEnd.Value) newEnd = b.EndsAt;
            }
            if (never) newEnd = null;
            bool extend = shared && GateRules.Lengthens(r.Effective, any, newEnd, now);
            bool over = false, capped;
            List<string> putBack;
            Gate g;
            List<Reporters.Backer> backers;
            var scope = new Reporters.Scope(without);   // (the gate and the confirmation only)
            try
            {
                if (extend && ShowBlock(r.Ev, "g.block.extend", true, out over)) return;   // v0.5.5 (「いいよ」): one host only: the author's written reason
                if (extend && GateRules.TooLong(r.Ev, newEnd, now)) { ShowNotice(S.Get("g.block.title"), S.Get("g.block.impext"), Art.Amber1); return; }
                // v0.5.5 review: the lines put back list the evidence's own player only (journal.json is a plain file), and on
                // imported records only they start again at level 1 (rule 5c)
                if (extend)
                    foreach (var l in restore)
                    {
                        var b = SharedLine.Parse(l);
                        if (b != null && BlockOtherPlayer(r, b.Hash)) return;
                    }
                putBack = extend ? GateRules.CapLines(r.Ev, restore) : restore;
                capped = extend && string.Join("\n", putBack.ToArray()) != string.Join("\n", restore.ToArray());
                var bullets = new List<string>();
                if (local) bullets.Add(S.Get(shared ? "cf.p.later" : "cf.p.now"));
                if (orig.Str("kind") == "add") bullets.Add(S.Get("cf.p.undoadd"));
                else if (r.IsLocal) bullets.Add(S.Get("cf.p.count", r.Count));
                if (extend) { bullets.Add(S.Get("cf.p.extend")); if (capped) bullets.Add(S.Get("cf.p.implevel")); CircBullet(bullets, r.Ev); BasisBullets(bullets, r.Ev, over); }
                if (shared) bullets.AddRange(SignBullets());
                g = extend ? GateRules.For(r.Ev) : new Gate { AskReason = true };
                if (extend) SetOverride(g, r.Ev, over);
                // v0.5.5 review: undoing a share (or a lengthening) takes that listing off: 「誤りだった」 for the hosts its backers came from
                backers = shared && !extend && (orig.Has("backers") || orig.Str("kind") == "share") ? Reporters.BackersOf(orig, data.Imported) : new List<Reporters.Backer>();
                g.MistakeHosts = MistakeHostsOf(backers);
                if (!Confirm(S.Get(shared ? "cf.undo.g" : "cf.undo.l", r.Display, what), bullets, shared, g)) return;
            }
            finally { scope.Dispose(); }
            var au = AuditFor("undo", r, g, extend && g.NeedRule ? g.Rule : orig.Str("kind"), "");
            if (extend) GateAudit(au, g, r.Ev);
            var a = Journal.NewAction("undo", Json.Strings(orig.Arr("hashes")), r.Name);
            a.Set("undoOf", orig.Str("id"));
            if (local)
            {
                a.Set("localNew", orig.Obj("localOld"));
                a.Set("localHist", HistLine("undo", "console: undo of " + orig.Str("kind")));
                if (orig.Str("guardSince").Length > 0) a.Set("guardSince", orig.Str("guardSince"));
            }
            // the shared line's id (the lines put back, else those taken away), else the evidence id; never "undo: " + the
            // old desc (an older build's desc could hold 8 digits of the friend code's hash)
            string lineHash = shared ? Ops.FirstLineHash(restore) : "";
            if (shared && lineHash.Length == 0) lineHash = Ops.FirstLineHash(Json.Strings(orig.Arr("sharedAfter")));
            Ops.SetDesc(a, lineHash, 0, null, "", false, EvIdOf(r), "", orig.Str("kind"));
            if (extend) SetBackers(a, r.Ev, g);   // (v0.5.5 review: the listing put back rests on this evidence)
            if (shared) { a.Set("sharedAfter", capped ? Json.Array(putBack) : (orig.Arr("sharedBefore") ?? new List<object>())); DoShared(a, au, MistakeAfter(g, backers, a, "undo")); }
            else DoLocal(a, au);
        }

        // ---- v0.5.5: admin proposals, adding a ban from a candidate, pasting a proposal

        static string EvIdOf(Row r) { return r.Evidence.Length > 0 ? r.Evidence : r.Ev != null ? r.Ev.Id : ""; }

        void DoProposeUnban()
        {
            var r = SelectedRow();
            if (r == null || r.Effective == null) return;
            if (!Guard()) return;   // a proposal carries the proposer: made only once unlocked
            var p = new Proposal { Kind = "unban", Ev = EvIdOf(r), Name = r.Name, Line = Proposal.LineId(r.Effective.Hash), Strength = Proposal.StrengthOf(r.Ev) };
            MakeProposal(p, S.Get("pp.unban", r.Display), false, new List<string> { S.Get("pp.send.unban") });
        }

        void DoProposeShare()
        {
            if (!Guard()) return;
            EvInfo ev;
            string name, evId;
            List<string> share;
            if (candView)
            {
                var c = SelectedCand();
                if (c == null || c.Ev == null) return;
                ev = c.Ev; evId = c.Ev.Id; share = c.ShareHashes();
                name = c.Ev.Name.Length > 0 ? c.Ev.Name : S.Get("noname") + " " + Hashes.Short(c.Ev.Hash);
            }
            else
            {
                var r = SelectedRow();
                if (r == null || r.Effective != null) return;
                ev = r.Ev; evId = EvIdOf(r); share = r.ShareHashes(); name = r.Display;
            }
            // the same gate as the author's: no evidence file, nothing to propose; no PUID, nothing that can be listed
            bool over;   // v0.5.5: the same rules for imported records (their log, a flagged host); one host only (「いいよ」): the author decides
            if (ShowBlock(ev, "g.block.noev.a", true, out over)) return;
            if (share.Count == 0) { ShowNotice(S.Get("g.block.title"), S.Get("e.nopuid"), Art.Amber1); return; }
            var p = new Proposal
            {
                Kind = "share", Ev = evId, Name = ev.Name, Line = Proposal.LineId(share[0]), Strength = Proposal.StrengthOf(ev),
                Rule = GateRules.Trusted(ev) ? SharedLine.ReasonOf(ev.Rule) : "",
            };
            // the author's gate trusts only certain evidence recorded on the PC that holds it: an imported record needs the rule too
            var notes = new List<string> { S.Get("pp.send.share") };
            if (over) notes.Add(GateRules.ShareBlock(ev) == "g.block.certcap" ? CertCapWhy(ev) : S.Get("pp.onehost"));   // (9/23: a certain detection past the cap says so)
            else if (App.Admin && GateRules.Basis(ev) == "certain") notes.Add(S.Get("cap.admin", GateRules.CertainCap, GateRules.CertainCapDays));   // (review: the author's PC counts the cap)
            MakeProposal(p, S.Get("pp.share", name), !GateRules.Trusted(ev), notes);
        }

        void MakeProposal(Proposal draft, string statement, bool needRule, List<string> notes)
        {
            Proposal q;
            using (var d = new ProposalDialog(draft, statement, needRule, notes))
            {
                if (d.ShowDialog(this) != DialogResult.OK || d.Result == null) return;
                q = d.Result;
            }
            if (!StillUnlocked()) return;
            bool logged = Audit.Append(new AuditRec { At = q.At, Action = "propose." + q.Kind, Ev = q.Ev, Name = q.Name, Rule = q.Rule, Reason = q.Reason, Proposer = q.By, Result = "copied" });
            if (logged) status.Set(S.Get("m.propcopied"), Art.Green1);
            else status.Set(S.Get("m.propcopied") + "  ·  " + S.Get("m.auditfail"), Art.Amber1);
            ShowDetail();
        }

        /// <summary>The level of the shared line that applies now to one of these hashes (the ladder goes on from it, like the mod).</summary>
        int SharedLevelNow(ICollection<string> hashes, DateTime now)
        {
            int lv = 0;
            if (data == null || data.Repo == null) return 0;
            foreach (var h in hashes) { var b = data.Repo.Find(h); if (b != null && b.ActiveAt(now)) lv = Math.Max(lv, b.Level); }
            return lv;
        }

        /// <summary>
        /// "BAN を追加（この PC）": this PC's ban of a candidate's player, from its evidence record only (never from a typed
        /// name). The legitimacy gate and the 5-second check first; the mod's ladder rules (<see cref="Ops.PlanAdd"/>).
        /// </summary>
        void DoAdd()
        {
            var c = SelectedCand();
            if (c == null || c.Ev == null || c.Ev.Hash.Length == 0 || data == null) return;
            if (!Guard()) return;
            var ev = c.Ev;
            // v0.5.5 review: a record naming two players (never made by the launcher) would ban both on this PC
            if (ev.Mixed) { ShowNotice(S.Get("g.block.title"), S.Get("g.block.mixed"), Art.Amber1); return; }
            var now = DateTime.UtcNow;
            var hashes = c.Hashes();
            Row have = null;
            foreach (var r in data.Rows)
                if (r.Entry != null && (hashes.Contains(r.Hash) || (r.PuidHash.Length > 0 && hashes.Contains(r.PuidHash)))) { have = r; break; }
            int prior = have != null ? have.Count : 0;
            bool running = have != null && have.LocalActive(now);
            int sharedLevel = SharedLevelNow(hashes, now);
            int step = Math.Min(Math.Max(prior, sharedLevel) + 1, 3);
            int days;
            using (var pd = new PeriodDialog(S.Get("pd.head.add"), now, false, null, LadderDays(step)))
            {
                if (pd.ShowDialog(this) != DialogResult.OK) return;
                days = pd.Days;
            }
            var plan = Ops.PlanAdd(prior, sharedLevel, running, have != null ? have.Expires : null, days, now);
            string name = ev.Name.Length > 0 ? ev.Name : S.Get("noname") + " " + Hashes.Short(ev.Hash);
            var g = GateRules.For(ev);
            g.Proposal = PastedFor(c.Key, true);
            var bullets = new List<string> { S.Get("cf.p.addcount", plan.Count, plan.Level), S.Get("cf.p.addlen", Fmt.UntilText(plan.Expires, S.Idx)) };
            if (plan.KeptLonger) bullets.Add(S.Get("cf.p.addrun", Fmt.UntilText(have.Expires, S.Idx)));
            bullets.Add(S.Get("cf.p.addfrom", ev.Id, c.FromText));
            if (!GateRules.Trusted(ev)) bullets.Add(S.Get("cf.p.circ"));
            if (c.Kind != "own") bullets.Add(S.Get("v.imported"));
            if (!ev.LogOk) bullets.Add(S.Get("cf.p.nolog", LogCheck.Why(ev, S.Idx)));   // this PC's ban is still possible; the shared list is not
            if (Reporters.Unreliable(ev)) { var ri = Reporters.InfoOf(ev); bullets.Add(S.Get("cf.p.unreliable", ri.Label.Length > 0 ? ri.Label : ev.FirstLabel, ri.Count)); }   // v0.5.5 (「いいよ」)
            bullets.Add(S.Get("cf.p.now"));
            bullets.Add(S.Get("cf.p.addnoshare"));
            if (!Confirm(S.Get("cf.add", name), bullets, false, g)) return;
            if (!StillUnlocked()) return;
            string rule = GateRules.Trusted(ev) ? ev.Rule : g.Rule;
            var a = Journal.NewAction("add", hashes, ev.Name);
            Ops.SetDesc(a, "", 0, null, rule, false, ev.Id, c.Kind == "own" ? "own" : "imp", "");   // this PC only: never in a commit
            var steps = new List<Step> { new Step(S.Get("step.local"), st => Ops.RunAdd(a, ev, days, rule, sharedLevel, st)) };
            bool ok;
            using (var f = new OpForm(S.Get("op.local"), steps, false, null) { OkText = S.Get("op.ok.local") }) { RunOp(f); ok = f.Ok; }
            if (ok) Record(new AuditRec { Action = "add", Ev = ev.Id, Name = ev.Name, Rule = rule, Reason = g.Reason ?? "", Act = a.Str("id"), Result = "done.local" });
            Reload(false);
        }

        /// <summary>
        /// "提案を貼り付け" (owner): reads a proposal, finds its target by evidence id or shared line id, selects it and shows the
        /// proposal next to the evidence. It never does anything else: the owner acts with the usual buttons and checks.
        /// </summary>
        void DoPaste()
        {
            if (App.Admin || data == null) return;
            string text;
            using (var d = new PasteDialog())
            {
                if (d.ShowDialog(this) != DialogResult.OK) return;
                text = d.Pasted;
            }
            string err;
            var p = Proposal.Parse(text, out err);
            if (p == null) { ShowNotice(S.Get("pa.title"), err ?? S.Get("pa.none"), Art.Amber1); return; }
            var hit = ProposalMatch.Find(data, p);
            if (hit == null)
            {
                pasted = null; pastedKey = ""; pastedWarn = "";
                ShowDetail();
                ShowNotice(S.Get("pa.title"), S.Get("pa.nomatch", S.Get("pa.desc", p.Ev.Length > 0 ? p.Ev : "—", p.Line.Length > 0 ? p.Line : "—")), Art.Amber1);
                return;
            }
            pasted = p;
            pastedCand = hit.Cand != null;
            pastedKey = hit.Key;
            pastedWarn = hit.Warn ?? "";
            App.Log("proposal pasted: " + p.Kind + " " + (p.Ev.Length > 0 ? p.Ev : "-") + " → " + (pastedCand ? "candidate" : "ban") + (pastedWarn.Length > 0 ? " (" + pastedWarn + ")" : "") + (p.Found > 1 ? " (" + p.Found + " proposal lines)" : ""));
            // show it whatever the filters and the search were
            filling = true;
            cState.SelectedIndex = 2;
            cScope.SelectedIndex = 0;
            filling = false;
            search.Text = "";
            searchDelay.Stop();
            searchMode = 0; searchNorm = ""; searchHash = "";
            if (pastedCand) selCand = pastedKey; else selBan = pastedKey;
            tab = 0; tEv.Active = true; tHist.Active = false; tPolicy.Active = false;
            SetView(pastedCand);
            status.Set(S.Get("pa.found", hit.Name), Ui.Violet);
        }

        void DoDismiss()
        {
            var c = SelectedCand();
            if (c == null) return;
            if (!Guard()) return;
            try
            {
                if (c.Kind == "own") File.AppendAllText(App.DismissedFile, c.Ev.Id + "\r\n", new UTF8Encoding(false));
                else
                {
                    string dir = Path.Combine(App.ReviewedDir, Path.GetFileName(Path.GetDirectoryName(c.Path)));
                    Directory.CreateDirectory(dir);
                    string dest = Path.Combine(dir, Path.GetFileName(c.Path));
                    if (File.Exists(dest)) File.Delete(dest);
                    File.Move(c.Path, dest);
                    // v0.5.5: the import's source.txt (its host) goes along, so the record still counts for its host
                    string src = Path.Combine(Path.GetDirectoryName(c.Path), "source.txt"), srcTo = Path.Combine(dir, "source.txt");
                    if (File.Exists(src) && !File.Exists(srcTo)) File.Copy(src, srcTo);
                }
                status.Set(S.Get("m.dismissed"), Ui.Muted);
            }
            catch (Exception e) { status.Set(e.Message, Art.Red1); App.Log("dismiss: " + e.Message); }
            Reload(false);
        }

        void DoPublish()
        {
            if (App.Admin) { status.Set(S.Get(AdminSharedKey()), Art.Amber1); return; }   // admin mode never publishes
            // v0.5.5 (2026-09-23): the push is what actually reaches every host (the change was signed, but it is still here)
            if (!KeyGate("publish")) return;
            var pend = Ops.LoadPending();
            if (pend == null) { status.Set(S.Get("e.nothing"), Art.Amber1); Reload(false); return; }
            var bullets = new List<string> { S.Get("cf.p.files", App.RepoDir) };
            // each change in the UI language (the commit message itself keeps the Japanese lines)
            var journal = Journal.Load();
            var ids = Json.Strings(pend.Arr("actions"));
            var changes = Json.Strings(pend.Arr("changes"));
            for (int i = 0; i < Math.Max(ids.Count, changes.Count); i++)
            {
                var act = i < ids.Count ? Journal.Find(journal, ids[i]) : null;
                string l = act != null ? Ops.DescIn(S.Idx, act) : i < changes.Count ? changes[i] : "";
                if (l.Length > 0) bullets.Add(S.Get("cf.p.change", l));
            }
            bullets.Add(S.Get("cf.p.checks"));
            if (!Confirm(S.Get("cf.publish", pend.Int("version")), bullets, true)) { Reload(false); return; }
            if (!StillUnlocked()) { Reload(false); return; }
            var ctx = new Ops.PublishCtx();
            var steps = new List<Step>
            {
                new Step(S.Get("step.git"), st => Ops.GitCheck(ctx, st)),
                new Step(S.Get("step.fetch"), st => Ops.GitFetch(ctx, st)),
                new Step(S.Get("step.place"), st => Ops.Place(ctx, st)),
                new Step(S.Get("step.commit"), st => Ops.Commit(ctx, st)),
                new Step(S.Get("step.push"), st => Ops.Push(ctx, st)),
                new Step(S.Get("step.finish"), st => Ops.Finish(ctx, st)),
            };
            bool ok;
            using (var f = new OpForm(S.Get("op.push"), steps, true, null))
            {
                ctx.Form = f;
                f.OkText = S.Get("op.ok.push", "v" + pend.Int("version").ToString(CultureInfo.InvariantCulture));
                RunOp(f);
                ok = f.Ok;
            }
            // v0.5.5: the audit line names the key that signed it and the commit (12 hex digits)
            if (ok) Record(new AuditRec { Action = "publish", Act = string.Join(",", Json.Strings(pend.Arr("actions")).ToArray()),
                Result = "pushed " + pend.Int("version").ToString(CultureInfo.InvariantCulture) + (ctx.Commit.Length > 0 ? " " + ctx.Commit.Substring(0, Math.Min(8, ctx.Commit.Length)) : ""),
                KeyId = SigKeyId(App.RepoDefs), Commit = ctx.Commit.Length > 0 ? ctx.Commit.Substring(0, Math.Min(12, ctx.Commit.Length)) : "" });
            Reload(false);
        }

        void DoDiscard()
        {
            var pend = Ops.LoadPending();
            if (pend == null) { Reload(false); return; }
            if (!Guard()) return;
            if (!Confirm(S.Get("cf.discard", pend.Int("version"), Json.Strings(pend.Arr("changes")).Count), new List<string> { S.Get("cf.p.discard") }, false)) return;
            if (!StillUnlocked()) return;
            Ops.Discard();
            status.Set(S.Get("m.discarded"), Ui.Muted);
            Record(new AuditRec { Action = "discard", Act = string.Join(",", Json.Strings(pend.Arr("actions")).ToArray()), Result = "discarded " + pend.Int("version").ToString(CultureInfo.InvariantCulture) });
            Reload(false);
        }

        void DoImport()
        {
            if (!Guard()) return;
            string init = Path.Combine(App.RepoDir, "reports");
            if (!Directory.Exists(init)) init = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
            string[] files;
            using (var ofd = new OpenFileDialog { Filter = "zip (*.zip)|*.zip", Multiselect = true, InitialDirectory = init, Title = S.Get("import") })
            {
                if (ofd.ShowDialog(this) != DialogResult.OK) return;
                files = ofd.FileNames;
            }
            // v0.5.5: the host of each zip (the two-hosts rule for imported records)
            List<string> hosts;
            using (var hd = new ImportHostDialog(files, ImportMeta.KnownHosts()))
            {
                if (hd.ShowDialog(this) != DialogResult.OK) return;
                hosts = new List<string>(hd.Labels);
            }
            if (!StillUnlocked()) return;
            int ev = 0, lines = 0;
            var steps = new List<Step>();
            for (int i = 0; i < files.Length; i++)
            {
                string zip = files[i], host = i < hosts.Count ? hosts[i] : "";
                steps.Add(new Step(S.Get("step.zip", Path.GetFileName(zip)), st => Ops.Import(zip, host, st, ref ev, ref lines)));
            }
            using (var f = new OpForm(S.Get("op.import"), steps, false, null))
            {
                // the result counts are known only after the steps: the text is filled in when the last step runs
                steps.Add(new Step(S.Get("step.record"), st => { f.OkText = S.Get("op.ok.import", ev, lines); st.Detail = S.Get("step.zip.d", ev, lines); return true; }));
                f.View.Steps.Add(steps[steps.Count - 1]);
                f.View.Height = f.View.PreferredRowsHeight;
                f.ClientSize = new Size(f.ClientSize.Width, f.View.Height + Ui.S(54));
                RunOp(f);
            }
            SetView(true);
            Reload(false);
        }

        void DoSettings()
        {
            bool hosts = false;
            using (var d = new SettingsDialog())
            {
                if (d.ShowDialog(this) != DialogResult.OK) return;
                hosts = d.OpenHosts;
                if (d.Proposer != Settings.Get("proposer", "")) Settings.Set("proposer", d.Proposer ?? "");
                if ((d.Staff ?? "") != Settings.Get("staff", "")) Settings.Set("staff", d.Staff ?? "");
                // v0.5.5: the folders decide what is read and written: changed only once unlocked
                bool repo = d.Repo.Length > 0 && !string.Equals(d.Repo, App.RepoDir, StringComparison.OrdinalIgnoreCase);
                bool game = d.Game.Length > 0 && !string.Equals(d.Game, App.GameDir, StringComparison.OrdinalIgnoreCase);
                if (repo || game)
                {
                    bool ok = Guard();
                    // v0.5.5 review: the unlock changed the mode and started a reload: nothing is changed (said once it is done)
                    if (!ok && Session.Unlocked) afterReload = (afterReload.Length > 0 ? afterReload + "  ·  " : "") + S.Get(Session.OwnerActive || !App.KeySignal ? "set.again" : "set.owneronly");
                    // v0.5.5 review: on a PC with the signing key the folders change only as the owner (the key password goes into
                    // a script found through them), unless no signing script is found at all (the owner would be locked out)
                    if (ok && App.KeySignal && !Session.OwnerActive && File.Exists(App.SignScript)) { ShowNotice(S.Get("settings"), S.Get("set.owneronly"), Art.Amber1); ok = false; }
                    if (ok)
                    {
                        if (repo) { App.RepoDir = d.Repo; Settings.Set("repo", d.Repo); }
                        if (game) { App.GameDir = d.Game; Settings.Set("game", d.Game); }
                        // the new folders in the audit line (this PC's log only)
                        string where = (repo ? "repo=" + d.Repo : "") + (repo && game ? "; " : "") + (game ? "game=" + d.Game : "");
                        Record(new AuditRec { Action = "settings", Reason = where, Result = "folder." + (repo && game ? "both" : repo ? "repo" : "game") });
                    }
                }
            }
            if (hosts && busy == 0) DoReporters();   // v0.5.5 (「いいよ」): 「取り込み元のホスト…」 (not while an unlock's reload runs)
            status.RightText = App.BansPath;
            Reload(true);
        }

        /// <summary>
        /// v0.5.5 (2026-09-22 「いいよ」) 「取り込み元のホスト」: make a host a trusted admin, stop trusting it, or clear its
        /// overturned reports. The owner mode only, after the unlock and the 5-second check (an optional reason); one line
        /// in reporters.txt and one in audit.log (host.trust / host.untrust / host.clear). The state is built again at once
        /// (the reload after the settings counts the hosts again); the dialog opens again until it is closed.
        /// </summary>
        void DoReporters()
        {
            string pick = "";
            while (true)
            {
                string act, label;
                var snap = data;
                Func<string, List<string>> active = l => snap == null ? new List<string>() : Reporters.ActiveLines(l, "", snap.Imported, snap.Journal, snap.Effective, DateTime.UtcNow, S.Idx);
                using (var d = new ReporterDialog(Reporters.Current, !App.Admin, pick, active))
                {
                    if (d.ShowDialog(this) != DialogResult.OK) return;
                    act = d.Act; label = d.Chosen;
                }
                pick = label;
                if (label.Length == 0) return;
                if (App.Admin) { ShowNotice(S.Get("rh.title"), S.Get("rh.owneronly"), Art.Amber1); return; }
                // v0.5.5 (2026-09-23 「乗っ取られたら…」): trusting a host, dropping that trust and clearing its overturned
                // reports all change how OTHER hosts' reports are treated here, and nothing about them is signed — so this is
                // the one 「みんなに届く」 path that the signing password never covered. It needs the key challenge of this run.
                if (act != "trust" && act != "untrust" && act != "clear") return;
                if (!KeyGate("host." + act)) return;
                if (!Session.OwnerActive || !Session.KeyProven) { ShowNotice(S.Get("rh.title"), S.Get("rh.owneronly"), Art.Amber1); return; }
                var info = Reporters.Current.For(label, "");
                var bullets = new List<string>();
                string statement;
                if (act == "trust")
                {
                    statement = S.Get("cf.trust", label);
                    bullets.Add(S.Get("cf.p.trust1", GateRules.CertainCap, GateRules.CertainCapDays)); bullets.Add(S.Get("cf.p.trust2")); bullets.Add(S.Get("cf.p.trust3", Reporters.WindowDays, Reporters.Threshold));
                }
                else if (act == "untrust") { statement = S.Get("cf.untrust", label); bullets.Add(S.Get("cf.p.untrust")); }
                else if (act == "clear")
                {
                    statement = S.Get("cf.clear", label);
                    // v0.5.5 review: a pause lifted, or only the overturns so far (no pause yet); and the names a PC mark links
                    bullets.Add(S.Get(info.Flagged ? "cf.p.clear" : "cf.p.clear1", info.Count, Fmt.Date(info.ResumeAt)));
                    string over = Reporters.OverText(info, S.Idx);
                    if (over.Length > 0) bullets.Add(over);
                    var linked = Reporters.Current.Linked(label);
                    if (linked.Count > 0) bullets.Add(S.Get("cf.p.clearlinked", string.Join(S.Idx == 2 ? ", " : "、", linked.ToArray())));
                    // review: the certain-only count is not reset (the host may still be at that cap)
                    if (info.Certain.Count > 0) bullets.Add(S.Get("cf.p.clearcap", info.Certain.Count, GateRules.CertainCap, GateRules.CertainCapDays));
                }
                else return;
                bullets.Add(S.Get("cf.p.hostset"));
                var g = new Gate { AskReason = true };
                if (!Confirm(statement, bullets, false, g)) continue;
                if (!StillUnlocked()) return;
                // v0.5.5 review: audit.log first (the authority: trust and clears count only from its lines), then the copy
                var at = DateTime.UtcNow;
                if (!Audit.Append(new AuditRec { At = at, Action = "host." + act, Name = label, Reason = g.Reason ?? "", Result = "done.local" })) { ShowNotice(S.Get("rh.title"), S.Get("m.auditfail"), Art.Amber1); return; }
                if (!Reporters.Append(new Reporters.Event { Kind = act, At = at, Label = label })) status.Set(S.Get("m.hostsfail"), Art.Amber1);
                Reporters.Current = Reporters.From(data, DateTime.UtcNow);
                status.Set(S.Get("m.hosts.done"), Art.Green1);
            }
        }

        void DoCopy()
        {
            string text = candView ? CopyCand(SelectedCand()) : CopyRow(SelectedRow());
            if (string.IsNullOrEmpty(text)) return;
            try { Clipboard.SetText(text); status.Set(S.Get("m.copied"), Art.Green1); }
            catch (Exception e) { status.Set(e.Message, Art.Red1); }
        }

        /// <summary>v0.5.5 review: every evidence record this console knows (this PC's and the imported ones): a reply's number for a row only on the shared list.</summary>
        List<EvInfo> Records()
        {
            var o = new List<EvInfo>();
            if (data == null) return o;
            o.AddRange(data.Ev.Values);
            o.AddRange(data.Imported);
            return o;
        }

        /// <summary>
        /// v0.5.5 the reply (the one way a reply is made: the ban list's 「返事の例」, for any row: this PC's ban, a shared ban
        /// seen here, a row only on the shared list, a lifted or minimised one; the search and the evidence / history tabs only
        /// select the row): the ban's number and date found for the row (<see cref="Replies.FieldsOf"/>), the addressee from the
        /// record's name (checked against the NG list in use), the rule for a rejection (a category only), the end.
        /// </summary>
        void DoReply()
        {
            var r = SelectedRow();
            if (r == null) return;
            var f = Replies.FieldsOf(r, data != null ? data.Journal : null, DateTime.UtcNow, Records());
            var ng = NgNames.Load(data != null ? data.Effective : null, App.NgFile);
            using (var d = new ReplyDialog(r.Name, f, ng, m => status.Set(m, Art.Green1))) d.ShowDialog(this);
        }

        // ---- the evidence sheet for a Discord ticket (always Japanese)

        static void Line(StringBuilder sb, string k, string v) { if (!string.IsNullOrEmpty(v)) sb.Append("・").Append(S.In(0, k)).Append(": ").Append(v).Append("\n"); }

        /// <summary>v0.5.5 review: the text key of a record's action other than "ban": a "hold" or "notice" record (the 30 days after an accepted appeal) is not shown as a kick.</summary>
        internal static string EvActionKey(string action) { return action == "hold" ? "v.hold" : action == "notice" ? "v.notice" : "v.kick"; }

        static string SheetOf(JObj o, StringBuilder sb)
        {
            string strength = o.Str("strength");
            Line(sb, "k.time", Fmt.LocalUtc(o.Time("time")));
            var ban = o.Obj("ban");
            if (o.Str("action") == "ban" && ban != null)
            {
                int days = ban.Int("days");
                Line(sb, "k.action", S.In(0, "v.ban", days > 0 ? S.In(0, "v.days", days) : S.In(0, "perm"), ban.Int("offence")) + "・" + S.In(0, "lv", ban.Int("level")) + (ban.Time("expires") != null ? "・" + S.In(0, "until", Fmt.Local(ban.Time("expires"))) : ""));
            }
            else Line(sb, "k.action", S.In(0, EvActionKey(o.Str("action"))));
            Line(sb, "k.strength", Fmt.Strength(strength, 0) + "（" + S.In(0, strength == "certain" ? "st.certain.n" : "st.circ.n") + "）");
            Line(sb, "k.rule", S.RuleIn(0, o.Str("rule")) + "（" + o.Str("rule") + "）");
            var d = o.Obj("detection");
            if (d != null)
            {
                Line(sb, "k.detail", d.Str("detail"));
                var hits = d.Obj("hits");
                if (hits != null && hits.Items.Count > 0)
                {
                    var h = new StringBuilder();
                    foreach (var kv in hits.Items) { if (h.Length > 0) h.Append(", "); h.Append(kv.Key).Append(" ×").Append(Json.ToInt(kv.Value)); }
                    Line(sb, "k.hits", h.ToString());
                }
                Line(sb, "k.rules", d.Str("rules"));
            }
            var l = o.Obj("lobby");
            if (l != null)
                Line(sb, "h.lobby", l.Str("code") + " / " + l.Str("server") + " / " + S.In(0, "k.reg") + " " + S.In(0, l.Bool("registered", false) ? "v.yes" : "v.no") + " / "
                    + S.In(0, l.Bool("inGame", false) ? "v.ingame" : "v.lobby") + " / " + S.In(0, "k.players") + " " + l.Int("players") + " / PocketRoles " + l.Str("hostVersion"));
            var p = o.Obj("player");
            if (p != null) Line(sb, "h.player", p.Str("name") + "（" + S.In(0, "k.hash") + " " + Hashes.Short(p.Str("hash")) + "、" + p.Str("platform") + "）");
            var ro = o.Obj("roles");
            if (ro != null && ro.Str("snapshot").Length > 0) Line(sb, "h.roles", ro.Str("snapshot") + (ro.Str("live").Length > 0 ? " → " + ro.Str("live") : ""));
            var rep = o.Obj("report");
            Line(sb, "h.report", rep != null && rep.Bool("sent", false) ? S.In(0, "v.sent", rep.Str("reason"), Fmt.Local(rep.Time("at"))) : S.In(0, "v.notsent"));
            var log = Json.Strings(o.Arr("log"));
            if (log.Count > 0)
            {
                sb.Append("・").Append(S.In(0, "h.log")).Append(":\n```\n");
                foreach (var x in log) sb.Append(x).Append("\n");
                sb.Append("```\n");
            }
            return sb.ToString();
        }

        string CopyRow(Row r)
        {
            if (r == null) return null;
            var sb = new StringBuilder();
            var now = DateTime.UtcNow;
            var o = r.Ev != null ? LoadEv(r.Ev.Path) : null;
            sb.Append(o != null ? S.In(0, "cp.head", o.Str("id")) : S.In(0, "cp.noev")).Append("\n");
            if (r.Entry != null && r.IsLocal)
            {
                string state = r.LocalActive(now) ? S.In(0, "bd.active") : !r.Active ? S.In(0, "lifted") : S.In(0, "expired");
                Line(sb, "h.entry", state + "・" + S.In(0, "lv", Math.Max(1, r.Level)) + "・" + (r.Expires == null ? S.In(0, "perm") : S.In(0, "until", Fmt.Local(r.Expires))) + "・" + S.In(0, "k.count") + " " + r.Count + "・" + S.In(0, r.Source == "auto" ? "src.auto" : "src.manual"));
            }
            if (r.Effective != null) Line(sb, "h.shared", S.In(0, "lv", r.Effective.Level) + "・" + Fmt.SharedUntil(r.Effective, 0) + "・" + r.Effective.Reason);
            if (o != null) SheetOf(o, sb);
            else
            {
                Line(sb, "k.name", r.Name);
                Line(sb, "k.hash", Hashes.Short(r.Hash));
                Line(sb, "k.rule", S.RuleIn(0, r.Rule));
                Line(sb, "k.since", Fmt.LocalUtc(r.Since));
            }
            return sb.ToString().TrimEnd('\n');
        }

        string CopyCand(Cand c)
        {
            if (c == null) return null;
            var sb = new StringBuilder();
            if (c.Kind == "log")
            {
                sb.Append(S.In(0, "cp.log", c.FromText)).Append("\n```\n");
                try { foreach (var l in File.ReadAllLines(c.Path, Encoding.UTF8)) sb.Append(l).Append("\n"); } catch (Exception) { }
                sb.Append("```");
                return sb.ToString();
            }
            var o = LoadEv(c.Path);
            if (o == null) return null;
            sb.Append(S.In(0, "cp.head", o.Str("id"))).Append("\n");
            if (c.Kind != "own") Line(sb, "k.from", c.FromText);
            SheetOf(o, sb);
            return sb.ToString().TrimEnd('\n');
        }
    }

    // ------------------------------------------------------------------ v0.5.5 -SelfTest: no window; the logic only, in a temp folder
    public static class SelfTest
    {
        static int pass, fail;
        static string root = "";
        static readonly Regex FcShape = new Regex("[#＃]\\s*[0-9０-９]{4}");
        static readonly Regex HexShape = new Regex("[0-9a-fA-F]{32}");

        static void Check(string name, bool ok, string detail)
        {
            if (ok) pass++; else fail++;
            Console.WriteLine((ok ? "PASS " : "FAIL ") + name + (!ok && !string.IsNullOrEmpty(detail) ? "  -- " + detail : ""));
        }

        static void Group(string name, Action a)
        {
            try { a(); }
            catch (Exception e) { Check(name + " (no exception)", false, e.GetType().Name + ": " + e.Message); }
        }

        /// <summary>Runs every test and prints PASS / FAIL lines; returns the number of failures. Touches only a temp folder.</summary>
        public static int Run(string scriptDir)
        {
            pass = 0; fail = 0;
            root = Path.Combine(Path.GetTempPath(), "AegisBanSelfTest-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            string oldState = App.StateDir, oldGame = App.GameDir, oldLang = S.Lang, oldRepo = App.RepoDir;
            bool oldAdmin = App.Admin;
            bool oldKeySignal = App.KeySignal;
            var oldKeys = Sig.TrustedKeys;
            var oldRevoked = Sig.RevokedKeyIds;
            try
            {
                Directory.CreateDirectory(root);
                App.StateDir = Path.Combine(root, "state");
                App.GameDir = Path.Combine(root, "game");
                App.RepoDir = Path.Combine(root, "no-repo");   // an empty folder (not a git repository): no test can reach the real one
                Directory.CreateDirectory(App.StateDir);
                Directory.CreateDirectory(App.RepoDir);
                Settings.Load(Path.Combine(App.StateDir, "settings.txt"));
                S.Lang = "en";
                Console.WriteLine("Aegis BAN console self-test (" + root + ")");
                Group("proposal", Proposals);
                Group("gate", GateTests);
                Group("admin", AdminTests);
                Group("audit", AuditTests);
                Group("import", ImportTests);
                Group("add", AddTests);
                Group("match", MatchTests);
                Group("defs", DefsTests);
                Group("desc", DescTests);
                Group("link", LinkTests);
                Group("hold", HoldTests);
                Group("unlock", UnlockTests);
                Group("lock", LockTests);
                Group("keygate", KeyGateTests);   // v0.5.5 (2026-09-23): what reaches other people needs the key check of this run
                Group("hello", HelloTests);
                Group("chain", ChainTests);
                Group("since", SinceTests);
                Group("outside", OutsideTests);
                Group("reply", ReplyTests);
                Group("replydlg", ReplyDialogTests);
                Group("clip", ClipTests);
                Group("palette", PaletteTests);   // v0.5.5 (2026-09-22 「BAN管理もなんか水色でみずらくない？」)
                Group("ai", AiTests);             // v0.5.5 (2026-09-22 「そこにもai搭載して欲しい」): a mock server on 127.0.0.1 only
                Group("fake", FakeTests);
                Group("sharegate", ShareGateTests);
                Group("source", () => SourceTests(scriptDir));
            }
            catch (Exception e) { Check("self-test setup", false, e.ToString()); }
            finally
            {
                App.StateDir = oldState; App.GameDir = oldGame; S.Lang = oldLang; App.Admin = oldAdmin; App.RepoDir = oldRepo;
                App.KeySignal = oldKeySignal; Sig.TrustedKeys = oldKeys; Sig.RevokedKeyIds = oldRevoked; Session.Lock(); Session.KeyProven = false;
                Reporters.Current = null;   // (v0.5.5: the tests' hosts never stay)
                try { if (Directory.Exists(root)) Directory.Delete(root, true); } catch (Exception) { }
            }
            Console.WriteLine("SELFTEST " + (fail == 0 ? "PASS" : "FAIL") + ": " + pass + " passed, " + fail + " failed");
            return fail;
        }

        static Proposal Sample()
        {
            return new Proposal
            {
                Kind = "unban", Ev = "AEG-7F3K2", Line = "1a2b3c4d5e6f7a8b", Strength = "circumstantial", Name = "たろう / テスト",
                By = "もみじ", Reason = "ラグで遠いキルに見えただけだと思います（証拠の距離 1.9、ほかの人の記録なし）",
                At = new DateTime(2026, 9, 22, 10, 0, 0, DateTimeKind.Utc),
            };
        }

        static string Diff(Proposal a, Proposal b)
        {
            if (b == null) return "null";
            var d = new List<string>();
            if (a.Kind != b.Kind) d.Add("kind " + b.Kind);
            if (a.Ev != b.Ev) d.Add("ev " + b.Ev);
            if (a.Line != b.Line) d.Add("line " + b.Line);
            if (a.Strength != b.Strength) d.Add("strength " + b.Strength);
            if (a.Rule != b.Rule) d.Add("rule " + b.Rule);
            if (a.Name != b.Name) d.Add("name [" + b.Name + "]");
            if (a.By != b.By) d.Add("by [" + b.By + "]");
            if (a.Reason != b.Reason) d.Add("reason [" + b.Reason + "]");
            if (a.At != b.At) d.Add("at " + Json.Time(b.At));
            return string.Join("; ", d.ToArray());
        }

        static void Proposals()
        {
            var p = Sample();
            string err;
            string[] langs = { "ja", "zh-CN", "en" };
            for (int i = 0; i < 3; i++)
            {
                var q = Proposal.Parse(Proposal.Clip(p, i), out err);
                Check("proposal.roundtrip." + langs[i], q != null && Diff(p, q).Length == 0, q == null ? err : Diff(p, q));
            }
            var s = Sample();
            s.Kind = "share"; s.Ev = "AEG-ABCDE"; s.Rule = "harass"; s.Strength = "manual"; s.Name = "Mori_1*";
            var qs = Proposal.Parse(Proposal.Clip(s, 1), out err);
            Check("proposal.roundtrip.share-with-rule", qs != null && Diff(s, qs).Length == 0, qs == null ? err : Diff(s, qs));
            var e2 = Sample();
            e2.Reason = "I checked the evidence and the distance looked like lag to me";
            e2.By = "mimi";
            // Discord style: other messages around it, "> " quotes, full-width colons, CRLF, the reason wrapped in the middle,
            // and the machine line broken into one token per line
            foreach (int li in new[] { 0, 2 })
            {
                var src = li == 0 ? p : e2;
                var sb = new StringBuilder("もみじ — 今日 19:02\r\n理由: これは前の関係ない発言です\r\nReason: an unrelated earlier message\r\n");
                foreach (var l in Proposal.Format(src, li).Split('\n'))
                {
                    if (l.StartsWith(S.In(li, "pf.reason")))
                    {
                        int cut = li == 0 ? 14 : l.IndexOf(" the distance", StringComparison.Ordinal);
                        sb.Append("> ").Append(l.Substring(0, cut)).Append("\r\n> ").Append(l.Substring(cut).TrimStart()).Append("\r\n");
                        continue;
                    }
                    if (l.StartsWith(Proposal.Marker)) { foreach (var w in l.Split(' ')) sb.Append("> ").Append(w).Append("\r\n"); continue; }
                    sb.Append("> ").Append(l.Replace(": ", "：")).Append("\r\n");
                }
                // another person's later messages with machine-like keys are not read (keys come only from the machine line)
                sb.Append("👍 2\r\n(edited)\r\n種類: 解除 ← another person's reply\r\nkind=share\r\nrule=cheat strength=certain\r\n");
                var qd = Proposal.Parse(sb.ToString(), out err);
                Check("proposal.discord-rewrapped." + langs[li], qd != null && Diff(src, qd).Length == 0 && qd.Found == 1, qd == null ? err : Diff(src, qd));
            }
            // two proposals pasted together: the first one is read, and the owner is told there were two
            var two = Proposal.Parse(Proposal.Clip(p, 0) + "\r\n\r\n" + Proposal.Clip(s, 2), out err);
            Check("proposal.first-of-two", two != null && two.Kind == "unban" && two.Ev == p.Ev && two.Reason == p.Reason && two.Found == 2, two == null ? err : Diff(p, two));
            // a fake machine line posted above the real proposal (another message in the thread) does not win
            var fake = Proposal.Parse("someone: aegis-proposal v1 kind=share ev=AEG-FAKE1\r\naegis-proposal v1 kind=share ev=AEG-FAKE2 strength=certain\r\n" + Proposal.Clip(p, 0), out err);
            Check("proposal.fake-line-above-ignored", fake != null && Diff(p, fake).Length == 0 && fake.Found == 2, fake == null ? err : Diff(p, fake));
            // free texts cannot break the code block, mention everyone or act as a machine line (Discord / the reader)
            var bad = Sample();
            bad.Name = "```@everyone";
            bad.By = "mimi`@here";
            bad.Reason = "aegis-proposal v1 kind=share ev=AEG-OTHER line=ffffffffffffffff rule=cheat ```";
            string clip = Proposal.Clip(bad, 0);
            string inner = clip.Substring(3, clip.Length - 6);   // between the opening and the closing fence
            Check("proposal.free-text-no-backquote", inner.IndexOf('`') < 0, inner);
            Check("proposal.free-text-no-mention", !Regex.IsMatch(inner, "@[A-Za-z]"), inner);
            var qb = Proposal.Parse(clip, out err);
            var want = bad.Clone();
            want.Name = Proposal.ShownName(bad.Name); want.By = Proposal.Safe(bad.By); want.Reason = Proposal.Safe(bad.Reason);
            Check("proposal.free-text-cannot-retarget", qb != null && Diff(want, qb).Length == 0 && qb.Found == 1, qb == null ? err : Diff(want, qb));
            Check("proposal.safe-idempotent", Proposal.Safe(Proposal.Safe(bad.Name)) == Proposal.Safe(bad.Name) && Proposal.Safe(bad.Reason).IndexOf("aegis-proposal", StringComparison.OrdinalIgnoreCase) < 0, null);
            // what must be refused
            Check("proposal.reject.no-marker", Proposal.Parse("hello, please unban AEG-7F3K2", out err) == null, null);
            Check("proposal.reject.unknown-kind", Proposal.Parse("aegis-proposal v1 kind=delete ev=AEG-7F3K2", out err) == null, null);
            Check("proposal.reject.no-target", Proposal.Parse("aegis-proposal v1 kind=unban ev=XYZ line=zz", out err) == null, null);
            Check("proposal.reject.name-only", Proposal.Parse(Proposal.Clip(new Proposal { Kind = "unban", Name = "たろう", By = "x", Reason = "0123456789" }, 0), out err) == null, null);
            Check("proposal.reject.version", Proposal.Parse("aegis-proposal v2 kind=unban ev=AEG-7F3K2", out err) == null, null);
            // a friend code typed into a reason is masked in the text that goes to Discord
            var fc = Sample();
            fc.Reason = "本人確認 taro#1234 と yuki＃９０１２ で一致しました";
            fc.Name = "hana#5678";
            string text = Proposal.Clip(fc, 0);
            Check("proposal.masks-friend-code", !FcShape.IsMatch(text), text);
            Check("proposal.no-hash-or-puid", !HexShape.IsMatch(text), text);
        }

        static EvInfo Ev(string id, string strength, string rule)
        {
            return new EvInfo { Id = id, Strength = strength, Rule = rule, Name = "p-" + id, Hash = Hashes.HashOf("selftest-player-" + id), PuidHash = Hashes.HashOf("selftest-puid-" + id), Time = DateTime.UtcNow };
        }

        static void GateTests()
        {
            var circ = Ev("AEG-C1RC1", "circumstantial", "ChatFlood");
            var manual = Ev("AEG-MANU1", "manual", "manual");
            var cert = Ev("AEG-CERT1", "certain", "KillRole");
            Check("gate.none.blocked", !GateRules.ShareAllowed(null), null);
            var g = GateRules.For(circ);
            Check("gate.circumstantial.needs-rule-and-reason", g.NeedRule && g.NeedReason, null);
            Check("gate.circumstantial.no-rule", !g.Ready("", "十文字以上の理由をここに書きます"), null);
            Check("gate.circumstantial.short-reason", !g.Ready("harass", "短い理由"), null);
            Check("gate.circumstantial.ready", g.Ready("harass", "十文字以上の理由をここに書きます"), null);
            Check("gate.circumstantial.unknown-rule", !g.Ready("killrole", "十文字以上の理由をここに書きます"), null);
            var gm = GateRules.For(manual);
            Check("gate.manual.counts-as-circumstantial", gm.NeedRule && gm.NeedReason, null);
            var gc = GateRules.For(cert);
            Check("gate.certain.shows-rule", !gc.NeedRule && !gc.NeedReason && gc.ShowRule.IndexOf("KillRole", StringComparison.Ordinal) >= 0 && gc.Ready("", ""), gc.ShowRule);
            Check("gate.certain.reason-code", GateRules.SharedReason(cert, "KillRole", "harass") == "killrole", GateRules.SharedReason(cert, "KillRole", "harass"));
            Check("gate.circumstantial.reason-code", GateRules.SharedReason(circ, "ChatFlood", "harass") == "harass" && GateRules.SharedReason(circ, "", "") == "other", null);
            Check("gate.reason.9-chars", !GateRules.ReasonOk("123456789"), null);
            Check("gate.reason.10-chars", GateRules.ReasonOk("1234567890") && GateRules.ReasonOk("あいうえおかきくけこ"), null);
            Check("gate.reason.spaces-only", !GateRules.ReasonOk("　　　　　　　　　　　　 "), null);
            Check("gate.reason.emoji-count-once", !GateRules.ReasonOk("👍👍👍👍👍👍👍👍👍") && GateRules.ReasonOk("👍👍👍👍👍👍👍👍👍👍"), null);
            // the codes the gate writes are valid [bans] reasons for the mod's parser (the same character rules)
            bool codes = true;
            foreach (var r in GateRules.Rules)
            {
                var line = SharedLine.Parse(SharedLine.Format(Hashes.HashOf("selftest-" + r), 1, null, r));
                if (line == null || line.Reason != r) codes = false;
            }
            Check("gate.reason-codes-parse", codes, null);
            // an imported record only claims its strength: "certain" from a report zip is gated like circumstantial evidence
            var imp = Ev("AEG-IMPC1", "certain", "KillRole");
            imp.Imported = true;
            var gi = GateRules.For(imp);
            Check("gate.imported-certain.needs-rule-and-reason", gi.NeedRule && gi.NeedReason && gi.ShowRule.Length == 0 && gi.Note.Length > 0 && !GateRules.Trusted(imp), null);
            Check("gate.imported-certain.reason-code-is-chosen", GateRules.SharedReason(imp, "KillRole", "harass") == "harass" && GateRules.SharedReason(imp, "KillRole", "") == "other", null);
            // the rule box: "(choose)" is no rule, even when a pasted proposal preset one
            Check("gate.picked.choose-means-none", GateRules.Picked(true, 0, "harass") == "", null);
            Check("gate.picked.box", GateRules.Picked(true, 2, "harass") == "chat" && GateRules.Picked(true, 99, "") == "", null);
            Check("gate.picked.no-box", GateRules.Picked(false, -1, "harass") == "harass", null);
            // lengthening a shared ban (a period change or an undo) is gated; shortening is not
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            var cur = new SharedLine { Hash = Hashes.HashOf("selftest-len"), Level = 1, Expires = new DateTime(2026, 10, 1, 0, 0, 0, DateTimeKind.Utc) };
            var old = new SharedLine { Hash = cur.Hash, Level = 1, Expires = new DateTime(2026, 9, 1, 0, 0, 0, DateTimeKind.Utc) };
            var perm = new SharedLine { Hash = cur.Hash, Level = 3, Expires = null };
            Check("gate.lengthens.later-end", GateRules.Lengthens(cur, true, new DateTime(2026, 12, 1, 0, 0, 0, DateTimeKind.Utc), now), null);
            Check("gate.lengthens.permanent", GateRules.Lengthens(cur, true, null, now), null);
            Check("gate.lengthens.brings-back-expired", GateRules.Lengthens(old, true, new DateTime(2026, 10, 1, 0, 0, 0, DateTimeKind.Utc), now) && GateRules.Lengthens(null, true, null, now), null);
            Check("gate.lengthens.not-shorter", !GateRules.Lengthens(cur, true, new DateTime(2026, 9, 25, 0, 0, 0, DateTimeKind.Utc), now) && !GateRules.Lengthens(perm, true, new DateTime(2027, 1, 1, 0, 0, 0, DateTimeKind.Utc), now), null);
            Check("gate.lengthens.not-ended-or-none", !GateRules.Lengthens(cur, true, now.AddHours(-1), now) && !GateRules.Lengthens(cur, false, null, now), null);
        }

        static void AdminTests()
        {
            string sd = Path.Combine(root, "fake-appdata", "PocketRoles", "signing");
            Check("admin.detect.no-signing-folder", App.DetectAdmin(sd, false), null);
            Directory.CreateDirectory(sd);
            Check("admin.detect.empty-folder", App.DetectAdmin(sd, false), null);
            File.WriteAllText(Path.Combine(sd, "definitions-public.xml"), "public key only (self-test)");
            File.WriteAllText(Path.Combine(sd, "signed-versions.txt"), "# ledger (self-test)");
            Check("admin.detect.public-key-and-ledger-only", App.DetectAdmin(sd, false), null);
            string fake = Path.Combine(sd, "definitions-private-selftest.xml");
            File.WriteAllText(fake, "not a key (self-test)");
            using (new FileStream(fake, FileMode.Open, FileAccess.ReadWrite, FileShare.None))   // held exclusively: detection must not open it
                Check("admin.detect.private-key-name-owner (file never opened)", !App.DetectAdmin(sd, false), null);
            Check("admin.detect.forced-admin", App.DetectAdmin(sd, true), null);
            File.Delete(fake);
            Check("admin.detect.after-key-removed", App.DetectAdmin(sd, false), null);
            // v0.5.5 (2026-09-23 「乗っ取られたら…」): protected-keys.txt is not a key by itself — it has to name a copy that is
            // there right now, so a PC whose key lives on an unplugged USB stick opens as an admin and can sign nothing
            string loc = Path.Combine(sd, "protected-keys.txt");
            string usb = Path.Combine(root, "fake-usb", "署名の鍵_USB控え.prkey");
            File.WriteAllText(loc, "# where the copies are (self-test)\r\nusb\t5e1f7e575e1f7e57\t" + usb + "\t2026-09-23T00:00:00Z\r\n", new UTF8Encoding(false));
            Check("admin.detect.protected-keys-but-no-copy-here", App.DetectAdmin(sd, false), null);
            Check("admin.detect.protected-keys-paths", App.ProtectedKeyPaths(loc).Count == 1 && App.ProtectedKeyPaths(loc)[0] == usb, string.Join("; ", App.ProtectedKeyPaths(loc).ToArray()));
            Directory.CreateDirectory(Path.GetDirectoryName(usb));
            File.WriteAllText(usb, "not a key (self-test)");
            using (new FileStream(usb, FileMode.Open, FileAccess.ReadWrite, FileShare.None))   // held exclusively: detection must not open it
                Check("admin.detect.protected-keys-owner", !App.DetectAdmin(sd, false), null);
            File.Delete(usb);   // the stick is unplugged again
            Check("admin.detect.protected-keys-copy-gone", App.DetectAdmin(sd, false), null);
            // defence in depth: in admin mode every signing / publishing step refuses by itself (the signing console step is
            // not called here: it would open a window; it has the same guard). App.RepoDir is an empty temp folder.
            bool was = App.Admin;
            App.Admin = true;
            try
            {
                string adminText = S.Get("e.admin");
                var names = new List<string>();
                var steps = new Dictionary<string, Func<Step, bool>>
                {
                    { "CheckRepo", st => Ops.CheckRepo(st) },
                    { "BuildWork", st => Ops.BuildWork(new JObj(), st) },
                    { "RecordPending", st => Ops.RecordPending(new JObj(), st) },
                    { "GitCheck", st => Ops.GitCheck(new Ops.PublishCtx(), st) },
                    { "Place", st => Ops.Place(new Ops.PublishCtx(), st) },
                    { "Commit", st => Ops.Commit(new Ops.PublishCtx(), st) },
                    { "Push", st => Ops.Push(new Ops.PublishCtx(), st) },
                };
                foreach (var kv in steps)
                {
                    var st = new Step(kv.Key, null);
                    if (kv.Value(st) || st.Detail != adminText) names.Add(kv.Key);
                }
                Check("admin.ops-refuse-signing-and-publishing", names.Count == 0, string.Join(", ", names.ToArray()));
                Check("admin.no-pending-written", !File.Exists(App.PendingFile) && !File.Exists(App.WorkDefs), null);
            }
            finally { App.Admin = was; }
        }

        static void AuditTests()
        {
            var rec = new AuditRec
            {
                Action = "share", Ev = "AEG-7F3K2", Name = "taro#1234", Rule = "harass",
                Reason = "本人確認 hana#5678 と yuki＃９０１２\nPUID 0123456789abcdef0123456789abcdef\tハッシュ " + Hashes.HashOf("selftest"),
                Proposer = "mimi # 0001", Act = "abc123def0", Result = "signed 12",
            };
            string line = Audit.Format(rec);
            Check("audit.line.no-friend-code", !FcShape.IsMatch(line), line);
            Check("audit.line.no-puid-or-hash", !HexShape.IsMatch(line), line);
            Check("audit.line.one-line-15-fields", line.IndexOf('\n') < 0 && line.IndexOf('\r') < 0 && line.Split('\t').Length == 15, line);
            Check("audit.append", Audit.Append(rec), null);
            // v0.5.5: the written line has the operator (from the session when not set) and ends with the chain field
            var written = Audit.ReadLines();
            string w0 = written.Count > 0 ? written[written.Count - 1] : "";
            Check("audit.line.operator-and-prev", w0.Split('\t').Length == 16 && Audit.PrevOf(w0) != null && w0.IndexOf("\tuser=" + Audit.Clean(Ident.UserName, 64) + "\t", StringComparison.Ordinal) >= 0
                && w0.IndexOf("\tmachine=" + Audit.Clean(Ident.MachineName, 64) + "\t", StringComparison.Ordinal) >= 0 && w0.IndexOf("\tmode=-\t", StringComparison.Ordinal) >= 0, w0);
            Audit.Append(new AuditRec { Action = "propose.unban", Ev = "AEG-7F3K2", Name = "hana", Reason = "理由は十文字以上あります", Proposer = "もみじ", Result = "copied" });
            var all = Audit.ReadAll();
            Check("audit.read-back", all.Count == 2 && all[0].Action == "share" && all[0].Ev == "AEG-7F3K2" && all[0].Rule == "harass" && all[1].Proposer == "もみじ", all.Count.ToString(CultureInfo.InvariantCulture));
            string file = File.ReadAllText(App.AuditFile, Encoding.UTF8);
            Check("audit.file.no-friend-code-or-puid", !FcShape.IsMatch(file) && !HexShape.IsMatch(file), file);
            Check("audit.for.by-action-id", Audit.For(new HashSet<string> { "abc123def0" }, "").Count == 1, null);
            Check("audit.for.by-evidence-id", Audit.For(null, "aeg-7f3k2").Count == 2, null);
            // the history shows a result from the 3-language table (audit.log keeps a code); an older line as written
            Check("audit.result.ja", Audit.ResultText("signed 12", 0) == "署名済み・反映待ち v12" && Audit.ResultText("done.local", 0) == "実行（この PC）", Audit.ResultText("signed 12", 0));
            Check("audit.result.zh-en", Audit.ResultText("pushed 12 1a2b3c4d", 1) == "已发布到 GitHub v12 1a2b3c4d" && Audit.ResultText("discarded 7", 2) == "discarded v7" && Audit.ResultText("copied", 2) == "copied only (nothing changed)", null);
            Check("audit.result.older-line", Audit.ResultText("done (this PC)", 0) == "done (this PC)", null);
            bool allCodes = true;
            foreach (var code in new[] { "done.local", "signed 3", "copied", "pushed 3 abcdef12", "discarded 3" })
                for (int i = 0; i < 3; i++) if (Audit.ResultText(code, i) == code) allCodes = false;
            Check("audit.result.every-code-translated", allCodes, null);
        }

        static string EvJson(EvInfo e, string action)
        {
            return "{\n  \"format\": \"PocketRoles.AegisEvidence\",\n  \"version\": 1,\n  \"id\": \"" + e.Id + "\",\n  \"time\": \"2026-09-20T12:00:00Z\",\n"
                + "  \"action\": \"" + action + "\",\n  \"source\": \"auto\",\n  \"strength\": \"" + e.Strength + "\",\n  \"rule\": \"" + e.Rule + "\",\n  \"ruleText\": \"\",\n  \"by\": \"Aegis\",\n  \"ban\": null,\n"
                + "  \"player\": { \"name\": \"" + e.Name + "\", \"hash\": \"" + e.Hash + "\", \"puidHash\": \"" + e.PuidHash + "\", \"clientId\": 5, \"playerId\": 2, \"platform\": \"StandaloneSteamPC\" },\n"
                + "  \"lobby\": { \"code\": \"ABCDEF\", \"server\": \"Asia\", \"registered\": false, \"inGame\": true, \"players\": 8, \"hostRttMs\": 20, \"hostVersion\": \"0.5.5\", \"gameVersion\": \"2026.8.18\" },\n"
                + "  \"log\": [ \"12:00:00Z CheatDetector: ChatFlood (Repeat) #2 test (client 5): 5 chat lines within 3 s\" ],\n  \"report\": null,\n  \"note\": \"\"\n}\n";
        }

        static void Put(ZipArchive za, string name, string text)
        {
            var e = za.CreateEntry(name);
            using (var w = new StreamWriter(e.Open(), new UTF8Encoding(false))) w.Write(text);
        }

        static void ImportTests()
        {
            string zip = Path.Combine(root, "PocketRoles-report-selftest.zip");
            using (var fs = new FileStream(zip, FileMode.CreateNew))
            using (var za = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                Put(za, "LogOutput.log", "[Info] CheatDetector: ChatFlood (Repeat) #2 test (client 5): 5 chat lines\n[Info] something else\n[Warning] AegisBans: ban recorded: hash 1a2b3c4d…\n");
                Put(za, "system.txt", "PocketRoles report\n");
                Put(za, "evidence/AEG-ABCDE.json", EvJson(Ev("AEG-ABCDE", "circumstantial", "ChatFlood"), "kick"));
                Put(za, "deep/nested/AEG-FGHJK.json", EvJson(Ev("AEG-FGHJK", "certain", "KillRole"), "ban"));
                Put(za, "evidence/AEG-BAD00.json", "{ \"format\": \"something else\", \"id\": \"AEG-BAD00\" }");
            }
            int ev = 0, lines = 0;
            var st = new Step("import", null);
            bool ok = Ops.Import(zip, "selftest-host", st, ref ev, ref lines);
            Check("import.evidence-anywhere-in-zip", ok && ev == 2, "evidence " + ev + ", " + st.Detail);
            Check("import.aegis-log-lines", lines == 2, "lines " + lines);
            var snap = new Snapshot();
            Loader.Rows(snap, new Step("rows", null));
            int evc = 0, logc = 0;
            foreach (var c in snap.Cands) { if (c.Kind == "ev") evc++; if (c.Kind == "log") logc++; }
            Check("import.candidates", evc == 2 && logc == 1, evc + " evidence, " + logc + " log");
        }

        static void AddTests()
        {
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            var p1 = Ops.PlanAdd(0, 0, false, null, -1, now);
            Check("add.plan.first-offence-30d", p1.Count == 1 && p1.Level == 1 && p1.Days == 30 && p1.Expires == now.AddDays(30), null);
            var p2 = Ops.PlanAdd(1, 0, false, null, -1, now);
            Check("add.plan.second-offence-180d", p2.Count == 2 && p2.Level == 2 && p2.Days == 180, null);
            var p3 = Ops.PlanAdd(2, 0, false, null, -1, now);
            Check("add.plan.third-offence-permanent", p3.Count == 3 && p3.Level == 3 && p3.Days == 0 && p3.Expires == null, null);
            var pk = Ops.PlanAdd(1, 0, true, now.AddDays(100), 30, now);
            Check("add.plan.never-shortens-running-ban", pk.KeptLonger && pk.Expires == now.AddDays(100) && pk.Days == 100, null);
            var ps = Ops.PlanAdd(0, 2, false, null, -1, now);
            Check("add.plan.shared-level-counts", ps.Count == 3 && ps.Level == 3 && ps.Expires == null, null);
            Check("add.plan.max-3650-days", Ops.PlanAdd(0, 0, false, null, 99999, now).Days == 3650, null);

            // into a fresh game folder: the file is made in the mod's format
            Directory.CreateDirectory(Path.Combine(App.GameDir, "BepInEx", "PocketRoles"));
            var ev = Ev("AEG-ADD01", "circumstantial", "ChatFlood");
            var hashes = new List<string> { ev.Hash, ev.PuidHash };
            var a1 = Journal.NewAction("add", hashes, ev.Name);
            string since1;
            string err = Ops.AddLocal(a1, ev, -1, "harass", 0, now, out since1);
            Check("add.local.creates-file", err == null && File.Exists(App.BansPath), err);
            var rootObj = Json.Parse(Json.ReadText(App.BansPath)) as JObj;
            var e1 = rootObj != null && rootObj.Arr("bans") != null && rootObj.Arr("bans").Count == 1 ? rootObj.Arr("bans")[0] as JObj : null;
            Check("add.local.mod-format", rootObj != null && rootObj.Str("format") == "PocketRoles.AegisBans" && rootObj.Str("salt") == Hashes.Salt && rootObj.Arr("reports") != null, null);
            string[] order = { "hash", "puidHash", "name", "count", "level", "days", "since", "expires", "rule", "source", "evidence", "by", "firstSeen", "lastSeen", "reported", "reportedAt", "active", "unbannedAt", "unbanBy", "history" };
            bool inOrder = e1 != null && e1.Items.Count >= order.Length;
            if (inOrder) for (int i = 0; i < order.Length; i++) if (e1.Items[i].Key != order[i]) inOrder = false;
            Check("add.local.entry-fields-in-mod-order", inOrder, null);
            Check("add.local.entry", e1 != null && e1.Str("hash") == ev.Hash && e1.Str("puidHash") == ev.PuidHash && e1.Int("count") == 1 && e1.Int("level") == 1 && e1.Int("days") == 30
                && e1.Str("source") == "manual" && e1.Str("evidence") == "AEG-ADD01" && e1.Str("rule") == "harass" && e1.Bool("active", false) && e1.Str("since") == since1 && e1.Arr("history").Count == 1, null);
            // the mod's and the console's unknown fields survive; a second add counts on
            e1.Set("consoleExtra", "keep");
            rootObj.Set("extraRoot", JNum.Of(7));
            File.WriteAllText(App.BansPath, Json.Write(rootObj), new UTF8Encoding(false));
            var a2 = Journal.NewAction("add", hashes, ev.Name);
            string since2;
            err = Ops.AddLocal(a2, ev, 30, "harass", 0, now.AddMinutes(5), out since2);
            var r2 = Json.Parse(Json.ReadText(App.BansPath)) as JObj;
            var e2 = r2.Arr("bans")[0] as JObj;
            Check("add.local.second-offence", err == null && r2.Arr("bans").Count == 1 && e2.Int("count") == 2 && e2.Int("level") == 2 && e2.Arr("history").Count == 2, err);
            Check("add.local.keeps-unknown-fields", e2.Str("consoleExtra") == "keep" && r2.Get("extraRoot") != null, null);
            // undo (元に戻す) of the second add: the offence count goes back too
            var undo = Journal.NewAction("undo", hashes, ev.Name);
            undo.Set("localNew", a2.Obj("localOld"));
            undo.Set("localHist", new JObj());
            undo.Obj("localHist").Set("event", "undo");
            undo.Obj("localHist").Set("detail", "self-test");
            undo.Set("guardSince", since2);
            err = Ops.ApplyLocal(undo);
            var e3 = (Json.Parse(Json.ReadText(App.BansPath)) as JObj).Arr("bans")[0] as JObj;
            Check("add.local.undo", err == null && e3.Int("count") == 1 && e3.Str("since") == since1 && e3.Bool("active", false), err);
            // the evidence of a candidate, never a typed name: no identity, no ban
            var none = new EvInfo { Id = "AEG-NONE1", Name = "typed name" };
            string s3;
            Check("add.local.needs-identity", Ops.AddLocal(Journal.NewAction("add", new List<string>(), ""), none, 30, "other", 0, now, out s3) != null, null);
        }

        static void MatchTests()
        {
            var snap = new Snapshot();
            string lineA = Hashes.HashOf("selftest-puid-A");
            var rowA = new Row { Key = "rowA", Hash = Hashes.HashOf("selftest-fc-A"), PuidHash = lineA, Name = "A", Evidence = "AEG-11111" };
            rowA.Effective = new SharedLine { Hash = lineA, Level = 1 };
            snap.Rows.Add(rowA);
            var evB = Ev("AEG-22222", "circumstantial", "ChatFlood");
            var candB = new Cand { Kind = "ev", Key = "imp:B", Ev = evB };
            snap.Cands.Add(candB);
            var h1 = ProposalMatch.Find(snap, new Proposal { Kind = "unban", Ev = "AEG-11111" });
            Check("match.by-evidence-id", h1 != null && h1.Row == rowA, null);
            var h2 = ProposalMatch.Find(snap, new Proposal { Kind = "share", Line = Proposal.LineId(evB.PuidHash) });
            Check("match.share-by-line-id-candidate", h2 != null && h2.Cand == candB, null);
            var h3 = ProposalMatch.Find(snap, new Proposal { Kind = "unban", Line = Proposal.LineId(lineA) });
            Check("match.unban-by-shared-line", h3 != null && h3.Row == rowA, null);
            Check("match.unknown", ProposalMatch.Find(snap, new Proposal { Kind = "unban", Ev = "AEG-99999" }) == null, null);
            Check("match.never-by-name", ProposalMatch.Find(snap, new Proposal { Kind = "unban", Name = "A" }) == null, null);
            Check("match.short-line-id-ignored", ProposalMatch.Find(snap, new Proposal { Kind = "unban", Line = lineA.Substring(0, 4) }) == null, null);
            // the evidence id of A with the line of B (an id drawn twice on two PCs, or a mixed-up proposal): the line wins, with a warning
            var h4 = ProposalMatch.Find(snap, new Proposal { Kind = "unban", Ev = "AEG-11111", Line = Proposal.LineId(evB.PuidHash) });
            Check("match.id-and-line-disagree-line-wins", h4 != null && h4.Cand == candB && h4.Warn == "pa.w.idline", h4 == null ? "null" : h4.Key + " " + h4.Warn);
            var h5 = ProposalMatch.Find(snap, new Proposal { Kind = "unban", Ev = "AEG-11111", Line = "0000000000000000" });
            Check("match.id-and-unknown-line-warns", h5 != null && h5.Row == rowA && h5.Warn == "pa.w.idline.ev", null);
            var h6 = ProposalMatch.Find(snap, new Proposal { Kind = "unban", Ev = "AEG-11111", Line = Proposal.LineId(lineA) });
            Check("match.id-and-line-agree", h6 != null && h6.Row == rowA && h6.Warn.Length == 0, null);
            // two candidates with the same evidence id: the one whose PUID fits the line
            var evC = Ev("AEG-22222", "circumstantial", "ChatFlood");
            evC.Name = "other"; evC.Hash = Hashes.HashOf("selftest-fc-C"); evC.PuidHash = Hashes.HashOf("selftest-puid-C");
            var candC = new Cand { Kind = "ev", Key = "imp:C", Ev = evC };
            snap.Cands.Insert(0, candC);
            var h7 = ProposalMatch.Find(snap, new Proposal { Kind = "share", Ev = "AEG-22222", Line = Proposal.LineId(evB.PuidHash) });
            Check("match.same-id-picks-the-line-player", h7 != null && h7.Cand == candB && h7.Warn.Length == 0, h7 == null ? "null" : h7.Key);
        }

        /// <summary>
        /// The commit message is public on GitHub: what an action did is described with the shared line's id (a PUID's hash)
        /// or the evidence id, never with digits of a friend code's hash; an older build's line with them is cut out.
        /// </summary>
        static void DescTests()
        {
            string fcHash = Hashes.HashOf("taro#1234"), puidHash = Hashes.HashOf("0123456789abcdef0123456789abcdef");
            string fc8 = fcHash.Substring(0, 8), pu8 = puidHash.Substring(0, 8);
            var date = new DateTime(2026, 10, 22, 0, 0, 0, DateTimeKind.Utc);
            var acts = new List<JObj>();
            var share = Journal.NewAction("share", new List<string> { fcHash, puidHash }, "taro");
            Ops.SetDesc(share, puidHash, 1, date, "harass", false, "AEG-7F3K2", "imp", "");
            acts.Add(share);
            var unban = Journal.NewAction("unban", new List<string> { fcHash, puidHash }, "taro");
            Ops.SetDesc(unban, puidHash, 0, null, "", true, "AEG-7F3K2", "", "");
            acts.Add(unban);
            var period = Journal.NewAction("period", new List<string> { fcHash, puidHash }, "taro");
            Ops.SetDesc(period, puidHash, 2, null, "killrole", true, "AEG-7F3K2", "", "");
            acts.Add(period);
            var undo = Journal.NewAction("undo", new List<string> { fcHash, puidHash }, "taro");
            Ops.SetDesc(undo, puidHash, 0, null, "", false, "AEG-7F3K2", "", "share");
            acts.Add(undo);
            var add = Journal.NewAction("add", new List<string> { fcHash, puidHash }, "taro");
            Ops.SetDesc(add, "", 0, null, "harass", false, "AEG-7F3K2", "own", "");
            acts.Add(add);
            var bad = new List<string>();
            foreach (var a in acts)
                for (int i = 0; i < 3; i++)
                {
                    string t = Ops.DescIn(i, a);
                    if (t.IndexOf(fc8, StringComparison.OrdinalIgnoreCase) >= 0 || FcShape.IsMatch(t) || HexShape.IsMatch(t) || t.IndexOf("taro", StringComparison.Ordinal) >= 0) bad.Add(a.Str("kind") + "/" + i + ": " + t);
                }
            Check("desc.never-friend-code-hash-or-name", bad.Count == 0, string.Join(" | ", bad.ToArray()));
            Check("desc.commit-line-uses-listed-id", share.Str("desc") == "+ " + pu8 + "… 段階 1・2026-10-22 まで（harass、取り込んだ記録）" && unban.Str("desc") == "- " + pu8 + "… 解除（この PC の BAN も）", share.Str("desc") + " / " + unban.Str("desc"));
            Check("desc.history-in-ui-language", Ops.DescIn(2, period) == "~ " + pu8 + "… period: permanent" && Ops.DescIn(1, add) == "+ AEG-7F3K2 本机封禁" && Ops.DescIn(2, undo) == "undo: add to shared bans (" + pu8 + "…)", Ops.DescIn(2, period) + " / " + Ops.DescIn(1, add) + " / " + Ops.DescIn(2, undo));
            // a pending change of an older build (8 digits of the friend code's hash) never reaches the commit message
            var pend = new JObj();
            pend.Set("version", JNum.Of(12));
            pend.Set("changes", Json.Array(new[] { "+ " + fc8 + "… 段階 1・無期限（killrole）", "undo: + " + fcHash.Substring(0, 12) + "… 段階 1", share.Str("desc"), "- " + pu8 + "… 解除" }));
            string msg = Ops.CommitMessage(pend, new HashSet<string> { puidHash });
            Check("desc.commit-message-cuts-unlisted-hash", msg.IndexOf(fc8, StringComparison.OrdinalIgnoreCase) < 0 && msg.IndexOf(pu8, StringComparison.Ordinal) >= 0 && msg.IndexOf("(id)", StringComparison.Ordinal) >= 0, msg);
            Check("desc.commit-message-no-friend-code", !FcShape.IsMatch(Ops.PublicLine("taro#1234 " + fcHash, new HashSet<string> { puidHash })), null);
            Check("desc.first-line-hash", Ops.FirstLineHash(new[] { "junk", SharedLine.Format(puidHash, 1, null, "other") }) == puidHash && Ops.FirstLineHash(new string[0]) == "", null);
        }

        /// <summary>
        /// v0.5.5 owner decision 2026-09-22: the mod's removal of a player in the 30 days after an accepted appeal is written
        /// as "hold" (nothing lasting). This PC's own "hold" record is never offered as a candidate (no ban, no shared-ban
        /// proposal from it), while a "kick" record still is; the record is read all the same, for a later review.
        /// </summary>
        static void HoldTests()
        {
            Directory.CreateDirectory(App.EvidenceDir);
            var kick = Ev("AEG-HKCK1", "circumstantial", "ChatFlood");
            var hold = Ev("AEG-HHLD1", "certain", "KillRole");
            string fk = Path.Combine(App.EvidenceDir, kick.Id + ".json"), fh = Path.Combine(App.EvidenceDir, hold.Id + ".json");
            File.WriteAllText(fk, EvJson(kick, "kick"), new UTF8Encoding(false));
            File.WriteAllText(fh, EvJson(hold, "hold"), new UTF8Encoding(false));
            try
            {
                var s = new Snapshot();
                Loader.Bans(s, new Step("bans", null));
                Loader.Evidence(s, new Step("ev", null));
                Loader.Rows(s, new Step("rows", null));
                bool kickOffered = false, holdOffered = false;
                foreach (var c in s.Cands)
                {
                    if (c.Ev == null) continue;
                    if (c.Ev.Id == kick.Id) kickOffered = true;
                    if (c.Ev.Id == hold.Id) holdOffered = true;
                }
                Check("hold.not-a-candidate", kickOffered && !holdOffered, "kick " + kickOffered + ", hold " + holdOffered);
                EvInfo read;
                Check("hold.still-read", s.Ev.TryGetValue(hold.Id, out read) && read.Action == "hold", null);
            }
            finally
            {
                try { File.Delete(fk); File.Delete(fh); } catch (Exception) { }
            }
        }

        /// <summary>
        /// A ban's evidence is linked by its id only when the record is of the same player (ids are drawn per PC and can
        /// repeat), also from a dismissed candidate (reviewed\); a record from a report zip keeps "imported" (not trusted).
        /// </summary>
        static void LinkTests()
        {
            string pe = Path.Combine(App.GameDir, "BepInEx", "PocketRoles");
            Directory.CreateDirectory(pe);
            var yuki = Ev("AEG-AAAAA", "circumstantial", "ChatFlood");
            yuki.Name = "Yuki"; yuki.Hash = Hashes.HashOf("yuki#2345"); yuki.PuidHash = Hashes.HashOf("selftest-puid-yuki");
            var xav = Ev("AEG-AAAAA", "certain", "KillRole");
            xav.Name = "Xavier"; xav.Hash = Hashes.HashOf("xavier#3456"); xav.PuidHash = Hashes.HashOf("selftest-puid-xavier");
            // this PC's ban of Yuki with evidence AEG-AAAAA, whose file is not on this PC
            var store = new JObj();
            store.Set("format", "PocketRoles.AegisBans"); store.Set("version", JNum.Of(1)); store.Set("salt", Hashes.Salt); store.Set("updated", "2026-09-22T00:00:00Z");
            var e = new JObj();
            e.Set("hash", yuki.Hash); e.Set("puidHash", yuki.PuidHash); e.Set("name", "Yuki"); e.Set("count", JNum.Of(1)); e.Set("level", JNum.Of(1)); e.Set("days", JNum.Of(30));
            e.Set("since", "2026-09-20T00:00:00Z"); e.Set("expires", "2099-01-01T00:00:00Z"); e.Set("rule", "ChatFlood"); e.Set("source", "manual"); e.Set("evidence", "AEG-AAAAA");
            e.Set("by", "host"); e.Set("active", true); e.Set("history", new List<object>());
            var bans = new List<object>(); bans.Add(e);
            store.Set("bans", bans); store.Set("reports", new List<object>());
            File.WriteAllText(App.BansPath, Json.Write(store), new UTF8Encoding(false));
            string ownFile = Path.Combine(App.EvidenceDir, "AEG-AAAAA.json");
            if (File.Exists(ownFile)) File.Delete(ownFile);
            // an imported record of another player with the same id
            string impX = Path.Combine(App.ImportDir, "20260922-000000-link-x");
            Directory.CreateDirectory(impX);
            File.WriteAllText(Path.Combine(impX, "AEG-AAAAA.json"), EvJson(xav, "ban"), new UTF8Encoding(false));
            Func<Row> yukiRow = () =>
            {
                var s = new Snapshot();
                Loader.Bans(s, new Step("bans", null));
                Loader.Evidence(s, new Step("ev", null));
                Loader.Rows(s, new Step("rows", null));
                foreach (var r in s.Rows) if (r.Name == "Yuki") return r;
                return null;
            };
            var y1 = yukiRow();
            Check("link.same-id-other-player-not-linked", y1 != null && y1.Ev == null, y1 == null ? "no row" : y1.Ev != null ? y1.Ev.Name : "");
            // the same id and the same player, as the launcher now writes it (the friend code's hash replaced by the PUID's)
            var yz = Ev("AEG-AAAAA", "certain", "KillRole");
            yz.Name = "Yuki"; yz.Hash = yuki.PuidHash; yz.PuidHash = yuki.PuidHash;
            string impY = Path.Combine(App.ImportDir, "20260922-000001-link-y");
            Directory.CreateDirectory(impY);
            File.WriteAllText(Path.Combine(impY, "AEG-AAAAA.json"), EvJson(yz, "ban"), new UTF8Encoding(false));
            var y2 = yukiRow();
            Check("link.same-player-linked-by-puid", y2 != null && y2.Ev != null && y2.Ev.PuidHash == yuki.PuidHash && y2.Ev.Imported && !GateRules.Trusted(y2.Ev), y2 == null ? "no row" : y2.Ev == null ? "not linked" : y2.Ev.Name);
            // dismissed (moved to reviewed\ like DoDismiss): the ban keeps its evidence
            string rev = Path.Combine(App.ReviewedDir, Path.GetFileName(impY));
            Directory.CreateDirectory(rev);
            File.Move(Path.Combine(impY, "AEG-AAAAA.json"), Path.Combine(rev, "AEG-AAAAA.json"));
            var y3 = yukiRow();
            Check("link.after-dismiss-from-reviewed", y3 != null && y3.Ev != null && y3.Ev.PuidHash == yuki.PuidHash && y3.Ev.Imported, y3 == null ? "no row" : y3.Ev == null ? "not linked" : y3.Ev.Name);
            // this PC's own file of another player under the ban's id is not linked either
            Directory.CreateDirectory(App.EvidenceDir);
            File.WriteAllText(ownFile, EvJson(xav, "ban"), new UTF8Encoding(false));
            var y4 = yukiRow();
            Check("link.own-file-other-player-not-linked", y4 != null && (y4.Ev == null || y4.Ev.Name == "Yuki"), y4 == null ? "no row" : y4.Ev == null ? "" : y4.Ev.Name);
            File.Delete(ownFile);
        }

        // ------------------------------------------------------------------ v0.5.5 the unlock, the audit chain, outside changes, replies, fake evidence

        /// <summary>A state folder of its own for a group (the chain and the snapshot start empty).</summary>
        static void Fresh(string name)
        {
            App.StateDir = Path.Combine(root, "state-" + name);
            Directory.CreateDirectory(App.StateDir);
        }

        static string SignText(string keyXml, string text)
        {
            using (var rsa = new RSACryptoServiceProvider())
            {
                rsa.PersistKeyInCsp = false;
                rsa.FromXmlString(keyXml);
                return Convert.ToBase64String(rsa.SignData(Encoding.UTF8.GetBytes(text), "SHA256"));
            }
        }

        /// <summary>A response / token file as tools\sign-definitions.ps1 -Unlock writes it, signed with <paramref name="keyXml"/>.</summary>
        static string ProofText(string keyXml, string keyId, string nonce, DateTime at, string machine, string user)
        {
            string atText = Json.Time(at);
            string sig = SignText(keyXml, UnlockProof.Message(nonce, atText, machine, user));
            return "# PocketRoles Aegis BAN console: proof that the owner holds the signing key (not secret; used once)\r\nformat=" + UnlockProof.Format + "\r\nnonce=" + nonce + "\r\nat=" + atText
                + "\r\nmachine=" + machine + "\r\nuser=" + user + "\r\nkeyid=" + keyId + "\r\nsig=" + sig + "\r\n";
        }

        /// <summary>
        /// The key proof (item 1): a valid answer passes; a wrong key, a revoked or unknown key, a wrong nonce, a too old or
        /// future time, another PC / user, and fake files (garbage, a made-up signature, a field changed after signing, a
        /// missing or extra field) do not. The stored token lasts 30 days on this PC and user and is checked again each time.
        /// Throwaway keys only (never the real one).
        /// </summary>
        static void UnlockTests()
        {
            Fresh("unlock");
            string priv, pub, other;
            using (var rsa = new RSACryptoServiceProvider(3072)) { rsa.PersistKeyInCsp = false; priv = rsa.ToXmlString(true); pub = rsa.ToXmlString(false); }
            using (var rsa = new RSACryptoServiceProvider(3072)) { rsa.PersistKeyInCsp = false; other = rsa.ToXmlString(true); }
            const string kid = "5e1f7e575e1f7e57";
            Sig.TrustedKeys = new[] { new Sig.Key(kid, pub) };
            Sig.RevokedKeyIds = new string[0];
            string machine = Ident.MachineId(), user = Ident.UserId();
            Check("unlock.ident", machine.Length > 17 && machine.IndexOf('/') > 0 && user.IndexOf('/') > 0 && Regex.IsMatch(machine, "/[0-9a-f]{16}$") && Regex.IsMatch(user, "/[0-9a-f]{16}$") && machine == Ident.MachineId(), machine + " " + user);
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            string nonce = UnlockProof.NewNonce();
            Check("unlock.nonce", UnlockProof.NonceOk(nonce) && nonce != UnlockProof.NewNonce(), nonce);
            Func<string, int> check = t => UnlockProof.Check(UnlockProof.Parse(t), nonce, machine, user, now.AddMinutes(1), UnlockProof.ChallengeAge);
            string good = ProofText(priv, kid, nonce, now, machine, user);
            Check("unlock.valid", check(good) == UnlockProof.Ok, check(good).ToString(CultureInfo.InvariantCulture));
            Check("unlock.wrong-key", check(ProofText(other, kid, nonce, now, machine, user)) == UnlockProof.BadSig, null);
            Check("unlock.unknown-keyid", check(ProofText(priv, "0000000000000000", nonce, now, machine, user)) == UnlockProof.UnknownKey, null);
            Sig.RevokedKeyIds = new[] { kid };
            Check("unlock.revoked-key", check(good) == UnlockProof.UnknownKey, null);
            Sig.RevokedKeyIds = new string[0];
            Check("unlock.wrong-nonce", UnlockProof.Check(UnlockProof.Parse(good), UnlockProof.NewNonce(), machine, user, now, UnlockProof.ChallengeAge) == UnlockProof.WrongNonce, null);
            Check("unlock.too-old", check(ProofText(priv, kid, nonce, now.AddMinutes(-6), machine, user)) == UnlockProof.TooOld, null);
            Check("unlock.future", check(ProofText(priv, kid, nonce, now.AddMinutes(10), machine, user)) == UnlockProof.Future, null);
            Check("unlock.other-pc", check(ProofText(priv, kid, nonce, now, "OTHER-PC/0123456789abcdef", user)) == UnlockProof.OtherPlace, null);
            Check("unlock.other-user", check(ProofText(priv, kid, nonce, now, machine, "someone/0123456789abcdef")) == UnlockProof.OtherPlace, null);
            // fake files
            Check("unlock.fake.garbage", check("hello, I am the owner") == UnlockProof.Malformed && UnlockProof.Parse("") == null, null);
            string madeUp = Regex.Replace(good, "sig=.*", "sig=" + Convert.ToBase64String(new byte[384]));
            Check("unlock.fake.made-up-signature", check(madeUp) == UnlockProof.BadSig, null);
            string edited = good.Replace("user=" + user, "user=" + user.Substring(0, user.Length - 1) + (user.EndsWith("0") ? "1" : "0"));
            Check("unlock.fake.field-changed-after-signing", check(edited) != UnlockProof.Ok, check(edited).ToString(CultureInfo.InvariantCulture));
            Check("unlock.fake.missing-field", UnlockProof.Parse(Regex.Replace(good, "keyid=.*\\r\\n", "")) == null, null);
            Check("unlock.fake.extra-field", UnlockProof.Parse(good + "admin=yes\r\n") == null && UnlockProof.Parse(good + "nonce=" + nonce + "\r\n") == null, null);
            // the answer file → the token (owner-proof.txt) → 30 days on this PC and user
            Directory.CreateDirectory(App.UnlockDir);
            var real = DateTime.UtcNow;
            string path = UnlockProof.ResponsePath(nonce);
            File.WriteAllText(path, ProofText(priv, kid, nonce, real, machine, user), new UTF8Encoding(false));
            Check("unlock.accept", UnlockProof.Accept(path, nonce, real) == UnlockProof.Ok && !File.Exists(path) && File.Exists(App.ProofFile), null);
            // v0.5.5 (2026-09-23): the window is one named constant (UnlockProof.TokenDays, 7): the test follows it, so
            // changing the number cannot leave a test asserting the old one
            Check("unlock.token.window-is-one-week", UnlockProof.TokenDays == 7 && UnlockProof.TokenAge == TimeSpan.FromDays(UnlockProof.TokenDays), UnlockProof.TokenDays.ToString(CultureInfo.InvariantCulture));
            Check("unlock.token.valid", UnlockProof.Token(real) != null && UnlockProof.Token(real.AddDays(UnlockProof.TokenDays).AddHours(-1)) != null, null);
            Check("unlock.token.after-the-window", UnlockProof.Token(real.AddDays(UnlockProof.TokenDays).AddHours(1)) == null && UnlockProof.Token(real.AddDays(31)) == null, null);
            string n2 = UnlockProof.NewNonce();
            string p2 = UnlockProof.ResponsePath(n2);
            File.WriteAllText(p2, ProofText(priv, kid, nonce, real, machine, user), new UTF8Encoding(false));   // an old answer to a new question
            Check("unlock.accept.replayed-answer", UnlockProof.Accept(p2, n2, real) == UnlockProof.WrongNonce && !File.Exists(p2), null);
            Check("unlock.accept.no-file", UnlockProof.Accept(UnlockProof.ResponsePath(UnlockProof.NewNonce()), n2, real) == UnlockProof.Missing, null);
            string keep = File.ReadAllText(App.ProofFile);
            Sig.RevokedKeyIds = new[] { kid };
            Check("unlock.token.revoked-key", UnlockProof.Token(real) == null, null);
            Sig.RevokedKeyIds = new string[0];
            File.WriteAllText(App.ProofFile, madeUp.Replace("at=" + Json.Time(now), "at=" + Json.Time(real)), new UTF8Encoding(false));
            Check("unlock.token.fake-file", UnlockProof.Token(real) == null, null);
            File.WriteAllText(App.ProofFile, ProofText(priv, kid, nonce, real, machine, "someone/0123456789abcdef"), new UTF8Encoding(false));
            Check("unlock.token.copied-from-another-user", UnlockProof.Token(real) == null, null);
            File.WriteAllText(App.ProofFile, ProofText(other, kid, nonce, real, machine, user), new UTF8Encoding(false));
            Check("unlock.token.signed-by-another-key", UnlockProof.Token(real) == null, null);
            File.WriteAllText(App.ProofFile, keep, new UTF8Encoding(false));
            Check("unlock.token.restored", UnlockProof.Token(real) != null, null);
            // v0.5.5 review: the clock set back (the days are counted on it) does not bring an expired proof back
            Check("unlock.token.clock-ok", UnlockProof.Token(real.AddDays(3)) != null && !UnlockProof.ClockWentBack(real.AddDays(3)), null);
            Audit.Append(new AuditRec { At = real.AddDays(3), Action = "unlock", Result = "as.owner" });   // the console was used on day 3
            Check("unlock.token.clock-set-back", UnlockProof.Token(real.AddDays(1)) == null && UnlockProof.ClockWentBack(real.AddDays(1)) && UnlockProof.Token(real.AddDays(4)) != null && S.Has("pv.9"), null);
            SeenMarks.Put(0, "x");
            File.WriteAllText(App.SeenFile, File.ReadAllText(App.SeenFile).Replace(Json.Time(DateTime.UtcNow).Substring(0, 10), Json.Time(real.AddDays(5)).Substring(0, 10)), new UTF8Encoding(false));
            Check("unlock.token.clock-seen-marks", UnlockProof.LatestSeen() >= real.AddDays(4) && UnlockProof.Token(real.AddDays(4.5)) == null, Json.Time(UnlockProof.LatestSeen()));
            // the console command passes only the nonce and the path (never a password)
            string cmd = Ops.UnlockCommand("C:\\repo\\tools\\sign-definitions.ps1", nonce, path);
            Check("unlock.console-command", cmd.IndexOf("-Unlock '" + nonce + "'", StringComparison.Ordinal) >= 0 && cmd.IndexOf("-UnlockOut", StringComparison.Ordinal) >= 0 && cmd.IndexOf("assword", StringComparison.OrdinalIgnoreCase) < 0, cmd);
            // v0.5.5 review: its own texts, no Enter to wait for when it worked, the script's path and fingerprint on top
            string sign = Ops.SignCommand("C:\\repo\\tools\\sign-definitions.ps1", "C:\\work\\definitions.txt");
            Check("unlock.console-own-texts", cmd.IndexOf(S.Get("ul.console.ok"), StringComparison.Ordinal) >= 0 && cmd.IndexOf(S.Get("ul.console.fail"), StringComparison.Ordinal) >= 0 && cmd.IndexOf(S.Get("sign.ok"), StringComparison.Ordinal) < 0
                && sign.IndexOf(S.Get("sign.ok"), StringComparison.Ordinal) >= 0, null);
            Check("unlock.console-no-enter-on-success", cmd.IndexOf("if ($code -eq 0) { Start-Sleep", StringComparison.Ordinal) >= 0 && sign.IndexOf("Start-Sleep", StringComparison.Ordinal) < 0 && sign.IndexOf("Read-Host", StringComparison.Ordinal) >= 0, null);
            Check("unlock.console-shows-script", cmd.IndexOf(S.Get("cs.script", "C:\\repo\\tools\\sign-definitions.ps1").Replace("'", "''"), StringComparison.Ordinal) >= 0 && cmd.IndexOf(S.Get("cs.sha", "—"), StringComparison.Ordinal) >= 0, cmd);
            string known = Path.Combine(root, "sha-test.txt");
            File.WriteAllText(known, "abc", new UTF8Encoding(false));
            Check("unlock.script-sha16", Ops.ScriptSha16(known) == "ba7816bf8f01cfea" && Ops.ScriptSha16(Path.Combine(root, "none.ps1")) == "—", Ops.ScriptSha16(known));
            // v0.5.5 review: the signing script next to the app wins over the repository folder (settings.txt cannot move it)
            string oldScriptDir = App.ScriptDir, oldRepo = App.RepoDir;
            try
            {
                string app = Path.Combine(root, "app"), repo2 = Path.Combine(root, "elsewhere");
                Directory.CreateDirectory(Path.Combine(app, "aegis")); Directory.CreateDirectory(Path.Combine(app, "tools")); Directory.CreateDirectory(Path.Combine(repo2, "tools"));
                File.WriteAllText(Path.Combine(app, "tools", "sign-definitions.ps1"), "# app's own", new UTF8Encoding(false));
                File.WriteAllText(Path.Combine(repo2, "tools", "sign-definitions.ps1"), "# somewhere else", new UTF8Encoding(false));
                App.ScriptDir = Path.Combine(app, "aegis");
                App.RepoDir = repo2;
                Check("unlock.sign-script-next-to-app", string.Equals(App.SignScript, Path.Combine(app, "tools", "sign-definitions.ps1"), StringComparison.OrdinalIgnoreCase), App.SignScript);
                File.Delete(Path.Combine(app, "tools", "sign-definitions.ps1"));
                Check("unlock.sign-script-repo-fallback", string.Equals(App.SignScript, Path.Combine(repo2, "tools", "sign-definitions.ps1"), StringComparison.OrdinalIgnoreCase), App.SignScript);
            }
            finally { App.ScriptDir = oldScriptDir; App.RepoDir = oldRepo; }
            bool threw = false;
            try { Ops.UnlockCommand("x", "not-a-nonce'; Remove-Item", path); } catch (ArgumentException) { threw = true; }
            Check("unlock.console-command.nonce-only-hex", threw, null);
        }

        /// <summary>The lock: every change is refused while locked (the local writes and the signing / publishing steps); an admin unlock never signs.</summary>
        static void LockTests()
        {
            Fresh("lock");
            bool was = App.Admin;
            Session.Lock();
            try
            {
                Check("lock.starts-locked", !Session.Unlocked && !Session.OwnerActive && Session.Mode.Length == 0, null);
                var st = new Step("local", null);
                var a = Journal.NewAction("unban", new List<string> { Hashes.HashOf("selftest-lock") }, "x");
                Check("lock.local-change-refused", !Ops.RunLocal(a, st) && st.Detail == S.Get("e.locked"), st.Detail);
                var st2 = new Step("add", null);
                Check("lock.add-refused", !Ops.RunAdd(Journal.NewAction("add", new List<string>(), ""), Ev("AEG-LOCK1", "certain", "KillRole"), 30, "", 0, st2) && st2.Detail == S.Get("e.locked"), st2.Detail);
                App.Admin = false;
                Func<List<string>> refused = () =>
                {
                    var names = new List<string>();
                    var steps = new Dictionary<string, Func<Step, bool>>
                    {
                        { "CheckRepo", s => Ops.CheckRepo(s) }, { "BuildWork", s => Ops.BuildWork(new JObj(), s) }, { "RecordPending", s => Ops.RecordPending(new JObj(), s) },
                        { "GitCheck", s => Ops.GitCheck(new Ops.PublishCtx(), s) }, { "Place", s => Ops.Place(new Ops.PublishCtx(), s) },
                        { "Commit", s => Ops.Commit(new Ops.PublishCtx(), s) }, { "Push", s => Ops.Push(new Ops.PublishCtx(), s) },
                    };
                    foreach (var kv in steps) { var s = new Step(kv.Key, null); if (kv.Value(s) || s.Detail != S.Get("e.notowner")) names.Add(kv.Key); }
                    return names;
                };
                var r1 = refused();
                Check("lock.owner-steps-refused-while-locked", r1.Count == 0, string.Join(", ", r1.ToArray()));
                Session.Unlock("admin", "code");
                var r2 = refused();
                Check("lock.owner-steps-refused-for-an-admin-unlock", Session.Unlocked && !Session.OwnerActive && r2.Count == 0, string.Join(", ", r2.ToArray()));
                Session.Unlock("owner", "key");
                Check("lock.owner-unlock", Session.OwnerActive && Session.Method == "key" && Session.MinutesLeft == Session.IdleMinutes, Session.MinutesLeft.ToString(CultureInfo.InvariantCulture));
                var msg = new Message { Msg = 0x0100 };
                Check("lock.input-counts", new InputWatch().PreFilterMessage(ref msg) == false && Session.IdleMs < 5000 && !Session.IdleExpired, null);
                Session.Lock();
                Check("lock.locks", !Session.Unlocked && !Session.OwnerActive, null);
                Check("lock.method-texts", Session.MethodText("code", 0) == "コード（確認なし）" && Session.MethodText("hello+proof", 2) == "Windows Hello + key record", null);
                // v0.5.5 review: the chip says what pressing it does; the English one joins with " · " (not "・")
                Check("lock.chip-says-how", S.In(0, "lk.locked").IndexOf("押して解錠", StringComparison.Ordinal) > 0 && S.In(1, "lk.locked").IndexOf("点击解锁", StringComparison.Ordinal) > 0
                    && S.In(2, "lk.locked").IndexOf("click to unlock", StringComparison.Ordinal) > 0 && S.In(0, "lk.open", "x", 3).EndsWith("押すとロック", StringComparison.Ordinal)
                    && S.In(2, "lk.open", "x", 3).EndsWith("click to lock", StringComparison.Ordinal) && S.In(1, "lk.open", "x", 3).EndsWith("点击锁定", StringComparison.Ordinal), null);
                Session.Unlock("owner", "key");
                Check("lock.describe-separator", Session.Describe(2) == "owner · signing key" && Session.Describe(0) == "作者・署名の鍵" && Session.Describe(2).IndexOf('・') < 0, Session.Describe(2));
                Session.Lock();
                // v0.5.5 review: only an operation whose steps run counts as input for the idle lock (not an open window, not a reload)
                using (var op = new OpForm("x", new List<Step>(), false, null)) Check("lock.idle-only-running-steps", !OpForm.AnyRunning, null);
                // an observed change names where it was noticed, not as if that user made it
                var obs = new AuditRec { Action = "observed.change", User = "riot", Machine = "PC1", Mode = "-", Method = "observed", Result = "outside" };
                string who = Audit.OperatorText(obs, 2);
                Check("lock.observed-operator-text", who == "noticed on: riot @ PC1" && Audit.OperatorText(obs, 0) == "見つけた PC: riot @ PC1" && SinceDialog.Line(obs).IndexOf("(-", StringComparison.Ordinal) < 0, who);
            }
            finally { App.Admin = was; Session.Lock(); }
        }

        /// <summary>
        /// v0.5.5 (2026-09-23 オーナーの質問「もし乗っ取られたりしたら Windows Hello で認証されて管理渡らない？」):
        /// what reaches other hosts and players needs the key challenge of THIS run (never the stored Windows Hello proof);
        /// the owner can invalidate every stored proof at once, even from a locked console, and cannot have that quietly
        /// undone (the audit chain); every unlock is counted and shown at the next start; the away lock and the 4-digit
        /// code follow whether this PC holds a key. Throwaway keys only (never the real one), in a temp folder.
        /// </summary>
        static void KeyGateTests()
        {
            Fresh("keygate");
            bool wasAdmin = App.Admin, wasSignal = App.KeySignal;
            Session.Lock();
            Session.KeyProven = false;
            try
            {
                App.Admin = false;
                App.KeySignal = true;
                // ---- the gate itself: the steps that sign or publish (App.RepoDir is an empty temp folder, never the real one)
                Func<string, List<string>> stoppedWith = detail =>
                {
                    var names = new List<string>();
                    var steps = new Dictionary<string, Func<Step, bool>>
                    {
                        { "CheckRepo", s => Ops.CheckRepo(s) }, { "BuildWork", s => Ops.BuildWork(new JObj(), s) }, { "RecordPending", s => Ops.RecordPending(new JObj(), s) },
                        { "GitCheck", s => Ops.GitCheck(new Ops.PublishCtx(), s) }, { "Place", s => Ops.Place(new Ops.PublishCtx(), s) },
                        { "Commit", s => Ops.Commit(new Ops.PublishCtx(), s) }, { "Push", s => Ops.Push(new Ops.PublishCtx(), s) },
                    };
                    foreach (var kv in steps) { var s = new Step(kv.Key, null); if (!kv.Value(s) && s.Detail == detail) names.Add(kv.Key); }
                    return names;
                };
                Session.Unlock("owner", "hello+proof");   // the owner mode by Windows Hello and the stored record
                var byHello = stoppedWith(S.Get("e.needkey"));
                Check("keygate.hello-proof-owner-cannot-sign-or-publish", Session.OwnerActive && !Session.KeyProven && byHello.Count == 7, byHello.Count.ToString(CultureInfo.InvariantCulture) + ": " + string.Join(", ", byHello.ToArray()));
                Session.KeyProven = true;
                var byKey = stoppedWith(S.Get("e.needkey"));
                Check("keygate.key-proven-in-this-run-passes-the-gate", byKey.Count == 0, string.Join(", ", byKey.ToArray()));
                Session.KeyProven = false;
                Session.Lock();
                Check("keygate.locked-still-refused", stoppedWith(S.Get("e.notowner")).Count == 7, null);
                Check("keygate.gate-text-in-three-languages", S.In(0, "e.needkey").Length > 0 && S.In(1, "e.needkey").Length > 0 && S.In(2, "e.needkey").Length > 0 && S.In(0, "e.needkey") != S.In(2, "e.needkey"), null);
                // ---- the window is one named constant, and the idle minutes are too
                Check("keygate.idle-minutes", Session.IdleMinutes == 10 && S.In(0, "lk.idle", Session.IdleMinutes).IndexOf("10 分", StringComparison.Ordinal) >= 0
                    && S.In(2, "ul.head", Session.IdleMinutes).IndexOf("10 minutes", StringComparison.Ordinal) >= 0
                    && S.In(2, "ul.ok", UnlockProof.TokenDays).IndexOf("7 days", StringComparison.Ordinal) >= 0, Session.IdleMinutes.ToString(CultureInfo.InvariantCulture));
                // ---- the away lock: the screen locked, a log off, the console or the remote session handed over
                Check("keygate.away-lock", Session.LocksOnSwitch(SessionSwitchReason.SessionLock) && Session.LocksOnSwitch(SessionSwitchReason.SessionLogoff)
                    && Session.LocksOnSwitch(SessionSwitchReason.ConsoleDisconnect) && Session.LocksOnSwitch(SessionSwitchReason.RemoteDisconnect)
                    && !Session.LocksOnSwitch(SessionSwitchReason.SessionUnlock) && !Session.LocksOnSwitch(SessionSwitchReason.SessionLogon)
                    && !Session.LocksOnSwitch(SessionSwitchReason.ConsoleConnect) && !Session.LocksOnSwitch(SessionSwitchReason.RemoteConnect), null);
                // ---- the 4-digit code (its answer is on the screen) is never offered where a signing key is reachable
                Check("keygate.no-code-on-a-key-pc", !UnlockDialog.CodeAllowed(), null);
                App.KeySignal = false;
                Check("keygate.code-on-an-admin-kit-pc", UnlockDialog.CodeAllowed(), null);
                App.KeySignal = true;
                // ---- the stored proof and its revocation (a throwaway key, never the real one)
                string priv, pub;
                using (var rsa = new RSACryptoServiceProvider(2048)) { rsa.PersistKeyInCsp = false; priv = rsa.ToXmlString(true); pub = rsa.ToXmlString(false); }
                const string kid = "a1b2c3d4a1b2c3d4";
                Sig.TrustedKeys = new[] { new Sig.Key(kid, pub) };
                Sig.RevokedKeyIds = new string[0];
                string machine = Ident.MachineId(), user = Ident.UserId();
                var now = DateTime.UtcNow;
                Directory.CreateDirectory(App.StateDir);
                string proof = ProofText(priv, kid, UnlockProof.NewNonce(), now, machine, user);
                File.WriteAllText(App.ProofFile, proof, new UTF8Encoding(false));
                Check("keygate.proof.counts-before-the-revoke", UnlockProof.Token(now) != null && UnlockProof.RevokedAt() == DateTime.MinValue, null);
                // a proof carried to another Windows user or another PC never counts (it names the PC and the user it was made for)
                File.WriteAllText(App.ProofFile, ProofText(priv, kid, UnlockProof.NewNonce(), now, machine, "someone-else/0123456789abcdef"), new UTF8Encoding(false));
                Check("keygate.proof.copied-to-another-user", UnlockProof.Token(now) == null, null);
                File.WriteAllText(App.ProofFile, ProofText(priv, kid, UnlockProof.NewNonce(), now, "OTHER-PC/0123456789abcdef", user), new UTF8Encoding(false));
                Check("keygate.proof.copied-to-another-pc", UnlockProof.Token(now) == null, null);
                File.WriteAllText(App.ProofFile, proof, new UTF8Encoding(false));
                // the revoke needs no unlock: the owner can do it from a locked console
                Session.Lock();
                Session.KeyProven = true;
                bool logged = UnlockProof.Revoke(now.AddSeconds(1));
                Check("keygate.revoke.from-a-locked-console", logged && !Session.Unlocked && !Session.KeyProven && !File.Exists(App.ProofFile) && UnlockProof.RevokedAt() >= now, Json.Time(UnlockProof.RevokedAt()));
                File.WriteAllText(App.ProofFile, proof, new UTF8Encoding(false));   // the file put back: it is still older than the revoke
                Check("keygate.revoke.old-proof-stays-dead", UnlockProof.Token(now.AddSeconds(2)) == null && UnlockProof.Token(now.AddDays(1)) == null, null);
                // only a new key challenge helps: a proof made AFTER the revoke counts again
                File.WriteAllText(App.ProofFile, ProofText(priv, kid, UnlockProof.NewNonce(), now.AddSeconds(30), machine, user), new UTF8Encoding(false));
                Check("keygate.revoke.only-a-new-key-check-helps", UnlockProof.Token(now.AddSeconds(31)) != null, null);
                // ---- 「前回からの解錠: N 回」: every unlock is an audit line with its mode, method, Windows user and PC
                Audit.Append(new AuditRec { At = now.AddSeconds(40), Action = "unlock", Result = "as.owner", Mode = "owner", Method = "key" });
                Audit.Append(new AuditRec { At = now.AddSeconds(50), Action = "unlock", Result = "as.admin" });   // (the session is locked: mode / method are filled in as "-")
                Audit.Append(new AuditRec { At = now.AddSeconds(60), Action = "unlock", Result = "as.admin", Mode = "admin", Method = "hello" });
                Audit.Append(new AuditRec { At = now.AddSeconds(70), Action = "unlock", Result = "as.admin", Mode = "admin", Method = "hello" });
                var all = Audit.Since(0);
                var unlockLines = new List<AuditRec>();
                foreach (var r in all) if (r.Action == "unlock") unlockLines.Add(r);
                var first = unlockLines.Count > 0 ? unlockLines[0] : null;
                Check("keygate.unlock-line-names-who-and-how", first != null && first.Mode == "owner" && first.Method == "key" && first.User.Length > 0 && first.Machine.Length > 0 && first.At >= now,
                    first == null ? "none" : first.Mode + "/" + first.Method + "/" + first.User + "@" + first.Machine);
                string sumEn = Audit.UnlockSummary(all, 2), sumJa = Audit.UnlockSummary(all, 0);
                Check("keygate.unlock-counter", sumEn.IndexOf("Unlocks since last time: 4", StringComparison.Ordinal) >= 0 && sumEn.IndexOf("signing key ×1", StringComparison.Ordinal) >= 0
                    && sumEn.IndexOf("Windows Hello ×2", StringComparison.Ordinal) >= 0 && sumJa.IndexOf("前回からの解錠: 4 回", StringComparison.Ordinal) >= 0
                    && sumJa.IndexOf("署名の鍵 1 回", StringComparison.Ordinal) >= 0, sumEn + " | " + sumJa);
                Check("keygate.unlock-counter.none", Audit.UnlockSummary(new List<AuditRec>(), 2).Length == 0 && Audit.UnlockSummary(null, 2).Length == 0, null);
                // the revoke line is in the same hash chain: taking it out again breaks the chain, so it cannot be done quietly
                var lines = Audit.ReadLines();
                var kept = new List<string>();
                int dropped = 0;
                foreach (var l in lines) { if (dropped == 0 && l.IndexOf("\t" + UnlockProof.RevokeAction + "\t", StringComparison.Ordinal) >= 0) { dropped++; continue; } kept.Add(l); }
                File.WriteAllText(App.AuditFile, string.Join("\r\n", kept.ToArray()) + "\r\n", new UTF8Encoding(false));
                var chain = Audit.Verify(0, null);
                Check("keygate.revoke.line-cannot-be-taken-out-quietly", dropped == 1 && !chain.Ok, dropped.ToString(CultureInfo.InvariantCulture) + " removed, chain ok=" + chain.Ok);
            }
            finally { App.Admin = wasAdmin; App.KeySignal = wasSignal; Session.Lock(); Session.KeyProven = false; }
        }

        /// <summary>Windows Hello through WinRT from PowerShell 5.1: the availability can be asked (no prompt is shown) and the IID the window call needs is right.</summary>
        static void HelloTests()
        {
            var rt = Hello.WinRt("Windows.Security.Credentials.UI.UserConsentVerificationResult");
            var iop = Hello.WinRt("Windows.Foundation.IAsyncOperation`1");
            Check("hello.winrt-types", rt != null && iop != null && Hello.WinRt(Hello.VerifierClass) != null, null);
            if (rt != null && iop != null) Check("hello.verification-iid", iop.MakeGenericType(rt).GUID == Hello.VerificationOpIid(), Hello.VerificationOpIid().ToString());
            int a = Hello.Availability(8000);
            Check("hello.availability-asked", a >= 0 && a <= 4, "result " + a + " (" + S.Get("hl." + a.ToString(CultureInfo.InvariantCulture)) + ")");
            Check("hello.window-interop-reachable", Hello.InteropReachable(), null);
            Check("hello.texts", S.Has("hl." + a.ToString(CultureInfo.InvariantCulture)) && S.Has("hr.6") && S.Has("hr.-1"), null);
        }

        static void WriteLines(string path, IList<string> lines) { File.WriteAllText(path, string.Join("\r\n", new List<string>(lines).ToArray()) + (lines.Count > 0 ? "\r\n" : ""), new UTF8Encoding(false)); }

        /// <summary>The audit log's hash chain (item 2): intact; an edited, a deleted or a legacy line; a cut end; a missing head; a crash between the line and the head.</summary>
        static void ChainTests()
        {
            Fresh("chain");
            // two lines of an older build first (no prev=): the first chained line covers them
            File.WriteAllText(App.AuditFile, "2026-09-21T10:00:00Z\tshare\tev=AEG-OLD01\tname=old\trule=harass\treason=\tby=\tact=a1\tresult=signed 3\r\n2026-09-21T11:00:00Z\tpublish\tev=\tname=\trule=\treason=\tby=\tact=a1\tresult=pushed 3 1a2b3c4d\r\n", new UTF8Encoding(false));
            for (int i = 0; i < 5; i++)
                Audit.Append(new AuditRec { Action = "unban", Ev = "AEG-CHN0" + i.ToString(CultureInfo.InvariantCulture), Name = "n" + i.ToString(CultureInfo.InvariantCulture), Result = "done.local", User = "tester", Machine = "PC1", Mode = "owner", Method = "key" });
            var c = Audit.Verify(0);
            var lines = Audit.ReadLines();
            Check("chain.intact", c.Ok && c.Lines == 7, c.Kind + " " + c.At);
            bool allPrev = true;
            for (int i = 2; i < lines.Count; i++) if (Audit.PrevOf(lines[i]) == null) allPrev = false;
            Check("chain.every-line-chained-no-hex", allPrev && !HexShape.IsMatch(File.ReadAllText(App.AuditFile)), null);
            string orig = File.ReadAllText(App.AuditFile);
            var ed = new List<string>(lines);
            ed[4] = ed[4].Replace("name=n2", "name=nX");
            WriteLines(App.AuditFile, ed);
            c = Audit.Verify(0);
            Check("chain.edited-line", !c.Ok && c.Kind == "edited" && c.At == 6, c.Kind + " " + c.At);
            var del = new List<string>(lines);
            del.RemoveAt(4);
            WriteLines(App.AuditFile, del);
            c = Audit.Verify(0);
            Check("chain.deleted-line", !c.Ok && c.Kind == "edited" && c.At == 5, c.Kind + " " + c.At);
            var leg = new List<string>(lines);
            leg[0] = leg[0].Replace("name=old", "name=new");
            WriteLines(App.AuditFile, leg);
            c = Audit.Verify(0);
            Check("chain.legacy-line-edited", !c.Ok && c.Kind == "legacy" && c.At == 3, c.Kind + " " + c.At);
            var last = new List<string>(lines);
            last[6] = last[6].Replace("name=n4", "name=n9");
            WriteLines(App.AuditFile, last);
            c = Audit.Verify(0);
            Check("chain.last-line-edited", !c.Ok && c.Kind == "edited" && c.At == 7, c.Kind + " " + c.At);
            var cut = new List<string>(lines);
            cut.RemoveRange(5, 2);
            WriteLines(App.AuditFile, cut);
            c = Audit.Verify(0);
            Check("chain.truncated", !c.Ok && c.Kind == "truncated" && c.At == 6 && c.Expected == 7, c.Kind + " " + c.At + " " + c.Expected);
            Check("chain.banner-text", S.In(0, "au.broken", c.At) == "履歴が書き換えられています（6 行目）" && Audit.Explain(c, 0).Length > 0, S.In(0, "au.broken", c.At));
            File.WriteAllText(App.AuditFile, orig, new UTF8Encoding(false));
            Check("chain.restored", Audit.Verify(0).Ok, null);
            Check("chain.seen-count-larger", Audit.Verify(9).Kind == "truncated", null);
            string head = File.ReadAllText(App.AuditHead);
            File.Delete(App.AuditHead);
            c = Audit.Verify(0);
            Check("chain.head-missing", !c.Ok && c.Kind == "head", c.Kind);
            File.WriteAllText(App.AuditHead, head, new UTF8Encoding(false));
            // a crash between the line and the head: one line more than the head knows is taken as it is (and the head repaired)
            Audit.Append(new AuditRec { Action = "discard", Result = "discarded 4" });
            string head8 = File.ReadAllText(App.AuditHead);
            File.WriteAllText(App.AuditHead, head, new UTF8Encoding(false));   // the head of 7 lines, the file of 8
            c = Audit.Verify(0);
            Check("chain.head-one-behind-repaired", c.Ok && Audit.ReadHead().Count == 8, c.Kind + " " + (Audit.ReadHead() != null ? Audit.ReadHead().Count : -1));
            File.WriteAllText(App.AuditHead, head8, new UTF8Encoding(false));
            // appends after a rewrite chain to the file's real last line (the break stays visible where it was)
            File.WriteAllText(App.AuditFile, orig, new UTF8Encoding(false));
            File.WriteAllText(App.AuditHead, head, new UTF8Encoding(false));
            WriteLines(App.AuditFile, ed);
            Audit.Append(new AuditRec { Action = "unlock", Result = "as.owner" });
            c = Audit.Verify(0);
            Check("chain.break-stays-after-append", !c.Ok && c.Kind == "edited" && c.At == 6, c.Kind + " " + c.At);
            Check("chain.read-all-numbers-lines", Audit.ReadAll().Count == 8 && Audit.ReadAll()[7].No == 8 && Audit.ReadAll()[7].Action == "unlock", null);
            ChainReviewTests();
        }

        /// <summary>Rebuilds a chain after an edit, the way a program of someone's own would (every prev= and audit.head computed again).</summary>
        static void Rechain(List<string> lines, int legacy)
        {
            string prev = Audit.Anchor(lines, legacy);
            for (int i = legacy; i < lines.Count; i++)
            {
                string l = lines[i];
                int t = l.LastIndexOf("\t" + Audit.PrevKey, StringComparison.Ordinal);
                if (t >= 0) l = l.Substring(0, t);
                l = l + "\t" + Audit.PrevKey + prev;
                lines[i] = l;
                prev = Audit.H(l);
            }
            WriteLines(App.AuditFile, lines);
            File.WriteAllText(App.AuditHead, "format=PocketRoles.AegisBanConsole.AuditHead.v1\r\ncount=" + lines.Count.ToString(CultureInfo.InvariantCulture) + "\r\nlast=" + prev + "\r\nlength=" + new FileInfo(App.AuditFile).Length.ToString(CultureInfo.InvariantCulture) + "\r\n", new UTF8Encoding(false));
        }

        /// <summary>
        /// v0.5.5 review (the audit log's tamper evidence): a chain rebuilt to the same length, and a log stripped of every
        /// prev= with its head deleted, show against this user's seen mark; a line appended with the head's value copied is
        /// taken but reported; an older log without a head gets one and is checked from then on.
        /// </summary>
        static void ChainReviewTests()
        {
            Fresh("chain2");
            for (int i = 0; i < 4; i++) Audit.Append(new AuditRec { Action = "unban", Ev = "AEG-RV00" + i.ToString(CultureInfo.InvariantCulture), Name = "r" + i.ToString(CultureInfo.InvariantCulture), Result = "done.local" });
            int n;
            string seenLast = Audit.Tail(out n);
            Check("chain.seen-value", n == 4 && Audit.ValueAfter(Audit.ReadLines(), 4) == seenLast && Audit.Verify(n, seenLast).Ok, null);
            string orig = File.ReadAllText(App.AuditFile), origHead = File.ReadAllText(App.AuditHead);
            // (a) line 2 edited and the whole chain and head computed again: the chain alone passes, the seen mark does not
            var re = Audit.ReadLines();
            re[1] = re[1].Replace("name=r1", "name=rX");
            Rechain(re, 0);
            Check("chain.rebuilt-passes-alone", Audit.Verify(0).Ok, Audit.Verify(0).Kind);
            var c = Audit.Verify(n, seenLast);
            Check("chain.rebuilt-caught-by-seen-mark", !c.Ok && c.Kind == "seen" && c.At == 4 && Audit.Explain(c, 0).IndexOf("4 行目", StringComparison.Ordinal) >= 0, c.Kind + " " + c.At);
            // a rebuilt chain made longer (a line added after the edit) is caught the same way
            re.Add("2026-09-22T12:00:00Z\tunlock\tev=\tname=\trule=\treason=\tby=\tact=\tresult=as.owner\tuser=x\tmachine=y\tmode=owner\tmethod=key\tkeyid=\tcommit=");
            Rechain(re, 0);
            c = Audit.Verify(n, seenLast);
            Check("chain.rebuilt-longer-caught", !c.Ok && c.Kind == "seen", c.Kind);
            // (b) every prev= stripped and audit.head deleted: no hashing needed, and caught by the seen mark
            File.WriteAllText(App.AuditFile, orig, new UTF8Encoding(false));
            File.WriteAllText(App.AuditHead, origHead, new UTF8Encoding(false));
            var st = Audit.ReadLines();
            for (int i = 0; i < st.Count; i++) { int t = st[i].LastIndexOf("\t" + Audit.PrevKey, StringComparison.Ordinal); if (t >= 0) st[i] = st[i].Substring(0, t); }
            WriteLines(App.AuditFile, st);
            File.Delete(App.AuditHead);
            c = Audit.Verify(n, seenLast);
            Check("chain.stripped-caught-by-seen-mark", !c.Ok && c.Kind == "seen", c.Kind);
            // stripped with the head left in place: caught by the head alone
            File.WriteAllText(App.AuditHead, origHead, new UTF8Encoding(false));
            c = Audit.Verify(0);
            Check("chain.stripped-head-kept", !c.Ok && c.Kind == "head", c.Kind);
            // (c) one line appended with prev= copied from audit.head's last= (no hashing): taken, but reported
            File.WriteAllText(App.AuditFile, orig, new UTF8Encoding(false));
            File.WriteAllText(App.AuditHead, origHead, new UTF8Encoding(false));
            var h = Audit.ReadHead();
            File.AppendAllText(App.AuditFile, "2026-09-22T13:00:00Z\tunban\tev=AEG-FORGE\tname=forged\trule=\treason=\tby=\tact=\tresult=done.local\tuser=x\tmachine=y\tmode=owner\tmethod=key\tkeyid=\tcommit=\t" + Audit.PrevKey + h.Last + "\r\n", new UTF8Encoding(false));
            c = Audit.Verify(n, seenLast);
            Check("chain.appended-line-reported", c.Ok && c.Added == 1 && Audit.ReadHead().Count == 5, c.Kind + " " + c.Added);
            var stA = new Step("audit", null);
            var sn = new Snapshot();
            File.WriteAllText(App.AuditFile, orig + "2026-09-22T13:00:00Z\tunban\tev=AEG-FORGE\tname=forged\trule=\treason=\tby=\tact=\tresult=done.local\tuser=x\tmachine=y\tmode=owner\tmethod=key\tkeyid=\tcommit=\t" + Audit.PrevKey + h.Last + "\r\n", new UTF8Encoding(false));
            File.WriteAllText(App.AuditHead, origHead, new UTF8Encoding(false));
            Loader.AuditStep(sn, stA);
            Check("chain.appended-line-in-scan-and-notes", stA.State == 3 && sn.Notes.Count == 1 && sn.Notes[0].StartsWith("au.added|", StringComparison.Ordinal), stA.State + " " + stA.Detail);
            // an older build's log (no chained line) without a head: adopted, then an edit of it shows
            Fresh("chain3");
            File.WriteAllText(App.AuditFile, "2026-09-21T10:00:00Z\tshare\tev=AEG-OLD01\tname=old\trule=harass\treason=\tby=\tact=a1\tresult=signed 3\r\n2026-09-21T11:00:00Z\tpublish\tev=\tname=\trule=\treason=\tby=\tact=a1\tresult=pushed 3 1a2b3c4d\r\n", new UTF8Encoding(false));
            c = Audit.Verify(0);
            Check("chain.legacy-adopted", c.Ok && File.Exists(App.AuditHead) && Audit.ReadHead().Count == 2 && Audit.Verify(0).Ok, c.Kind);
            File.WriteAllText(App.AuditFile, File.ReadAllText(App.AuditFile).Replace("name=old", "name=new"), new UTF8Encoding(false));
            c = Audit.Verify(0);
            Check("chain.legacy-edited-after-adoption", !c.Ok && c.Kind == "head", c.Kind);
        }

        /// <summary>「前回からの操作」: the lines after this user's close mark (item 3).</summary>
        static void SinceTests()
        {
            Fresh("since");
            for (int i = 0; i < 3; i++) Audit.Append(new AuditRec { Action = "unban", Ev = "AEG-SNC0" + i.ToString(CultureInfo.InvariantCulture), Name = "s" + i.ToString(CultureInfo.InvariantCulture), Result = "done.local" });
            int n;
            string lastHash = Audit.Tail(out n);
            SeenMarks.Put(n, lastHash);
            Audit.Append(new AuditRec { Action = "share", Ev = "AEG-SNC09", Name = "later", Result = "signed 5", User = "other-admin", Machine = "PC2", Mode = "admin", Method = "code" });
            int c;
            string l;
            Check("since.mark", SeenMarks.Get(out c, out l) && c == 3 && l == lastHash, c.ToString(CultureInfo.InvariantCulture));
            var since = Audit.Since(c);
            Check("since.lines-after-close", since.Count == 1 && since[0].Name == "later" && since[0].User == "other-admin" && since[0].Machine == "PC2" && since[0].Method == "code", since.Count.ToString(CultureInfo.InvariantCulture));
            string shown = SinceDialog.Line(since[0]);
            Check("since.line-shows-who-and-unverified", shown.IndexOf("other-admin", StringComparison.Ordinal) >= 0 && shown.IndexOf("PC2", StringComparison.Ordinal) >= 0 && shown.IndexOf(S.Get("au.unverified"), StringComparison.Ordinal) >= 0, shown);
            File.AppendAllText(App.SeenFile, "someone-else/0000000000000000@PC9/0000000000000000\t1\tx\t2026-09-22T00:00:00Z\r\n", new UTF8Encoding(false));
            SeenMarks.Put(4, "y");
            Check("since.per-user-and-pc", SeenMarks.Get(out c, out l) && c == 4 && File.ReadAllText(App.SeenFile).IndexOf("someone-else", StringComparison.Ordinal) >= 0, null);
        }

        static JObj BanEntry(string key, string name, string source, string by, bool active, string since, string expires, string ev, string lastEvent, string lastDetail)
        {
            var e = new JObj();
            e.Set("hash", Hashes.HashOf("selftest-fc-" + key)); e.Set("puidHash", Hashes.HashOf("selftest-puid-" + key)); e.Set("name", name);
            e.Set("count", JNum.Of(1)); e.Set("level", JNum.Of(1)); e.Set("days", JNum.Of(30)); e.Set("since", since); e.Set("expires", expires);
            e.Set("rule", "KillRole"); e.Set("source", source); e.Set("evidence", ev); e.Set("by", by);
            e.Set("firstSeen", since); e.Set("lastSeen", since); e.Set("reported", false); e.Set("reportedAt", null);
            e.Set("active", active); e.Set("unbannedAt", null); e.Set("unbanBy", "");
            var h = new List<object>();
            var x = new JObj(); x.Set("at", since); x.Set("event", lastEvent); x.Set("detail", lastDetail); h.Add(x);
            e.Set("history", h);
            return e;
        }

        static JObj Store(params JObj[] entries)
        {
            var s = new JObj();
            s.Set("format", "PocketRoles.AegisBans"); s.Set("version", JNum.Of(1)); s.Set("salt", Hashes.Salt); s.Set("updated", "2026-09-22T00:00:00Z");
            var b = new List<object>();
            foreach (var e in entries) b.Add(e);
            s.Set("bans", b); s.Set("reports", new List<object>());
            return s;
        }

        static JObj EntryOf(JObj store, string name) { foreach (var x in store.Arr("bans")) { var e = x as JObj; if (e != null && e.Str("name") == name) return e; } return null; }

        /// <summary>"アプリの外で変わった BAN" (item 3): the mod's changes and direct edits are told apart; this console's own writes are not reported.</summary>
        static void OutsideTests()
        {
            Fresh("outside");
            App.GameDir = Path.Combine(root, "game-outside");
            Directory.CreateDirectory(Path.Combine(App.GameDir, "BepInEx", "PocketRoles"));
            var store = Store(
                BanEntry("A", "Aki", "auto", "Aegis", true, "2026-09-20T00:00:00Z", "2026-10-20T00:00:00Z", "AEG-OUT0A", "ban", "auto KillRole 30 d AEG-OUT0A"),
                BanEntry("B", "Ben", "manual", "console (BAN 管理)", true, "2026-09-20T00:00:00Z", "2026-10-20T00:00:00Z", "AEG-OUT0B", "ban", "manual harass 30 d AEG-OUT0B (console)"),
                BanEntry("E", "Emi", "manual", "host", true, "2026-09-20T00:00:00Z", "2026-10-20T00:00:00Z", "AEG-OUT0E", "ban", "manual manual 30 d AEG-OUT0E"));
            File.WriteAllText(App.BansPath, Json.Write(store), new UTF8Encoding(false));
            bool first;
            var ch = BanSnap.Observe(App.BansPath, out first);
            Check("outside.first-run-snapshot-only", first && ch.Count == 0 && File.Exists(App.SnapFile), null);
            string snapText = File.ReadAllText(App.SnapFile);
            Check("outside.snapshot-has-no-identity-hash", snapText.IndexOf(Hashes.HashOf("selftest-fc-A"), StringComparison.Ordinal) < 0 && !HexShape.IsMatch(snapText), null);
            // the mod: a new ban (C) and a lift (A, "no longer on the shared list"); someone: B's end edited by hand, E removed
            var a = EntryOf(store, "Aki");
            a.Set("active", false); a.Set("unbannedAt", "2026-09-22T01:00:00Z"); a.Set("unbanBy", "shared list");
            var ah = a.Arr("history"); var ax = new JObj(); ax.Set("at", "2026-09-22T01:00:00Z"); ax.Set("event", "unban"); ax.Set("detail", "no longer on the shared ban list (definitions v3)"); ah.Add(ax);
            var b = EntryOf(store, "Ben");
            b.Set("expires", "2099-01-01T00:00:00Z");
            b.Set("lastSeen", "2026-09-22T02:00:00Z");   // (the mod's everyday field: not compared)
            store.Arr("bans").Add(BanEntry("C", "Chika", "auto", "Aegis", true, "2026-09-22T03:00:00Z", "2026-10-22T03:00:00Z", "AEG-OUT0C", "ban", "auto TaskImpostor 30 d AEG-OUT0C"));
            store.Arr("bans").Remove(EntryOf(store, "Emi"));
            File.WriteAllText(App.BansPath, Json.Write(store), new UTF8Encoding(false));
            ch = BanSnap.Observe(App.BansPath, out first);
            Func<string, BanSnap.Change> of = n => ch.Find(x => x.Name == n);
            Check("outside.four-changes", !first && ch.Count == 4, ch.Count.ToString(CultureInfo.InvariantCulture));
            Check("outside.mod-ban-added", of("Chika") != null && of("Chika").Kind == "add" && of("Chika").Mod, null);
            Check("outside.mod-lift", of("Aki") != null && of("Aki").Kind == "change" && of("Aki").Mod, null);
            Check("outside.direct-edit", of("Ben") != null && of("Ben").Kind == "change" && !of("Ben").Mod && of("Ben").Diffs.Count == 1 && of("Ben").Diffs[0].StartsWith("expires:", StringComparison.Ordinal), of("Ben") != null ? string.Join(" | ", of("Ben").Diffs.ToArray()) : "none");
            Check("outside.removed", of("Emi") != null && of("Emi").Kind == "remove" && !of("Emi").Mod && of("Emi").Ev == "AEG-OUT0E", null);
            var obs = Audit.ReadAll().FindAll(x => x.Action.StartsWith("observed.", StringComparison.Ordinal));
            Check("outside.audit-lines", obs.Count == 4 && obs.TrueForAll(x => x.Method == "observed" && x.Mode == "-" && (x.Result == "mod" || x.Result == "outside")), obs.Count.ToString(CultureInfo.InvariantCulture));
            string file = File.ReadAllText(App.AuditFile);
            Check("outside.audit-no-identity", !FcShape.IsMatch(file) && !HexShape.IsMatch(file), null);
            Check("outside.second-look-quiet", BanSnap.Observe(App.BansPath, out first).Count == 0, null);
            Check("outside.field-names-in-3-languages", BanSnap.DiffText("expires: a → b", 0) == "期限（expires）: a → b" && BanSnap.DiffText("unbanBy: \"\" → x", 2) == "lifted by (unbanBy): \"\" → x"
                && BanSnap.DiffText("x: 1", 1) == "x: 1" && BanSnap.DiffsText("count: 1 → 2; level: 1 → 2", 0) == "違反の回数（count）: 1 → 2、段階（level）: 1 → 2" && Audit.ResultText("folder.both", 0) == "リポジトリとゲームのフォルダを変えた", null);
            // this console's own change is not "outside"; the mod's change made meanwhile still is
            store = Json.Parse(Json.ReadText(App.BansPath)) as JObj;
            var c = EntryOf(store, "Chika");
            var aki = EntryOf(store, "Aki");
            aki.Set("active", true); aki.Set("since", "2026-09-22T04:00:00Z"); aki.Set("count", JNum.Of(2)); aki.Set("unbanBy", "");
            File.WriteAllText(App.BansPath, Json.Write(store), new UTF8Encoding(false));   // the mod bans Aki again
            Session.Unlock("admin", "hello");
            try
            {
                var act = Journal.NewAction("unban", new List<string> { c.Str("hash") }, "Chika");
                var nw = new JObj(); nw.Set("active", false); nw.Set("unbannedAt", "@now"); nw.Set("unbanBy", Ops.ConsoleBy);
                act.Set("localNew", nw);
                var hl = new JObj(); hl.Set("event", "unban"); hl.Set("detail", Ops.ConsoleBy);
                act.Set("localHist", hl);
                var st = new Step("local", null);
                Check("outside.console-write", Ops.RunLocal(act, st), st.Detail);
            }
            finally { Session.Lock(); }
            ch = BanSnap.Observe(App.BansPath, out first);
            Check("outside.own-write-not-reported-mod-still-seen", ch.Count == 1 && ch[0].Name == "Aki" && ch[0].Mod, ch.Count.ToString(CultureInfo.InvariantCulture) + (ch.Count > 0 ? " " + ch[0].Name : ""));
            // a direct edit that looks like the console's (by = console) is outside, not the mod
            store = Json.Parse(Json.ReadText(App.BansPath)) as JObj;
            store.Arr("bans").Add(BanEntry("F", "Fumi", "manual", "console (BAN 管理)", true, "2026-09-22T05:00:00Z", null, "AEG-OUT0F", "ban", "manual harass permanent AEG-OUT0F (console)"));
            File.WriteAllText(App.BansPath, Json.Write(store), new UTF8Encoding(false));
            ch = BanSnap.Observe(App.BansPath, out first);
            Check("outside.console-looking-add-is-outside", ch.Count == 1 && ch[0].Kind == "add" && !ch[0].Mod, null);
            // v0.5.5 review: the snapshot deleted after the console has run (audit lines, seen marks): a warning and an audit
            // line, not a silent first run; a real first run (nothing before) stays quiet
            Check("outside.ran-before", BanSnap.RanBefore(), null);
            File.Delete(App.SnapFile);
            bool missing;
            ch = BanSnap.Observe(App.BansPath, BanSnap.RanBefore(), out first, out missing);
            var lastLine = Audit.ReadAll()[Audit.ReadAll().Count - 1];
            Check("outside.snapshot-deleted-reported", missing && first && ch.Count == 0 && File.Exists(App.SnapFile) && lastLine.Action == "observed.snapshot-missing" && lastLine.Result == "outside" && S.Has("ak.observed.snapshot-missing"), lastLine.Action);
            var stO = new Step("outside", null);
            var snO = new Snapshot();
            File.Delete(App.SnapFile);
            Loader.Outside(snO, stO);
            Check("outside.snapshot-deleted-scan-warning", stO.State == 3 && stO.Detail == S.Get("ld.outside.missing") && snO.Notes.Contains("sn.snapmissing"), stO.Detail);
