                && ja.IndexOf("ほかのホストに連絡していただく必要はありません", StringComparison.Ordinal) > 0 && ja.IndexOf("そのホストにしか", StringComparison.Ordinal) < 0 && ja.IndexOf("次にゲームを起動", StringComparison.Ordinal) < 0, ja);
