                for (int i = 0; i < 3; i++)
                {
                    string t = S.In(i, "rc." + cat);
                    if (t.IndexOf('(') >= 0 && i == 2) nested = true;
                    if (S.In(i, "rt.reject", "(x)", t).IndexOf("（" + t + "）", StringComparison.Ordinal) >= 0 || S.In(i, "rt.reject", "(x)", t).IndexOf("(" + t + ")", StringComparison.Ordinal) >= 0) nested = true;
                }
            Check("reply.reject.rule-not-in-nested-brackets", !nested, null);
