            string endedJa = Replies.Body(0, "reject", ended), endedEn = Replies.Body(2, "reject", ended);
            Check("reply.reject.ended", endedJa.IndexOf("すでに自動で解除されています", StringComparison.Ordinal) > 0 && endedJa.IndexOf("期限より早い", StringComparison.Ordinal) < 0 && endedJa.IndexOf("自動で解除されます", StringComparison.Ordinal) < 0
                && endedEn.IndexOf("has already been lifted", StringComparison.Ordinal) > 0 && endedEn.IndexOf("not lifted early", StringComparison.Ordinal) < 0, endedEn);
