            Check("evidence.erasecode", evCode != null && evCode.EraseCode == "BDZNXHNJJSXDGZDG" && EvInfo.ShowCode(evCode.EraseCode) == "BDZN XHNJ JSXD GZDG" && EvInfo.CodeOf("BDZN XHNJ JSXD GZD") == "", evCode == null ? "null" : evCode.EraseCode);
            Check("policy.unban.code-from-record", S.In(0, "policy").IndexOf("記録（証拠）の「コード（/cmd id）」の欄から取ります", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("from the \"Code (/cmd id)\" field of the ban record", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("“代码（/cmd id）”一栏中取", StringComparison.Ordinal) > 0
                && S.In(0, "rt.info").IndexOf("分からなければ書かなくて大丈夫です", StringComparison.Ordinal) > 0, null);
            // v0.5.5 owner 2026-09-22 「他の部屋って言うけどおとなしくやらなくない？」: an appeal works without the code, and nobody is
