                && S.In(2, "rt.info").IndexOf("answers it too, before it removes you", StringComparison.Ordinal) > 0
                && S.In(0, "rt.info").IndexOf("登録ありの部屋で打って", StringComparison.Ordinal) < 0 && S.In(1, "rt.info").IndexOf("请在已注册的房间输入", StringComparison.Ordinal) < 0
