            Check("policy.unban.author-only", routeGone
                && S.In(0, "policy").IndexOf("解除を決めて [unban] に載せるのは作者だけです", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("記録が手元に届くまでは載せません", StringComparison.Ordinal) > 0
                && S.In(0, "policy").IndexOf("管理人がほかの PC で確かめた証拠 ID やコードだけでは載せません", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("直近 90 日", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("ひとり分の証拠", StringComparison.Ordinal) > 0
                && S.In(1, "policy").IndexOf("决定解除并写入 [unban] 的只有作者", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("仅凭管理员在其他电脑上核对过的证据 ID 或代码，不写入", StringComparison.Ordinal) > 0
                && S.In(1, "policy").IndexOf("只包含最近 90 天的证据", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("单人证据", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("Only the author decides to lift a ban and lists it on [unban]", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("An evidence id or code an admin checked on another PC is not enough", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("only the last 90 days of evidence", StringComparison.Ordinal) > 0 && S.In(2, "policy").IndexOf("One player's evidence", StringComparison.Ordinal) > 0, null);
            // review 2026-09-23: the identity bullet and the "no code" bullet name the one-player zip (a report zip is not the
            // only route any more), say that identity is the code in the record or the host's friend-code search, and that
            // neither proves who sent the appeal (3 languages)
            Check("policy.identity.one-player",
                S.In(0, "policy").IndexOf("「ひとり分の証拠」の zip から取り込んだ記録には、フレンドコードのハッシュがありません", StringComparison.Ordinal) > 0
                && S.In(0, "policy").IndexOf("証明にはなりません", StringComparison.Ordinal) > 0
                && S.In(0, "policy").IndexOf("そのホストに頼んで報告 zip を作者に送ってもらいます", StringComparison.Ordinal) < 0
                && S.In(1, "policy").IndexOf("“单人证据”zip 导入的记录没有好友编号的哈希", StringComparison.Ordinal) > 0
                && S.In(1, "policy").IndexOf("都不能证明发来的人就是本人", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("or a one-player evidence zip hold no friend-code hash", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("Neither proves that the sender is that player", StringComparison.Ordinal) > 0, null);
            // review 2026-09-23: the author lifts only from records in the author's hands, so an admin's unban proposal says to
            // mail that player's zip (the launcher's one-player evidence, +host) when the record is on that PC, and that a
            // report zip holds only 90 days of evidence (3 languages; owner 2026-09-23 「A」「B」)
            bool unbanSendOk = true;
            foreach (var arText in adminRoute) for (int arLang = 0; arLang < 3; arLang++) if (S.In(arLang, "pp.send.unban").IndexOf(arText, StringComparison.Ordinal) >= 0) unbanSendOk = false;
            for (int arLang = 0; arLang < 3; arLang++)
                if (S.In(arLang, "pp.send.unban").IndexOf("pocketroles.report+host@gmail.com", StringComparison.Ordinal) < 0 || S.In(arLang, "pp.send.unban").IndexOf("90", StringComparison.Ordinal) < 0
                    || S.In(arLang, "pp.send.unban").IndexOf(new[] { "ひとり分の証拠", "单人证据", "One player's evidence" }[arLang], StringComparison.Ordinal) < 0) unbanSendOk = false;
            Check("strings.unban-proposal-zip", unbanSendOk && S.In(0, "pp.send.unban").IndexOf("作者は手元に届いた記録でだけ解除を決めます", StringComparison.Ordinal) > 0
                && S.In(1, "pp.send.unban").IndexOf("作者只根据自己手上的记录决定是否解除", StringComparison.Ordinal) > 0
                && S.In(2, "pp.send.unban").IndexOf("The author decides only from records in the author's hands", StringComparison.Ordinal) > 0, null);
            Check("reply.info.host-name", S.In(0, "rt.info").IndexOf("ホストの名前", StringComparison.Ordinal) > 0 && S.In(1, "rt.info").IndexOf("房主的名字", StringComparison.Ordinal) > 0
                && S.In(2, "rt.info").IndexOf("the host's name", StringComparison.Ordinal) > 0, null);
            // the appeal policy tells the team how to lift everywhere ([unban]) in 3 languages
            Check("policy.unban", S.In(0, "policy").IndexOf("[unban]", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("[unban]", StringComparison.Ordinal) > 0 && S.In(2, "policy").IndexOf("[unban]", StringComparison.Ordinal) > 0
                && S.In(0, "policy").IndexOf("AEG-", StringComparison.Ordinal) > 0 && S.In(2, "policy").IndexOf("tie to the player", StringComparison.Ordinal) > 0, null);
            // owner decision 2026-09-22: for 30 days no host's PC bans the player automatically (removal only), the PC with the
