                && S.In(0, "policy").IndexOf("そのルールでは部屋から出すこともしません", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("その人が何をしても延びません", StringComparison.Ordinal) > 0
                && S.In(0, "policy").IndexOf("30 日の間そのルールでは自動で退出・BAN させません", StringComparison.Ordinal) < 0
                && S.In(1, "policy").IndexOf("Aegis 都不会自动封禁此人", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("连移出也不会", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("Aegis bans that player automatically on no host's PC", StringComparison.Ordinal) > 0 && S.In(2, "policy").IndexOf("does not even remove them", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("the paused rule", StringComparison.Ordinal) < 0, null);
