                && S.In(0, "policy").IndexOf("届いた時に解けて回数も戻ります", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("ほかの人にはふつうの退出に見えます", StringComparison.Ordinal) < 0
                && S.In(0, "policy").IndexOf("30 日の間だったことが残ります。載せる前に本人に伝えて", StringComparison.Ordinal) > 0
                && S.In(1, "policy").IndexOf("在其他玩家看来只是普通的移出", StringComparison.Ordinal) > 0 && S.In(1, "policy").IndexOf("名单传到时会解除", StringComparison.Ordinal) > 0
                && S.In(1, "policy").IndexOf("会留下这是在 30 天内。写入前先告诉本人", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("to other players it looks like any removal, while the host's line lacks", StringComparison.Ordinal) > 0
                && S.In(2, "policy").IndexOf("lifted when the list arrives", StringComparison.Ordinal) > 0 && S.In(2, "policy").IndexOf("show it was within the 30 days. Tell the player", StringComparison.Ordinal) > 0, null);
            string zh = Replies.Body(1, "info", f);
            Check("reply.zh.info", zh.StartsWith("もみじ，您好！\n\n感谢您联系 PocketRoles。\n我是 PocketRoles Aegis 团队的かえで。", StringComparison.Ordinal) && zh.IndexOf("③ 好友编号", StringComparison.Ordinal) > 0 && zh.EndsWith("かえで\nPocketRoles Aegis 团队", StringComparison.Ordinal), zh);
            string info = Replies.Body(0, "info", f);
            Check("reply.ja.info.whole-lines", info.IndexOf("あらかじめご了承ください。", StringComparison.Ordinal) > 0 && info.IndexOf("① BAN されたときの名前", StringComparison.Ordinal) > 0, info);
