            var alLines = new List<string>(); alLines.Add(AegisHash.NgAllowLine(tsalt, "ほげらむ"));
            var ngh = NgNames.FromLines(ngLines, alLines, new[] { "ばか", "!ばかうけ" }, tsalt);
            bool h2;
            Check("reply.to.ng-hashed", Replies.Addressee("もみじ", ngh, out h2) == "もみじ" && !h2
                && Replies.Addressee("ほげらほげら", ngh, out h2) == "" && h2
                && Replies.Addressee("ＺＯＲＰer", ngh, out h2) == "" && h2
                && Replies.Addressee("ピヨ太郎", ngh, out h2) == "" && h2
                && Replies.Addressee("ばかうけ", ngh, out h2) == "ばかうけ" && !h2
                && Replies.Addressee("ほげらむくん", ngh, out h2) == "ほげらむくん", null);
            Check("reply.to.empty", Replies.Addressee("  ", ng, out ngHit) == "" && !ngHit && Replies.Addressee(null, null, out ngHit) == "" && !ngHit, null);
            string thanksJa = S.In(0, "rt.thanks") + "\n";
            bool thanksFirst = true;
            foreach (var k in Replies.Kinds)
                foreach (var to in new[] { "", "  ", null })
                    if (!Replies.Body(0, k, new ReplyFields { To = to }).StartsWith(thanksJa, StringComparison.Ordinal)) thanksFirst = false;
            Check("reply.greeting.empty-ja-starts-with-thanks", thanksFirst && Replies.Body(0, "info", new ReplyFields()).StartsWith("このたびは PocketRoles へお問い合わせいただき、ありがとうございます。\nPocketRoles Aegis チームです。\n\n", StringComparison.Ordinal)
                && Replies.Greeting(0, "") == "", Replies.Body(0, "info", new ReplyFields()));
            Check("reply.greeting.empty-zh-en", Replies.Body(1, "info", new ReplyFields()).StartsWith("您好！\n\n感谢您联系 PocketRoles。", StringComparison.Ordinal) && Replies.Body(2, "info", new ReplyFields()).StartsWith("Hi there,\n\nThank you for contacting PocketRoles.", StringComparison.Ordinal), null);
            Check("reply.greeting.typed-name", Replies.Body(0, "accept", new ReplyFields { To = "さくら" }).StartsWith("さくら さま\n\n" + thanksJa, StringComparison.Ordinal)
                && Replies.Body(1, "reject", new ReplyFields { To = "さくら" }).StartsWith("さくら，您好！\n\n", StringComparison.Ordinal) && Replies.Body(2, "info", new ReplyFields { To = " Sakura " }).StartsWith("Hi Sakura,\n\n", StringComparison.Ordinal), null);
            Check("reply.greeting.ng-name-no-addressee", Replies.Body(0, "reject", new ReplyFields { To = Replies.Addressee("ほげらほげら", ng, out ngHit) }).StartsWith(thanksJa, StringComparison.Ordinal) && ngHit
                && Replies.Body(2, "reject", new ReplyFields { To = Replies.Addressee("ＺＯＲＰer", ng, out ngHit) }).StartsWith("Hi there,\n\n", StringComparison.Ordinal), null);
            string inquirer = "お問い合わせいただいた" + "方";   // (split: this file holds the old words nowhere else)
            bool inquirerLeft = false;
            for (int i = 0; i < 3; i++) foreach (var k in Replies.Kinds) if (Replies.Body(i, k, new ReplyFields()).IndexOf(inquirer, StringComparison.Ordinal) >= 0) inquirerLeft = true;
            Check("reply.greeting.no-inquirer-words", !inquirerLeft && !S.Has("rt.anon"), null);
            Check("reply.subject", Replies.Subject(0, "accept", "AEG-7F3K2") == "【PocketRoles Aegis】BAN を解除しました（AEG-7F3K2）" && Replies.Subject(2, "reject", "AEG-7F3K2") == "[PocketRoles Aegis] The result of your appeal (AEG-7F3K2)"
                && Replies.Subject(1, "info", "") == "【PocketRoles Aegis】请提供核查所需的信息", Replies.Subject(0, "accept", "AEG-7F3K2"));
            ReplyIdTests();
            Check("reply.category", Replies.Category("KillRole") == "cheat" && Replies.Category("killrole") == "cheat" && Replies.Category("NgWord") == "chat" && Replies.Category("chat") == "chat"
                && Replies.Category("ColorSpam") == "harass" && Replies.Category("harass") == "harass" && Replies.Category("name") == "name" && Replies.Category("manual") == "other"
                && Replies.Category("") == "other" && Replies.Category("xyz") == "other" && Replies.Category("cheat") == "cheat", null);
            Check("reply.appeals-go-to-help", Replies.Body(2, "accept", f).IndexOf("pocketroles.report+help@gmail.com", StringComparison.Ordinal) > 0, null);
            var bad = S.BadEntries();
            Check("strings.every-key-in-3-languages", bad.Count == 0, string.Join(", ", bad.ToArray()));
            Check("strings.hosts-mail-to-host", S.In(0, "pp.send.share").IndexOf("pocketroles.report+host@gmail.com", StringComparison.Ordinal) > 0 && S.In(1, "pp.send.share").IndexOf("+host@", StringComparison.Ordinal) > 0
                && S.In(2, "pp.send.share").IndexOf("+host@", StringComparison.Ordinal) > 0 && S.In(0, "policy").IndexOf("+help@", StringComparison.Ordinal) > 0, null);
        }

        /// <summary>
        /// v0.5.5 (2026-09-22 「自動でばんidを文章に足してよ」) the ban's number every kind of row gives the reply
        /// (<see cref="Replies.FieldsOf"/>), and that no mail ever holds a dash, a sample, a friend code's hash or a whole hash.
        /// </summary>
        static void ReplyIdTests()
        {
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            string fcH = Hashes.HashOf("selftest-reply-fc"), puidH = Hashes.HashOf("selftest-reply-puid"), ln8 = puidH.Substring(0, 8);
            var line = new SharedLine { Hash = puidH, Level = 1, Expires = new DateTime(2026, 10, 20, 0, 0, 0, DateTimeKind.Utc), Reason = "harass" };
            // 1. this PC's ban with its evidence: its evidence ID and start
            var own = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Name = "もみじ", Rule = "KillRole", Source = "auto", Evidence = "AEG-7F3K2", Active = true,
                Since = new DateTime(2026, 9, 20, 3, 0, 0, DateTimeKind.Utc), Expires = new DateTime(2026, 10, 20, 3, 0, 0, DateTimeKind.Utc) };
            var fOwn = Replies.FieldsOf(own, null, now);
            string ownJa = Replies.Body(0, "accept", fOwn);
            Check("reply.id.from-evidence", fOwn.Id == "AEG-7F3K2" && fOwn.IdFrom == "entry" && fOwn.Since == own.Since && fOwn.End == own.Expires && fOwn.Rule == "KillRole"
                && ownJa.IndexOf("BAN の記録（AEG-7F3K2、" + Fmt.Date(own.Since) + "）を確認しました", StringComparison.Ordinal) > 0
                && Replies.Subject(0, "reject", fOwn) == "【PocketRoles Aegis】異議申し立ての結果について（AEG-7F3K2）"
                && Replies.Body(2, "reject", fOwn).IndexOf("the ban record (AEG-7F3K2, " + Fmt.Date(own.Since) + ").", StringComparison.Ordinal) > 0
                && Replies.Body(1, "accept", fOwn).IndexOf("限制进入的记录（AEG-7F3K2，" + Fmt.Date(own.Since) + "）。", StringComparison.Ordinal) > 0, ownJa);
            // the same ban also on the shared list: still its own evidence ID
            own.Effective = line; own.Committed = line;
            Check("reply.id.local-and-shared-keeps-evidence", Replies.FieldsOf(own, null, now).Id == "AEG-7F3K2", null);
            // 2. a shared ban seen here (the mod's mirror entry has no evidence) that this console listed: the evidence ID it was listed with, the day it was listed
            var mirror = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Rule = "harass", Source = "shared", Active = true, Since = new DateTime(2026, 9, 21, 0, 0, 0, DateTimeKind.Utc), Effective = line, Committed = line };
            var share = Journal.NewAction("share", new List<string> { fcH, puidH }, "もみじ");
            Ops.SetDesc(share, puidH, 1, line.Expires, "harass", false, "AEG-SHR01", "", "");
            var listedAt = new DateTime(2026, 9, 19, 9, 0, 0, DateTimeKind.Utc);
            share.Set("at", Json.Time(listedAt));
            share.Set("state", "pushed");
            var journal = new List<JObj> { share };
            var fMirror = Replies.FieldsOf(mirror, journal, now);
            Check("reply.id.shared-seen-here-from-history", fMirror.Id == "AEG-SHR01" && fMirror.IdFrom == "listed" && fMirror.Since == listedAt && fMirror.Rule == "harass" && fMirror.End == line.EndsAt && fMirror.Shared,
                fMirror.Id + " " + fMirror.IdFrom + " " + Fmt.Date(fMirror.Since));
            // a discarded (never published) action does not count: the line's number, no date (the mirror's start is when it was first seen here)
            share.Set("state", "discarded");
            var fDiscarded = Replies.FieldsOf(mirror, journal, now);
            Check("reply.id.discarded-action-ignored", fDiscarded.Id == "" && fDiscarded.Line == ln8 && fDiscarded.IdFrom == "line" && fDiscarded.Since == null, fDiscarded.Id + " " + fDiscarded.Line);
            share.Set("state", "pushed");
            // 3. a row only on the shared list, linked to the record of the line's PUID (this PC's or an imported one)
            var evL = new EvInfo { Id = "AEG-LNK02", Hash = fcH, PuidHash = puidH, Action = "ban", Time = new DateTime(2026, 9, 18, 0, 0, 0, DateTimeKind.Utc) };
            var onlyLinked = new Row { Key = puidH, Hash = fcH, PuidHash = puidH, Source = "shared", Rule = "harass", Effective = line, Committed = line, Ev = evL };
            var fLinked = Replies.FieldsOf(onlyLinked, new List<JObj>(), now);
            Check("reply.id.shared-only-linked-evidence", fLinked.Id == "AEG-LNK02" && fLinked.IdFrom == "linked" && fLinked.Since == evL.Time, fLinked.Id);
            // ... this console's listing wins over a guessed record
            Check("reply.id.history-before-linked", Replies.FieldsOf(onlyLinked, journal, now).Id == "AEG-SHR01", null);
            // 4. only on the shared list, no evidence anywhere: the line's number (first 8 hex digits, public in the definitions file)
            var onlyLine = new Row { Key = puidH, Hash = puidH, Source = "shared", Rule = "harass", Effective = line, Committed = line };
            var fLine = Replies.FieldsOf(onlyLine, null, now);
            string lineJa = Replies.Body(0, "accept", fLine);
            Check("reply.id.shared-line-number", fLine.Id == "" && fLine.Line == ln8 && fLine.IdFrom == "line" && fLine.Since == null
                && lineJa.IndexOf("BAN の記録（共有 BAN " + ln8 + "）を確認しました", StringComparison.Ordinal) > 0
                && Replies.Subject(0, "accept", fLine) == "【PocketRoles Aegis】BAN を解除しました（共有 BAN " + ln8 + "）"
                && Replies.Body(2, "reject", fLine).IndexOf("the ban record (shared ban " + ln8 + ").", StringComparison.Ordinal) > 0
                && Replies.Subject(1, "reject", fLine) == "【PocketRoles Aegis】关于申诉的结果（共享限制进入 " + ln8 + "）", lineJa);
            // v0.5.5 review: a shared ban is said to be one as a fact in the accepted reply (not "if it was"); this PC's own ban keeps "if it was"
            Check("reply.accept.shared-said-as-fact", fLine.Shared && lineJa.IndexOf("この BAN は共有 BAN（PocketRoles を使うすべての部屋に入れない BAN）でした。この BAN も、ほかに PocketRoles であなたに出された BAN も", StringComparison.Ordinal) > 0
                && lineJa.IndexOf("だった場合は", StringComparison.Ordinal) < 0 && Replies.Body(2, "accept", fLine).IndexOf("It was a shared ban (", StringComparison.Ordinal) > 0
                && Replies.Body(1, "accept", fLine).IndexOf("此次封禁是共享封禁", StringComparison.Ordinal) > 0
                && !fOwn.Shared && ownJa.IndexOf("だったため", StringComparison.Ordinal) < 0 && ownJa.IndexOf("PocketRoles（v0.5.5 以降）を使うすべての部屋で解けます", StringComparison.Ordinal) > 0, lineJa);
            // v0.5.5 review: "need more info" goes out before the person is confirmed: its subject never names the ban, whatever is known
            bool infoNumber = false;
            foreach (var x in new[] { fOwn, fMirror, fLinked, fLine })
                for (int i = 0; i < 3; i++)
                    if (Replies.Subject(i, "info", x) != S.In(i, "rs.info") || Replies.Subject(i, "info", Replies.IdText(i, x)) != S.In(i, "rs.info")) infoNumber = true;
            Check("reply.info-subject-never-names-the-ban", !infoNumber && Replies.Subject(0, "info", fLine) == "【PocketRoles Aegis】確認のため情報をお送りください", Replies.Subject(0, "info", fOwn));
            // a line being taken off (unpublished unban: only the repository's line is left) still has its number
            var leaving = new Row { Key = puidH, Hash = puidH, Source = "shared", Rule = "harass", Committed = line };
            Check("reply.id.line-being-lifted", Replies.FieldsOf(leaving, null, now).Line == ln8 && Replies.FieldsOf(leaving, null, now).End == line.EndsAt, null);
            // 5. a shared ban seen here whose line is gone (lifted and published): the number this console's history kept for it
            var gone = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Source = "shared", Rule = "harass", Active = true, Since = mirror.Since };
            var unban = Journal.NewAction("unban", new List<string> { fcH, puidH }, "");
            Ops.SetDesc(unban, puidH, 0, null, "", false, "", "", "");
            unban.Set("state", "pushed");
            var fGone = Replies.FieldsOf(gone, new List<JObj> { unban }, now);
            Check("reply.id.lifted-shared-from-history", fGone.Id == "" && fGone.Line == ln8 && fGone.IdFrom == "history" && fGone.Shared, fGone.Line);
            // 6. this PC's ban without evidence (an older build's, or minimised: name, rule and evidence gone): nothing a player or
            // a host could quote, so no number (the dialog says so); the date stays
            var minimised = new Row { Entry = new JObj(), Key = puidH, Hash = puidH, PuidHash = puidH, Source = "auto", Active = false,
                Since = new DateTime(2026, 7, 1, 0, 0, 0, DateTimeKind.Utc), Expires = new DateTime(2026, 7, 31, 0, 0, 0, DateTimeKind.Utc) };
            var fMin = Replies.FieldsOf(minimised, null, now);
            string minJa = Replies.Body(0, "accept", fMin);
            Check("reply.id.minimised-none", fMin.Id == "" && fMin.Line == "" && fMin.IdFrom == "" && Replies.IdText(0, fMin) == ""
                && minJa.IndexOf("BAN の記録（" + Fmt.Date(minimised.Since) + "）を確認しました", StringComparison.Ordinal) > 0
                && Replies.Subject(0, "accept", fMin) == "【PocketRoles Aegis】BAN を解除しました" && Replies.Subject(2, "info", fMin) == "[PocketRoles Aegis] We need a little more information", minJa);
            // ... a line number kept in the history is not used for this PC's own ban (it may belong to another, lifted shared ban)
            Check("reply.id.local-no-old-line", Replies.FieldsOf(minimised, new List<JObj> { unban }, now).Line == "", null);
            // ... but the evidence ID this console's own action on it kept (an unban, an undo) is
            var old = Journal.NewAction("unban", new List<string> { fcH, puidH }, "");
            Ops.SetDesc(old, "", 0, null, "", true, "AEG-OLD03", "", "");
            old.Set("state", "done");
            var fMinJ = Replies.FieldsOf(minimised, new List<JObj> { old }, now);
            Check("reply.id.minimised-from-history", fMinJ.Id == "AEG-OLD03" && fMinJ.IdFrom == "journal", fMinJ.Id);
            // v0.5.5 review 1: this PC's ban ended (AEG-OLD01 from 6/1, 30 days; kept because the player is on the shared list)
            // and the player was listed meanwhile from another host's record (AEG-NEW01): the reply tells the shared ban only,
            // its number, date, rule and end; a later period change that carries this PC's older evidence ID does not count
            var stale = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Name = "もみじ", Rule = "KillRole", Source = "auto", Evidence = "AEG-OLD01", Active = true,
                Since = new DateTime(2026, 6, 1, 0, 0, 0, DateTimeKind.Utc), Expires = new DateTime(2026, 7, 1, 0, 0, 0, DateTimeKind.Utc), Effective = line, Committed = line };
            var fromCand = Journal.NewAction("share", new List<string> { puidH }, "もみじ");
            Ops.SetDesc(fromCand, puidH, 1, line.Expires, "harass", false, "AEG-NEW01", "imp", "");
            var candAt = new DateTime(2026, 6, 15, 0, 0, 0, DateTimeKind.Utc);
            fromCand.Set("at", Json.Time(candAt));
            fromCand.Set("state", "pushed");
            var period = Journal.NewAction("period", new List<string> { fcH, puidH }, "もみじ");
            Ops.SetDesc(period, puidH, 1, line.Expires, "harass", false, "AEG-OLD01", "", "");   // (EvIdOf: this PC's older evidence)
            period.Set("state", "pushed");
            var fStale = Replies.FieldsOf(stale, new List<JObj> { fromCand, period }, now);
            string staleJa = Replies.Body(0, "reject", fStale);
            Check("reply.id.ended-local-tells-the-shared-ban", fStale.Id == "AEG-NEW01" && fStale.IdFrom == "listed" && fStale.Since == candAt && fStale.Rule == "harass" && fStale.End == line.EndsAt && fStale.Shared
                && staleJa.IndexOf("BAN の記録（AEG-NEW01、" + Fmt.Date(candAt) + "）を確認しました", StringComparison.Ordinal) > 0 && staleJa.IndexOf("「迷惑行為・嫌がらせ」", StringComparison.Ordinal) > 0
                && staleJa.IndexOf("AEG-OLD01", StringComparison.Ordinal) < 0 && staleJa.IndexOf(Fmt.Date(stale.Since), StringComparison.Ordinal) < 0, staleJa);
            // ... without this console's listing (another PC listed it): the line's number, no date (never this PC's older ban's)
            var fStaleNoJ = Replies.FieldsOf(stale, new List<JObj> { period }, now);
            Check("reply.id.ended-local-without-listing", fStaleNoJ.Id == "" && fStaleNoJ.Line == ln8 && fStaleNoJ.IdFrom == "line" && fStaleNoJ.Since == null && fStaleNoJ.Rule == "harass", fStaleNoJ.Id + " " + fStaleNoJ.Line);
            // ... while this PC's ban still counts, the reply tells that one
            var fStaleLive = Replies.FieldsOf(stale, new List<JObj> { fromCand, period }, new DateTime(2026, 6, 20, 0, 0, 0, DateTimeKind.Utc));
            Check("reply.id.live-local-tells-its-own", fStaleLive.Id == "AEG-OLD01" && fStaleLive.IdFrom == "entry" && fStaleLive.Since == stale.Since && fStaleLive.Rule == "KillRole" && fStaleLive.End == stale.Expires && !fStaleLive.Shared, fStaleLive.Id);
            // ... a listing made from another record is never this PC's own ban's number (a minimised one, a live one of an older build)
            var oldBuild = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Rule = "KillRole", Source = "auto", Active = true, Since = own.Since, Expires = own.Expires, Effective = line, Committed = line };
            var fromRow = Journal.NewAction("share", new List<string> { fcH, puidH }, "");
            Ops.SetDesc(fromRow, puidH, 1, line.Expires, "harass", false, "", "", "");   // listed from this very ban (no evidence ID: an older build's)
            fromRow.Set("state", "pushed");
            var fOldRow = Replies.FieldsOf(oldBuild, new List<JObj> { fromRow }, now);
            var fOldCand = Replies.FieldsOf(oldBuild, new List<JObj> { fromCand }, now);
            Check("reply.id.local-not-from-another-listing", Replies.FieldsOf(minimised, new List<JObj> { fromCand }, now).Id == ""
                && fOldCand.Id == "" && fOldCand.Line == "" && fOldCand.Since == oldBuild.Since
                && fOldRow.Line == ln8 && fOldRow.IdFrom == "line" && fOldRow.Since == oldBuild.Since, fOldCand.Id + " " + fOldCand.Line + " / " + fOldRow.Line);
            // v0.5.5 review 2: a row only on the list names a BAN record of its player, never a removal-only one ("kick"), an
            // imported one only when its zip's log confirms it, the newest of them; the kick's time is never the ban's date
            var kick = new EvInfo { Id = "AEG-KCK01", Hash = fcH, PuidHash = puidH, Action = "kick", Time = new DateTime(2026, 5, 5, 0, 0, 0, DateTimeKind.Utc) };
            var onlyKick = new Row { Key = puidH, Hash = fcH, PuidHash = puidH, Source = "shared", Rule = "harass", Effective = line, Committed = line, Ev = kick };
            var impNo = new EvInfo { Id = "AEG-IMP01", Imported = true, Hash = puidH, PuidHash = puidH, Action = "ban", Time = new DateTime(2026, 6, 1, 0, 0, 0, DateTimeKind.Utc), LogState = LogCheck.Mismatch };
            var impOk = new EvInfo { Id = "AEG-IMP02", Imported = true, Hash = puidH, PuidHash = puidH, Action = "ban", Time = new DateTime(2026, 5, 1, 0, 0, 0, DateTimeKind.Utc), LogState = LogCheck.Ok };
            var impNew = new EvInfo { Id = "AEG-IMP03", Imported = true, Hash = puidH, PuidHash = puidH, Action = "ban", Time = new DateTime(2026, 6, 10, 0, 0, 0, DateTimeKind.Utc), LogState = LogCheck.Ok };
            var fKick = Replies.FieldsOf(onlyKick, null, now, new List<EvInfo> { kick, impNo });
            var fImp = Replies.FieldsOf(onlyKick, null, now, new List<EvInfo> { kick, impNo, impOk });
            var fImpNew = Replies.FieldsOf(onlyKick, null, now, new List<EvInfo> { kick, impNo, impOk, impNew });
            Check("reply.id.linked-ban-records-only", fKick.Id == "" && fKick.Line == ln8 && fKick.IdFrom == "line" && fKick.Since == null
                && fImp.Id == "AEG-IMP02" && fImp.IdFrom == "linked" && fImp.Since == impOk.Time && fImpNew.Id == "AEG-IMP03" && fImpNew.Since == impNew.Time
                && Replies.Body(0, "accept", fKick).IndexOf("AEG-KCK01", StringComparison.Ordinal) < 0 && Replies.Body(0, "accept", fKick).IndexOf(Fmt.Date(kick.Time), StringComparison.Ordinal) < 0, fKick.Id + " " + fImp.Id + " " + fImpNew.Id);
            // v0.5.5 review 5: a line of the player's friend code's hash (an older build's, or written by hand) never gives its digits
            var fcLine = new SharedLine { Hash = fcH, Level = 1, Expires = line.Expires, Reason = "harass" };
            var byFc = new Row { Entry = new JObj(), Key = fcH, Hash = fcH, PuidHash = puidH, Rule = "KillRole", Source = "auto", Active = false, Since = minimised.Since, Expires = minimised.Expires, Effective = fcLine, Committed = fcLine };
            var fFc = Replies.FieldsOf(byFc, null, now);
            var onlyFc = new Row { Key = fcH, Hash = fcH, PuidHash = puidH, Source = "shared", Rule = "harass", Effective = fcLine, Committed = fcLine };
            var fOnlyFc = Replies.FieldsOf(onlyFc, null, now);
            var unbanFc = Journal.NewAction("unban", new List<string> { fcH, puidH }, "");
            Ops.SetDesc(unbanFc, fcH, 0, null, "", false, "", "", "");
            unbanFc.Set("state", "pushed");
            var fGoneFc = Replies.FieldsOf(gone, new List<JObj> { unbanFc }, now);
            Check("reply.id.no-friend-code-line-digits", fFc.Line == "" && fFc.IdFrom == "" && fFc.Rule == "harass" && fOnlyFc.Line == "" && fOnlyFc.IdFrom == "" && fGoneFc.Line == "" && fGoneFc.IdFrom == "",
                fFc.Line + " / " + fOnlyFc.Line + " / " + fGoneFc.Line);
            // v0.5.5 review 4: the number a reply names, pasted as it is into the search box, and the history's evidence IDs
            Check("reply.search.pasted-number", Replies.NumberQuery("共有 BAN " + ln8) == ln8 && Replies.NumberQuery("（共享限制进入 " + ln8 + "）") == ln8 && Replies.NumberQuery("(shared ban " + ln8.ToUpperInvariant() + ")") == ln8
                && Replies.NumberQuery("Shared Ban " + ln8) == ln8 && Replies.NumberQuery("（共享封禁 " + ln8 + "）") == ln8 && Replies.NumberQuery("（AEG-7F3K2）") == "AEG-7F3K2" && Replies.NumberQuery("もみじ") == "もみじ" && Replies.NumberQuery("共有 BAN もみじ") == "共有 BAN もみじ"
                && Replies.NumberQuery(" " + ln8 + " ") == ln8, Replies.NumberQuery("共有 BAN " + ln8));
            share.Set("state", "pushed");
            var discardedShare = Journal.NewAction("share", new List<string> { puidH }, "");
            Ops.SetDesc(discardedShare, puidH, 1, line.Expires, "harass", false, "AEG-DIS01", "imp", "");
            discardedShare.Set("state", "discarded");
            var hist = Replies.HistoryIds(mirror, new List<JObj> { share, fromCand, period, discardedShare });
            Check("reply.search.history-ids", hist.Contains("AEG-SHR01") && hist.Contains("AEG-NEW01") && hist.Contains("AEG-OLD01") && !hist.Contains("AEG-DIS01") && hist.Count == 3, string.Join(",", hist.ToArray()));
            // 7. nothing known at all: the bracket goes, never a dash
            var nothing = new ReplyFields();
            Check("reply.id.nothing-known", Replies.Body(0, "reject", nothing).IndexOf("BAN の記録を確認しました", StringComparison.Ordinal) > 0 && Replies.Body(1, "accept", nothing).IndexOf("和限制进入的记录。", StringComparison.Ordinal) > 0
                && Replies.Body(2, "accept", nothing).IndexOf("the ban record. We found", StringComparison.Ordinal) > 0 && Replies.Subject(0, "reject", nothing) == "【PocketRoles Aegis】異議申し立ての結果について", Replies.Body(0, "reject", nothing));
            // only a number: never a whole hash (8 hex digits at most) and never a friend code's hash as a line number
            Check("reply.id.line-number-only", Replies.LineNo(puidH) == ln8 && Replies.LineNo(ln8 + "…") == ln8 && Replies.LineNo("xyz") == "" && Replies.LineNo("1a2b3c4") == "" && Replies.LineNo("") == ""
                && Replies.IdText(2, new ReplyFields { Line = puidH }) == "shared ban " + ln8 && Replies.IdText(0, new ReplyFields { Id = "#1234" }) == "", null);
            // every case, 3 languages × 3 results: no dash, no sample, no empty bracket, no format hole, no identifier beyond the 8 digits
            bool dash = false, ids = false;
            string where = "";
            foreach (var x in new[] { fOwn, fMirror, fDiscarded, fLinked, fLine, fGone, fMin, fMinJ, fStale, fStaleNoJ, fStaleLive, fOldRow, fOldCand, fKick, fImp, fFc, fOnlyFc, fGoneFc, nothing })
                for (int i = 0; i < 3; i++)
                    foreach (var k in Replies.Kinds)
                    {
                        x.Now = now;
                        string m = Replies.Subject(i, k, x) + "\n" + Replies.Body(i, k, x);
                        foreach (var bad in new[] { "—", "XXXX", "{", "}", "（）", "()", "（、", "、）", "（，", "，）", "(, ", ", )" })
                            if (m.IndexOf(bad, StringComparison.Ordinal) >= 0) { dash = true; where = bad + " in " + m; }
                        if (HexShape.IsMatch(m) || m.IndexOf(fcH.Substring(0, 8), StringComparison.Ordinal) >= 0 || m.IndexOf(puidH.Substring(0, 9), StringComparison.Ordinal) >= 0) { ids = true; where = m; }
                    }
            Check("reply.no-dash-or-placeholder", !dash, where);
            Check("reply.no-identifiers", !ids, where);
        }

        static T Named<T>(Control root, string name) where T : Control
        {
            var todo = new Stack<Control>(); todo.Push(root);
            while (todo.Count > 0)
            {
                var c = todo.Pop();
                if (c is T && (name == null || c.Name == name)) return (T)c;
                foreach (Control ch in c.Controls) todo.Push(ch);
            }
            return null;
        }

