                using (var d = new PeriodDialog(S.Get("pd.head.g"), DateTime.UtcNow, false, null, 7, 30))
                {
                    bool plain = true;
                    var todo = new Stack<Control>(); todo.Push(d);
                    while (todo.Count > 0) { var c = todo.Pop(); foreach (Control ch in c.Controls) todo.Push(ch); if (c is NumericUpDown || (c is RadioButton && !(c is DarkRadio))) plain = false; }
                    var days = Named<TextBox>(d, "days");
                    Check("clip.period-dark-controls", plain && days != null, null);
                    days.Text = "12"; int twelve = d.ChosenDays;
                    days.Text = "999"; int capped = d.ChosenDays;   // over the 30-day cap: 30
                    days.Text = ""; int kept = d.ChosenDays;        // empty: the last good number
                    Check("clip.period-days-box", twelve == 12 && capped == 30 && kept == 30, twelve + "/" + capped + "/" + kept);
                }
            }
            finally { S.Lang = lang; }
        }

