        static string ZipLog(EvInfo e, bool written, bool detection, string action) { return ZipLog(e, written, detection, action, false); }

        /// <summary>A report zip's LogOutput.log; <paramref name="tagged"/>: the written line names the player like the v0.5.5 mod ("puid-hash 1a2b3c4d").</summary>
        static string ZipLog(EvInfo e, bool written, bool detection, string action, bool tagged)
        {
            var sb = new StringBuilder("[Info   :PocketRoles] PocketRoles v0.5.5 loaded\n");
            if (detection) sb.Append("[Warning:PocketRoles] CheatDetector: ChatFlood (Repeat) #2 test (client 5): 5 chat lines within 3 s\n");
            sb.Append("[Info   :PocketRoles] something else\n");
            if (written) sb.Append("[Info   :PocketRoles] AegisEvidence: " + e.Id + " written (" + action + ", " + e.Rule + (tagged ? ", puid-hash " + (e.PuidHash.Length >= 8 ? e.PuidHash.Substring(0, 8) : "-") + ")" : ", hash ********…)") + "\n");
            return sb.ToString();
        }

        static string MakeZip(string name, EvInfo e, string action, bool written, bool detection, string system) { return MakeZip(name, e, action, written, detection, system, false); }

        static string MakeZip(string name, EvInfo e, string action, bool written, bool detection, string system, bool tagged)
        {
            string zip = Path.Combine(root, name + ".zip");
            using (var fs = new FileStream(zip, FileMode.CreateNew))
            using (var za = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                Put(za, "LogOutput.log", ZipLog(e, written, detection, action, tagged));
                Put(za, "system.txt", system);
                Put(za, "launcher-state.json", "{ \"lastBuiltGameVersion\": \"2026.8.18\", \"lastBuiltAt\": \"" + "2026-09-01 10:00:00" + "\" }");
                Put(za, "evidence/" + e.Id + ".json", EvJson(e, action));
            }
            return zip;
        }

        /// <summary>A record as the launcher's report zip carries it: imported, player.hash = player.puidHash (ConvertTo-ReportEvidence).</summary>
        static EvInfo Imp(string id, string strength, string rule)
        {
            var e = Ev(id, strength, rule);
            e.Hash = e.PuidHash;
            e.Imported = true;
            return e;
        }

        /// <summary>
        /// The fake-evidence rules (item 5): (a) an imported record counts only when its zip's log shows the mod writing
        /// it (same id, action and rule; for an automatic record the detection line within 5 minutes, before it); (b) it
        /// backs a shared ban only when two different hosts reported the player; (c) such a ban is level 1, 30 days at most.
        /// v0.5.5 review: the player too (a record naming two identities, the written line's puid-hash), hosts counted by the
        /// listed PUID's hash only and each record once, level 1 when an ended line comes back, never a shorter line.
        /// </summary>
        static void FakeTests()
        {
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            var ev = Imp("AEG-FK001", "certain", "KillRole");
            ev.Action = "ban"; ev.Source = "auto"; ev.Time = new DateTime(2026, 9, 20, 12, 0, 5, DateTimeKind.Utc);
            ev.Trail = new List<string> { "11:59:40Z joined as x (StandaloneSteamPC, hash ********…)", "12:00:01Z CheatDetector: KillRole #3 x (client 5): killed #4 without a killing role (puid 0123456789abcdef0123456789abcdef)" };
            string det = "[LogOutput.log] [Warning:PocketRoles] CheatDetector: KillRole #3 x (client 5): killed #4 without a killing role (puid <puid-masked>)";
            string wr = "[LogOutput.log] [Info   :PocketRoles] AegisEvidence: AEG-FK001 written (ban, KillRole, hash ********…)";
            var log = new List<string> { "[LogOutput.log] [Info   :PocketRoles] loaded", det, wr };
            Check("fake.log.matches", LogCheck.Check(ev, log, now) == LogCheck.Ok, null);
            Check("fake.log.no-written-line", LogCheck.Check(ev, new List<string> { det }, now) == LogCheck.NoLog, null);
            Check("fake.log.other-id", LogCheck.Check(ev, new List<string> { det, wr.Replace("AEG-FK001", "AEG-FK002") }, now) == LogCheck.NoLog, null);
            Check("fake.log.rule-differs", LogCheck.Check(ev, new List<string> { det, wr.Replace("KillRole, hash", "TaskImpostor, hash") }, now) == LogCheck.Mismatch, null);
            Check("fake.log.action-differs", LogCheck.Check(ev, new List<string> { det, wr.Replace("(ban,", "(kick,") }, now) == LogCheck.Mismatch, null);
            var moved = Imp("AEG-FK001", "certain", "KillRole");
            moved.Action = "ban"; moved.Source = "auto"; moved.Trail = ev.Trail; moved.Time = ev.Time.AddHours(1);   // the record's time edited
            Check("fake.log.time-edited", LogCheck.Check(moved, log, now) == LogCheck.Time, null);
            Check("fake.log.detection-line-missing", LogCheck.Check(ev, new List<string> { wr }, now) == LogCheck.Time, null);
            Check("fake.log.detection-in-another-file", LogCheck.Check(ev, new List<string> { det.Replace("[LogOutput.log]", "[LogOutput-2026-09-19_220000.log]"), wr }, now) == LogCheck.Time, null);
            var future = Imp("AEG-FK001", "certain", "KillRole");
            future.Action = "ban"; future.Source = "auto"; future.Trail = ev.Trail; future.Time = now.AddDays(1);
            Check("fake.log.future", LogCheck.Check(future, log, now) == LogCheck.Future, null);
            var manual = Imp("AEG-FK003", "manual", "manual");
            manual.Action = "ban"; manual.Source = "manual"; manual.Time = ev.Time;
            Check("fake.log.manual-record-id-action-rule", LogCheck.Check(manual, new List<string> { "[LogOutput.log] AegisEvidence: AEG-FK003 written (ban, manual, hash ********…)" }, now) == LogCheck.Ok, null);
            // v0.5.5 review: the written line of the v0.5.5 mod names the player ("puid-hash 1a2b3c4d"): it must be the record's
            string tag8 = ev.PuidHash.Substring(0, 8);
            string wrTag = "[LogOutput.log] [Info   :PocketRoles] AegisEvidence: AEG-FK001 written (ban, KillRole, puid-hash " + tag8 + ")";
            Check("fake.log.tag-matches", LogCheck.Check(ev, new List<string> { det, wrTag }, now) == LogCheck.Ok, null);
            var other = Imp("AEG-FK001", "certain", "KillRole");   // the same record with another player's PUID hash written in
            other.Action = "ban"; other.Source = "auto"; other.Trail = ev.Trail; other.Time = ev.Time; other.PuidHash = Hashes.HashOf("selftest-puid-victim"); other.Hash = other.PuidHash;
            int otherState = LogCheck.Check(other, new List<string> { det, wrTag }, now);
            Check("fake.log.tag-other-player", otherState == LogCheck.Player, otherState.ToString(CultureInfo.InvariantCulture));
            Check("fake.log.tag-none-for-no-puid", LogCheck.Check(manual, new List<string> { "[LogOutput.log] AegisEvidence: AEG-FK003 written (ban, manual, puid-hash " + manual.PuidHash.Substring(0, 8) + ")" }, now) == LogCheck.Ok
                && LogCheck.Check(manual, new List<string> { "[LogOutput.log] AegisEvidence: AEG-FK003 written (ban, manual, puid-hash -)" }, now) == LogCheck.Player, null);
            // an untagged written line in a log file whose other written lines are tagged is not the mod's
            string wrOtherTagged = "[LogOutput.log] [Info   :PocketRoles] AegisEvidence: AEG-ZZZZZ written (kick, ChatFlood, puid-hash 1a2b3c4d)";
            Check("fake.log.untagged-among-tagged", LogCheck.Check(ev, new List<string> { det, wrOtherTagged, wr }, now) == LogCheck.Player
                && LogCheck.Check(ev, new List<string> { wrOtherTagged.Replace("[LogOutput.log]", "[LogOutput-2026-09-19_220000.log]"), det, wr }, now) == LogCheck.Ok, null);
            // v0.5.5 review: a record naming two players (player.hash of one, puidHash of another) is not the launcher's
            var mixed = Imp("AEG-FK006", "certain", "KillRole");
            mixed.Action = "ban"; mixed.Source = "manual"; mixed.Hash = Hashes.HashOf("selftest-puid-hostB-player");
            Check("fake.mixed.log-check", mixed.Mixed && LogCheck.Check(mixed, new List<string> { "[LogOutput.log] AegisEvidence: AEG-FK006 written (ban, KillRole, hash ********…)" }, now) == LogCheck.Mixed
                && LogCheck.Why(new EvInfo { Id = "AEG-FK006", LogState = LogCheck.Mixed }, 0) == S.In(0, "lc.6") && S.Has("lc.7"), null);
            Check("fake.mixed.own-record-is-not", !Ev("AEG-FK007", "certain", "KillRole").Mixed, null);   // this PC's own record: friend code's hash + PUID's hash, as the mod writes it
            // (b) the hosts
            List<string> names = null;
            Func<string[], string[], int> hosts = (labels, pcs) => { var l = new List<HostCount.Src>(); for (int i = 0; i < labels.Length; i++) l.Add(new HostCount.Src(labels[i], pcs[i])); return HostCount.Distinct(l, out names); };
            Check("fake.hosts.same-name", hosts(new[] { "もみじ", "もみじ " }, new[] { "", "" }) == 1, null);
            Check("fake.hosts.two-names", hosts(new[] { "もみじ", "かえで" }, new[] { "", "" }) == 2, null);
            Check("fake.hosts.case", hosts(new[] { "Momiji", "momiji" }, new[] { "", "" }) == 1, null);
            Check("fake.hosts.no-name-not-counted", hosts(new[] { "もみじ", "" }, new[] { "", "" }) == 1 && hosts(new[] { "", "" }, new[] { "a", "b" }) == 0, null);
            Check("fake.hosts.same-pc-one-host", hosts(new[] { "もみじ", "かえで" }, new[] { "1111222233334444", "1111222233334444" }) == 1, null);
            Check("fake.hosts.two-pcs", hosts(new[] { "もみじ", "かえで" }, new[] { "1111222233334444", "5555666677778888" }) == 2, null);
            Check("fake.hosts.this-pc-counts", hosts(new[] { HostCount.ThisPc, "かえで" }, new[] { "", "" }) == 2 && names.Contains(S.Get("from.own")), null);
            // v0.5.5 review: the attack with mixed hashes. Host B honestly reported player B (a listed PUID hash is public);
            // host A forges a record with player.hash = B's and player.puidHash = the victim's. The either-hash match counted
            // B's report (and this PC's own record of B) for the victim, and the shared line would list the victim.
            string pB = Hashes.HashOf("selftest-puid-hostB-player"), pV = Hashes.HashOf("selftest-puid-victim");
            var honest = new EvInfo { Id = "AEG-HB001", Imported = true, Action = "kick", Hash = pB, PuidHash = pB, HostLabel = "B", ImportDir = "20260920-100000-b", LogState = LogCheck.Ok };
            var forged = new EvInfo { Id = "AEG-HA001", Imported = true, Hash = pB, PuidHash = pV, HostLabel = "A", ImportDir = "20260921-100000-a", Action = "kick", Rule = "" };
            forged.LogState = LogCheck.Check(forged, new List<string> { "[LogOutput.log] AegisEvidence: AEG-HA001 written (kick, , hash ********…)" }, now);
            var ownB = new EvInfo { Id = "AEG-OWNB1", Action = "ban", Hash = Hashes.HashOf("hostb#1234"), PuidHash = pB };   // this PC's own record of B
            var imps = new List<EvInfo> { honest, forged };
            forged.HostCount = HostCount.For(forged, imps, new[] { ownB }, out names);
            Check("fake.mixed.host-count-and-blocked", forged.HostCount <= 1 && GateRules.ShareBlock(forged) != "" && forged.LogState == LogCheck.Mixed, forged.HostCount + " " + forged.LogState);
            forged.LogState = LogCheck.Ok;   // even if it passed the log check: B's reports never count for the victim
            Check("fake.mixed.never-counts-other-player", HostCount.For(forged, imps, new[] { ownB }, out names) <= 1, null);
            var victimOnly = new EvInfo { Id = "AEG-HA002", Imported = true, Action = "kick", Hash = pV, PuidHash = pV, HostLabel = "A", ImportDir = "20260921-100000-a", LogState = LogCheck.Ok };
            Check("fake.hosts.by-listed-puid-only", HostCount.For(victimOnly, new List<EvInfo> { honest, victimOnly }, new[] { ownB }, out names) == 1 && HostCount.For(honest, new List<EvInfo> { honest, victimOnly }, new[] { ownB }, out names) == 2, null);
            // v0.5.5 review: the same record imported twice (a copy of a zip under another host's name) counts once, under its first import
            var copy1 = new EvInfo { Id = "AEG-CP001", Imported = true, Action = "kick", Hash = pV, PuidHash = pV, HostLabel = "もみじ", ImportDir = "20260922-100000-r5", LogState = LogCheck.Ok };
            var copy2 = new EvInfo { Id = "AEG-CP001", Imported = true, Action = "kick", Hash = pV, PuidHash = pV, HostLabel = "かえで", ImportDir = "20260922-110000-r5-copy", LogState = LogCheck.Ok };
            var copies = new List<EvInfo> { copy2, copy1 };
            int nCopy = HostCount.For(copy2, copies, null, out names);
            Check("fake.hosts.same-record-twice-one-host", nCopy == 1 && names.Count == 1 && names[0] == "もみじ" && HostCount.For(copy1, copies, null, out names) == 1, nCopy + " " + string.Join(",", names.ToArray()));
            // the gate and (c) the cap
            var g = Imp("AEG-FK004", "circumstantial", "ChatFlood");
            g.LogState = LogCheck.Ok; g.HostCount = 1; g.HostLabel = "A";   // (v0.5.5 review: a zip with no host name is "g.block.noname": sgate.*)
            Check("fake.gate.one-host-blocked", GateRules.ShareBlock(g) == "g.block.onehost" && !GateRules.ShareAllowed(g), null);
            g.HostCount = 2;
            Check("fake.gate.two-hosts-allowed", GateRules.ShareBlock(g) == "", null);
            g.LogState = LogCheck.NoLog;
            Check("fake.gate.no-log-blocked", GateRules.ShareBlock(g) == "g.block.nolog", null);
            var own = Ev("AEG-FK005", "circumstantial", "ChatFlood");
            Check("fake.gate.own-record-as-before", GateRules.ShareBlock(own) == "" && GateRules.ShareBlock(null) == "g.block.noev", null);
            Check("fake.cap.level-1", GateRules.ShareLevel(g, 3) == 1 && GateRules.ShareLevel(own, 3) == 3 && GateRules.ShareLevel(own, 0) == 1 && GateRules.ShareLevel(own, 9) == 3, null);
            Check("fake.cap.30-days", GateRules.MaxDays(g) == 30 && GateRules.MaxDays(own) == 0 && GateRules.TooLong(g, null, now) && GateRules.TooLong(g, now.AddDays(40), now)
                && !GateRules.TooLong(g, now.AddDays(30).Date.AddDays(1), now) && !GateRules.TooLong(own, null, now), null);
            // v0.5.5 review (rule 5c): bringing back an ended line (a period change or an undo) on imported records only starts at level 1
            var ended3 = new SharedLine { Hash = g.PuidHash, Level = 3, Expires = now.AddDays(-5).Date, Reason = "cheat" };
            var active2 = new SharedLine { Hash = g.PuidHash, Level = 2, Expires = now.AddDays(10).Date, Reason = "cheat" };
            var perm3 = new SharedLine { Hash = g.PuidHash, Level = 3, Expires = null, Reason = "cheat" };
            Check("fake.cap.period-brings-back-at-level-1", GateRules.ExtendLevel(g, ended3, now) == 1 && GateRules.ExtendLevel(g, null, now) == 1 && GateRules.ExtendLevel(own, ended3, now) == 3
                && GateRules.ExtendLevel(g, active2, now) == 2, null);
            var putBack = GateRules.CapLines(g, new List<string> { SharedLine.Format(g.PuidHash, 3, now.AddDays(20).Date, "cheat"), "junk" });
            var pb = SharedLine.Parse(putBack[0]);
            Check("fake.cap.undo-puts-back-level-1", pb != null && pb.Level == 1 && pb.Expires == now.AddDays(20).Date && pb.Reason == "cheat" && putBack[1] == "junk"
                && GateRules.CapLines(own, new List<string> { SharedLine.Format(own.PuidHash, 3, null, "cheat") })[0] == SharedLine.Format(own.PuidHash, 3, null, "cheat"), putBack[0]);
            Check("fake.cap.period-dialog", GateRules.PeriodCap(g, null, now, now) == 30 && GateRules.PeriodCap(g, ended3, now.AddDays(-10), now) == 40 && GateRules.PeriodCap(g, perm3, now, now) == 0
                && GateRules.PeriodCap(g, active2, now, now) == 30 && GateRules.PeriodCap(own, null, now, now) == 0, null);
            // v0.5.5 review: an imported record never cuts down a longer shared ban in effect (sharing a candidate replaces the line)
            Check("fake.cap.never-shortens-a-ban-in-effect", GateRules.TooLong(g, perm3.EndsAt, now) && GateRules.Shortens(perm3, now.AddDays(30), now) && GateRules.Shortens(active2, now.AddDays(3), now)
                && !GateRules.Shortens(active2, now.AddDays(30), now) && !GateRules.Shortens(ended3, now.AddDays(3), now) && !GateRules.Shortens(null, now, now) && !GateRules.Shortens(perm3, null, now), null);
            // v0.5.5 review: the shared line lists the evidence's own player (a ban entry whose puidHash was swapped to a victim's)
            Check("fake.puid.listed-must-be-evidence-player", GateRules.ListsEvidencePlayer(own, own.PuidHash) && !GateRules.ListsEvidencePlayer(own, pV) && !GateRules.ListsEvidencePlayer(null, pV)
                && !GateRules.ListsEvidencePlayer(new EvInfo { Id = "AEG-NOPU1" }, "") && !GateRules.ListsEvidencePlayer(own, own.Hash), null);
            // end to end: report zips imported with their hosts' names, then the loader
            Fresh("fake");
            string sysA = "PocketRoles report 2026-09-22 10:00:00\r\nOS              : Windows 11 Pro 24H2 build 26100.1\r\nculture         : ja-JP / UI ja-JP\r\n";
            string sysB = "PocketRoles report 2026-09-22 11:00:00\r\nOS              : Windows 10 Home 22H2 build 19045.9\r\nculture         : zh-CN / UI zh-CN\r\n";
            var p1 = Imp("AEG-E2E01", "circumstantial", "ChatFlood");
            var p2 = Imp("AEG-E2E02", "circumstantial", "ChatFlood");
            p2.Hash = p1.Hash; p2.PuidHash = p1.PuidHash; p2.Name = p1.Name;   // the same player, reported by a second host
            var p3 = Imp("AEG-E2E03", "circumstantial", "ChatFlood");            // another player: one host only
            var p4 = Imp("AEG-E2E04", "circumstantial", "ChatFlood");            // a record whose log lacks it
            var p5 = Imp("AEG-E2E05", "circumstantial", "ChatFlood");            // a mixed identity: player.hash of p3's player, puidHash of p5's
            p5.Hash = p3.PuidHash;
            int evn = 0, ln = 0;
            var s1 = new Step("zip", null);
            Ops.Import(MakeZip("r1", p1, "kick", true, true, sysA), "もみじ", s1, ref evn, ref ln);
            Ops.Import(MakeZip("r2", p2, "kick", true, true, sysB, true), "かえで", s1, ref evn, ref ln);   // (a v0.5.5 mod's tagged line)
            Ops.Import(MakeZip("r3", p3, "kick", true, true, sysA), "もみじ", s1, ref evn, ref ln);
            Ops.Import(MakeZip("r4", p4, "kick", false, true, sysB), "かえで", s1, ref evn, ref ln);
            Ops.Import(MakeZip("r5", p5, "kick", true, true, sysB), "かえで", s1, ref evn, ref ln);
            Ops.Import(MakeZip("r3-copy", p3, "kick", true, true, sysA.Replace("10:00:00", "10:00:01")), "さくら", s1, ref evn, ref ln);   // r3 again, under another name
            string src1 = "";
            foreach (var d in Directory.GetDirectories(App.ImportDir)) if (d.EndsWith("r1", StringComparison.Ordinal)) src1 = File.ReadAllText(Path.Combine(d, "source.txt"));
            Check("fake.import.source-host-and-pc", src1.IndexOf("host=もみじ", StringComparison.Ordinal) > 0 && Regex.IsMatch(src1, "pc=[0-9a-f]{16}"), src1);
            var snap = new Snapshot();
            Loader.Evidence(snap, new Step("ev", null));
            Loader.Rows(snap, new Step("rows", null));
            var stI = new Step("imports", null);
            Loader.Imports(snap, stI);
            Func<string, EvInfo> find = id => snap.Imported.Find(x => x.Id == id);
            Check("fake.e2e.log-ok", find("AEG-E2E01") != null && find("AEG-E2E01").LogState == LogCheck.Ok && find("AEG-E2E02").LogState == LogCheck.Ok && find("AEG-E2E03").LogState == LogCheck.Ok, stI.Detail);
            Check("fake.e2e.log-missing", find("AEG-E2E04") != null && find("AEG-E2E04").LogState == LogCheck.NoLog && GateRules.ShareBlock(find("AEG-E2E04")) == "g.block.nolog", null);
            Check("fake.e2e.two-hosts", find("AEG-E2E01").HostCount == 2 && find("AEG-E2E02").HostCount == 2 && GateRules.ShareAllowed(find("AEG-E2E01")), find("AEG-E2E01").HostCount.ToString(CultureInfo.InvariantCulture));
            var p3s = snap.Imported.FindAll(x => x.Id == "AEG-E2E03");
            Check("fake.e2e.one-host-even-imported-twice", p3s.Count == 2 && p3s.TrueForAll(x => x.HostCount == 1 && GateRules.ShareBlock(x) == "g.block.onehost"), p3s.Count + " " + (p3s.Count > 0 ? p3s[0].HostCount.ToString(CultureInfo.InvariantCulture) : ""));
            var p5r = find("AEG-E2E05");
            Check("fake.e2e.mixed-blocked", p5r != null && p5r.LogState == LogCheck.Mixed && p5r.HostCount == 0 && GateRules.ShareBlock(p5r) == "g.block.nolog", p5r != null ? p5r.LogState + " " + p5r.HostCount : "none");
            Check("fake.e2e.step-detail", stI.State == 3 && stI.Detail == S.Get("ld.imp.d", 6, 4), stI.Detail);
            Check("fake.pcmark", Ops.PcMark(sysA, "{\"lastBuiltAt\": \"2026-09-01 10:00:00\"}").Length == 16 && Ops.PcMark(sysA, "{}") == "" && Ops.PcMark(sysA, "{\"lastBuiltAt\": \"x\"}") != Ops.PcMark(sysB, "{\"lastBuiltAt\": \"x\"}"), null);
            HoldImportTest(sysA, sysB);
            BackingImportTest(sysA);
            PuidSwapTest(pV);
        }

        /// <summary>
        /// v0.5.5 owner decision 2026-09-23 「A」: evidence records are kept 90 days, logs 30. A record whose log was deleted
        /// comes in the report zip (and the one-player zip) with evidence/&lt;id&gt;.log: a comment line and the two lines of
        /// the deleted log that back it (the detection line and the written line; PocketRolesLauncher.ps1
        /// Save-EvidenceBackingFrom, src\Net\AegisEvidence.cs BackingJob). Imported like any log (under its own file name),
        /// it passes the same log check; without the written line it does not.
        /// </summary>
        static void BackingImportTest(string sysA)
        {
            Fresh("backing");
            var b1 = Imp("AEG-BK001", "circumstantial", "ChatFlood");
            var b2 = Imp("AEG-BK002", "circumstantial", "ChatFlood");
            string det = "[Warning:PocketRoles] CheatDetector: ChatFlood (Repeat) #2 test (client 5): 5 chat lines within 3 s\r\n";
            string zip = Path.Combine(root, "backing-r1.zip");
            using (var fs = new FileStream(zip, FileMode.CreateNew))
            using (var za = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                Put(za, "LogOutput.log", "[Info   :PocketRoles] PocketRoles v0.5.5 loaded\n");   // that game's log is gone
                Put(za, "system.txt", sysA);
                Put(za, "launcher-state.json", "{ \"lastBuiltAt\": \"2026-09-01 10:00:00\" }");
                Put(za, "evidence/AEG-BK001.json", EvJson(b1, "kick"));
                Put(za, "evidence/AEG-BK001.log", "# PocketRoles: the lines of LogOutput-2026-08-01_120000.log that back the evidence record AEG-BK001 (kept after that log was deleted at 30 days; deleted with the record)\r\n"
                    + det + "[Info   :PocketRoles] AegisEvidence: AEG-BK001 written (kick, ChatFlood, puid-hash " + b1.PuidHash.Substring(0, 8) + ")\r\n");
                Put(za, "evidence/AEG-BK002.json", EvJson(b2, "kick"));
                Put(za, "evidence/AEG-BK002.log", "# PocketRoles: the lines of LogOutput-2026-08-01_120000.log that back the evidence record AEG-BK002\r\n" + det);   // no written line
            }
            int evn = 0, ln = 0;
            Ops.Import(zip, "もみじ", new Step("zip", null), ref evn, ref ln);
            var snap = new Snapshot();
            Loader.Evidence(snap, new Step("ev", null));
            Loader.Rows(snap, new Step("rows", null));
            Loader.Imports(snap, new Step("imports", null));
            var r1 = snap.Imported.Find(x => x.Id == "AEG-BK001");
            var r2 = snap.Imported.Find(x => x.Id == "AEG-BK002");
            Check("backing.import.log-ok", r1 != null && r1.LogState == LogCheck.Ok, r1 != null ? r1.LogState.ToString(CultureInfo.InvariantCulture) : "none");
            Check("backing.import.no-written-line", r2 != null && r2.LogState == LogCheck.NoLog, r2 != null ? r2.LogState.ToString(CultureInfo.InvariantCulture) : "none");
            string collected = "";
            foreach (var d in Directory.GetDirectories(App.ImportDir)) if (File.Exists(Path.Combine(d, "aegis-log.txt"))) collected += File.ReadAllText(Path.Combine(d, "aegis-log.txt"));
            Check("backing.import.lines", evn == 2 && collected.IndexOf("[AEG-BK001.log] [Info   :PocketRoles] AegisEvidence: AEG-BK001 written", StringComparison.Ordinal) >= 0
                && collected.IndexOf("# PocketRoles", StringComparison.Ordinal) < 0, evn + " " + collected.Length);

            // review 2026-09-23: a busy report zip. Its LogOutput.log alone fills the 5000 "other" lines, and the zip's
            // evidence/ folder is read last, so before the fix the kept detection line of AEG-BK003 was dropped and its log
            // check failed (lc.4). The backing files have a cap of their own now.
            Fresh("backing-busy");
            var b3 = Imp("AEG-BK003", "circumstantial", "ChatFlood");
            var busy = new StringBuilder();
            for (int i = 0; i < 6000; i++) busy.Append("[Warning:PocketRoles] CheatDetector: ChatFlood (Repeat) #1 someone (client 9): 5 chat lines within 3 s\r\n");
            string zip2 = Path.Combine(root, "backing-busy.zip");
            using (var fs = new FileStream(zip2, FileMode.CreateNew))
            using (var za = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                Put(za, "LogOutput.log", busy.ToString());
                Put(za, "system.txt", sysA);
                Put(za, "launcher-state.json", "{ \"lastBuiltAt\": \"2026-09-01 10:00:00\" }");
                Put(za, "export.txt", "PocketRoles one-player evidence 2026-09-23 03:00:00\r\n!! for the author only: send this zip to pocketroles.report+host@gmail.com and to nobody else\r\nrecords         : 1\r\n");
                Put(za, "evidence/AEG-BK003.json", EvJson(b3, "kick"));
                Put(za, "evidence/AEG-BK003.log", "# PocketRoles: the lines of LogOutput-2026-08-01_120000.log that back the evidence record AEG-BK003 (kept after that log was deleted at 30 days; deleted with the record)\r\n"
                    + det + "[Info   :PocketRoles] AegisEvidence: AEG-BK003 written (kick, ChatFlood, puid-hash " + b3.PuidHash.Substring(0, 8) + ")\r\n");
            }
            int evn2 = 0, ln2 = 0;
            Ops.Import(zip2, "もみじ", new Step("zip", null), ref evn2, ref ln2);
            var snap2 = new Snapshot();
            Loader.Evidence(snap2, new Step("ev", null));
            Loader.Rows(snap2, new Step("rows", null));
            Loader.Imports(snap2, new Step("imports", null));
            var r3 = snap2.Imported.Find(x => x.Id == "AEG-BK003");
            Check("backing.import.busy-log", r3 != null && r3.LogState == LogCheck.Ok, r3 != null ? r3.LogState.ToString(CultureInfo.InvariantCulture) : "none");
            // review 2026-09-23: a one-player evidence zip (an appeal export) is marked in source.txt, so the author can see that
            // these records are all of one player's records on that PC and came in through an appeal
            string kinds = "";
            foreach (var d in Directory.GetDirectories(App.ImportDir))
                if (File.Exists(Path.Combine(d, "source.txt"))) kinds += File.ReadAllText(Path.Combine(d, "source.txt")) + "|" + ImportMeta.Of(Path.GetFileName(d)).Kind + "|";
            Check("import.one-player.kind", kinds.IndexOf("kind=one-player", StringComparison.Ordinal) >= 0 && kinds.IndexOf("|one-player|", StringComparison.Ordinal) >= 0, kinds.Length.ToString(CultureInfo.InvariantCulture));
        }

        /// <summary>
        /// v0.5.5 review: a report zip holds every record of the last 90 days. Another host's "hold" (removed only, in the 30
        /// days after an accepted appeal) and "notice" records are no candidates and, like this PC's own "hold" record, never
        /// count as a host's report: one real "kick" of that player stays one host (blocked), where the held-back records
        /// used to make it three or four (allowed).
        /// </summary>
        static void HoldImportTest(string sysA, string sysB)
        {
            string sysC = "PocketRoles report 2026-09-22 12:00:00\r\nOS              : Windows 11 Home 23H2 build 22631.2\r\nculture         : en-US / UI en-US\r\n";
            var h6 = Imp("AEG-HLD06", "certain", "KillRole");
            var h7 = Imp("AEG-HLD07", "certain", "KillRole");
            var h8 = Imp("AEG-HLD08", "circumstantial", "ChatFlood");
            h7.Hash = h6.Hash; h7.PuidHash = h6.PuidHash; h8.Hash = h6.Hash; h8.PuidHash = h6.PuidHash;
            int evn = 0, ln = 0;
            var s1 = new Step("zip", null);
            Ops.Import(MakeZip("hold-h6", h6, "hold", true, true, sysA, true), "もみじ", s1, ref evn, ref ln);
            Ops.Import(MakeZip("hold-h7", h7, "notice", true, true, sysB, true), "かえで", s1, ref evn, ref ln);
            Ops.Import(MakeZip("hold-h8", h8, "kick", true, true, sysC, true), "さくら", s1, ref evn, ref ln);
            Directory.CreateDirectory(App.EvidenceDir);
            var own = Ev("AEG-HLD09", "certain", "KillRole");
            own.PuidHash = h6.PuidHash;   // this PC's own "hold" record of the same player
            string ownFile = Path.Combine(App.EvidenceDir, own.Id + ".json");
            File.WriteAllText(ownFile, EvJson(own, "hold"), new UTF8Encoding(false));
            try
            {
                var snap = new Snapshot();
                Loader.Evidence(snap, new Step("ev", null));
                Loader.Rows(snap, new Step("rows", null));
                Loader.Imports(snap, new Step("imports", null));
                bool offered = snap.Cands.Exists(c => c.Ev != null && (c.Ev.Id == h6.Id || c.Ev.Id == h7.Id || c.Ev.Id == own.Id));
                Check("hold.import.not-a-candidate", !offered && snap.Imported.Find(x => x.Id == h6.Id) == null && snap.Imported.Find(x => x.Id == h7.Id) == null
                    && snap.Cands.Exists(c => c.Ev != null && c.Ev.Id == h8.Id), null);
                var k = snap.Imported.Find(x => x.Id == h8.Id);
                Check("hold.import.not-a-host-report", k != null && k.LogState == LogCheck.Ok && k.HostCount == 1 && GateRules.ShareBlock(k) == "g.block.onehost",
                    k == null ? "none" : k.LogState + " " + k.HostCount + " " + string.Join(",", k.HostNames.ToArray()));
                List<string> names;
                var holdEv = new EvInfo { Id = "AEG-HLD10", Imported = true, Action = "hold", Hash = h6.PuidHash, PuidHash = h6.PuidHash, HostLabel = "X", ImportDir = "20260922-130000-x", LogState = LogCheck.Ok };
                Check("hold.host-count-kick-and-ban-only", HostCount.For(k, new List<EvInfo> { k, holdEv }, new[] { own }, out names) == 1
                    && HostCount.For(k, new List<EvInfo> { k }, new[] { new EvInfo { Id = "AEG-HLD11", Action = "kick", PuidHash = h6.PuidHash } }, out names) == 2, null);
                Check("hold.shown-as-hold", MainForm.EvActionKey("hold") == "v.hold" && MainForm.EvActionKey("notice") == "v.notice" && MainForm.EvActionKey("kick") == "v.kick"
                    && S.Has("v.hold") && S.Has("v.notice") && S.In(0, "v.hold").IndexOf("30 日", StringComparison.Ordinal) >= 0, null);
            }
            finally
            {
                try { File.Delete(ownFile); } catch (Exception) { }
            }
        }

        /// <summary>
        /// v0.5.5 review: a crafted aegis-bans.json. Player C's entry gets the victim's PUID hash; this PC's own evidence of C
        /// is still linked (by the friend code's hash), but the line it would list is not that evidence's player, and the
        /// change shows as an outside change (without any PUID hash in the snapshot).
        /// </summary>
        static void PuidSwapTest(string victim)
        {
            Fresh("swap");
            string oldGame = App.GameDir;
            App.GameDir = Path.Combine(root, "game-swap");
            try
            {
                Directory.CreateDirectory(App.EvidenceDir);
                var c = Ev("AEG-SWAP1", "certain", "KillRole");
                c.Name = "Chika";
                File.WriteAllText(Path.Combine(App.EvidenceDir, "AEG-SWAP1.json"), EvJson(c, "ban"), new UTF8Encoding(false));
                var e = BanEntry("swap", "Chika", "auto", "Aegis", true, "2026-09-20T00:00:00Z", "2099-01-01T00:00:00Z", "AEG-SWAP1", "ban", "auto KillRole 30 d AEG-SWAP1");
                e.Set("hash", c.Hash); e.Set("puidHash", c.PuidHash);
                File.WriteAllText(App.BansPath, Json.Write(Store(e)), new UTF8Encoding(false));
                bool first;
                BanSnap.Observe(App.BansPath, out first);   // the snapshot before the edit
                e.Set("puidHash", victim);
                File.WriteAllText(App.BansPath, Json.Write(Store(e)), new UTF8Encoding(false));
                var s = new Snapshot();
                Loader.Bans(s, new Step("bans", null));
                Loader.Evidence(s, new Step("ev", null));
                Loader.Rows(s, new Step("rows", null));
                var row = s.Rows.Find(x => x.Name == "Chika");
                var share = row != null ? row.ShareHashes() : new List<string>();
                Check("fake.puid.swapped-entry-blocked", row != null && row.Ev != null && share.Count == 1 && share[0] == victim && !GateRules.ListsEvidencePlayer(row.Ev, share[0]), row == null ? "no row" : row.Ev == null ? "no evidence" : "");
                var ch = BanSnap.Observe(App.BansPath, out first);
                string snapText = File.ReadAllText(App.SnapFile);
                Check("fake.puid.swap-seen-outside", ch.Count == 1 && ch[0].Kind == "change" && !ch[0].Mod && ch[0].Diffs.Contains(BanSnap.PuidDiff) && BanSnap.DiffText(BanSnap.PuidDiff, 0) == S.In(0, "bf.puid")
                    && snapText.IndexOf(victim, StringComparison.Ordinal) < 0 && snapText.IndexOf(c.PuidHash, StringComparison.Ordinal) < 0 && !HexShape.IsMatch(snapText), ch.Count > 0 ? string.Join(" | ", ch[0].Diffs.ToArray()) : "none");
                // the mod fills an empty PUID hash when it learns it: not reported
                e.Set("puidHash", ""); File.WriteAllText(App.BansPath, Json.Write(Store(e)), new UTF8Encoding(false));
                BanSnap.Observe(App.BansPath, out first);
                e.Set("puidHash", c.PuidHash); File.WriteAllText(App.BansPath, Json.Write(Store(e)), new UTF8Encoding(false));
                Check("fake.puid.fill-not-reported", BanSnap.Observe(App.BansPath, out first).Count == 0, null);
            }
            finally { App.GameDir = oldGame; }
        }

        /// <summary>
        /// v0.5.5 (2026-09-22 owner decision 「いいよ」 on 「確実な検知ならホスト 1 人で OK」): when an imported record may back a
        /// shared ban. A certain detection its zip's log agrees with: one host is enough (level 1, 30 days, once per record);
        /// chat, NG words, harassment, names, the host's own call, Repeat and Notice rules: two hosts, a trusted admin, or the
        /// author's written reason (asked in the confirmation, written to audit.log); a paused host: blocked. D-35 (9/23: 3, was 5)
        /// overturns in the last 30 days pause, rolling (no latch), certain detections never charged, reporters.txt pruned after
        /// 30 days. 9/23: one host's certain-only shares, 2 in any rolling 30 days (audit.log), then a second host or the author.
        /// Review: overturns count once per host per lift, only the records a listing named as its backers are charged,
        /// trust and pauses follow the record's first import, the [unban] list counts only "mistake" lines, trust and clears
        /// come from audit.log only, a zip without a host name and an unreadable hosts' record allow no single-host share.
        /// </summary>
        static void ShareGateTests()
        {
            var now = new DateTime(2026, 9, 22, 12, 0, 0, DateTimeKind.Utc);
            Reporters.Current = null;
            string reason10 = "チャットで何度も暴言を確認しました";
            // (1) a certain detection: the log shows the detection line at the Certain level before the written line
            var k = Imp("AEG-SG001", "certain", "KillRole");
            k.Action = "ban"; k.Source = "auto"; k.Time = new DateTime(2026, 9, 20, 12, 0, 5, DateTimeKind.Utc);
            k.HostLabel = "もみじ"; k.ImportDir = "20260921-100000-sg1";
            string trail = "12:00:01Z CheatDetector: KillRole (Certain) #3 x (client 5): role Crewmate (live Crewmate), flags 0";
            k.Trail = new List<string> { "11:59:40Z joined as x (StandaloneSteamPC, hash ********…)", trail };
            string det = "[LogOutput.log] [Warning:PocketRoles] CheatDetector: KillRole (Certain) #3 x (client 5): role Crewmate (live Crewmate), flags 0";
            string wr = "[LogOutput.log] [Info   :PocketRoles] AegisEvidence: AEG-SG001 written (ban, KillRole, puid-hash " + k.PuidHash.Substring(0, 8) + ")";
            var log = new List<string> { "[LogOutput.log] [Info   :PocketRoles] loaded", det, wr };
            k.LogState = LogCheck.Check(k, log, now);
            k.CertainLog = LogCheck.CertainInLog(k, log, null);
            k.HostCount = 1;
            Check("sgate.certain.log-backs-certain", k.LogState == LogCheck.Ok && k.CertainLog, k.LogState.ToString(CultureInfo.InvariantCulture));
            Check("sgate.certain.one-host-allowed", GateRules.ShareBlock(k) == "" && GateRules.Basis(k) == "certain" && GateRules.ShareAllowed(k) && GateRules.BasisText(k, 0) == S.In(0, "bs.certain"), GateRules.ShareBlock(k));
            Check("sgate.certain.first-stage-cap", GateRules.ShareLevel(k, 3) == 1 && GateRules.MaxDays(k) == 30 && GateRules.TooLong(k, null, now) && GateRules.TooLong(k, now.AddDays(40), now)
                && !GateRules.TooLong(k, now.AddDays(30).Date.AddDays(1), now) && GateRules.PeriodCap(k, null, now, now) == 30
                && GateRules.ExtendLevel(k, new SharedLine { Hash = k.PuidHash, Level = 3, Expires = now.AddDays(-5).Date, Reason = "cheat" }, now) == 1
                && GateRules.IsSingleHost("certain") && GateRules.IsSingleHost("trusted") && GateRules.IsSingleHost("override") && !GateRules.IsSingleHost("hosts") && !GateRules.IsSingleHost("own"), null);
            var gk = GateRules.For(k);
            // review: the rule is never preset (the record and its log come from the same zip), and the box says why it is asked
            Check("sgate.certain.still-asks-rule-and-reason", gk.NeedRule && gk.NeedReason && gk.Rule == "" && gk.RuleKey == "g.rule.check" && gk.Note == S.Get("g.imported.certain", S.Rule("KillRole") + "（KillRole）")
                && !gk.Ready("cheat", "短い") && !gk.Ready("", reason10) && gk.Ready("cheat", reason10), gk.Note);
            Check("sgate.certain.says-same-zip", S.In(0, "bs.certain.why").IndexOf("同じ zip", StringComparison.Ordinal) > 0 && S.In(0, "g.imported.certain").IndexOf("見分けられません", StringComparison.Ordinal) > 0
                && S.In(2, "bs.certain.note").IndexOf("same zip", StringComparison.Ordinal) > 0 && S.In(1, "st.log").IndexOf("同一个 zip", StringComparison.Ordinal) > 0
                && Fmt.StrengthOf(k, 0) == S.In(0, "st.certain.log") && GateRules.BasisWhy(k, 0) == S.In(0, "bs.certain.why") && S.In(0, "bs.certain.why").IndexOf("使えます", StringComparison.Ordinal) < 0, null);
            var circBullets = new List<string>();
            MainForm.CircBullet(circBullets, k);
            var circOther = new List<string>();
            MainForm.CircBullet(circOther, Imp("AEG-SGC01", "circumstantial", "ChatFlood"));
            Check("sgate.certain.no-circumstantial-line", circBullets.Count == 0 && circOther.Count == 1 && circOther[0] == S.Get("cf.p.circ"), null);
            foreach (var rule in GateRules.CertainRules) Check("sgate.certain.rule." + rule, GateRules.IsCertainRule(rule), null);
            Check("sgate.certain.not-other-rules", !GateRules.IsCertainRule("ChatFlood") && !GateRules.IsCertainRule("SpeedHack") && !GateRules.IsCertainRule("NgWord") && !GateRules.IsCertainRule("manual") && !GateRules.IsCertainRule("killrole"), null);
            // what does not make one host enough
            Func<string, string, string, string, List<string>, EvInfo> variant = (strength, rule, source, trailLine, lines) =>
            {
                var v = Imp("AEG-SG001", strength, rule);
                v.PuidHash = k.PuidHash; v.Hash = k.Hash; v.Action = "ban"; v.Source = source; v.Time = k.Time; v.HostLabel = "もみじ"; v.ImportDir = k.ImportDir;
                v.Trail = new List<string> { trailLine };
                v.LogState = LogCheck.Check(v, lines, now);
                v.CertainLog = v.LogState == LogCheck.Ok && LogCheck.CertainInLog(v, lines, null);
                v.HostCount = 1;
                return v;
            };
            string relaxedTrail = trail.Replace("(Certain)", "(Repeat)"), relaxedDet = det.Replace("(Certain)", "(Repeat)");
            var relaxed = variant("certain", "KillRole", "auto", relaxedTrail, new List<string> { relaxedDet, wr });
            Check("sgate.certain.relaxed-level-is-not", relaxed.LogState == LogCheck.Ok && !relaxed.CertainLog && GateRules.ShareBlock(relaxed) == "g.block.onehost", relaxed.LogState + " " + relaxed.CertainLog);
            var edited = variant("certain", "KillRole", "auto", trail, new List<string> { relaxedDet, wr });   // the record says Certain, its log Repeat
            Check("sgate.certain.record-says-certain-log-does-not", !edited.CertainLog && GateRules.ShareBlock(edited) != "", edited.LogState.ToString(CultureInfo.InvariantCulture));
            var noDet = variant("certain", "KillRole", "auto", trail, new List<string> { wr });
            Check("sgate.certain.detection-line-missing", !noDet.CertainLog && GateRules.ShareBlock(noDet) == "g.block.nolog", noDet.LogState.ToString(CultureInfo.InvariantCulture));
            var testLine = variant("certain", "KillRole", "auto", trail, new List<string> { det.Replace("CheatDetector: KillRole", "CheatDetector: [test] KillRole"), wr });
            Check("sgate.certain.test-line-is-not", !testLine.CertainLog && GateRules.ShareBlock(testLine) != "", null);
            string chatTrail = "12:00:01Z CheatDetector: ChatFlood (Certain) #3 x (client 5): 5 chat lines within 3 s";
            var chatClaim = variant("certain", "ChatFlood", "auto", chatTrail, new List<string> { "[LogOutput.log] CheatDetector: ChatFlood (Certain) #3 x (client 5): 5 chat lines within 3 s", wr.Replace("KillRole", "ChatFlood") });
            Check("sgate.certain.chat-rule-is-not", chatClaim.LogState == LogCheck.Ok && !chatClaim.CertainLog && GateRules.ShareBlock(chatClaim) == "g.block.onehost", chatClaim.LogState.ToString(CultureInfo.InvariantCulture));
            var manualKill = variant("certain", "KillRole", "manual", trail, log);
            Check("sgate.certain.manual-record-is-not", manualKill.LogState == LogCheck.Ok && !manualKill.CertainLog && GateRules.ShareBlock(manualKill) == "g.block.onehost", null);
            var circKill = variant("circumstantial", "KillRole", "auto", trail, log);
            Check("sgate.certain.circumstantial-strength-is-not", circKill.CertainLog && !GateRules.CertainOneHost(circKill) && GateRules.ShareBlock(circKill) == "g.block.onehost", null);
            var late = variant("certain", "KillRole", "auto", "11:40:00Z CheatDetector: KillRole (Certain) #3 x (client 5): role Crewmate (live Crewmate), flags 0", log);
            Check("sgate.certain.detection-out-of-window", !late.CertainLog && GateRules.ShareBlock(late) != "", late.LogState.ToString(CultureInfo.InvariantCulture));
            // review: a zip with no host name: nobody to charge a later overturn to, so no single-host share at all (not even the author's call)
            var noName = variant("certain", "KillRole", "auto", trail, log);
            noName.HostLabel = " ";
            Check("sgate.certain.needs-a-host-name", noName.CertainLog && !GateRules.CertainOneHost(noName) && GateRules.ShareBlock(noName) == "g.block.noname" && !GateRules.Overridable("g.block.noname")
                && GateRules.BasisText(noName, 0) == S.In(0, "bs.noname"), GateRules.ShareBlock(noName));
            // review: one host's record backs one listing only (bringing it back or listing the player again: a second host or the author's call)
            var used = variant("certain", "KillRole", "auto", trail, log);
            used.UsedBefore = true;
            string bUsed = GateRules.ShareBlock(used);
            Check("sgate.certain.one-listing-per-record", bUsed == "g.block.used" && GateRules.Overridable(bUsed) && GateRules.Basis(used) == "" && GateRules.BasisText(used, 0) == S.In(0, "bs.used"), bUsed);
            used.HostCount = 2;
            Check("sgate.certain.used-but-two-hosts", GateRules.ShareBlock(used) == "" && GateRules.Basis(used) == "hosts", GateRules.ShareBlock(used));
            // (2) chat and the other rules: one host is blocked (only the author's written reason passes it)
            foreach (var r in new[] { new[] { "circumstantial", "ChatFlood" }, new[] { "circumstantial", "NgWord" }, new[] { "manual", "manual" }, new[] { "circumstantial", "SpeedHack" }, new[] { "circumstantial", "Callout" }, new[] { "certain", "ChatAlive" } })
            {
                var one = Imp("AEG-SG0" + r[1].Substring(0, 2).ToUpperInvariant(), r[0], r[1]);
                one.LogState = LogCheck.Ok; one.HostCount = 1; one.HostLabel = "かえで"; one.Source = r[0] == "manual" ? "manual" : "auto";
                string b = GateRules.ShareBlock(one);
                Check("sgate.onehost.blocked." + r[1], b == "g.block.onehost" && GateRules.Overridable(b) && GateRules.Basis(one) == "" && GateRules.BasisText(one, 0) == S.In(0, "bs.onehost"), b);
            }
            var c1 = Imp("AEG-SG002", "circumstantial", "ChatFlood");
            c1.LogState = LogCheck.Ok; c1.HostCount = 1; c1.HostLabel = "Kaede"; c1.ImportDir = "20260921-110000-sg2";
            // (3) two hosts
            c1.HostCount = 2;
            Check("sgate.chat.two-hosts-allowed", GateRules.ShareBlock(c1) == "" && GateRules.Basis(c1) == "hosts" && GateRules.ShareLevel(c1, 3) == 1 && GateRules.MaxDays(c1) == 30 && GateRules.BasisWhy(c1, 0) == S.In(0, "bs.hosts.why", 2), GateRules.ShareBlock(c1));
            c1.HostCount = 1;
            // (4) a trusted admin: one host is enough (first stage only); the trust is by the zip's name (any case), revocable
            var trust = new List<Reporters.Event> { new Reporters.Event { Kind = "trust", At = now.AddDays(-3), Label = "kaede" } };
            Reporters.Current = Reporters.Build(trust, null, new[] { c1 }, null, now);
            Check("sgate.trusted.allowed", GateRules.ShareBlock(c1) == "" && GateRules.Basis(c1) == "trusted" && Reporters.TrustedHost(c1) && GateRules.ShareLevel(c1, 3) == 1 && GateRules.MaxDays(c1) == 30
                && GateRules.BasisText(c1, 0) == S.In(0, "bs.trusted", "Kaede"), GateRules.ShareBlock(c1));
            var other = Imp("AEG-SG003", "circumstantial", "ChatFlood");
            other.LogState = LogCheck.Ok; other.HostCount = 1; other.HostLabel = "さくら";
            var unnamed = Imp("AEG-SG004", "circumstantial", "ChatFlood");
            unnamed.LogState = LogCheck.Ok; unnamed.HostCount = 1;
            Check("sgate.trusted.only-that-name", GateRules.ShareBlock(other) == "g.block.onehost" && GateRules.ShareBlock(unnamed) == "g.block.noname" && !Reporters.TrustedHost(unnamed), null);
            var noLogTrusted = Imp("AEG-SG005", "circumstantial", "ChatFlood");
            noLogTrusted.LogState = LogCheck.NoLog; noLogTrusted.HostLabel = "Kaede";
            Check("sgate.trusted.log-check-stays", GateRules.ShareBlock(noLogTrusted) == "g.block.nolog", null);
            // review: trust goes by the record's FIRST import: a zip first imported under another name and forwarded by the trusted admin is not trusted
            var fwd = Imp("AEG-SG006", "circumstantial", "ChatFlood");
            fwd.LogState = LogCheck.Ok; fwd.HostCount = 1; fwd.HostLabel = "Kaede";
            fwd.RecordSrcs = new List<HostCount.Src> { new HostCount.Src("つばき", ""), new HostCount.Src("Kaede", "") };
            var fwd2 = Imp("AEG-SG007", "circumstantial", "ChatFlood");
            fwd2.LogState = LogCheck.Ok; fwd2.HostCount = 1; fwd2.HostLabel = "つばき";
            fwd2.RecordSrcs = new List<HostCount.Src> { new HostCount.Src("Kaede", ""), new HostCount.Src("つばき", "") };
            Check("sgate.trusted.first-import-only", !Reporters.TrustedHost(fwd) && GateRules.ShareBlock(fwd) == "g.block.onehost" && Reporters.TrustedHost(fwd2) && GateRules.Basis(fwd2) == "trusted", null);
            trust.Add(new Reporters.Event { Kind = "untrust", At = now.AddDays(-1), Label = "KAEDE " });
            Reporters.Current = Reporters.Build(trust, null, new[] { c1 }, null, now);
            Check("sgate.trusted.revoked", GateRules.ShareBlock(c1) == "g.block.onehost" && !Reporters.TrustedHost(c1), null);
            // review: the hosts' record could not be read: one host is never enough (not even the author's call); two hosts still are
            var failed = Reporters.Build(new List<Reporters.Event> { new Reporters.Event { Kind = "trust", At = now.AddDays(-3), Label = "Kaede" } }, null, new[] { c1 }, null, now);
            failed.Failed = true;
            Reporters.Current = failed;
            string bFail = GateRules.ShareBlock(k), bFailT = GateRules.ShareBlock(c1);
            c1.HostCount = 2;
            string bFail2 = GateRules.ShareBlock(c1);
            c1.HostCount = 1;
            Check("sgate.hostsfail.no-single-host", bFail == "g.block.hostsfail" && bFailT == "g.block.hostsfail" && !GateRules.Overridable(bFail) && bFail2 == "" && GateRules.BasisText(k, 0) == S.In(0, "bs.hostsfail"), bFail + " " + bFailT + " " + bFail2);
            Reporters.Current = null;
            // the list on disk: appended, read back (a tab in a name cannot split a line; every column, the listing lifted too)
            Fresh("sgate-hosts");
            bool appended = Reporters.Append(new Reporters.Event { Kind = "trust", At = now, Label = "Kaede\tx" });
            appended &= Reporters.Append(new Reporters.Event { Kind = "overturn", At = now, Label = "Kaede", Pc = "pc1", Ev = "AEG-X0001,AEG-X0002", Act = "a1", How = "undo", Share = "s1" });
            appended &= Reporters.Append(new Reporters.Event { Kind = "flag", At = now, Label = "Kaede", Act = "a1,a2" });   // (D-35: the review's latch line is not read)
            bool readOk;
            var back = Reporters.Read(out readOk);
