            string b3 = e3 != null ? GateRules.ShareBlock(e3) : "none";
            Check("sgate.e2e.certain-cap", freeFirst && b3 == "g.block.certcap" && Reporters.CertainOf(e3).Certain.Count == 2 && capSnap.Chain != null && capSnap.Chain.Ok
                && MainForm.CertCapLine(e3, 0).StartsWith("このホストの確実な検知だけの共有: 直近 30 日に 2/2 件", StringComparison.Ordinal), b3);
            Audit.Append(new AuditRec { At = DateTime.UtcNow, Action = "host.trust", Name = "もみじ", Result = "done.local" });
            Loader.AuditStep(capSnap, new Step("audit", null));
            Loader.Imports(capSnap, new Step("imports", null));
            Check("sgate.e2e.certain-cap-trusted", e3 != null && GateRules.Basis(e3) == "trusted" && GateRules.ShareBlock(e3) == "", e3 != null ? GateRules.ShareBlock(e3) : "none");
            // review: lines added past audit.head (outside the console) only raise the count: it stands (and trust from the
            // unverified lines does not)
            string headT = File.ReadAllText(App.AuditHead);
            Audit.Append(new AuditRec { At = DateTime.UtcNow, Action = "host.untrust", Name = "もみじ", Result = "done.local" });
            Audit.Append(new AuditRec { At = DateTime.UtcNow, Action = "share", Ev = "AEG-SGX10", Name = "third", Rule = "cheat", Gate = "certain", Host = "もみじ", Act = "e2e-cap-3", Result = "signed 4" });
            File.WriteAllText(App.AuditHead, headT, new UTF8Encoding(false));   // (the head two lines behind)
            Loader.AuditStep(capSnap, new Step("audit", null));
            Loader.Imports(capSnap, new Step("imports", null));
            Check("sgate.e2e.added-lines-still-count", e3 != null && capSnap.Chain.Kind == "head" && capSnap.Chain.AddedOnly && !Reporters.Current.CertainUnknown && Reporters.CertainOf(e3).Certain.Count == 3
                && GateRules.ShareBlock(e3) == "g.block.certcap" && GateRules.BasisText(e3, 0) == S.In(0, "bs.certcap", 2, 30), capSnap.Chain.Kind + " " + (e3 != null ? GateRules.ShareBlock(e3) : "none"));
            // review: a log cut short (the second and third shares taken off with the last lines) must not free a slot: the count
            // cannot be confirmed, so the certain path waits for a second host or the author, as at the cap
            var cutLog = Audit.ReadLines();
            cutLog.RemoveRange(cutLog.Count - 4, 4);
            WriteLines(App.AuditFile, cutLog);
            Loader.AuditStep(capSnap, new Step("audit", null));
            Loader.Imports(capSnap, new Step("imports", null));
            Check("sgate.e2e.truncated-log-fails-closed", e3 != null && !capSnap.Chain.Ok && Reporters.Current.CertainUnknown && Reporters.CertainOf(e3).Certain.Count == 1
                && GateRules.ShareBlock(e3) == "g.block.certcap" && GateRules.Overridable(GateRules.ShareBlock(e3)) && GateRules.BasisText(e3, 0) == S.In(0, "bs.capunknown", 2, 30)
                && MainForm.CertCapLine(e3, 0) == S.In(0, "cap.unknown", 2, 30), capSnap.Chain.Kind + " " + (e3 != null ? GateRules.ShareBlock(e3) + " " + Reporters.CertainOf(e3).Certain.Count : "none"));
            Reporters.Current = null;
        }

        /// <summary>v0.5.5 (「いいよ」): a report zip with one automatic record (its rule, strength and trail line) and a log with the detection line, then the tagged written line.</summary>
        static string CertZip(string name, string id, string puid, string action, string strength, string rule, string trail, string logLine, string system)
        {
            string zip = Path.Combine(root, name + ".zip");
            string json = "{\n  \"format\": \"PocketRoles.AegisEvidence\",\n  \"version\": 1,\n  \"id\": \"" + id + "\",\n  \"time\": \"2026-09-20T12:00:00Z\",\n"
                + "  \"action\": \"" + action + "\",\n  \"source\": \"auto\",\n  \"strength\": \"" + strength + "\",\n  \"rule\": \"" + rule + "\",\n  \"ruleText\": \"\",\n  \"by\": \"Aegis\",\n  \"ban\": null,\n"
                + "  \"player\": { \"name\": \"test\", \"hash\": \"" + puid + "\", \"puidHash\": \"" + puid + "\", \"clientId\": 5, \"playerId\": 2, \"platform\": \"StandaloneSteamPC\" },\n"
                + "  \"log\": [ \"" + trail + "\" ],\n  \"report\": null,\n  \"note\": \"\"\n}\n";
            string log = "[Info   :PocketRoles] PocketRoles v0.5.5 loaded\n" + logLine + "\n"
                + "[Info   :PocketRoles] AegisEvidence: " + id + " written (" + action + ", " + rule + ", puid-hash " + puid.Substring(0, 8) + ")\n";
            using (var fs = new FileStream(zip, FileMode.CreateNew))
            using (var za = new ZipArchive(fs, ZipArchiveMode.Create))
            {
                Put(za, "LogOutput.log", log);
                Put(za, "system.txt", system);
                Put(za, "launcher-state.json", "{ \"lastBuiltGameVersion\": \"2026.8.18\", \"lastBuiltAt\": \"2026-09-01 10:00:00\" }");
                Put(za, "evidence/" + id + ".json", json);
            }
            return zip;
        }

        /// <summary>v0.5.5 review: no invisible control character in this app's source (one lost by an editor would break the C#: '\u0001' is written as an escape).</summary>
        static void SourceTests(string scriptDir)
        {
            string file = Path.Combine(scriptDir ?? "", "AegisBan.ps1");
            if (!File.Exists(file)) { Check("source.found", false, file); return; }
            string text = File.ReadAllText(file, Encoding.UTF8);
            int bad = -1;
            for (int i = 0; i < text.Length; i++) { char ch = text[i]; if (ch < ' ' && ch != '\r' && ch != '\n' && ch != '\t') { bad = i; break; } }
            Check("source.no-control-characters", bad < 0, bad < 0 ? null : "at char " + bad.ToString(CultureInfo.InvariantCulture));
            // v0.5.5 (2026-09-22 「なまえわかるのに」): the old neutral addressee is gone from every text (split: this line is not a hit)
            Check("source.no-inquirer-addressee", text.IndexOf("お問い合わせいただいた" + "方", StringComparison.Ordinal) < 0, null);
        }

        static void DefsTests()
        {
            string d1 = Path.Combine(root, "d1.txt"), d2 = Path.Combine(root, "d2.txt"), d3 = Path.Combine(root, "none.txt");
            File.WriteAllText(d1, "version=3\n[bans]\n");
            File.WriteAllText(d2, "version=5\n[bans]\n" + Hashes.HashOf("selftest-line") + " 1 never other\n");
            string src;
            var best = Loader.PickShared(new List<string> { d1, d2, d3 }, new List<string> { "repo", "tray", "mod" }, out src);
            Check("defs.admin-picks-newest-copy", best != null && best.Version == 5 && src == "tray" && best.Bans.Count == 1, src);
            var none = Loader.PickShared(new List<string> { d3 }, new List<string> { "mod" }, out src);
            Check("defs.admin-no-copy", none == null && src.Length == 0, null);
        }
    }

    public static class Entry
    {
        const string MutexName = "Local\\wakayamachannel.Aegis.BanConsole", ShowName = "Local\\wakayamachannel.Aegis.BanConsole.Show";

        public static void MakeIcon(string path) { Art.WriteIcon(path); }

        public static void Run(string scriptDir, string gameDir, string repoDir, string lang, string stateDir, bool admin)
        {
            bool created;
            using (var mutex = new Mutex(true, MutexName, out created))
            {
                if (!created)
                {
                    // one console at a time: bring the open one to the front
                    try { using (var ev = EventWaitHandle.OpenExisting(ShowName)) ev.Set(); } catch (Exception) { }
                    return;
                }
                using (var show = new EventWaitHandle(false, EventResetMode.AutoReset, ShowName))
                {
                    Native.Init();
                    Ui.InitScale();
                    App.Init(scriptDir, gameDir, repoDir, lang, stateDir, admin);
                    Application.EnableVisualStyles();
                    try { Application.SetCompatibleTextRenderingDefault(false); } catch (InvalidOperationException) { }
                    Application.AddMessageFilter(new InputWatch());   // v0.5.5: input keeps the unlock alive (15 minutes)
                    var f = new MainForm();
                    var t = new Thread(() =>
                    {
                        while (true)
                        {
                            try { show.WaitOne(); } catch (Exception) { return; }
                            try { if (f.IsDisposed) return; f.BeginInvoke(new Action(f.BringUp)); } catch (Exception) { return; }
                        }
                    });
                    t.IsBackground = true;
                    t.Start();
                    Application.Run(f);
                }
            }
        }
    }
}
'@

try {
    Add-Type -TypeDefinition $source -ReferencedAssemblies @('System.Windows.Forms', 'System.Drawing', 'System.Core', 'System.IO.Compression', 'System.IO.Compression.FileSystem') -Language CSharp -ErrorAction Stop
    if ($SelfTest) {
        # v0.5.5: no window; the C# compiled above (C# 5, like every start) and the logic tests in a temp folder
        [Console]::WriteLine('PASS compile (C# in memory, Windows PowerShell 5.1)')
        $fails = [AegisBanApp.SelfTest]::Run($PSScriptRoot)
        exit $(if ($fails -eq 0) { 0 } else { 1 })
    }
    if ($MakeIcon) { [AegisBanApp.Entry]::MakeIcon([IO.Path]::GetFullPath($MakeIcon)); exit 0 }
    [AegisBanApp.Entry]::Run($PSScriptRoot, $GameDir, $RepoDir, $Lang, $stateDir, [bool]$Admin)
} catch {
    Write-BanLog ('Aegis BAN console failed: ' + $_.Exception.ToString())
    if ($SelfTest) { [Console]::WriteLine('FAIL compile or self-test: ' + $_.Exception.Message); exit 1 }
    if (-not $MakeIcon) {
        try { [void][System.Windows.Forms.MessageBox]::Show(('Aegis BAN 管理を開けませんでした / could not start:' + "`r`n" + $_.Exception.Message + "`r`n`r`n" + $errLog), 'Aegis BAN 管理') } catch { }
    }
    exit 1
}
